@charset "UTF-8";

/* Panel rules sit in Bootstrap 6's custom layer: above its components,
   below its helpers and utilities, which win as they did with !important. */
@layer custom {

/* Bootstrap 6 shell: what the panel keeps of Bootstrap 5's look. */
.pg-menu-wrap {
  position: relative;
}
/* v5's navbar has no minimum height; a button with no variant is clear. */
.navbar {
  --bs-navbar-min-height: 0;
  --bs-navbar-nav-link-padding-x: 0.5rem;
}
:where(.btn:not(.btn-solid, .btn-outline, .btn-subtle, .btn-text, .btn-link)) {
  --bs-btn-bg: transparent;
  --bs-btn-hover-bg: transparent;
  --bs-btn-active-bg: transparent;
  --bs-btn-disabled-bg: transparent;
}
/* v6 buttons centre their content with flexbox, so text-start/text-end
   (text-align) no longer move it as they did on v5's inline-block button.
   :where() keeps the specificity of .btn alone: a panel rule on the
   button's own class and the justify-content utilities still win. */
.btn:where(.text-start) {
  justify-content: flex-start;
}
.btn:where(.text-end) {
  justify-content: flex-end;
}
/* A switched-off ghost button draws no frame. With a theme class
   (.theme-secondary) v6 leaves the disabled border colour unset, so it falls
   back to the text colour and the disabled button looked stronger than the
   enabled one beside it (the settings step arrows). */
.btn-text:is(:disabled, .disabled) {
  border-color: transparent;
}
/* Card: block body and header, v5's cap tint, children keep their own
   margins (v6 zeroes them and spaces them with a gap). Bootstrap 6's
   padding; the header text starts where the body text does. */
.card {
  --bs-card-spacer-y: var(--bs-spacer-6);
  --bs-card-spacer-x: var(--bs-spacer-6);
  --bs-card-cap-padding-y: var(--bs-spacer-4);
  --bs-card-cap-padding-x: var(--bs-card-spacer-x);
  --bs-card-cap-bg: color-mix(in srgb, var(--pg-fg-body) 3%, transparent);
  --bs-card-border-color: var(--pg-border-color-translucent);
}
.card-body,
.card-header {
  display: block;
  flex-direction: row;
}
:where(.card-body) > :where(p, ul, ol, dl, pre, blockquote, figure) {
  margin-top: 0;
  margin-bottom: 1rem;
}
:where(.card-body) > :where(h1, h2, h3, h4, h5, h6, .h1, .h2, .h3, .h4, .h5, .h6, .card-title) {
  margin-top: 0;
  margin-bottom: 0.5rem;
}
:where(.card-body) > :where(hr) {
  margin: 1rem 0;
}
:where(.card-body) > :where(.card-text:last-child) {
  margin-bottom: 0;
}
/* v6 zeroes the block margins of a card body's children; a row keeps its
   negative gutter, a table and a form hint their v5 margins. */
.card-body > .row {
  margin-top: calc(-1 * var(--bs-gutter-y));
}
.card-body > .table {
  margin-bottom: 1rem;
}
.card-body > .form-text {
  margin-top: 0.25rem;
}
/* v5's accordion colours, radius and chevron size. */
.accordion {
  --bs-accordion-btn-color: var(--pg-fg-body);
  --bs-accordion-border-radius: var(--pg-radius);
  --bs-accordion-btn-icon-width: 1.25rem;
