.navbar-nav {
  --bs-nav-gap: 0;
  --bs-nav-link-gap: 0;
}
.navbar-nav {
  --bs-nav-link-border-width: 0;
}
.navbar-nav .nav-link {
  padding-top: 0.5rem;
  padding-bottom: 0.5rem;
}
.nav {
  --bs-nav-link-padding-x: 1rem;
  --bs-nav-link-padding-y: 0.5rem;
}
/* v5's nav links: start-aligned (v6 centres them; filled and justified
   navs centre as in v5) and borderless (tabs draw their own); v5's pills:
   no bar around them, the links with v5's radius. */
