  --bs-nav-link-justify: flex-start;
  --bs-nav-link-border-width: 0;
}
.nav-fill,
.nav-justified {
  --bs-nav-link-justify: center;
}
.nav-pills {
  --bs-nav-pills-bg: transparent;
  --bs-nav-pills-padding: 0;
  --bs-nav-pills-border-radius: 0;
  --bs-nav-pills-link-border-radius: var(--pg-radius);
