  font-weight: 500;
  line-height: 1.2;
}
:where(h1, .h1):not(.menu-header, .popover-header) {
  font-size: min(calc(1.375rem + 1.5vw), 2.5rem);
}
:where(h2, .h2):not(.menu-header, .popover-header) {
  font-size: min(calc(1.325rem + 0.9vw), 2rem);
}
:where(h3, .h3):not(.menu-header, .popover-header) {
  font-size: min(calc(1.3rem + 0.6vw), 1.75rem);
}
:where(h4, .h4):not(.menu-header, .popover-header) {
  font-size: min(calc(1.275rem + 0.3vw), 1.5rem);
}
:where(h5, .h5):not(.menu-header, .popover-header) {
  font-size: 1.25rem;
}
:where(h6, .h6):not(.menu-header, .popover-header) {
  font-size: 1rem;
