/* Dropdown menu: 1rem text, rows inset from the menu's edge on Bootstrap 6's
   spacers, rounded to the menu's radius minus that inset so the corners
   nest (a heading in a menu keeps the header's own size). */
.menu {
  --bs-menu-font-size: 1rem;
  --bs-menu-padding-x: var(--bs-spacer-1);
  --bs-menu-padding-y: var(--bs-spacer-1);
  --bs-menu-gap: 0;
  --bs-menu-item-gap: 0;
  --bs-menu-item-padding-x: var(--bs-spacer-4);
  --bs-menu-item-padding-y: var(--bs-spacer-2);
  --bs-menu-item-border-radius: var(--pg-radius-lg);
  --bs-menu-header-padding-x: var(--bs-spacer-4);
  --bs-menu-header-padding-y: var(--bs-spacer-3);
  --bs-menu-divider-margin-x: 0;
  --bs-menu-divider-margin-y: 0.5rem;
