  --pg-secondary-active: #607d8b;
  --pg-secondary-ink: #455a64;
  --pg-secondary-ink-rgb: 69, 90, 100;
  --pg-secondary-subtle: #eceff1;
  --pg-secondary-line: #cfd8dc;

  --pg-success: #81c784;
