  --pg-warning-ink-rgb: 138, 109, 0;
  --pg-warning-subtle: #fff8e1;
  --pg-warning-line: #ffecb3;

  --pg-info: #4dd0e1;
  --pg-info-rgb: 77, 208, 225;
  --pg-info-hover: #26c6da;
