  --pg-info-ink: #006064;
  --pg-info-ink-rgb: 0, 96, 100;
  --pg-info-subtle: #e0f7fa;
  --pg-info-line: #b2ebf2;

  /* Access level colours used by the folder tree and the chart tables. */
  --pg-access-public: var(--bs-fg-2);
  --pg-access-private: #ac2929;
  --pg-access-guest: #c66e28;
  --pg-access-registration: #2976ac;
  --pg-access-membership: #148340;

  /* Neutral surface tints shared by the dashboard widgets. They carry the only
     values that differ between themes, so the widget rules below need no
     theme specific duplicates. */
  --pg-tint: rgba(128, 128, 128, 0.08);
  --pg-tint-strong: rgba(128, 128, 128, 0.16);
  --pg-tint-hover: rgba(128, 128, 128, 0.18);
  --pg-tint-soft: rgba(128, 128, 128, 0.06);
  --pg-rule: rgba(128, 128, 128, 0.16);

  --pg-rule-strong: rgba(128, 128, 128, 0.18);
  --pg-rule-dashed: rgba(128, 128, 128, 0.35);
  --pg-scrollbar-thumb: #939393;

  --pg-body-bg-rgb: 255, 255, 255;
  --pg-navbar-bg-rgb: 248, 248, 248;
  --clock-fallback-color: #0891b2;
  --clock-gradient: linear-gradient(100deg, #0891b2 0%, #6366f1 50%, #db2777 100%);
  /* The bloom is the neon; on white it stays small, because a wide one reads as
     a blurred glyph rather than a lit one. */
  --clock-glow: rgba(219, 39, 119, 0.28);
  --clock-bloom: 7px;
  /* Logo gradient stops: blue, purple in the middle (3) and pink, the colours
     of the mascot's nebula, deep enough to read on white. The inline wordmark
     and the CSS text gradient read them. */
  --pg-logo-color-1: #3D5AFE;
  --pg-logo-color-2: #FF3D72;
  --pg-logo-color-3: #B44DFF;
  --pg-card-bg: rgb(245, 245, 245);
