  outline-color: var(--pg-success);
  box-shadow: 0 0 0 var(--pg-focus-ring-width)
    color-mix(in srgb, var(--pg-success) 35%, transparent);
}
:is(.check, .radio):checked,
:is(.check, .radio)[type="checkbox"]:indeterminate {
  background-color: var(--pg-primary);
  border-color: var(--pg-primary);
}
/* The tick, the dot and the switch knob ship white; on a tone 300 fill that is
   2.2:1, under the 3:1 a graphical control needs, so all three take the ink. */
:is(.check, .radio):checked[type="checkbox"],
:is(.check, .radio)[type="checkbox"]:indeterminate {
  --bs-form-check-bg-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 20 20'%3e%3cpath fill='none' stroke='%231a1c1e' stroke-linecap='round' stroke-linejoin='round' stroke-width='3' d='m6 10 3 3 6-6'/%3e%3c/svg%3e");
}
:is(.check, .radio)[type="checkbox"]:indeterminate {
  --bs-form-check-bg-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 20 20'%3e%3cpath fill='none' stroke='%231a1c1e' stroke-linecap='round' stroke-linejoin='round' stroke-width='3' d='M6 10h8'/%3e%3c/svg%3e");
}
:is(.check, .radio):checked[type="radio"] {
  --bs-form-check-bg-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='-4 -4 8 8'%3e%3ccircle r='2' fill='%231a1c1e'/%3e%3c/svg%3e");
}
/* v6's .switch::before reads only --bs-switch-indicator-bg: a checked thumb
   takes the dark on-accent ink against the light blue track, and the blue
   focus knob is kept for unchecked switches, where the track is not blue.
   A look switch (a settings card's, the report drawer's) has its own white
   thumb on the accent gradient, so neither reaches it. */
.switch:not(:where(.pg-set-card *, #report_settings *)):has(input:checked) {
  --bs-switch-indicator-bg: var(--pg-on-accent);
}
.switch:not(:where(.pg-set-card *, #report_settings *)):focus-within:not(:has(input:checked)) {
  --bs-switch-indicator-bg: var(--pg-primary);
}
.form-range {
  --bs-range-thumb-bg: var(--pg-primary);
  --bs-range-thumb-active-bg: var(--pg-primary-line);
  --bs-range-track-fill-bg: var(--pg-primary);
}
/* Room above a Range for its value bubble, which sits over the thumb */
.pg-range-bubble {
  margin-top: 1.75rem;
}

