    background-color: color-mix(in srgb, var(--pg-bg-body) calc(var(--bs-bg-opacity) * 100%), transparent) !important;
    width:100%;
    top: var(--pg-navbar-h);
    border-radius: 0;
    padding-left: 20px;
    padding-right: 20px;
