  box-shadow: inset 0 -1px 0 var(--pg-border-color-translucent);
  font-size: var(--pg-text-meta);
  font-weight: var(--pg-weight-strong);
  color: var(--pg-fg-3);
  white-space: nowrap;
  vertical-align: middle;
}
.erp-list-table > thead > tr > th[aria-sort] {
  color: var(--pg-fg-body);
}
.erp-list-table > tbody > tr > td {
  height: 52px;
  padding: 6px 14px;
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.erp-list-table > tbody > tr:last-child > td {
  border-bottom: 0;
}
/* A phone: the table scrolls sideways, so a cell keeps at least 6rem and
   a name that may break anywhere (text-break) is not squeezed to a few
   letters a line; the sides are the table's 8 px (the driver lists are
   cards there). */
@media (max-width: 575.98px) {
  .erp-list-table > thead > tr > th,
  .erp-list-table > tbody > tr > td {
