}
.pg-sale-ig > .btn { border-radius: 0; }
/* The box clips and the frame glows for any of its controls: the focused
   one wears its own ring, inset. */
.pg-sale-ig input:focus-visible,
.pg-sale-ig > .btn:focus-visible {
  outline: 2px solid var(--pg-primary-ink);
  outline-offset: -2px;
}
.pg-sale-mult {
