.pg-sale[data-mode="kasa"] #pg_sale_product { font-size: 1.15rem; padding: .7rem .25rem; }
.pg-sale[data-mode="kasa"] #pg_sale_product_group .pg-sale-ig-icon { font-size: 1.3rem; padding: 0 .85rem; }
.pg-sale[data-mode="kasa"] #pg_sale_product_group > .btn { padding-inline: 1.1rem; font-size: 1rem; }
.pg-sale-foot {
