  box-shadow: var(--pg-shadow);
}
#pg_sale_customer { position: relative; }
#pg_sale_cust_results { top: calc(100% + .25rem); }
.pg-sale-res {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: .1rem 1rem;
  align-items: center;
  padding: .5rem .6rem;
  border-radius: var(--pg-radius);
  cursor: pointer;
}
.pg-sale-res:hover,
.pg-sale-res.is-active { background: var(--pg-bg-1); }
.pg-sale-res b {
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pg-sale-res small { grid-column: 1; color: var(--pg-fg-2); font-size: .78rem; }
.pg-sale-res-price {
  grid-row: 1 / 3;
  grid-column: 2;
  text-align: end;
  font-variant-numeric: tabular-nums;
}
.pg-sale-res-price small { display: block; }
.pg-sale-res[aria-disabled="true"] { opacity: .55; cursor: not-allowed; }
/* A button for an action that does nothing here: aria-disabled, not
   disabled, so it still takes focus and names its reason. */
.btn.pg-btn-inert { opacity: .65; cursor: default; }
.pg-sale-res-new b { color: var(--pg-link-color); }
.pg-sale-res-empty { padding: .7rem; color: var(--pg-fg-2); font-size: .875rem; }

/* The customer box, closed. */
.pg-sale-cust {
  display: flex;
  align-items: center;
  gap: .6rem;
  min-height: 3.05rem;
  padding: .35rem .4rem .35rem .6rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--pg-radius-lg);
  background: var(--pg-bg-body);
}
.pg-sale[data-mode="kasa"] .pg-sale-cust { min-height: 3.55rem; }
.pg-sale-av {
  flex: none;
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  background: var(--pg-bg-2);
  color: var(--pg-fg-2);
}
.pg-sale-av.is-picked { background: color-mix(in srgb, var(--pg-primary) 16%, transparent); color: var(--pg-link-color); }
.pg-sale-who { flex: 1; min-width: 0; line-height: 1.25; }
.pg-sale-who b,
.pg-sale-who small {
  display: block;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pg-sale-who b { font-weight: 600; }
.pg-sale-who small { color: var(--pg-fg-2); font-size: .76rem; }

/* The cart. */
.pg-sale-cart { container-type: inline-size; }
.pg-sale-table { --bs-table-bg: transparent; }
.card .pg-sale-table { margin: 0 !important; }
.pg-sale-table th {
  font-size: .76rem;
  font-weight: 600;
  color: var(--pg-fg-2);
  white-space: nowrap;
  vertical-align: bottom;
}
.pg-sale-table th small { display: block; font-weight: 400; opacity: .8; }
.pg-sale-table td { vertical-align: middle; }
.pg-sale-table td.text-end,
.pg-sale-table th.text-end { white-space: nowrap; font-variant-numeric: tabular-nums; }
.pg-sale[data-mode="kasa"] .pg-sale-table td { padding-top: .8rem; padding-bottom: .8rem; }
.pg-sale-c-no { width: 1%; color: var(--pg-fg-2); font-variant-numeric: tabular-nums; }
.pg-sale-c-thumb,
.pg-sale-c-rm { width: 1%; }
.pg-sale-thumb {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: var(--pg-radius);
  background: var(--pg-bg-2);
  color: var(--pg-fg-2);
  font-size: 1.1rem;
  object-fit: cover;
}
.pg-sale-pname { display: block; font-weight: 600; line-height: 1.3; }
.pg-sale[data-mode="kasa"] .pg-sale-pname { font-size: 1.05rem; }
.pg-sale-psub { display: block; margin-top: .1rem; font-size: .76rem; color: var(--pg-fg-2); }
.pg-sale-unit-inline { display: none; font-size: .76rem; color: var(--pg-fg-2); }
.pg-sale-step {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--pg-radius-lg);
  background: var(--pg-bg-body);
}
.pg-sale-step button {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  padding: 0;
  border: 0;
  border-radius: var(--pg-radius);
  background: transparent;
  color: var(--pg-fg-2);
}
.pg-sale-step button:hover:not(:disabled) { background: var(--pg-bg-1); color: var(--pg-fg-body); }
.pg-sale-step button:disabled { opacity: .35; }
.pg-sale-step input {
  width: 2.8em;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: center;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  outline: 0;
}
.pg-sale-step input:focus-visible {
  outline: 2px solid var(--pg-primary-ink);
  outline-offset: -2px;
  border-radius: var(--pg-radius);
  box-shadow: none;
}
.pg-sale[data-mode="kasa"] .pg-sale-step button { width: 38px; height: 38px; }
.pg-sale-linemsg {
  display: block;
  max-width: 15rem;
  margin-top: .25rem;
  font-size: .74rem;
  color: var(--pg-danger-fg-emphasis);
  white-space: normal;
}
.pg-sale-rm {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0;
  border-radius: var(--pg-radius);
  background: transparent;
  color: var(--pg-fg-2);
}
.pg-sale-rm:hover { background: color-mix(in srgb, var(--pg-danger) 14%, transparent); color: var(--pg-danger-fg-emphasis); }
.pg-sale-table tr.pg-sale-flash > td { animation: pg-sale-flash 1.4s ease-out; }
@keyframes pg-sale-flash {
  0% { background: color-mix(in srgb, var(--pg-primary) 18%, transparent); }
  100% { background: transparent; }
}
.pg-sale-table tr.pg-sale-line-error > td { background: color-mix(in srgb, var(--pg-danger) 10%, transparent); }
.pg-sale-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .2rem;
  padding: 2.2rem 1rem;
  text-align: center;
  color: var(--pg-fg-2);
}
.pg-sale-empty .bi { font-size: 2.2rem; opacity: .6; }
.pg-sale-empty strong { color: var(--pg-fg-body); font-size: 1rem; }

/* A narrow cart (phone, or a narrow column) turns each row into two lines:
   the name, then the quantity, the amount and the bin. */
@container (max-width: 575px) {
  .pg-sale-table thead { display: none; }
  .pg-sale-table tbody tr {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
    column-gap: .6rem;
    padding: .7rem .75rem;
    border-bottom: 1px solid var(--pg-border-color-translucent);
  }
  .pg-sale-table tbody tr:last-child { border-bottom: 0; }
  .pg-sale-table tbody tr.pg-sale-empty-row { display: block; padding: 0; }
  .pg-sale-table tbody tr.pg-sale-line-error { background: color-mix(in srgb, var(--pg-danger) 10%, transparent); }
  .pg-sale-table tbody td { padding: 0; border: 0; background: transparent; }
  .pg-sale-table td.pg-sale-c-thumb,
  .pg-sale-table td.pg-sale-c-no,
  .pg-sale-table td.pg-sale-c-unit,
  .pg-sale-table td.pg-sale-c-rate,
  .pg-sale-table td.pg-sale-c-tax { display: none !important; }
  .pg-sale-table td.pg-sale-c-name { grid-column: 1 / -1; margin-bottom: .5rem; }
  .pg-sale-unit-inline { display: block; }
}

/* The status column: summary, payment, account. The column is as tall as
   the row, so the stickiness is on this box. */
.pg-sale-status { display: flex; flex-direction: column; gap: 1rem; }
@media (min-width: 1024px) {
  .pg-sale-status { position: sticky; top: 3.3rem; }
}
/* Database Engine: the side column sticks beside the long table list, but
   it is taller than a short window, so it scrolls inside itself rather than
   leaving its lower cards out of reach until the end of the page. */
@media (min-width: 1024px) {
  .pg-engine-side {
    position: sticky;
    top: 3.3rem;
    max-height: calc(100vh - 4.3rem);
    overflow-y: auto;
    overscroll-behavior: contain;
  }
}
.pg-sale-total { padding: 1rem 1rem .85rem; }
.pg-sale-total-label {
  font-size: .72rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--pg-fg-2);
}
.pg-sale-total-amount {
  margin: .15rem 0 .2rem;
  font-size: 2.35rem;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -.01em;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}
.pg-sale-total-sm { font-size: 1.8rem; }
.pg-sale-total-sub { font-size: .8rem; color: var(--pg-fg-2); }
.pg-sale-rows {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: .3rem 1rem;
  margin: 0;
  padding: .75rem 1rem;
  border-top: 1px solid var(--pg-border-color-translucent);
  font-size: .875rem;
}
.pg-sale-rows-flush { border-top: 0; }
.pg-sale-rows dt { font-weight: 400; color: var(--pg-fg-2); }
.pg-sale-rows dd { margin: 0; text-align: end; font-variant-numeric: tabular-nums; }
.pg-sale-rows .pg-sale-grand {
  margin-top: .2rem;
  padding-top: .45rem;
  border-top: 1px solid var(--pg-border-color-translucent);
  color: var(--pg-fg-body);
  font-weight: 700;
}
.pg-sale-rows dt.pg-sale-grand { align-self: end; }
.pg-sale-rows dd.pg-sale-grand { font-size: 1.35rem; }

.pg-sale-pay { display: flex; flex-direction: column; gap: .85rem; }
.pg-sale-methods {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: .4rem;
}
.pg-sale-method {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .2rem;
  padding: .5rem .2rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--pg-radius-lg);
  background: var(--pg-bg-body);
  color: var(--pg-fg-2);
  font-size: .78rem;
  line-height: 1.2;
}
.pg-sale-method .bi { font-size: 1.15rem; }
.pg-sale-method:hover { background: var(--pg-bg-1); color: var(--pg-fg-body); }
.pg-sale-method[aria-pressed="true"] {
  border-color: var(--pg-primary);
  background: color-mix(in srgb, var(--pg-primary) 14%, transparent);
  color: var(--pg-fg-body);
  box-shadow: inset 0 0 0 1px var(--pg-primary);
}
.pg-sale[data-mode="kasa"] .pg-sale-method { padding: .8rem .2rem; font-size: .84rem; }
.pg-sale[data-mode="kasa"] .pg-sale-method .bi { font-size: 1.45rem; }
.pg-sale-link {
  align-self: flex-start;
  padding: 0;
  border: 0;
  background: none;
  color: var(--pg-link-color);
  font-size: .78rem;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.pg-sale-quick { display: flex; flex-wrap: wrap; gap: .3rem; margin-top: .4rem; }
.pg-sale-quick button {
  padding: .12rem .6rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--pg-radius-pill);
  background: transparent;
  color: inherit;
  font-size: .78rem;
  font-variant-numeric: tabular-nums;
}
.pg-sale-quick button:hover { background: var(--pg-bg-1); }
.pg-sale-change {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: .5rem;
  margin-top: .6rem;
  padding: .55rem .75rem;
  border-radius: var(--pg-radius-lg);
  background: color-mix(in srgb, var(--pg-success) 16%, transparent);
}
.pg-sale-change span { font-size: .8rem; color: var(--pg-fg-2); }
.pg-sale-change b { font-size: 1.5rem; color: var(--pg-success-fg-emphasis); font-variant-numeric: tabular-nums; }
.pg-sale-change.is-short { background: color-mix(in srgb, var(--pg-warning) 18%, transparent); }
.pg-sale-change.is-short b { font-size: 1.1rem; color: var(--pg-warning-fg-emphasis); }
.pg-sale-inv,
.pg-sale-note { display: flex; gap: .55rem; align-items: flex-start; }
.pg-sale-inv { font-size: .875rem; }
.pg-sale-inv .bi { margin-top: .15rem; color: var(--pg-fg-2); }
.pg-sale-inv small { display: block; font-size: .76rem; color: var(--pg-fg-2); }
.pg-sale-note { margin-top: .5rem; font-size: .76rem; color: var(--pg-fg-2); }
.pg-sale-pay > .pg-sale-note:first-child { margin-top: 0; }
.pg-sale-note .bi { margin-top: .1rem; }
#pg_sale_invoice:empty { display: none; }
.pg-sale-go {
  display: flex;
  align-items: center;
  gap: .5rem;
  width: 100%;
  padding: .8rem 1rem;
  font-size: 1.05rem;
  font-weight: 600;
}
.pg-sale-go kbd { margin-left: auto; background: rgba(0, 0, 0, .1); border-color: rgba(0, 0, 0, .15); color: inherit; }
.pg-sale-go.is-working { cursor: progress; }

.pg-sale-balance { display: flex; align-items: baseline; flex-wrap: wrap; gap: .5rem; margin-bottom: .75rem; }
.pg-sale-balance b { font-size: 1.5rem; font-variant-numeric: tabular-nums; }
.pg-sale-facts {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: .3rem .9rem;
  margin: 0;
  font-size: .84rem;
}
.pg-sale-facts dt { font-weight: 400; color: var(--pg-fg-2); }
.pg-sale-facts dd { margin: 0; overflow-wrap: anywhere; }

/* The card that replaces the summary once the sale is done. */
.pg-sale-done-head {
  display: flex;
  align-items: center;
  gap: .8rem;
  padding: 1rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.pg-sale-done-head > .bi { font-size: 2.1rem; color: var(--pg-success); }
.pg-sale-done-head b { display: block; font-size: 1.05rem; }
.pg-sale-done-head small { font-size: .8rem; color: var(--pg-fg-2); }
.pg-sale-done-list {
  list-style: none;
  margin: 0;
  padding: .25rem 0;
  border-top: 1px solid var(--pg-border-color-translucent);
}
.pg-sale-done-list li { display: flex; align-items: center; gap: .6rem; padding: .5rem 1rem; font-size: .86rem; }
.pg-sale-done-list .bi { color: var(--pg-fg-2); }
.pg-sale-done-actions { display: flex; flex-wrap: wrap; gap: .4rem; padding: .5rem 1rem 1rem; }
.pg-sale-next {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: .6rem;
  padding: .75rem 1rem;
  border-top: 1px solid var(--pg-border-color-translucent);
  font-size: .8rem;
  color: var(--pg-fg-2);
}
.pg-sale-next .btn { margin-left: auto; }
.pg-sale-next .btn kbd { background: transparent; border-color: rgba(0, 0, 0, .2); color: inherit; }

/* Below lg the column drops under the cart; the total and the button come
   back in a bar at the foot of the screen, clear of the chat launcher. */
.pg-sale-savebar {
  bottom: 0;
  z-index: 3;
  padding: .5rem 0 .25rem;
  background: linear-gradient(to top, var(--pg-bg-body) 70%, transparent);
}
.pg-sale-savebar-in {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .5rem .55rem .5rem .9rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--pg-radius-pill);
  background: var(--pg-bg-body);
  box-shadow: var(--pg-shadow);
}
body:has(#pg-chat-root) .pg-sale-savebar-in { margin-right: 4.75rem; }
.pg-sale-savebar-text { min-width: 0; line-height: 1.2; }
.pg-sale-savebar-text b { display: block; font-size: 1.15rem; font-variant-numeric: tabular-nums; }
.pg-sale-savebar-text small {
  display: block;
  font-size: .74rem;
  color: var(--pg-fg-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pg-sale-savebar-in .btn { flex: none; margin-left: auto; }

.pg-sale-recent { --pg-drawer-width: min(430px, 100vw); }
.pg-sale-rs {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: .25rem .8rem;
  padding: .75rem 1rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.pg-sale-rs-acts { grid-column: 1 / -1; display: flex; align-items: center; flex-wrap: wrap; gap: .4rem; }
.pg-sale-keys { display: grid; grid-template-columns: auto 1fr; gap: .5rem 1rem; margin: 0; }
.pg-sale-keys dt { font-weight: 400; text-align: end; }
.pg-sale-keys dd { margin: 0; color: var(--pg-fg-2); }

@media (prefers-reduced-motion: reduce) {
  .pg-sale-table tr.pg-sale-flash > td,
  .pg-sale-dot.is-pulse { animation: none; }
}



/* ── Workspace ───────────────────────────────────────────────────────────
   Channels, tasks and the planning board (workspace*.php), and the
   Workspace drawer the order, contact and product screens open. Colours
   come from the Bootstrap variables so the dark theme follows. */
body .workspace-color {
  color: var(--workspace-color) !important;
}
html[data-bs-theme="dark"] body .workspace-color {
  color: var(--workspace-color-highlight) !important;
}

/* The workspace's own accent, on its screens and in its drawers elsewhere,
   and the scale every workspace rule measures with: four corner radii from
   a chip to a drawer, four spaces, a row's and a header's padding,
   four sizes of face, two shadows. The
   RGB numbers are --workspace-color written out, for rgba(); the two are
   kept together here so a change to one is a change to both. */
body.workspace,
.ws-app,
[id^="ws-"] {
  --ws-accent: var(--workspace-color);
  --ws-accent-rgb: 94, 53, 177;
  --ws-soft: rgba(var(--ws-accent-rgb), .08);
  --ws-radius-xs: .45rem;
  --ws-radius-sm: .65rem;
  --ws-radius: 1rem;
  --ws-radius-lg: 1.25rem;
  --ws-space-1: .25rem;
  --ws-space-2: .5rem;
  --ws-space-3: .75rem;
  --ws-space-4: 1rem;
  --ws-row-y: .3rem;
  --ws-head-y: .6rem;
  --ws-head-h: 3.4rem;
  --ws-avatar-xs: 1rem;
  --ws-avatar-sm: 1.6rem;
  --ws-avatar: 2.2rem;
  --ws-avatar-lg: 3rem;
  --ws-shadow: 0 1px 2px rgba(0, 0, 0, .04), 0 10px 30px -14px rgba(0, 0, 0, .16);
  --ws-shadow-accent: 0 .75rem 1.5rem -.75rem rgba(var(--ws-accent-rgb), .45);
  /* The channel panes' cards (Decisions, Tasks, Board): a lift lighter than
     --ws-shadow, and the width of a column the Decisions and Tasks cards
     flow in (about twice the grids' old 22rem and 20rem). */
  --ws-shadow-soft: 0 1px 2px rgba(0, 0, 0, .04), 0 4px 14px -8px rgba(0, 0, 0, .14);
  --ws-flow-col: 34rem;
  /* The graph canvas core's tokens (pgc-) on the Workspace's scale; set
     beside the --ws-* names so the dark values below reach them too. */
  --pgc-accent: var(--ws-accent);
  --pgc-soft: var(--ws-soft);
  --pgc-radius: var(--ws-radius);
  --pgc-radius-sm: var(--ws-radius-sm);
  --pgc-shadow: var(--ws-shadow);
  --pgc-shadow-accent: var(--ws-shadow-accent);
  --pgc-ring: #7c3aed;
}
html[data-bs-theme="dark"] body.workspace,
html[data-bs-theme="dark"] .ws-app,
html[data-bs-theme="dark"] [id^="ws-"] {
  --ws-accent: var(--workspace-color-highlight);
  --ws-accent-rgb: 179, 157, 219;
  --ws-soft: rgba(var(--ws-accent-rgb), .1);
  --ws-shadow: 0 1px 2px rgba(0, 0, 0, .2), 0 10px 30px -14px rgba(0, 0, 0, .5);
  --ws-shadow-accent: 0 .75rem 1.5rem -.75rem rgba(var(--ws-accent-rgb), .35);
  --ws-shadow-soft: 0 1px 2px rgba(0, 0, 0, .25), 0 4px 14px -8px rgba(0, 0, 0, .5);
  --pgc-ring: #a78bfa;
}
/* Compact density, chosen per browser in the overview's header
   (workspace.js sets the class on <html> before the first draw): the same
   screens with the spaces narrowed, so only the tokens change here. */
html.ws-compact body.workspace,
html.ws-compact .ws-app,
html.ws-compact [id^="ws-"] {
  --ws-space-1: .15rem;
  --ws-space-2: .35rem;
  --ws-space-3: .5rem;
  --ws-space-4: .65rem;
  --ws-row-y: .1rem;
  --ws-head-y: .35rem;
  --ws-head-h: 2.8rem;
}

/* Focus rings follow the keyboard, not the mouse: the workspace is full of
   small controls, and a ring left on whatever was last clicked drew a box
   around it, so a click leaves no ring (:focus without :focus-visible),
   while the Tab key draws the accent ring the keyboard needs to see where
   it stands. Borders still change colour on a focused field. */
body.workspace *:focus:not(:focus-visible),
[id^="ws-"] *:focus:not(:focus-visible),
.ws-ctx *:focus:not(:focus-visible),
.ws-ask-modal *:focus:not(:focus-visible) {
  outline: 0;
  box-shadow: none;
}
body.workspace *:focus-visible,
[id^="ws-"] *:focus-visible,
.ws-ctx *:focus-visible,
.ws-ask-modal *:focus-visible {
  outline: 2px solid var(--ws-accent);
  outline-offset: 2px;
  box-shadow: none;
}

/* Drawers and the overview's cards sit on the scale too: a drawer's inner
   corners rounded and the panel lifted on the soft shadow instead of a
   hairline. */
body.workspace .drawer.drawer-end,
[id^="ws-"].drawer.drawer-end {
  border-left: 0;
  border-radius: var(--ws-radius-lg) 0 0 var(--ws-radius-lg);
  box-shadow: var(--ws-shadow);
}

/* On a touch screen the composer text is 16px so iOS does not zoom in on it. */
@media (pointer: coarse) {
  .ws-composer textarea {
    font-size: 16px;
  }
}
/* The panel gives list tables room above for their toolbar; the tables on
   the workspace screens sit inside cards and have none. */
body.workspace .card .table {
  margin-top: 0;
}
/* The workspace screens run to the edges of the page (their main area has
   no padding). The channel screen is one panel and fills it. Every other
   screen sits in .ws-shell-main, which gives what it holds the side padding
   of the panel's toolbar, so the rounded cards do not meet the edge of the
   page and line up with the first button above them. The padding is on the
   shared wrapper, never on a list of screens: a row in it keeps its own
   gutter (its side margins fall inside the padding; its top margin rises
   over the breadcrumb bar, which stays on top, see .pg-breadcrumb), and a
   screen drawn in #ws-root by its script gets the same edge as one drawn by
   the server.
   The toolbar runs across the whole width over that padding. */
body.workspace #content.p-0 > .row {
  --bs-gutter-x: 0;
}
body.workspace .ws-shell-main {
  padding: 0 .75rem .75rem;
}
body.workspace .ws-shell-main #ws-root > .pg-toolbar,
body.workspace .ws-shell-main > #button_bar {
  max-width: none;
  margin-left: -.75rem;
  margin-right: -.75rem;
}
body.workspace .ws-shell-main > #button_bar {
  padding: .5rem .75rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-app {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0;
  height: calc(100vh - 8.5rem);
  min-height: 28rem;
  background: var(--pg-bg-body);
  overflow: hidden;
  border-bottom: 1px solid var(--pg-border-color-translucent);
  box-shadow: 0 1px 2px rgba(0, 0, 0, .04), 0 10px 30px -12px rgba(0, 0, 0, .18);
  
}
@supports (height: 100dvh) {
  .ws-app { height: calc(100dvh - 8.5rem); }
}
/* The channel view prints no foot, so the conversation and its writing box
   reach the window's bottom. Today (.ws-home, drawn in the same root by
   showHome()) keeps the foot and the height above. The foot is hidden here
   rather than left out by output_footer() because the script switches
   between the two views without loading the page again. */
body.workspace_channels .software-content:not(:has(.ws-home)) > #footer {
  /* The foot carries d-flex, and @layer utilities beats @layer custom. */
  display: none !important;
}
.ws-app:not(:has(.ws-home)) {
  height: calc(100vh - var(--pg-navbar-h));
}
@supports (height: 100dvh) {
  .ws-app:not(:has(.ws-home)) { height: calc(100dvh - var(--pg-navbar-h)); }
}
/* A discussion beside the channel (threads.php): a third column on a wide
   screen; on a phone it covers the channel until it is closed (below). */
.ws-thread-panel {
  display: none;
}
.ws-app.ws-thread-open {
  grid-template-columns: minmax(0, 1fr) var(--ws-thread-w, minmax(20rem, 26rem));
}
.ws-app.ws-thread-open .ws-thread-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  border-left: 1px solid var(--pg-border-color);
  background: var(--pg-bg-body);
}
/* The discussion panel is widened by dragging its left edge; the strip
   sits over the border so the panel keeps its own padding. */
.ws-thread-resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  left: -3px;
  width: 7px;
  cursor: col-resize;
  z-index: 5;
  touch-action: none;
}
.ws-thread-resizer::after {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: 3px;
  width: 1px;
  background: transparent;
  transition: background .15s;
}
.ws-thread-resizer:hover::after,
.ws-thread-resizer:focus-visible::after,
.ws-app.ws-thread-resizing .ws-thread-resizer::after {
  background: var(--ws-accent);
}
.ws-app.ws-thread-resizing {
  cursor: col-resize;
  user-select: none;
}
.ws-app.ws-thread-resizing iframe {
  pointer-events: none;
}
.ws-send-group .pg-button {
  white-space: nowrap;
}
.ws-thread-panel > .ws-head,
.ws-thread-panel > .alert,
.ws-thread-panel > .ws-thread-source,
.ws-thread-panel > .ws-composer-wrap {
  flex-shrink: 0;
}
/* An assistant following the discussion: a soft line under the head with
   its sign, what it does and Stop; Follow again alone when it stopped. */
.ws-thread-follow {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: .5rem;
  margin: .6rem var(--ws-space-3);
  padding: .3rem .35rem .3rem .75rem;
  border-radius: .75rem;
  background: var(--ws-soft);
  font-size: .82rem;
}
.ws-thread-follow.ws-thread-follow-off {
  padding-top: 0;
  padding-bottom: 0;
  background: transparent;
}
.ws-thread-follow-text {
  flex: 1 1 auto;
  min-width: 0;
}
.ws-thread-follow-icon {
  margin-right: .4rem;
  color: var(--ws-accent);
}
/* The channel's info beside the conversation (showMembers()), in the
   discussion's place: one of the two at a time; on a phone it covers the
   channel until it is closed. */
.ws-info-panel {
  display: none;
}
.ws-app.ws-info-open {
  grid-template-columns: minmax(0, 1fr) minmax(18rem, 22.5rem);
}
.ws-app.ws-info-open .ws-info-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  border-left: 1px solid var(--pg-border-color);
  background: var(--pg-bg-body);
}
.ws-panel-head {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: var(--ws-space-2);
  min-height: var(--ws-head-h);
  padding: var(--ws-head-y) var(--ws-space-2) var(--ws-head-y) var(--ws-space-4);
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-panel-title {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  font-size: 1rem;
  font-weight: 700;
}
.ws-panel-title:focus {
  outline: none;
}
.ws-panel-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 0 var(--ws-space-4) var(--ws-space-4);
}
.ws-panel-kicker {
  margin: 1.15rem 0 .5rem;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--pg-fg-2);
}
.ws-info-purpose {
  margin: 0;
  font-size: .9rem;
  overflow-wrap: anywhere;
}
.ws-info-tags {
  display: flex;
  flex-wrap: wrap;
  gap: .35rem;
  margin-top: .5rem;
}
.ws-info-person {
  display: flex;
  align-items: center;
  gap: .65rem;
  padding: .3rem 0;
}
.ws-info-person > .avatar {
  flex: none;
  --bs-avatar-size: 1.75rem;
}
.ws-info-person-text {
  flex: 1 1 auto;
  min-width: 0;
}
.ws-info-person-text a.ws-person-link {
  color: inherit;
  text-decoration: none;
}
.ws-info-person-text a.ws-person-link:hover {
  text-decoration: underline;
}
.ws-info-person-name {
  overflow: hidden;
  font-size: .88rem;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-info-person-role {
  overflow: hidden;
  font-size: .75rem;
  color: var(--pg-fg-2);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-info-add {
  margin-top: .5rem;
}
/* A guest's line (access, who shared and when) wraps: its date is the point. */
.ws-info-guests .ws-info-person-role {
  white-space: normal;
}
/* An agent's row in a narrow column: the name and its role stay on the
   first line with the last seen at its right, the role is the part cut;
   the badges move to the next line whole; the line under it wraps. */
.ws-info-agents .ws-info-person {
  align-items: flex-start;
}
.ws-info-agents .ws-info-person-name {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: .15rem .4rem;
  overflow: visible;
  white-space: normal;
}
.ws-info-agent-title {
  display: flex;
  flex: 0 1 auto;
  align-items: baseline;
  gap: .4rem;
  min-width: 0;
  white-space: nowrap;
}
.ws-info-agent-name {
  flex: none;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-info-agent-role {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-info-agent-badges {
  display: inline-flex;
  flex-wrap: wrap;
  gap: .3rem;
}
.ws-info-agent-badges .ws-info-badge {
  margin-left: 0;
}
.ws-info-agents .ws-info-person-role {
  white-space: normal;
}
.ws-info-agents .ws-info-seen {
  margin-top: .1rem;
}
/* Channel info's agents and last seen: an agent's face is a rounded square
   with its mark, a person's stays round; the last seen sits at the right. */
.avatar.ws-agent-face {
  border-radius: 30%;
}
.avatar.ws-agent-face .bi {
  font-size: 13px;
  line-height: 1;
}
/* An agent's state in a message: the agents' dot (.ws-agent-dot, its colour
   map) in the face's lower right corner; its role is a violet pill after the
   name. */
.ws-msg-avatar .ws-msg-agent-state {
  position: absolute;
  right: -2px;
  bottom: -2px;
}
.ws-msg-meta .ws-msg-agent-role {
  align-self: center;
}
.ws-agent-stack {
  margin-left: .45rem;
}
/* Channel info's Info and Activity tabs (workspace_channel_activity.js):
   the segmented control under the panel's head, each tab its own scrolling
   pane. */
.ws-act-tabs-row {
  flex-shrink: 0;
  padding: var(--ws-space-2) var(--ws-space-4) 0;
}
.ws-act-tabs {
  display: flex;
  width: 100%;
}
.ws-act-tabs > .pg-seg-item {
  flex: 1 1 0;
}
.ws-act-body[hidden],
.ws-info-panel > .ws-panel-body[hidden] {
  display: none;
}
/* The Activity pane under the agents block: the project, label and value
   lines, linked lines with their age at the right, and the bars of context
   and plan usage. */
.ws-act-project {
  margin-top: var(--ws-space-3);
  overflow-wrap: anywhere;
}
.ws-act-count {
  margin-inline-start: .4rem;
  vertical-align: baseline;
}
/* Channel info's agents block (workspace_channel_activity.js), the same
   under both tabs: a head with the count, the states that ask for a look
   and the manager's icon button; a two-line row each agent, 8 above and
   below, 10 at the sides, reaching 10 past the text column, corner 12, 2
   between rows and no line; pointed at it takes the hover ground, opened
   the inset card ground with a hairline and its facts under it. */
.ws-agents {
  margin-top: 1.15rem;
}
.ws-agents-head {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 24px;
}
.ws-agents-head > .ws-panel-kicker {
  margin: 0;
  white-space: nowrap;
}
.ws-agents-count {
  font-size: var(--pg-text-count);
  font-weight: var(--pg-weight-medium);
  color: var(--pg-fg-3);
  font-variant-numeric: tabular-nums;
}
.ws-agents-sum {
  min-width: 0;
  margin-inline-start: auto;
  overflow: hidden;
  font-size: var(--pg-text-meta);
  color: var(--pg-fg-3);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-agents-manage {
  flex: none;
  margin: -2px -6px -2px 4px;
}
.ws-agents-rows {
  display: grid;
  gap: 2px;
  margin: 6px -10px 0;
}
.ws-agents-row {
  padding: 8px 10px;
  border-radius: 12px;
}
.ws-agents-row:hover {
  background: var(--pg-hover);
}
.ws-agents-row.is-open {
  background: var(--pg-surface-inset);
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
}
.ws-agents-row:has(> .ws-agents-rowhead:focus-visible) {
  box-shadow: 0 0 0 2px var(--pg-accent);
}
.ws-agents-row.is-paused {
  opacity: .5;
}
.ws-agents-rowhead {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  column-gap: 10px;
  align-items: center;
  width: 100%;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  text-align: start;
}
.ws-agents-rowhead:focus-visible {
  outline: 0;
}
.ws-agents-face {
  position: relative;
  display: inline-flex;
}
.ws-agents-face > .avatar {
  --bs-avatar-size: 1.75rem;
}
.ws-agents-face > .ws-agent-dot {
  position: absolute;
  right: -3px;
  bottom: -3px;
}
.ws-agents-text {
  display: block;
  min-width: 0;
}
.ws-agents-l1 {
  display: flex;
  align-items: baseline;
  gap: 7px;
  white-space: nowrap;
}
.ws-agents-name {
  flex: none;
  max-width: 100%;
  overflow: hidden;
  font-size: var(--pg-text-base);
  font-weight: var(--pg-weight-strong);
  line-height: 18px;
  text-overflow: ellipsis;
}
.ws-agents-role {
  min-width: 0;
  overflow: hidden;
  font-size: var(--pg-text-meta);
  color: var(--pg-fg-3);
  text-overflow: ellipsis;
}
.ws-agents-l2 {
  display: block;
  margin-top: 1px;
  overflow: hidden;
  font-size: var(--pg-text-meta);
  line-height: 17px;
  color: var(--pg-fg-2);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-agents-word {
  font-style: normal;
  font-weight: var(--pg-weight-strong);
}
.ws-agents-word.is-blue {
  color: var(--pg-tone-blue);
}
.ws-agents-word.is-amber,
.ws-agents-warn {
  color: var(--pg-tone-amber);
}
.ws-agents-end {
  display: flex;
  align-items: center;
  gap: 8px;
}
.ws-agents-ring {
  display: block;
  flex: none;
}
.ws-agents-ring circle {
  fill: none;
  stroke-width: 2.5;
}
.ws-agents-ring-track {
  stroke: color-mix(in srgb, var(--pg-fg-body) 13%, transparent);
}
.ws-agents-ring-arc {
  stroke: var(--pg-fg-2);
  stroke-linecap: round;
}
.ws-agents-ring.is-high .ws-agents-ring-arc {
  stroke: var(--pg-tone-amber);
}
/* The chevron only while the row is pointed at, holds the focus or is open. */
.ws-agents-chev {
  font-size: .72em;
  color: var(--pg-fg-3);
  visibility: hidden;
}
.ws-agents-row:hover .ws-agents-chev,
.ws-agents-row.is-open .ws-agents-chev,
.ws-agents-rowhead:focus-visible .ws-agents-chev {
  visibility: visible;
}
/* An opened row's facts, 10 under the second line in the text column:
   labels 76 wide in the third ink, values in the first, 7 between facts. */
.ws-agents-facts {
  display: grid;
  grid-template-columns: 76px minmax(0, 1fr);
  gap: 7px 0;
  margin: 10px 0 2px 38px;
  font-size: var(--pg-text-meta);
  line-height: 17px;
}
.ws-agents-facts[hidden] {
  display: none;
}
.ws-agents-facts > dt {
  font-weight: var(--pg-weight-regular);
  color: var(--pg-fg-3);
}
.ws-agents-facts > dd {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-agents-facts > .ws-agents-fact-doing {
  display: block;
  white-space: normal;
}
.ws-agents-facts > .ws-agents-fact-asked {
  display: block;
}
.ws-agents-cut {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-agents-facts .ws-act-link {
  text-decoration: underline;
  text-decoration-color: var(--pg-fg-3);
  text-underline-offset: 3px;
}
.ws-agents-facts .ws-act-bar {
  flex: 0 1 52px;
  min-width: 20px;
  height: 4px;
  margin-top: 0;
}
.ws-agents-facts .ws-act-bar > span {
  background: var(--pg-fg-2);
}
.ws-agents-facts .ws-act-bar.is-high > span {
  background: var(--pg-tone-amber);
}
.ws-agents-facts .ws-act-bar.is-high + span {
  color: var(--pg-tone-amber);
}
.ws-agents-more {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 7px 10px 7px 48px;
  border: 0;
  border-radius: 12px;
  background: none;
  font-size: var(--pg-text-meta);
  color: var(--pg-fg-2);
}
.ws-agents-more:hover {
  background: var(--pg-hover);
}
.ws-agents-more > .bi {
  font-size: .84em;
  color: var(--pg-fg-3);
}
/* On a phone a row is 52 high, for the finger. */
@media (max-width: 767.98px) {
  .ws-agents-rowhead {
    min-height: 36px;
  }
}
.ws-act-bar {
  height: 6px;
  margin-top: .2rem;
  overflow: hidden;
  border-radius: 3px;
  background: var(--pg-quiet);
}
.ws-act-bar > span {
  display: block;
  height: 100%;
  border-radius: 3px;
  background: var(--pg-tone-blue);
}
.ws-act-bar.is-high > span {
  background: var(--pg-tone-amber);
}
.ws-act-fact {
  display: flex;
  justify-content: space-between;
  gap: .75rem;
  padding: .3rem 0;
  font-size: var(--pg-text-2);
}
.ws-act-fact + .ws-act-fact {
  border-top: 1px solid var(--pg-field-line);
}
.ws-act-fact-key {
  color: var(--pg-fg-3);
}
.ws-act-fact-value {
  text-align: end;
  overflow-wrap: anywhere;
}
.ws-act-line {
  display: flex;
  align-items: baseline;
  gap: .5rem;
  padding: .25rem 0;
  font-size: var(--pg-text-2);
}
.ws-act-line > .bi {
  flex: none;
  color: var(--pg-fg-3);
}
.ws-act-line-text {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-act-line-side {
  flex: none;
}
.ws-act-link {
  color: inherit;
  text-decoration: none;
}
.ws-act-link:hover,
.ws-act-link:focus-visible {
  text-decoration: underline;
}
.ws-act-more,
.ws-act-all {
  margin-top: .25rem;
}
.ws-act-window {
  padding: .3rem 0;
  font-size: var(--pg-text-2);
}
.ws-act-window + .ws-act-window {
  border-top: 1px solid var(--pg-field-line);
}
.ws-act-tip,
.ws-act-loading {
  margin: var(--ws-space-3) 0 0;
}
/* Channel settings' "Agents in this channel": one compact row an agent in
   an inner card (look A), which opens its settings under it, one agent at
   a time; the row's own classes only place things. */
.ws-cha-intro {
  margin: 0 0 12px;
}
.ws-cha-list {
  overflow: hidden;
}
.ws-cha-item + .ws-cha-item {
  border-top: 1px solid var(--pg-border-color-translucent);
}
.ws-cha-head {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 12px 16px;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: start;
}
.ws-cha-head:hover {
  background: var(--pg-surface-hi);
}
.ws-cha-head:focus-visible {
  outline: 0;
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--pg-accent) 50%, transparent);
}
.ws-cha-face {
  position: relative;
  flex: none;
  overflow: hidden;
}
.ws-cha-picture {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.ws-cha-main {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  gap: 2px;
  min-width: 0;
}
.ws-cha-name {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 8px;
  min-width: 0;
}
.ws-cha-name > .pg-list-row-title {
  flex: 0 0 auto;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-cha-state {
  flex: none;
  max-width: 40%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-cha-chevron {
  flex: none;
  color: var(--pg-fg-3);
}
@media (prefers-reduced-motion: no-preference) {
  .ws-cha-chevron {
    transition: transform 0.15s ease;
  }
}
.ws-cha-item.is-open .ws-cha-chevron {
  transform: rotate(180deg);
}
.ws-cha-body {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 4px 16px 16px 62px;
}
.ws-cha-choices {
  margin: 0;
  padding: 0;
  border: 0;
}
.ws-cha-choice {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 6px 0;
  cursor: pointer;
}
.ws-cha-radio {
  flex: none;
  margin-top: 3px;
  accent-color: var(--pg-accent);
}
.ws-cha-choice-text,
.ws-cha-switch-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.ws-cha-choice-title {
  font-weight: 550;
}
.ws-cha-tier-note {
  margin-top: -10px;
}
.ws-cha-switch-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.ws-cha-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}
.ws-cha-remove {
  margin-inline-end: auto;
  color: var(--pg-tone-rose-text);
}
.ws-cha-add {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
}
/* The chosen agent is read whole: the list is as wide as its longest
   agent, and when it and the button do not fit side by side it takes a row
   of its own and the button goes under. */
.ws-cha-add > select {
  flex: 1 0 auto;
  width: auto;
  max-width: 100%;
}
.ws-cha-add > button {
  flex: none;
}
@media (max-width: 575.98px) {
  .ws-cha-head {
    padding: 12px;
  }
  .ws-cha-body {
    padding: 4px 12px 16px;
