  .ws-cha-head {
    flex-wrap: wrap;
  }
  .ws-cha-main {
    flex-basis: calc(100% - 92px);
  }
  .ws-cha-chevron {
    order: 2;
  }
  .ws-cha-state {
    order: 3;
    max-width: calc(100% - 52px);
    margin-inline-start: 52px;
  }
}
/* Site Settings' agents card (agents_settings.php): each agent a row by the
   recipe of "Agents in this channel" in one inner card, Edit always at the
   row's end; its drawer in sections over the agent card's boxes. The
   classes only place things. */
.ws-agset-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
}
.ws-agset-row + .ws-agset-row {
  border-top: 1px solid var(--pg-border-color-translucent);
}
.ws-agset-face {
  position: relative;
  flex: none;
  overflow: hidden;
}
.ws-agset-picture {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.ws-agset-main {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  gap: 2px;
  min-width: 0;
}
.ws-agset-name {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 8px;
  min-width: 0;
}
.ws-agset-name > .pg-list-row-title {
  flex: 0 0 auto;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-agset-state {
  flex: none;
  max-width: 40%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-agset-edit {
  flex: none;
}
.ws-agset-drawer-head {
  display: flex;
  align-items: center;
  gap: 12px;
}
.ws-agset-section {
  margin-top: 24px;
}
.ws-agent-form:first-child > .ws-agset-section:first-child {
  margin-top: 0;
}
.ws-agset-section > .pg-group-label {
  margin: 0 0 8px;
}
.ws-agset-section > .ws-agent-card-box:first-of-type {
  margin-top: 0;
}
.ws-agset-section > [data-ws-agent-door-state],
.ws-agset-section > .alert {
  margin-top: 12px;
}
.ws-agset-advanced > summary {
  cursor: pointer;
}
.ws-agset-check {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
}
.ws-agset-delete {
  margin-inline-start: auto;
}
@media (max-width: 575.98px) {
  /* On a phone the name and Edit share the first line; the summary, the
     warnings and the state's pill take the row's full width under them. */
  .ws-agset-row {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    column-gap: 12px;
    row-gap: 6px;
    padding: 12px;
  }
  .ws-agset-main {
    display: contents;
  }
  .ws-agset-main > * {
    grid-column: 1 / -1;
  }
  .ws-agset-face {
    grid-column: 1;
    grid-row: 1;
    align-self: start;
  }
  .ws-agset-main > .ws-agset-name {
    grid-column: 2;
    grid-row: 1;
  }
  .ws-agset-edit {
    grid-column: 3;
    grid-row: 1;
    align-self: start;
  }
  .ws-agset-state {
    grid-column: 1 / -1;
    justify-self: start;
    max-width: 100%;
  }
}
/* The agent card (workspace.js agentCardShow()): a floating .pg-card on
   the float surface, placed by script; boxes of rows, one bar a usage
   window, amber from WS_AGENT_USAGE_HIGH. */
.ws-agent-card-anchor {
