  gap: .15rem;
  padding: 0 .25rem .1rem 0;
  border-radius: var(--ws-radius-xs);
}
.ws-group-toggle {
  display: flex;
  align-items: center;
  gap: .35rem;
  flex: 1 1 auto;
  min-width: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  text-align: left;
  padding: .2rem .25rem;
  border-radius: var(--ws-radius-xs);
}
.ws-group-toggle:hover {
  background: var(--pg-bg-2);
}
.ws-group-chevron {
  font-size: 11px;
  opacity: .7;
}
.ws-group-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.3rem;
  height: 1.3rem;
  border-radius: var(--ws-radius-xs);
  background: color-mix(in srgb, var(--ws-group, var(--pg-fg-2)) 16%, transparent);
  color: color-mix(in srgb, var(--ws-group, var(--pg-fg-2)) 75%, var(--pg-fg-emphasis));
  font-size: .75rem;
}
html[data-bs-theme="dark"] .ws-group-icon {
  background: color-mix(in srgb, var(--ws-group, var(--pg-fg-2)) 26%, transparent);
}
.ws-group-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: color-mix(in srgb, var(--ws-group, var(--pg-fg-2)) 60%, var(--pg-fg-emphasis));
}
.ws-group-access {
  display: inline-flex;
  align-items: center;
  gap: .15rem;
  font-size: .68rem;
  font-weight: 600;
  opacity: .75;
}
.ws-group-more {
  opacity: 0;
  padding: 0 .3rem;
}
.ws-group-title:hover .ws-group-more,
.ws-group-more:focus-visible {
  opacity: .85;
}
/* New group closes the Channels section of the list: a quiet row in the
   channels' column, for whoever manages the groups. */
.ws-group-new {
  display: flex;
  align-items: center;
  gap: .4rem;
  width: 100%;
  margin-top: .35rem;
  padding: var(--ws-row-y, .3rem) var(--ws-space-2, .5rem);
  border: 0;
  border-radius: var(--ws-radius-sm);
  background: transparent;
  color: var(--pg-fg-2);
  font-size: .82rem;
  text-align: start;
}
.ws-group-new:is(:hover, :focus-visible) {
  background: var(--pg-bg-2);
  color: var(--pg-fg-body);
}
.ws-group-new > .bi {
  flex: 0 0 auto;
  width: 1rem;
  text-align: center;
}
.ws-group-empty {
  padding-top: .15rem;
  padding-bottom: .25rem;
  border-radius: var(--ws-radius-xs);
}
.ws-drop-into {
  outline: 2px dashed var(--ws-group, var(--ws-accent));
  outline-offset: -2px;
}
.ws-drop-before {
  box-shadow: inset 0 2px 0 var(--ws-accent);
}
.ws-drop-after {
  box-shadow: inset 0 -2px 0 var(--ws-accent);
}
.ws-group-title.ws-dragging {
  opacity: .45;
}
/* The palette: twenty solid, matte colours and none. */
.ws-swatches {
  display: flex;
  flex-wrap: wrap;
  gap: .35rem;
}
.ws-swatch {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
  padding: 0;
  border: 2px solid transparent;
  border-radius: var(--ws-radius-sm);
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .08);
}
.ws-swatch.active {
  border-color: var(--pg-fg-emphasis);
  box-shadow: inset 0 0 0 2px var(--pg-bg-body);
}
.ws-swatch-none {
  background: var(--pg-bg-1);
  color: var(--pg-fg-2);
}
/* A channel's own icon (includes/workspace/channel_icons.php): the picker
   beside the colours, a search over a grid of radio buttons; "none" is
   dashed and shows the icon the channel's kind gives. */
.ws-icon-picker {
  display: flex;
  flex-direction: column;
  gap: var(--ws-space-2);
}
.ws-icon-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(2.1rem, 1fr));
  gap: .35rem;
  max-height: 11.5rem;
  overflow-y: auto;
  padding: .15rem;
}
.ws-icon-choice {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 2.1rem;
  padding: 0;
  border: 2px solid transparent;
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-1);
  color: var(--pg-fg-body);
  font-size: 1.05rem;
}
.ws-icon-choice:hover {
  background: rgba(var(--ws-accent-rgb), .1);
}
.ws-icon-choice.active {
  border-color: var(--ws-accent);
  background: rgba(var(--ws-accent-rgb), .14);
  color: var(--ws-accent);
}
.ws-icon-choice-none {
  border-style: dashed;
  border-color: var(--pg-border-color);
  color: var(--pg-fg-2);
}
.ws-icon-choice-none.active {
  border-style: solid;
  border-color: var(--ws-accent);
}
.ws-icon-empty {
  font-size: .8rem;
  color: var(--pg-fg-2);
}
/* The mark of a private, guest or customer channel in the corner of an icon
   chosen for it: a lock, a door, a person (ws_icon_badged_html()). */
.ws-icon-badged {
  position: relative;
  display: inline-block;
  line-height: 1;
}
.ws-icon-badge {
  position: absolute;
  right: -.3em;
  bottom: -.3em;
  padding: .1em;
  border-radius: 50%;
  background: var(--pg-bg-body);
  color: var(--pg-fg-2);
  font-size: .6em;
  line-height: 1;
}
/* Scheduled actions: a follow-up of the card that runs on a failure. */
.ws-sa-follow-line.ws-sa-on-failed b {
  color: var(--pg-danger-fg-emphasis);
}
.ws-sa-follow-line.ws-sa-on-skipped b {
  color: var(--pg-fg-2);
}
/* The catch-up line and the pinned message over the conversation
   (drawCenter()): one above the other, on a phone one thin row. */
.ws-strip {
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
}
.ws-strip:not(:has(.ws-catchup, .ws-pin-bar, .ws-open-bar)) {
  display: none;
}
/* The pinned message: one line, a click opens it in the conversation. */
.ws-pin-bar {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin: .5rem 1rem 0;
  padding: .3rem .4rem .3rem .65rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-left: 3px solid var(--ws-accent);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-1);
  font-size: .85rem;
}
.ws-pin-icon {
  flex: 0 0 auto;
  color: var(--ws-accent);
}
.ws-pin-text {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  gap: .45rem;
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
}
.ws-pin-words {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* The open items line under the pin (drawOpenItems()): the pin bar's look,
   the first item with Go and, for more than one, the count that lists them. */
.ws-open-bar {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin: .5rem 1rem 0;
  padding: .3rem .4rem .3rem .65rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-left: 3px solid var(--ws-accent);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-1);
  font-size: var(--pg-text-2);
}
.ws-open-mine {
  border-left-color: var(--pg-warning);
}
.ws-open-icon {
  flex: 0 0 auto;
  color: var(--ws-accent);
}
.ws-open-text {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  gap: .45rem;
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
}
.ws-open-words {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-open-yours {
  flex: 0 0 auto;
}
.ws-open-go,
.ws-open-count {
  flex: 0 0 auto;
  gap: .3rem;
  font-size: var(--pg-text-meta);
  white-space: nowrap;
}
.ws-open-count-mine .ws-open-number {
  font-weight: var(--pg-weight-title);
}
.ws-open-single .ws-open-count {
  display: none;
}
/* The list the count opens: the panel menu, opaque, as wide as its
   longest row up to 30rem; a row too long ends with an ellipsis. */
.ws-ctx.contextmenu.popover.ws-open-menu {
  max-width: min(30rem, calc(100vw - 16px));
}
.ws-ctx.ws-open-menu .ws-ctx-item {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-msg-pinned {
  color: var(--ws-accent);
  font-size: .75rem;
}
/* Messages chosen together. */
.ws-msg-choosable {
  cursor: pointer;
  border-radius: var(--ws-radius-sm);
  padding-left: 2rem;
}
/* The tick box sits in the padding: .ws-msg is a grid, a pseudo element in
   it would take a cell of its own. */
.ws-msg-choosable::before {
  content: "";
  position: absolute;
  left: .5rem;
  top: .55rem;
  width: 1rem;
  height: 1rem;
  border: 2px solid var(--pg-border-color);
  border-radius: var(--ws-radius-xs);
}
.ws-msg-selected {
  background: rgba(var(--ws-accent-rgb), .1);
}
.ws-msg-selected::before {
  border-color: var(--ws-accent);
  background: var(--ws-accent);
  box-shadow: inset 0 0 0 2px var(--pg-bg-body);
}
.ws-select-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .4rem;
  padding: .5rem .75rem;
  border-top: 1px solid var(--pg-border-color);
  background: var(--pg-bg-body);
}
.ws-select-count {
  font-size: .85rem;
  font-weight: 600;
  margin-right: .25rem;
}
.ws-selecting > :not(.ws-select-bar):not(.ws-jump-end) {
  display: none !important;
}
.ws-pane-selecting .ws-msg-tools {
  display: none !important;
}
.ws-msg-quote-more {
  margin-top: -.15rem;
}
/* A forward: the copies it carries. */
.ws-fwd-list {
  display: flex;
  flex-direction: column;
  gap: .4rem;
  margin-top: .3rem;
}
.ws-fwd {
  padding: .45rem .6rem;
  border: 1px solid var(--pg-border-color);
  border-left: 3px solid var(--pg-fg-2);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-1);
}
.ws-fwd-head {
  display: flex;
  align-items: center;
  font-size: .75rem;
  color: var(--pg-fg-2);
  margin-bottom: .2rem;
}
.ws-fwd-who {
  display: flex;
  align-items: center;
  gap: .35rem;
  font-size: .82rem;
  margin-bottom: .15rem;
}
.ws-fwd-body {
  font-size: .9rem;
}
.ws-fwd-preview {
  max-height: 12rem;
  overflow: auto;
  padding: .4rem .6rem;
  margin-bottom: .75rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  font-size: .82rem;
}
.ws-fwd-preview-line {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* The customer of a channel and the records tied to it. */
.ws-customer {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .25rem;
  vertical-align: middle;
}
.ws-customer-tie .ws-chip {
  opacity: .75;
  font-size: .85em;
}
.ws-customer-tie .ws-chip:hover {
  opacity: 1;
}
.ws-customer-links {
  display: flex;
  flex-direction: column;
  gap: .3rem;
  margin-bottom: .6rem;
}
.ws-customer-links:empty {
  display: none;
}
.ws-customer-links-title {
  font-size: .72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .03em;
  color: var(--pg-fg-2);
}
.ws-customer-link {
  display: flex;
  align-items: center;
  gap: .5rem;
}
/* A file of this site on a note line of its own, drawn as the file
   (includes/workspace/note_media.php): a picture up to 20rem high, players,
   or a card with the file's icon, name and size. */
.ws-media {
  display: block;
  margin: .4rem 0;
  max-width: 100%;
}
.ws-media-image a {
  display: inline-block;
  max-width: 100%;
  cursor: zoom-in;
}
.ws-media-image img {
  display: block;
  max-width: 100%;
  max-height: 20rem;
  height: auto;
  border-radius: var(--ws-radius-sm);
}
.ws-media-video video {
  display: block;
  width: 100%;
  max-height: 20rem;
  border-radius: var(--ws-radius-sm);
  background: #000;
}
.ws-media-audio audio {
  display: block;
  width: 100%;
  max-width: 28rem;
}
.ws-media-file {
  display: inline-flex;
  align-items: center;
  gap: .6rem;
  max-width: 100%;
  padding: .5rem .75rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  color: inherit;
  text-decoration: none;
}
.ws-media-file:hover {
  background: var(--pg-bg-1);
}
.ws-media-file .bi {
  font-size: 1.4rem;
  color: var(--ws-accent);
}
.ws-media-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 600;
}
.ws-media-size {
  flex-shrink: 0;
  font-size: .8rem;
  color: var(--pg-fg-2);
}
/* A block with a title, and the list of titled blocks to pull in. */
.ws-block-titled {
  margin: .25rem 0;
}
.ws-block-title {
  display: flex;
  align-items: center;
  gap: .35rem;
  font-size: .8rem;
  font-weight: 700;
  color: var(--pg-fg-2);
  margin-bottom: .2rem;
}
.ws-block-title .bi {
  color: var(--ws-accent);
}
.ws-pull-list {
  display: flex;
  flex-direction: column;
  gap: .35rem;
}
.ws-pull-item {
  display: flex;
  align-items: flex-start;
  gap: .6rem;
  width: 100%;
  padding: .5rem .6rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  background: transparent;
  color: inherit;
  text-align: left;
}
.ws-pull-item:hover {
  background: var(--pg-bg-1);
}
.ws-pull-icon {
  color: var(--ws-accent);
  margin-top: .15rem;
}
.ws-pull-words {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
/* Versions of a conversation: one list in a settings card, the current
   conversation first. */
.ws-era-row > .btn,
.ws-era-row > .pg-button {
  flex-shrink: 0;
}
/* Channel settings: the segmented control at the top places its tabs
   across the drawer. */
.ws-settings-tabs {
  display: flex;
  width: 100%;
  margin-bottom: var(--ws-space-4);
}
.ws-settings-tabs .pg-seg-item {
  flex: 1 1 0;
  min-width: 0;
}
/* On a phone the chosen tab takes the room its name needs, the others
   keep their icon; a name too long for even that ends in an ellipsis. */
@media (max-width: 575.98px) {
  .ws-settings-tabs .pg-seg-item.is-active {
    flex: 0 1 auto;
  }
  .ws-settings-tabs .pg-seg-item.is-active .pg-seg-label {
    display: block;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }
}
/* The channel's name with its icon button at the left and its colour
   button at the right; each opens its list in a floating box. */
.ws-look-row {
  display: flex;
  align-items: center;
  gap: var(--ws-space-2);
}
.ws-look-row > .pg-input {
  flex: 1 1 auto;
  min-width: 0;
}
/* As tall as the name's field, a square tile on the field's surface. */
.ws-look-row > .ws-look-button {
  flex-shrink: 0;
  align-self: stretch;
  width: 2.6rem;
  height: auto;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-body);
  font-size: 1.1rem;
}
.ws-look-dot {
  display: block;
  width: 1.1rem;
  height: 1.1rem;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
}
.ws-look-none {
  color: var(--pg-fg-2);
}
.ws-ctx.contextmenu.popover.ws-look-picker {
  width: 19.5rem;
  max-width: calc(100vw - 16px);
}
.ws-look-pop {
  padding: var(--ws-space-2);
  border-radius: inherit;
  background: var(--pg-surface-float);
}
.ws-count {
  flex-shrink: 0;
  min-width: 1.35rem;
  padding: 0 .35rem;
  border-radius: 999px;
  font-size: .72rem;
  line-height: 1.35rem;
  text-align: center;
  background: var(--pg-bg-2);
  color: var(--pg-fg-body);
}
.ws-count.ws-count-mention {
  background: var(--pg-danger);
  color: #fff;
}
.ws-center {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  /* Anchors .ws-drop-overlay. */
  position: relative;
}
.ws-head {
  display: flex;
  align-items: center;
  gap: var(--ws-space-3, .75rem);
  padding: var(--ws-head-y, .6rem) var(--ws-space-4, 1rem);
  border-bottom: 1px solid var(--pg-border-color);
  min-height: var(--ws-head-h, 3.4rem);
}
/* A header's title: its name, and under it a line of context (the
   overview's date, a discussion's channel). */
.ws-head-title {
  flex: 1 1 auto;
  min-width: 0;
}
/* The channel's header (drawCenter()), one line: the sign and the name,
   then how the work stands, the department and the customer, which give
   way before the name does. */
.ws-head-title.ws-head-row {
  display: flex;
  align-items: center;
  gap: .5rem;
}
.ws-head-row > h2 {
  display: flex;
  flex: 0 1 auto;
  align-items: center;
  min-width: 0;
}
.ws-head-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-head-tags {
  display: flex;
  flex: 0 100 auto;
  align-items: center;
  gap: .375rem;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
}
.ws-head-tags > * {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 16rem;
}
.ws-head-tags .ws-customer {
  flex-wrap: nowrap;
  overflow: hidden;
}
.ws-head-tags .ws-status-pill {
  margin-right: 0;
  overflow: hidden;
  white-space: nowrap;
}
.ws-status-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-head-tags .ws-head-tag.badge {
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-head-faces {
  align-items: center;
  gap: .25rem;
}
/* The channel's info (showMembers()): what it is for, its customer and
   department, then its people. */
.ws-info-about {
  margin-bottom: .75rem;
  padding-bottom: .75rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-info-label {
  margin: .25rem 0;
  color: var(--pg-fg-2);
  font-size: .72rem;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.ws-info-purpose {
  margin: 0 0 .5rem;
  white-space: pre-wrap;
}
/* A narrow channel header (a phone, or the discussion panel open beside
   it): the people, search, info and new task move into the menu, which
   then lists them first, and of the tags only the status icon stays. The
   menu is drawn inside the header, so the query reaches it too. */
.ws-head-channel {
  container-type: inline-size;
}
.ws-head-channel .ws-head-narrow {
  display: none;
}
@container (max-width: 40rem) {
  .ws-head-channel .ws-head-wide {
    display: none;
  }
  .ws-head-channel .ws-head-narrow {
    display: block;
  }
  .ws-head-channel .ws-head-tags > :not(.ws-status-pill) {
    display: none;
  }
  .ws-head-channel .ws-status-pill .ws-status-text {
    display: none;
  }
}
/* The way to the channel list where the menu's Workspace list is out of
   sight: below lg, where the menu is a drawer, and on the mini rail (the
   workspace never hides the menu: main-menu-navigator-screens); the open
   menu shows the list itself. A labelled back
   arrow, so it is not taken for a second main menu button. */
.ws-channels-toggle {
  display: inline-flex;
  align-items: center;
  gap: .1rem;
  flex-shrink: 0;
  /* A touch target as tall as the header's other buttons (it measured
     23 px on a phone). */
  min-height: 2rem;
  padding: .25rem .6rem .25rem .35rem;
  border: 0;
  border-radius: 999px;
  background: rgba(var(--ws-accent-rgb), .12);
  color: var(--ws-accent);
  font-size: .8rem;
  font-weight: 600;
  line-height: 1.2;
}
.ws-channels-toggle:hover,
.ws-channels-toggle:focus-visible {
  background: rgba(var(--ws-accent-rgb), .2);
}
@media (min-width: 1024px) {
  .software-container.expanded:not(.menu-hidden) .ws-channels-toggle {
    display: none;
  }
}
@media (max-width: 359.98px) {
  .ws-channels-toggle-label {
    display: none;
  }
}
.ws-head-title h2 {
  font-size: 1.1rem;
  letter-spacing: -.01em;
  font-weight: 700;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* The channel's sign: its icon on a soft tile in its colour, and a thin
   stripe of the colour along the top of the header. */
.ws-head-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
  margin-right: .45rem;
  vertical-align: middle;
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-2);
  color: var(--pg-fg-2);
  font-size: .95rem;
  font-weight: 400;
}
.ws-channel-card[data-ws-colored] .ws-head-icon {
  background: color-mix(in srgb, var(--ws-ch) 16%, transparent);
  color: var(--ws-ch);
}
html[data-bs-theme="dark"] .ws-channel-card[data-ws-colored] .ws-head-icon {
  background: color-mix(in srgb, var(--ws-ch) 26%, transparent);
}
.ws-head-title .ws-topic {
  font-size: .8rem;
  color: var(--pg-fg-2);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-head-actions {
  display: flex;
  gap: .25rem;
  flex-shrink: 0;
  align-items: center;
}
/* The channel's More menu holds about twenty entries on a phone (the
   header's own buttons move into it) and .ws-app clips what runs past the
   screen, so the menu keeps to the screen's height and scrolls itself. */
.ws-head-menu {
  max-height: calc(100vh - 9rem);
  overflow-y: auto;
  overscroll-behavior: contain;
}
@supports (height: 100dvh) {
  .ws-head-menu { max-height: calc(100dvh - 9rem); }
}
/* The share notice above the tabs: the sentence starts from no width, so it
   stays beside its icon instead of wrapping onto a row of its own (a phone
   showed the icon alone on the first line). */
.ws-share-bar-text {
  flex: 1 1 0;
  min-width: 0;
}
/* While a link is open the row stands out: an edge in the warning colour
   and its mark in a filled circle. With no link open there is no row; the
   head carries a small button with an exclamation mark instead. */
.ws-share-bar-open {
  box-shadow: inset 4px 0 0 var(--bs-warning-base);
}
[dir="rtl"] .ws-share-bar-open {
  box-shadow: inset -4px 0 0 var(--bs-warning-base);
}
.ws-share-bar-open .ws-share-bar-icon {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  background: var(--bs-warning-base);
  color: var(--bs-warning-contrast);
}
.pg-icon-button.ws-head-share {
  color: var(--bs-warning-fg-emphasis);
}
.ws-avatars {
  display: inline-flex;
}
.ws-avatars .avatar {
  --bs-avatar-size: var(--ws-avatar-sm);
}
.ws-tabs {
  display: flex;
  gap: .25rem;
  padding: .35rem 1rem 0;
  border-bottom: 1px solid var(--pg-border-color);
  overflow-x: auto;
  scrollbar-width: none;
}
.ws-tabs button {
  border: 0;
  background: transparent;
  padding: .4rem .7rem;
  font-size: .85rem;
  color: var(--pg-fg-2);
  border-bottom: 2px solid transparent;
  white-space: nowrap;
}
.ws-tabs button.active {
  color: var(--ws-accent);
  border-bottom-color: var(--ws-accent);
  font-weight: 600;
}
.ws-tabs button:hover {
  color: var(--pg-fg-emphasis);
}
/* What a tab holds, before it is opened: a count of the decisions and the
   open tasks, a dot when the summary is written. */
.ws-tab-mark {
  display: inline-block;
  min-width: 1.15rem;
  margin-left: .35rem;
  padding: 0 .35rem;
  border-radius: var(--ws-radius);
  background: var(--ws-soft);
  color: var(--ws-accent);
  font-size: .68rem;
  font-weight: 700;
  line-height: 1.15rem;
  text-align: center;
  vertical-align: .05em;
}
.ws-tabs button.active .ws-tab-mark {
  background: var(--ws-accent);
  color: #fff;
}
.ws-tab-mark.ws-tab-dot {
  min-width: 0;
  width: .45rem;
  height: .45rem;
  padding: 0;
  margin-left: .3rem;
  line-height: 0;
  vertical-align: .15em;
  background: var(--ws-accent);
}
.ws-pane {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: var(--ws-space-3, .75rem) var(--ws-space-4, 1rem);
}
/* The channel's shell (drawCenter()): the header, the bars under it (audit
   or join, guest, share, era) and the tabs are one card, with no rule
   between its rows. A channel with a colour (--ws-ch, set on the card so
   the tabs see it too) tints the border and lays a soft wash from the side
   its sign stands on; one without keeps a plain card. The strengths are
   custom properties so the dark theme and right to left change only them. */
.ws-channel-card {
  flex-shrink: 0;
  margin: var(--ws-space-3, .75rem) var(--ws-space-3, .75rem) 0;
  border: 1px solid var(--pg-border-color);
  border-radius: .875rem;
  background: var(--pg-card-bg);
}
.ws-channel-card[data-ws-colored] {
  --ws-wash-from: to right;
  --ws-wash: 15%;
  --ws-wash-mid: 5%;
  --ws-edge: 26%;
  border-color: color-mix(in srgb, var(--ws-ch) var(--ws-edge), var(--pg-border-color));
  background:
    linear-gradient(var(--ws-wash-from), color-mix(in srgb, var(--ws-ch) var(--ws-wash), transparent) 0%, color-mix(in srgb, var(--ws-ch) var(--ws-wash-mid), transparent) 38%, transparent 70%),
    var(--pg-card-bg);
}
[dir="rtl"] .ws-channel-card[data-ws-colored] {
  --ws-wash-from: to left;
}
html[data-bs-theme="dark"] .ws-channel-card[data-ws-colored] {
  --ws-wash: 22%;
  --ws-wash-mid: 8%;
  --ws-edge: 40%;
}
.ws-channel-card > .ws-head {
  border-bottom: 0;
}
/* A bar is a tinted row of the card: no border of its own. */
.ws-channel-card > .alert {
  border: 0;
}
.ws-channel-card > .ws-tabs {
  gap: .3rem;
  padding: .45rem 1rem .6rem;
  border-bottom: 0;
}
.ws-channel-card > .ws-head + .ws-tabs {
  padding-top: 0;
}
/* Tabs are pills; the open one is filled, in the channel's colour when it
   has one. */
.ws-channel-card .ws-tabs button {
  padding: .3rem .75rem;
  border: 1px solid transparent;
  border-radius: 999px;
  font-size: .8125rem;
  line-height: 1.4;
}
.ws-channel-card .ws-tabs button:hover {
  background: var(--pg-bg-2);
}
.ws-channel-card .ws-tabs button.active {
  --ws-tab-fill: 14%;
  border-color: rgba(var(--ws-accent-rgb), .35);
  background: rgba(var(--ws-accent-rgb), .14);
  color: var(--pg-fg-emphasis);
}
.ws-channel-card[data-ws-colored] .ws-tabs button.active {
  border-color: color-mix(in srgb, var(--ws-ch) 45%, transparent);
  background: color-mix(in srgb, var(--ws-ch) var(--ws-tab-fill), transparent);
}
html[data-bs-theme="dark"] .ws-channel-card .ws-tabs button.active {
  --ws-tab-fill: 26%;
  border-color: rgba(var(--ws-accent-rgb), .5);
  background: rgba(var(--ws-accent-rgb), .26);
}
html[data-bs-theme="dark"] .ws-channel-card[data-ws-colored] .ws-tabs button.active {
  border-color: color-mix(in srgb, var(--ws-ch) 60%, transparent);
  background: color-mix(in srgb, var(--ws-ch) var(--ws-tab-fill), transparent);
}
/* The strip scrolls sideways and would clip a ring drawn outside a pill. */
.ws-channel-card .ws-tabs button:focus-visible {
  outline: 2px solid var(--ws-accent);
  outline-offset: -2px;
}
/* The conversation timeline (workspace_conversation_timeline.js) at the end
   of the tabs row: the card is a grid whose rows span both columns but the
   tabs' one, so the tabs keep their width and the timeline takes what is
   left. Its well is at most 420px wide and ends 16px from the card's edge;
   where the column leaves it under 220px the script marks the screen
   .ws-ctl-narrow and the well moves to the foot of Channel info. The holder
   keeps its padding either way, so its width (what the script measures)
   does not swing with the switch. */
.ws-channel-card {
  display: grid;
  grid-template-columns: minmax(0, auto) minmax(0, 1fr);
}
.ws-channel-card > * {
  grid-column: 1 / -1;
}
.ws-channel-card > .ws-tabs {
  grid-column: 1;
}
.ws-channel-card > .ws-ctl {
  display: flex;
  grid-column: 2;
  align-self: center;
  justify-content: flex-end;
  padding: .45rem 1rem .6rem .75rem;
}
.ws-channel-card > .ws-head + .ws-tabs + .ws-ctl {
  padding-top: 0;
}
.ws-app.ws-ctl-narrow .ws-channel-card > .ws-ctl > *,
.ws-app:not(.ws-ctl-narrow) .ws-info-panel .ws-ctl-section {
  display: none;
}
.ws-ctl {
  --ws-ctl-line: color-mix(in srgb, var(--pg-quiet) 50%, var(--pg-field-line));
  min-width: 0;
}
/* One writer, one colour, by the order they first wrote; grey for the
   system's lines. The tone is the recipes' too (a legend pill, the card's
   initials and kind). */
.ws-ctl [data-tone],
.ws-ctl-card {
  --ws-ctl-c: var(--pg-tone-gray);
  --pg-tone: var(--ws-ctl-c);
}
.ws-ctl [data-tone="0"], .ws-ctl-card[data-tone="0"] { --ws-ctl-c: var(--pg-tone-blue); }
.ws-ctl [data-tone="1"], .ws-ctl-card[data-tone="1"] { --ws-ctl-c: var(--pg-tone-teal); }
.ws-ctl [data-tone="2"], .ws-ctl-card[data-tone="2"] { --ws-ctl-c: var(--pg-tone-violet); }
.ws-ctl [data-tone="3"], .ws-ctl-card[data-tone="3"] { --ws-ctl-c: var(--pg-tone-amber); }
.ws-ctl [data-tone="4"], .ws-ctl-card[data-tone="4"] { --ws-ctl-c: var(--pg-tone-rose); }
.ws-ctl [data-tone="5"], .ws-ctl-card[data-tone="5"] { --ws-ctl-c: color-mix(in srgb, var(--pg-tone-blue) 50%, var(--pg-tone-teal)); }
.ws-ctl [data-tone="6"], .ws-ctl-card[data-tone="6"] { --ws-ctl-c: color-mix(in srgb, var(--pg-tone-violet) 50%, var(--pg-tone-rose)); }
.ws-ctl [data-tone="7"], .ws-ctl-card[data-tone="7"] { --ws-ctl-c: color-mix(in srgb, var(--pg-tone-amber) 55%, var(--pg-tone-teal)); }
/* The well: 30px high, the card's tint with a hairline, no shadow. The
   port cuts the strip and shows no scrollbar; a cut end fades over 22px. */
.ws-ctl-bar {
  display: flex;
  flex: 0 1 420px;
  align-items: stretch;
  min-width: 220px;
  height: 30px;
  border-radius: 9px;
  background: var(--pg-surface-inset);
  box-shadow: inset 0 0 0 1px var(--ws-ctl-line);
}
.ws-ctl-port {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  border-radius: 9px 0 0 9px;
  cursor: pointer;
  touch-action: pan-y;
  -webkit-user-select: none;
  user-select: none;
}
.ws-ctl-port.is-cut-l {
  -webkit-mask-image: linear-gradient(90deg, transparent 0, var(--pg-surface-1) 22px);
  mask-image: linear-gradient(90deg, transparent 0, var(--pg-surface-1) 22px);
}
.ws-ctl-port.is-cut-r {
  -webkit-mask-image: linear-gradient(270deg, transparent 0, var(--pg-surface-1) 22px);
  mask-image: linear-gradient(270deg, transparent 0, var(--pg-surface-1) 22px);
}
.ws-ctl-port.is-cut-l.is-cut-r {
  -webkit-mask-image: linear-gradient(90deg, transparent 0, var(--pg-surface-1) 22px, var(--pg-surface-1) calc(100% - 22px), transparent 100%);
  mask-image: linear-gradient(90deg, transparent 0, var(--pg-surface-1) 22px, var(--pg-surface-1) calc(100% - 22px), transparent 100%);
}
.ws-ctl-track {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  min-width: 100%;
}
.ws-ctl-track:focus-visible {
  outline: 0;
}
.ws-ctl-bar:has(.ws-ctl-track:focus-visible) {
  box-shadow: inset 0 0 0 1px var(--ws-ctl-line), 0 0 0 2px var(--pg-accent);
}
/* Zoom out and in after a hairline, inside the well; the one at its end is
   dimmed. */
.ws-ctl-zoom {
  display: flex;
  flex: none;
  align-items: center;
  margin-left: 2px;
  padding: 0 3px;
  border-left: 1px solid var(--ws-ctl-line);
}
.ws-ctl-zoom .pg-icon-button {
  width: 24px;
  height: 24px;
  border-radius: 7px;
  font-size: var(--pg-text-meta);
}
.ws-ctl-zoom .pg-icon-button:disabled {
  opacity: .35;
  cursor: default;
}
/* Before the first read, with no message and when it failed: an empty
   well, shimmering while it reads. */
.ws-ctl[data-ws-ctl-state] .ws-ctl-port {
  cursor: default;
}
.ws-ctl[data-ws-ctl-state="reading"] .ws-ctl-track::before {
  content: "";
  position: absolute;
  top: 19px;
  right: 8px;
  left: 6px;
  height: 6px;
  border-radius: 3px;
  background: linear-gradient(90deg, var(--pg-quiet) 0%, color-mix(in srgb, var(--pg-fg-2) 18%, transparent) 50%, var(--pg-quiet) 100%);
  background-size: 200% 100%;
}
/* A day: a hairline before it, its short date over its column; today's one
   step stronger. */
.ws-ctl-day {
  position: absolute;
  top: 5px;
  bottom: 5px;
  width: 1px;
  background: var(--ws-ctl-line);
  pointer-events: none;
}
.ws-ctl-date {
  position: absolute;
  top: 4px;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-count);
  font-weight: var(--pg-weight-medium);
  line-height: 11px;
  letter-spacing: .01em;
  white-space: nowrap;
  pointer-events: none;
}
.ws-ctl-date.is-now {
  color: var(--pg-fg-2);
}
/* A run: one 6px bar of its turns, 1px apart, square inside and round at
   the run's two ends; flat colour over the surface. */
.ws-ctl-turn {
  position: absolute;
  top: 19px;
  height: 6px;
  background: color-mix(in srgb, var(--ws-ctl-c) 82%, var(--pg-surface-1));
}
.ws-ctl-turn.is-first {
  border-radius: 3px 0 0 3px;
}
.ws-ctl-turn.is-last {
  border-radius: 0 3px 3px 0;
}
.ws-ctl-turn.is-first.is-last {
  border-radius: 3px;
}
/* A decision: an amber diamond on the bar, the strip's only mark. */
.ws-ctl-turn[data-mark="decision"]::after {
  content: "";
  position: absolute;
  top: -1px;
  left: 50%;
  width: 6px;
  height: 6px;
  margin-left: -3px;
  border-radius: 1.5px;
  background: var(--pg-tone-amber);
  box-shadow: 0 0 0 2px var(--pg-surface-1);
  transform: rotate(45deg) scale(1.05);
}
/* Pointing: the turn grows to 10px in its full colour, the rest dims. */
.ws-ctl-track.is-pointing .ws-ctl-turn {
  opacity: .38;
}
.ws-ctl-track.is-pointing .ws-ctl-turn.is-on {
  z-index: 2;
  top: 17px;
  height: 10px;
  border-radius: 3px;
  opacity: 1;
  background: var(--ws-ctl-c);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--ws-ctl-c) 22%, transparent);
}
/* The message shown in a turn of several: a playhead. */
.ws-ctl-cursor {
  position: absolute;
  z-index: 3;
  top: 14px;
  bottom: 1px;
  width: 2px;
  margin-left: -1px;
  border-radius: 1px;
  background: var(--pg-fg-emphasis);
  box-shadow: 0 0 0 1.5px var(--pg-surface-1);
  pointer-events: none;
}
/* The part of the conversation on the screen: an accent line under the
   bars, 2px above the well's foot. */
.ws-ctl-here {
  position: absolute;
  bottom: 2px;
  height: 2px;
  border-radius: 1px;
  background: var(--pg-accent);
  opacity: .9;
  pointer-events: none;
}
@media (prefers-reduced-motion: no-preference) {
  .ws-ctl-turn {
    transition: opacity .15s ease, top .15s ease, height .15s ease, box-shadow .15s ease;
  }
  .ws-ctl-here {
    transition: left .2s ease, width .2s ease;
  }
  .ws-ctl[data-ws-ctl-state="reading"] .ws-ctl-track::before {
    animation: ws-ctl-shimmer 1.4s linear infinite;
  }
  .ws-ctl-card:not([hidden]) {
    animation: ws-ctl-card-in .14s ease-out;
  }
  /* A message just written comes onto the strip live. */
  .ws-ctl-turn.is-new {
    animation: ws-ctl-turn-in .6s cubic-bezier(.2, .9, .3, 1.3);
  }
}
@keyframes ws-ctl-turn-in {
  0% { opacity: 0; transform: scaleX(.2); }
  60% { opacity: 1; transform: scaleX(1.1); }
  100% { transform: none; }
}
@keyframes ws-ctl-shimmer {
  from { background-position: 100% 0; }
  to { background-position: -100% 0; }
}
@keyframes ws-ctl-card-in {
  from { opacity: 0; transform: translateY(var(--ws-ctl-from, -4px)); }
  to { opacity: 1; transform: none; }
}
/* In Channel info, under the heading: the well full width and 34px high,
   then the writers as pills in their colours. */
.ws-ctl-section > .ws-ctl {
  margin-top: .35rem;
}
.ws-ctl-section .ws-ctl-bar {
  width: 100%;
  min-width: 0;
  height: 34px;
}
.ws-ctl-section .ws-ctl-date {
  top: 5px;
}
.ws-ctl-section .ws-ctl-turn,
.ws-ctl-section .ws-ctl[data-ws-ctl-state="reading"] .ws-ctl-track::before {
  top: 21px;
}
.ws-ctl-section .ws-ctl-track.is-pointing .ws-ctl-turn.is-on {
  top: 19px;
}
.ws-ctl-section .ws-ctl-cursor {
  top: 16px;
}
.ws-ctl-section .ws-ctl-zoom .pg-icon-button {
  width: 28px;
  height: 28px;
  font-size: var(--pg-text-2);
}
.ws-ctl-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}
.ws-ctl-legend .pg-pill {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-ctl-legend-cut {
  flex-basis: 100%;
  color: var(--pg-fg-3);
}
/* The card of the message pointed at: a floating surface under the well
   that the pointer can reach; it stays while the pointer is on the turn or
   on it. */
.ws-ctl-card {
  position: fixed;
  z-index: 1080;
  width: 304px;
  max-width: calc(100vw - 1rem);
  padding: 12px 14px 11px;
  border-radius: 14px;
  background: var(--pg-surface-float);
  -webkit-backdrop-filter: blur(18px);
  backdrop-filter: blur(18px);
  box-shadow: var(--pg-shadow-float);
  color: var(--pg-fg);
  font-size: var(--pg-text-2);
  line-height: var(--pg-leading);
}
/* The Design examples screen draws the card in place, under its well. */
.pg-look-example .ws-ctl-card {
  position: relative;
  z-index: auto;
}
.ws-ctl-card-head {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  font-weight: var(--pg-weight-strong);
}
/* The writer: their initials on a tint of their colour. */
.ws-ctl-card .pg-initials {
  flex: none;
  width: 24px;
  height: 24px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--ws-ctl-c) 16%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ws-ctl-c) 26%, transparent);
  color: var(--ws-ctl-c);
  font-size: var(--pg-text-count);
  font-weight: var(--pg-weight-title);
}
.ws-ctl-card-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-ctl-card-head .pg-pill {
  flex: none;
  height: 18px;
  padding: 0 7px;
  font-size: var(--pg-text-count);
}
.ws-ctl-card-time {
  flex: none;
  margin-left: auto;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
  font-weight: var(--pg-weight-regular);
}
.ws-ctl-card-text {
  display: -webkit-box;
  margin: 8px 0 0;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  color: var(--pg-fg-2);
  line-height: 1.45;
  overflow-wrap: anywhere;
}
.ws-ctl-card-text.is-empty {
  color: var(--pg-fg-3);
}
/* A decision or a note mark: a plain line, never a row. */
.ws-ctl-card-mark {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 9px;
  color: var(--pg-fg-2);
  font-size: var(--pg-text-meta);
}
.ws-ctl-card-mark .pg-icon-tile,
.ws-ctl-row .pg-icon-tile {
  flex: none;
  width: 22px;
  height: 22px;
  border-radius: 7px;
  font-size: var(--pg-text-count);
}
/* What the message carries: a shortcut row each, the whole row the link. */
.ws-ctl-rows {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 1px;
  margin: 9px -6px 0;
}
.ws-ctl-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  height: 30px;
  padding: 0 6px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--pg-fg);
  font: inherit;
  text-align: left;
  white-space: nowrap;
}
.ws-ctl-row:hover,
.ws-ctl-row:focus-visible {
  outline: 0;
  background: var(--pg-hover);
  box-shadow: inset 0 0 0 1px var(--ws-ctl-line);
}
.ws-ctl-row:focus-visible {
  box-shadow: inset 0 0 0 1px var(--ws-ctl-line), 0 0 0 2px var(--pg-accent);
}
.ws-ctl-row-kind {
  flex: none;
  color: var(--pg-fg-3);
  font-style: normal;
}
.ws-ctl-row-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-ctl-row-result {
  flex: none;
  margin-left: auto;
  padding-left: 8px;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
}
.ws-ctl-row-go {
  flex: none;
  margin-left: 6px;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-count);
}
.ws-ctl-row-name + .ws-ctl-row-go {
  margin-left: auto;
}
.ws-ctl-row.is-more {
  color: var(--pg-fg-2);
}
/* The foot: the wait since the message before, and the way into the
   message. */
.ws-ctl-card-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  margin-top: 9px;
  padding-top: 8px;
  border-top: 1px solid var(--ws-ctl-line);
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
  white-space: nowrap;
}
.ws-ctl-card-wait {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-ctl-card-go {
  flex: none;
  margin-left: auto;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--pg-accent);
  font: inherit;
  font-weight: var(--pg-weight-strong);
}
.ws-ctl-card-go:hover {
  text-decoration: underline;
}
.ws-ctl-card-go:focus-visible {
  outline: 2px solid var(--pg-accent);
  outline-offset: 2px;
}
/* Only the pane gives way when the screen is short: the header, the tabs and
   the composer keep their height (the tabs scroll sideways, so without this
   they were squeezed to a sliver). */
.ws-center > .ws-head,
.ws-center > .ws-tabs,
.ws-center > .ws-composer-wrap,
.ws-center > .alert {
  flex-shrink: 0;
}
.ws-strip > .ws-catchup {
  flex-shrink: 0;
  max-height: 40vh;
  overflow-y: auto;
}
.ws-tabs::-webkit-scrollbar {
  display: none;
}
/* Send goes right even where nothing grows before it. */
.ws-composer-tools > .pg-button-fill:last-child {
  margin-left: auto;
}
.ws-pane-messages {
  padding-bottom: .25rem;
}
/* The day a conversation turns to: a chip in the middle, not a rule across
   the pane. */
.ws-day {
  display: block;
  width: fit-content;
  margin: .9rem auto .4rem;
  padding: .15rem .7rem;
  border-radius: 999px;
  background: var(--pg-bg-2);
  font-size: .75rem;
  font-weight: 600;
  color: var(--pg-fg-2);
}
/* The "New" line over the first message that came since the last visit: a
   rose hairline with its words in the middle. */
.ws-new-line {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 6px 4px;
  font-size: 11.5px;
  font-weight: 650;
  color: var(--pg-tone-rose);
  scroll-margin-top: 1rem;
}
.ws-new-line::before,
.ws-new-line::after {
  content: "";
  flex: 1;
  border-top: 1px solid color-mix(in srgb, var(--pg-tone-rose) 45%, transparent);
}
.ws-msg {
  position: relative;
  display: grid;
  grid-template-columns: 2.2rem minmax(0, 1fr);
  gap: .6rem;
  padding: var(--ws-row-y, .3rem) var(--ws-space-2, .5rem);
  border-radius: var(--ws-radius-sm);
}
.ws-msg:hover {
  background: color-mix(in srgb, var(--pg-fg-emphasis) 3.5%, transparent);
}
.ws-msg.ws-msg-follow {
  padding-top: 0;
}
/* A later line of one author's group: no face, its time in the face's
   column while the pointer or the focus is on it (a tap on a phone). */
.ws-msg.ws-msg-follow .ws-msg-avatar {
  display: flex;
  justify-content: flex-end;
}
.ws-msg.ws-msg-follow .ws-msg-avatar > :not(.ws-msg-clock) {
  display: none;
}
.ws-msg-clock {
  padding-top: .2rem;
  font-size: .68rem;
  line-height: 1.2;
  color: var(--pg-fg-2);
  white-space: nowrap;
  opacity: 0;
}
.ws-msg:hover .ws-msg-clock,
.ws-msg:focus .ws-msg-clock,
.ws-msg:focus-within .ws-msg-clock,
.ws-msg.ws-msg-active .ws-msg-clock {
  opacity: 1;
}
.ws-msg.ws-msg-follow .ws-msg-meta {
  display: none;
}
.ws-msg-main {
  grid-column: 2;
  min-width: 0;
}
.ws-msg.ws-msg-highlight {
  background: color-mix(in srgb, var(--pg-warning) 18%, transparent);
}
/* A folded run of an application's one-line messages (workspace.js
   foldAppLines()): the hidden lines, the newest line read with its name
   again, and the row that opens and closes the run. */
.ws-msg.ws-msg-folded {
  display: none;
}
.ws-msg.ws-msg-follow.ws-msg-fold-head {
  padding-top: var(--ws-row-y, .3rem);
}
.ws-msg.ws-msg-follow.ws-msg-fold-head .ws-msg-avatar {
  display: block;
}
.ws-msg.ws-msg-follow.ws-msg-fold-head .ws-msg-avatar > :not(.ws-msg-clock) {
  display: revert;
}
.ws-msg.ws-msg-fold-head .ws-msg-clock {
  display: none;
}
.ws-msg.ws-msg-follow.ws-msg-fold-head .ws-msg-meta {
  display: flex;
}
.ws-app-fold {
  padding: 0 var(--ws-space-2, .5rem) .2rem calc(2.2rem + .6rem + var(--ws-space-2, .5rem));
}
.ws-app-fold .btn {
  font-size: .78rem;
}
/* A channel's message boxes stop growing on a wide pane and stand half a
   rem apart; one sender's grouped lines (.ws-msg-follow) keep no gap, so a
   group reads as one box. On a screen wider than 1700px each box takes a
   very faint tint of its sender's colour (the theme of the face,
   data-ws-tone from senderTone() in workspace.js). The tint sits under
   :where() and its hover skips a highlighted or selected message, so those
   still show as such. */
.ws-pane-messages:not(.ws-thread-pane) > .ws-msg {
  max-width: 90rem;
  margin-bottom: .5rem;
}
.ws-pane-messages:not(.ws-thread-pane) > .ws-msg:has(+ .ws-msg.ws-msg-follow) {
  margin-bottom: 0;
}
@media (min-width: 1700px) {
  :where(.ws-pane-messages:not(.ws-thread-pane) > .ws-msg[data-ws-tone]) {
    --ws-msg-tone: var(--pg-primary);
    background: color-mix(in srgb, var(--ws-msg-tone) 5%, transparent);
  }
  .ws-pane-messages:not(.ws-thread-pane) > .ws-msg[data-ws-tone]:hover:not(.ws-msg-highlight, .ws-msg-selected) {
    background: color-mix(in srgb, var(--ws-msg-tone) 8%, transparent);
  }
  :where(html[data-bs-theme="dark"] .ws-pane-messages:not(.ws-thread-pane) > .ws-msg[data-ws-tone]) {
    background: color-mix(in srgb, var(--ws-msg-tone) 2.2%, transparent);
  }
  html[data-bs-theme="dark"] .ws-pane-messages:not(.ws-thread-pane) > .ws-msg[data-ws-tone]:hover:not(.ws-msg-highlight, .ws-msg-selected) {
    background: color-mix(in srgb, var(--ws-msg-tone) 3.5%, transparent);
  }
  .ws-msg[data-ws-tone="info"] { --ws-msg-tone: var(--pg-info); }
  .ws-msg[data-ws-tone="warning"] { --ws-msg-tone: var(--pg-warning); }
  .ws-msg[data-ws-tone="accent"] { --ws-msg-tone: var(--pg-tone-violet); }
  .ws-msg[data-ws-tone="danger"] { --ws-msg-tone: var(--pg-danger); }
  .ws-msg[data-ws-tone="secondary"] { --ws-msg-tone: var(--pg-secondary); }
  .ws-msg[data-ws-tone="success"] { --ws-msg-tone: var(--pg-success); }
  .ws-msg[data-ws-tone="inverse"] { --ws-msg-tone: var(--pg-fg-emphasis); }
  .ws-pane-messages:not(.ws-thread-pane) > .ws-msg.ws-msg-follow {
    border-top-left-radius: 0;
    border-top-right-radius: 0;
  }
  .ws-pane-messages:not(.ws-thread-pane) > .ws-msg:has(+ .ws-msg.ws-msg-follow) {
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
  }
}
.ws-msg-avatar .avatar {
  --bs-avatar-size: var(--ws-avatar);
}
/* The head line wraps by its own column's width: the name keeps a line
   of its own when it and the marks after it do not fit, and wraps between
   words only when it alone is wider than the column. */
.ws-msg-meta {
  font-size: .8rem;
  color: var(--pg-fg-2);
  display: flex;
  flex-wrap: wrap;
  gap: .1rem .5rem;
  align-items: baseline;
  min-width: 0;
}
/* A mark longer than the column (the client a message came through, an
   MCP agent's mark) is cut with an ellipsis; its whole text is its title. */
.ws-msg-meta > .badge {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-msg-meta b {
  color: var(--pg-fg-body);
  font-size: .9rem;
}
.ws-msg-body {
  font-size: .92rem;
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.ws-msg-body code {
  font-size: .85em;
  background: var(--pg-bg-2);
  padding: 0 .25rem;
  border-radius: .25rem;
}
.ws-msg-deleted .ws-msg-body {
  font-style: italic;
  color: var(--pg-fg-2);
}
.ws-msg-system {
  display: block;
  text-align: center;
  font-size: .8rem;
  color: var(--pg-fg-2);
  padding: .25rem 0;
}
.ws-msg-system .ws-chip {
  font-size: .78rem;
}
.ws-flow-run-card {
  display: flex;
  justify-content: center;
  margin-top: .25rem;
  text-align: start;
}
.ws-flow-run-card .wsf-flag {
  width: min(32rem, 100%);
}
.ws-flow-start-item {
  display: flex;
  flex-direction: column;
  gap: .35rem;
  padding: .6rem 0;
  border-bottom: 1px solid var(--pg-border-color);
}
/* A decision's or a note's tag in its head line: it alone names the kind,
   in the conversation and on the Decisions tab. */
.ws-msg-flag {
  display: inline-flex;
  align-items: center;
  align-self: center;
  gap: .25rem;
  height: 1.25rem;
  padding: 0 .45rem;
  border-radius: .375rem;
  font-size: .68rem;
  font-weight: 700;
  line-height: 1;
  text-transform: uppercase;
  letter-spacing: .04em;
}
.ws-msg-flag.ws-flag-decision {
  background: color-mix(in srgb, var(--pg-success) 15%, transparent);
  color: var(--pg-success-fg-emphasis);
}
.ws-msg-flag.ws-flag-note {
  background: color-mix(in srgb, var(--pg-info) 15%, transparent);
  color: var(--pg-info-fg-emphasis);
}
/* On the Decisions tab each one is a card of its own, one under the other
   down the pane: a card is as wide as the pane up to --ws-decision-max, so
   nothing runs past the side and the pane only scrolls down (columns on a
   pane of set height grew sideways). The tag names the kind: no coloured
   edge (a status update's either). In the conversation they keep the
   rhythm of the messages around them. */
.ws-pane-decisions {
  --ws-decision-max: 72rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  overflow-x: hidden;
}
.ws-pane-decisions > * {
  width: 100%;
  max-width: var(--ws-decision-max);
  margin-inline: auto;
}
.ws-pane-decisions > .ws-msg {
  flex-shrink: 0;
  margin-block: 0;
  padding: .9rem 1.1rem 1rem;
  border: 1px solid var(--pg-border-color);
  border-radius: 1rem;
  background: var(--pg-card-bg);
  box-shadow: var(--ws-shadow-soft);
}
.ws-pane-decisions > .ws-msg:hover {
  border-color: rgba(var(--ws-accent-rgb), .45);
  background: var(--pg-card-bg);
}
@media (prefers-reduced-motion: no-preference) {
  .ws-pane-decisions > .ws-msg,
  .ws-task-grid > .ws-list-row,
  .ws-pane-board .ws-cb-card {
    transition: border-color .15s ease, box-shadow .15s ease;
  }
}
/* The head line: the name, time and tag, with Show in conversation at its
   end, always there (keyboard and touch reach it); it wraps in a narrow
   card rather than running past the edge. */
.ws-pane-decisions > .ws-msg .ws-msg-meta {
  flex-wrap: wrap;
  align-items: center;
  row-gap: .15rem;
  margin-bottom: .35rem;
}
.ws-pane-decisions > .ws-msg .ws-msg-meta > .btn {
  margin-inline-start: auto;
  padding-block: 0;
  font-size: .78rem;
}
.ws-pane-decisions > .ws-msg .ws-msg-meta > .pg-button {
  margin-inline-start: auto;
}
.ws-pane-decisions > .ws-msg .ws-msg-quote {
  margin-bottom: .45rem;
}
.ws-pane-decisions > .ws-msg .ws-msg-body {
  line-height: 1.55;
  overflow-wrap: anywhere;
}
/* An agent channel's choice between its own decisions and every agent
   channel's sits above the cards; a card from another agent channel names
   it in its head line. */
.ws-pane-decisions > .ws-decisions-scope {
  display: flex;
}
/* A decision longer than about eight lines is folded (foldLong() in
   workspace.js): its text fades out under the eighth line and Show more
   under it opens the rest. */
.ws-pane-decisions > .ws-msg .ws-msg-main > .ws-msg-body.ws-folded {
  max-height: calc(1.55em * 8);
  overflow: hidden;
  -webkit-mask-image: linear-gradient(to bottom, currentColor 70%, transparent);
  mask-image: linear-gradient(to bottom, currentColor 70%, transparent);
}
.ws-pane-decisions > .ws-msg .ws-fold-toggle {
  margin-top: .35rem;
}
/* ── Workspace: status updates and check-ins (assets/js/workspace_status.js) ── */
.ws-msg-status {
  border-left: 3px solid var(--pg-success);
}
.ws-msg-status-at_risk {
  border-left-color: var(--pg-warning);
}
.ws-msg-status-off_track {
  border-left-color: var(--pg-danger);
}
.ws-status-pill {
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  margin-right: .35rem;
  padding: 0 .5rem;
  border: 0;
  border-radius: var(--ws-radius);
  font-size: .72rem;
  font-weight: 600;
  line-height: 1.5;
  vertical-align: middle;
}
.ws-status-on_track {
  background: color-mix(in srgb, var(--pg-success) 14%, transparent);
  color: var(--pg-success-fg-emphasis);
}
.ws-status-at_risk {
  background: color-mix(in srgb, var(--pg-warning) 20%, transparent);
  color: var(--pg-warning-fg-emphasis);
}
.ws-status-off_track {
  background: color-mix(in srgb, var(--pg-danger) 14%, transparent);
  color: var(--pg-danger-fg-emphasis);
}
.ws-status-facts {
  margin-bottom: 1rem;
  padding: .6rem .7rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-1);
}
.ws-status-chips {
  display: flex;
  flex-wrap: wrap;
  gap: .3rem;
}
.ws-status-chip {
  display: inline-flex;
  align-items: center;
  padding: .1rem .5rem;
  border-radius: var(--ws-radius);
  font-size: .75rem;
  background: var(--pg-bg-body);
  border: 1px solid var(--pg-border-color);
}
.ws-status-chip-warn {
  border-color: color-mix(in srgb, var(--pg-warning) 60%, transparent);
  color: var(--pg-warning-fg-emphasis);
}
.ws-status-stale-task {
  display: flex;
  align-items: center;
  gap: .4rem;
  width: 100%;
  padding: .2rem 0;
  border: 0;
  background: transparent;
  font-size: .8rem;
  text-align: left;
  color: var(--pg-fg-body);
}
.ws-status-stale-task:hover .ws-grow {
  text-decoration: underline;
}
.ws-status-choices {
  display: flex;
  flex-wrap: wrap;
  gap: .4rem;
}
.ws-status-choice {
  border: 1px solid transparent;
  border-radius: var(--ws-radius);
}
/* A v6 label.btn-check wrapping its radio: the checked choice keeps its
   tint and takes an outline in its own colour, not the button fill; the
   focus ring is the panel's. */
.ws-status-choice.btn-check:has(input:checked) {
  border-color: currentColor;
  box-shadow: 0 0 0 1px currentColor;
}
.ws-status-choice.btn-check:has(input:focus-visible) {
  outline: var(--pg-focus-ring-width) solid var(--pg-primary-ink);
  outline-offset: var(--pg-focus-ring-offset);
}
.ws-checkin {
  max-width: 34rem;
  margin-top: .4rem;
  padding: .55rem .65rem .5rem;
  border: 1px solid var(--pg-border-color);
  border-left: 3px solid rgb(var(--ws-accent-rgb));
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-body);
}
.ws-checkin-head {
  display: flex;
  align-items: center;
  gap: .4rem;
  margin-bottom: .4rem;
  font-size: .8rem;
}
.ws-checkin-head > .bi {
  color: rgb(var(--ws-accent-rgb));
}
.ws-checkin-count {
  margin-left: auto;
  font-size: .75rem;
  color: var(--pg-fg-2);
}
.ws-checkin-answers {
  margin: 0 0 .4rem;
  padding: 0;
  list-style: none;
}
.ws-checkin-answer {
  display: flex;
  gap: .5rem;
  padding: .35rem 0;
  border-top: 1px solid var(--pg-border-color-translucent);
}
.ws-checkin-answer:first-child {
  border-top: 0;
}
/* A Bootstrap .avatar (workspace_status.js keeps the class): its size
   variable sizes the photo too, which a plain width here would not. */
.ws-checkin-face {
  --bs-avatar-size: var(--ws-avatar-sm);
  flex: 0 0 auto;
}
.ws-checkin-text {
  min-width: 0;
  font-size: .85rem;
}
.ws-checkin-who {
  display: flex;
  gap: .4rem;
  align-items: baseline;
}
.ws-checkin-time {
  font-size: .72rem;
  color: var(--pg-fg-2);
}
.ws-checkin-body {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.ws-checkin-waiting {
  margin-bottom: .4rem;
  font-size: .75rem;
  color: var(--pg-fg-2);
}
.ws-checkin-form-foot {
  display: flex;
  justify-content: flex-end;
  margin-top: .35rem;
}
.ws-msg-tools {
  position: absolute;
  top: -1rem;
  right: 1rem;
  z-index: 2;
  display: none;
  gap: .125rem;
  padding: .2rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: .75rem;
  background: var(--pg-bg-body);
  box-shadow: 0 4px 14px rgba(0, 0, 0, .1);
}
.ws-msg:hover .ws-msg-tools,
.ws-msg:focus-within .ws-msg-tools {
  display: flex;
}
.ws-msg-tools button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.9rem;
  height: 1.9rem;
  padding: 0;
  border: 0;
  border-radius: .5rem;
  background: transparent;
  color: var(--pg-fg-2);
}
.ws-msg-tools button:hover {
  background: var(--pg-bg-2);
  color: var(--pg-fg-body);
}
/* A message's text to select and copy by hand. 16px keeps iOS from zooming
   in on the field. Two classes to outrank the field recipe's own size. */
.pg-input.ws-copy-area {
  font-size: 16px;
  resize: vertical;
  max-height: 60vh;
}

/* Reactions under a message: who left one shows on hover. */
.ws-reactions {
  display: flex;
  flex-wrap: wrap;
  gap: .25rem;
  margin-top: .3rem;
}
.ws-react {
  display: inline-flex;
  align-items: center;
  gap: .25rem;
  height: 1.6rem;
  padding: 0 .45rem;
  border: 1px solid var(--pg-border-color);
  border-radius: 999px;
  background: var(--pg-bg-body);
  color: var(--pg-fg-body);
  font-size: .78rem;
  line-height: 1;
}
.ws-react:hover {
  border-color: rgba(var(--ws-accent-rgb), .6);
}
.ws-react-emoji {
  font-size: .95rem;
}
.ws-react-count {
  font-weight: 600;
  color: var(--pg-fg-2);
}
.ws-react.ws-react-mine {
  background: rgba(var(--ws-accent-rgb), .12);
  border-color: rgba(var(--ws-accent-rgb), .55);
}
.ws-react.ws-react-mine .ws-react-count {
  color: rgb(var(--ws-accent-rgb));
}
.ws-react.ws-react-readonly {
  cursor: default;
}
.ws-react.ws-react-readonly:hover {
  border-color: var(--pg-border-color);
}
.ws-react.ws-react-add {
  color: var(--pg-fg-2);
  opacity: 0;
  transition: opacity .1s;
}
.ws-msg:hover .ws-react-add,
.ws-msg:focus-within .ws-react-add,
.ws-msg.ws-msg-active .ws-react-add {
  opacity: 1;
}

/* The emoji row at the top of a message's menu, and the emoji picker. */
.ws-ctx-emoji {
  display: flex;
  gap: .1rem;
  padding: .1rem .15rem .3rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
  margin-bottom: .2rem;
}
.ws-ctx-emoji-item,
.ws-emoji-item,
.ws-emoji-tab {
  border: 0;
  background: transparent;
  border-radius: var(--ws-radius-xs);
  line-height: 1;
  padding: 0;
  color: var(--pg-fg-2);
}
.ws-ctx-emoji-item {
  width: 2rem;
  height: 2rem;
  font-size: 1.1rem;
}
.ws-ctx-emoji-item:hover,
.ws-ctx-emoji-item:focus-visible,
.ws-emoji-item:hover,
.ws-emoji-item:focus-visible,
.ws-emoji-tab:hover {
  background: var(--pg-bg-2);
}
.ws-ctx-emoji-item.active {
  background: rgba(var(--ws-accent-rgb), .16);
}
.ws-ctx.contextmenu.popover.ws-emoji-picker {
  width: 19.5rem;
  max-width: calc(100vw - 16px);
}
.ws-emoji {
  padding: .35rem;
}
.ws-emoji-search {
  margin-bottom: .35rem;
}
.ws-emoji-tabs {
  display: flex;
  gap: .05rem;
  padding-bottom: .3rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-emoji-tab {
  flex: 1 1 0;
  height: 1.9rem;
  font-size: 1rem;
  opacity: .6;
}
.ws-emoji-tab.active {
  opacity: 1;
  background: rgba(var(--ws-accent-rgb), .14);
}
.ws-emoji-title {
  font-size: .72rem;
  font-weight: 700;
  color: var(--pg-fg-2);
  padding: .35rem .15rem .2rem;
}
.ws-emoji-grid {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  align-content: start;
  height: 12.6rem;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.ws-emoji-item {
  height: 2.1rem;
  font-size: 1.25rem;
}

/* Tables and checklists written in a message. */
.ws-msg-body .ws-text + .ws-table-wrap,
.ws-msg-body .ws-text + .ws-checklist,
.ws-msg-body .ws-table-wrap + .ws-text,
.ws-msg-body .ws-checklist + .ws-text {
  margin-top: .3rem;
}
/* The frame scrolls sideways; a swipe that reaches its end stays in it
   instead of panning the pane or going back a page. */
.ws-table-wrap {
  max-width: 100%;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  margin: .15rem 0 .3rem;
}
.ws-table-wrap .table.ws-table {
  width: auto;
  min-width: 40%;
  margin: 0;
  font-size: .85rem;
  border: 1px solid var(--pg-border-color);
}
.ws-table > :not(caption) > * > * {
  padding: .3rem .6rem;
  min-width: 4rem;
  max-width: 24rem;
  overflow-wrap: normal;
  vertical-align: top;
}
.ws-table thead th {
  background: var(--pg-bg-1);
  font-weight: 600;
}
/* On a phone a table wider than the message would be laid out at its
   narrowest: every column one word wide, a sentence a word per line and
   the right-hand column a sliver at the frame's edge. There the table
   takes each column's natural width, a cell wrapping at 11rem, and the
   frame scrolls to the columns past the edge; a table that fits (two
   short columns) still fits. A link, path or code word longer than the
   cell breaks inside it rather than running past it (the code element
   is named: the theme's own wrap on code does not reach it). */
@media (max-width: 575.98px) {
  .ws-table-wrap .table.ws-table {
    width: max-content;
  }
  .ws-table-wrap > .ws-table > :not(caption) > * > * {
    max-width: 11rem;
  }
  .ws-table-wrap > .ws-table > :not(caption) > * > *,
  .ws-table-wrap > .ws-table code {
    overflow-wrap: anywhere;
  }
}
/* Below 768px the frame is as tall as its table up to 90vh and scrolls the
   rest inside, so a long table always shows at least 70vh of rows and a
   short one keeps its own height. It never shrinks under its table in a
   flex column (flex: none), whose scroll-container items may otherwise be
   squeezed to a sliver. Vertical overscroll still chains to the
   conversation, so a swipe on a full table moves on past it. */
@media (max-width: 767.98px) {
  .ws-table-wrap {
    flex: none;
    max-height: 90vh;
    overflow-y: auto;
  }
}
.ws-checklist {
  list-style: none;
  padding: 0;
  margin: 0 0 .15rem;
}
/* Lists and quotes written in a text (ws_text_blocks_html()). Classed, so
   one rule serves every place a drawn text appears: messages, forwards,
   note cards, task and channel fields. */
.ws-list {
  margin: .1rem 0 .25rem;
  padding-left: 1.4rem;
}
.ws-list > li + li {
  margin-top: .05rem;
}
.ws-quote {
  margin: .1rem 0 .25rem;
  padding: .05rem 0 .05rem .7rem;
  border-left: 3px solid var(--pg-border-color);
  color: var(--pg-fg-2);
}
.ws-check {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0 .5rem;
  padding: .1rem 0;
}
.ws-check label {
  display: inline-flex;
  align-items: baseline;
  gap: .45rem;
  margin: 0;
  cursor: pointer;
}
.ws-check :is(.check, .radio) {
  flex-shrink: 0;
  margin: 0;
  position: relative;
  top: .15em;
}
.ws-check :is(.check, .radio):disabled {
  opacity: .7;
}
.ws-check.ws-checked .ws-check-text {
  text-decoration: line-through;
  color: var(--pg-fg-2);
}
.ws-check-who {
  font-size: .72rem;
  color: var(--pg-fg-2);
}
/* A checklist item's task: its tag, or the button that makes one, shown on
   hover (always on a touch screen). */
.ws-check-task .ws-chip {
  font-size: .78rem;
}
.ws-check-make {
  padding: 0 .2rem;
  border: 0;
  border-radius: var(--ws-radius-sm);
  background: none;
  color: var(--pg-fg-2);
  font-size: .8rem;
  line-height: 1.2;
  opacity: 0;
}
.ws-check:hover .ws-check-make,
.ws-check-make:focus-visible {
  opacity: 1;
}
.ws-check-make:hover {
  color: var(--pg-primary);
  background: var(--pg-tint-hover);
}
@media (hover: none) {
  .ws-check-make {
    opacity: 1;
  }
}

/* A poll in the conversation. */
/* The box is the container its narrow layout is read from (below), so it
   follows the column it stands in, never the window. */
.ws-poll {
  container: ws-poll / inline-size;
  max-width: 34rem;
  margin-top: .4rem;
  padding: .55rem .65rem .45rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-body);
}
.ws-poll-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .4rem;
  margin-bottom: .45rem;
  font-size: .8rem;
}
.ws-poll-head > .bi {
  color: rgb(var(--ws-accent-rgb));
}
.ws-poll-tag {
  padding: 0 .4rem;
  border-radius: var(--ws-radius-xs);
  font-size: .68rem;
  font-weight: 600;
  background: var(--pg-bg-2);
  color: var(--pg-fg-2);
}
.ws-poll-when {
  margin-left: auto;
  font-size: .75rem;
  color: var(--pg-fg-2);
}
.ws-poll-options {
  display: grid;
  gap: .3rem;
}
.ws-poll-option {
  position: relative;
  display: flex;
  align-items: center;
  gap: .5rem;
  margin: 0;
  padding: .4rem .55rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-xs);
  overflow: hidden;
  font-size: .88rem;
  cursor: pointer;
}
.ws-poll-option > * {
  position: relative;
}
.ws-poll-option > .ws-poll-bar {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  background: rgba(var(--ws-accent-rgb), .1);
  transition: width .25s ease;
}
.ws-poll-option :is(.check, .radio) {
  flex-shrink: 0;
  margin: 0;
}
.ws-poll-label {
  flex: 1 1 auto;
  min-width: 0;
}
.ws-poll-count {
  font-size: .75rem;
  font-weight: 600;
  color: var(--pg-fg-2);
  white-space: nowrap;
}
.ws-poll-option.ws-poll-mine {
  border-color: rgba(var(--ws-accent-rgb), .55);
}
.ws-poll-option.ws-poll-winner {
  border-color: var(--pg-success);
}
.ws-poll-option.ws-poll-winner > .ws-poll-bar {
  background: color-mix(in srgb, var(--pg-success) 16%, transparent);
}
.ws-poll-closed .ws-poll-option {
  cursor: default;
}
.ws-poll-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .25rem;
  margin-top: .4rem;
  font-size: .78rem;
  color: var(--pg-fg-2);
}
.ws-poll-note {
  padding: .5rem .6rem;
  border-radius: var(--ws-radius-sm);
  font-size: .8rem;
  color: var(--pg-fg-2);
  background: var(--pg-bg-1);
}
/* An option's parts under its label: description, links, the words
   written on the "Other" row; a picture beside it or beside the list. */
.ws-poll-option {
  align-items: flex-start;
}
.ws-poll-option :is(.check, .radio) {
  margin-top: .2rem;
}
.ws-poll-text {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: .1rem;
  min-width: 0;
  overflow-wrap: break-word;
}
.ws-poll-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .4rem;
}
/* The agent question: no counts; the answer stays in the box. */
.ws-poll-asks {
  color: var(--pg-fg-2);
}
.ws-poll-answer {
  display: flex;
  align-items: flex-start;
  gap: .5rem;
  padding: .45rem .6rem;
  border-radius: var(--ws-radius-xs);
  background: color-mix(in srgb, var(--pg-success) 12%, transparent);
}
.ws-poll-answer > .bi {
  margin-top: .15rem;
  color: var(--pg-success);
}
.ws-poll-answer > .ws-poll-thumb {
  padding: 0;
  border: 0;
}
.ws-poll-send {
  display: flex;
  flex-wrap: wrap;
  gap: .4rem;
  margin-top: .4rem;
}
.ws-poll-send > :not(.btn, .pg-button) {
  flex: 1 1 10rem;
  min-width: 0;
}
.ws-poll-send > .btn,
.ws-poll-send > .pg-button {
  flex: 0 0 auto;
  margin-left: auto;
}
.ws-poll-error {
  margin-top: .25rem;
  font-size: var(--pg-text-meta);
  color: var(--pg-danger);
}
.ws-poll-meta {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: .4rem;
}
/* The foot's sentence is never cut: it wraps, and the buttons take the
   next line when the two do not fit. */
.ws-poll-foot > .ws-grow {
  flex: 1 1 auto;
}
.ws-poll-foot-label {
  margin-left: .25rem;
}
.ws-poll-foot > .btn,
.ws-poll-foot > .pg-button {
  flex: 0 0 auto;
  white-space: nowrap;
}
/* On a phone the title takes the row's width: the pill, the voters and
   the count go to the row's last line. A foot shared with the asker's
   buttons shows the plain ones by their icon. */
@media (max-width: 575.98px) {
  .ws-poll-option {
    flex-wrap: wrap;
  }
  .ws-poll-text {
    flex: 1 1 0;
  }
  .ws-poll-meta {
    flex-basis: 100%;
    padding-left: 1.5rem;
  }
  .ws-poll-foot > .btn,
  .ws-poll-foot > .pg-button {
    padding-inline: .35rem;
  }
  .ws-poll-foot-tight .ws-poll-foot-label {
    display: none;
  }
}
/* The same in a narrow box on a wide window (a discussion panel): read
   from the box's own width. A picture beside the options goes above
   them, and "Write your own answer" takes a line of its own over Send
   when the two do not fit. */
@container ws-poll (max-width: 30rem) {
  .ws-poll-option {
    flex-wrap: wrap;
  }
  .ws-poll-text {
    flex: 1 1 0;
  }
  .ws-poll-meta {
    flex-basis: 100%;
    padding-left: 1.5rem;
  }
  .ws-poll-foot > .btn,
  .ws-poll-foot > .pg-button {
    padding-inline: .35rem;
  }
  .ws-poll-foot-tight .ws-poll-foot-label {
    display: none;
  }
  .ws-poll .ws-poll-split {
    grid-template-columns: minmax(0, 1fr);
  }
  /* A row's own picture stays on the tick's line and the words take the
     whole width under it, so they read in lines of several words. */
  .ws-poll-thumb + .ws-poll-text {
    flex-basis: 100%;
    padding-left: 1.5rem;
  }
}
.ws-poll-desc,
.ws-poll-links,
.ws-poll-words {
  font-size: var(--pg-text-meta);
  color: var(--pg-fg-2);
}
.ws-poll-links {
  display: flex;
  flex-wrap: wrap;
  gap: .1rem .75rem;
}
.ws-poll-links .bi {
  font-size: var(--pg-text-count);
}
.ws-poll-words {
  display: grid;
  gap: .1rem;
}
.ws-poll-thumb {
  flex: 0 0 auto;
  width: 4.5rem;
  height: 3.25rem;
  overflow: hidden;
  border-radius: var(--ws-radius-xs);
  background: var(--pg-bg-2);
  cursor: zoom-in;
}
.ws-poll-thumb img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.ws-poll-other {
  display: flex;
  gap: .4rem;
  padding-left: 1.6rem;
}
.ws-poll:is(.ws-poll-shape-split, .ws-poll-shape-question) {
  max-width: 46rem;
}
/* A question's own picture: it stays at the left whatever the rows do;
   Send and its error stand under the options beside it. */
.ws-poll-column {
  display: grid;
  min-width: 0;
}
.ws-poll-split {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: .6rem;
  align-items: start;
}
.ws-poll-figure {
  display: block;
  width: 100%;
  padding: .4rem;
  border: 0;
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-2);
  cursor: zoom-in;
  position: relative;
}
.ws-poll-figure img {
  display: block;
  width: 100%;
  max-height: 18rem;
  object-fit: contain;
}
/* How many distinct pictures the viewer holds, at the frame's bottom right.
   Its surface is nearly opaque, so it reads as one piece where it lies half
   on the picture and half on the frame; the hairline keeps it standing on a
   dark picture. The figures are tabular: the number may change while the
   rows are pointed at. */
.ws-poll-picture-count {
  position: absolute;
  right: .7rem;
  bottom: .7rem;
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  padding: .15rem .5rem;
  border: 1px solid color-mix(in srgb, var(--pg-media-mark-fg) 30%, transparent);
  border-radius: 999px;
  background: var(--pg-media-mark-bg);
  color: var(--pg-media-mark-fg);
  font-size: var(--pg-text-meta);
  font-weight: var(--pg-weight-medium);
  font-variant-numeric: tabular-nums;
  line-height: 1.4;
  white-space: nowrap;
  pointer-events: none;
}
@media (max-width: 575.98px) {
  .ws-poll-split {
    grid-template-columns: minmax(0, 1fr);
  }
}
/* Taken back: the box stays, greyed, and takes no vote. */
.ws-poll-withdrawn :is(.ws-poll-head, .ws-poll-options, .ws-poll-split) {
  opacity: .55;
  filter: grayscale(1);
}
.ws-poll-withdrawn .ws-poll-option {
  cursor: default;
}
/* The New poll form: an option's parts folded under its label. */
.ws-poll-form-more {
  display: grid;
  gap: .4rem;
  margin: .25rem 0 .5rem;
  padding: .5rem;
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-1);
}
.ws-poll-form-picture {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .25rem;
}
/* The chosen picture's thumbnail keeps an edge: a light picture would
   vanish on the form's background (the question's and an option's). */
.ws-poll-form-picture > .ws-poll-thumb {
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-xs);
}
.ws-poll-form-more > .btn,
.ws-poll-form-more > .pg-button {
  justify-self: start;
}
.ws-poll-form-links {
  display: grid;
  gap: .25rem;
}
.ws-poll-pick {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(4.5rem, 1fr));
  gap: .3rem;
  max-height: 12rem;
  overflow: auto;
}
.ws-poll-pick-item {
  height: 3.25rem;
  padding: 0;
  overflow: hidden;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-xs);
  background: var(--pg-bg-2);
}
.ws-poll-pick-item img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* The table size picker above the composer. */
.ws-ctx.contextmenu.popover.ws-table-picker {
  min-width: 0;
}
.ws-table-pick {
  padding: .45rem;
}
.ws-table-pick-size {
  margin-bottom: .35rem;
  font-size: .75rem;
  font-weight: 600;
  color: var(--pg-fg-2);
}
.ws-table-pick-grid {
  display: grid;
  grid-template-columns: repeat(6, 1.4rem);
  gap: .2rem;
}
.ws-table-pick-cell {
  width: 1.4rem;
  height: 1.4rem;
  padding: 0;
  border: 1px solid var(--pg-border-color);
  border-radius: .2rem;
  background: var(--pg-bg-body);
}
.ws-table-pick-cell.active {
  border-color: rgba(var(--ws-accent-rgb), .7);
  background: rgba(var(--ws-accent-rgb), .25);
}
@media (pointer: coarse) {
  .ws-emoji-item {
    height: 2.5rem;
  }
  /* Cells a finger can pick, as the emoji items; six still fit 320 px. */
  .ws-table-pick-grid {
    grid-template-columns: repeat(6, 2.5rem);
  }
  .ws-table-pick-cell {
    width: 2.5rem;
    height: 2.5rem;
  }
  .ws-react {
    height: 1.9rem;
  }
}

/* How far a task's checklist has got: on its card, in lists, on the board,
   under the channel list it came from and in its drawer. */
.ws-progress.progress {
  height: .45rem;
  background: var(--pg-bg-2);
}
/* The colour only: the background shorthand would also reset the stripes of
   .progress-bar-striped (the notes import's reading step). */
.ws-progress .progress-bar {
  background-color: rgb(var(--ws-accent-rgb));
  transition: width .25s ease;
}
.ws-progress.ws-progress-full .progress-bar {
  background-color: var(--pg-success);
}
.ws-progress.ws-progress-sm {
  height: .3rem;
  width: 3.5rem;
  flex-shrink: 0;
}
.ws-task-progress {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin: .35rem 0 .1rem;
  font-size: .75rem;
  color: var(--pg-fg-2);
}
.ws-task-progress .progress {
  flex: 1 1 auto;
  max-width: 14rem;
  height: .4rem;
  background: var(--pg-bg-2);
}
.ws-task-progress .progress-bar {
  background: rgb(var(--ws-accent-rgb));
}
.ws-task-progress.ws-task-progress-full .progress-bar {
  background: var(--pg-success);
}
.ws-task-progress-hint {
  font-size: .78rem;
  color: var(--pg-success-fg-emphasis);
}
.ws-task-card-notes {
  font-size: .75rem;
  color: var(--pg-fg-2);
  margin-top: .15rem;
}
.ws-row-progress {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  font-size: .75rem;
  color: var(--pg-fg-2);
  white-space: nowrap;
}
.ws-row-notes {
  font-size: .75rem;
  color: var(--pg-fg-2);
  white-space: nowrap;
}
.ws-board-item.ws-item-progress {
  background-image: linear-gradient(to right, rgba(var(--ws-accent-rgb), .55) var(--ws-progress, 0%), transparent var(--ws-progress, 0%));
  background-size: 100% 2px;
  background-position: left bottom;
  background-repeat: no-repeat;
}
.ws-list-tasks {
  display: flex;
  flex-wrap: wrap;
  gap: .3rem;
  margin-top: .3rem;
}
.ws-list-task {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  max-width: 100%;
  padding: .2rem .55rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-body);
  color: var(--pg-fg-body);
  font-size: .78rem;
}
.ws-list-task:hover {
  border-color: rgba(var(--ws-accent-rgb), .6);
}
.ws-list-task > .bi {
  color: rgb(var(--ws-accent-rgb));
}
.ws-list-task-number {
  font-weight: 600;
  color: var(--pg-fg-2);
}
.ws-list-task-title {
  min-width: 0;
  max-width: 16rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-list-task-share {
  font-weight: 600;
  color: var(--pg-fg-2);
}
.ws-list-task.ws-list-task-closed .ws-list-task-title {
  text-decoration: line-through;
  color: var(--pg-fg-2);
}

/* The task drawer: progress, lists, notes. */
.ws-task-link-note {
  display: flex;
  align-items: flex-start;
  margin-bottom: 1rem;
  padding: .55rem .7rem;
  border-radius: var(--ws-radius-sm);
  font-size: .84rem;
  background: rgba(var(--ws-accent-rgb), .08);
}
.ws-task-work {
  margin-bottom: 1rem;
  padding: .65rem .75rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
}
.ws-task-work-head {
  display: flex;
  align-items: baseline;
  gap: .5rem;
  margin-bottom: .35rem;
  font-size: .85rem;
}
.ws-task-work-done {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-top: .5rem;
  font-size: .84rem;
  color: var(--pg-success-fg-emphasis);
}
.ws-task-list {
  margin-top: .65rem;
}
.ws-task-list-head {
  display: flex;
  align-items: center;
  gap: .35rem;
  margin-bottom: .2rem;
  font-size: .75rem;
  font-weight: 600;
  color: var(--pg-fg-2);
}
.ws-task-notes {
  margin-top: .5rem;
  padding-top: .75rem;
  border-top: 1px solid var(--pg-border-color);
}
.ws-task-notes-head {
  display: flex;
  align-items: center;
  margin-bottom: .5rem;
  font-size: .9rem;
}
.ws-task-note-list {
  display: grid;
  gap: .6rem;
  margin-bottom: .6rem;
}
.ws-task-note {
  display: grid;
  grid-template-columns: 1.8rem minmax(0, 1fr);
  gap: .5rem;
}
.ws-task-note-avatar {
  --bs-avatar-size: var(--ws-avatar-sm);
}
.ws-task-note-meta {
  display: flex;
  align-items: baseline;
  gap: .5rem;
  font-size: .75rem;
  color: var(--pg-fg-2);
}
.ws-task-note-meta b {
  font-size: .82rem;
  color: var(--pg-fg-body);
}
.ws-task-note-tools {
  margin-left: auto;
  opacity: 0;
  transition: opacity .1s;
}
.ws-task-note:hover .ws-task-note-tools,
.ws-task-note:focus-within .ws-task-note-tools {
  opacity: 1;
}
.ws-note-compose {
  position: relative;
}
/* A note box without the formatted editor: its list over the box, as wide
   as it. A formatted box's list opens at the caret (.ws-picker-caret). */
.ws-note-compose .ws-picker {
  left: 0;
  right: 0;
  width: auto;
  bottom: calc(100% + .25rem);
}
/* The formatted box in the task drawer (description and notes). */
.ws-rich.ws-rich-field {
  min-height: 3.2rem;
  max-height: 18rem;
  overflow-y: auto;
  font-size: .9rem;
  line-height: 1.45;
}
.ws-desc-field .ws-rich.ws-rich-field {
  min-height: 4.6rem;
}
/* The channel summary: a page of its own, its picker below the caret line. */
.ws-summary-field .ws-rich.ws-rich-field {
  min-height: 16rem;
  max-height: 60vh;
}
.ws-item-add {
  margin-top: .4rem;
}
.ws-note-actions {
  display: flex;
  align-items: center;
  gap: .25rem;
  margin-top: .35rem;
}
@media (pointer: coarse) {
  .ws-task-note-tools {
    opacity: 1;
  }
}
@media (max-width: 575.98px) {
  .ws-row-progress .ws-progress,
  .ws-list-task .ws-progress {
    display: none;
  }
  .ws-list-task-title {
    max-width: 10rem;
  }
}
.ws-msg-quote {
  display: block;
  max-width: 100%;
  font-size: .8rem;
  color: var(--pg-fg-2);
  border: 0;
  border-left: 2px solid var(--pg-border-color);
  border-radius: 0;
  background: transparent;
  padding: 0 0 0 .5rem;
  margin-bottom: .2rem;
  overflow: hidden;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
}
.ws-msg-quote:hover {
  color: var(--pg-fg-body);
  border-left-color: var(--ws-accent);
}
/* A task's priority badge (high or urgent) in the Today card and every
   task list (homeDue(), taskRows() in workspace.js). */
.ws-priority {
  display: inline-block;
  margin-left: .35rem;
  padding: 0 .4rem;
  border-radius: 999px;
  font-size: .68rem;
  font-weight: 700;
  vertical-align: middle;
  background: color-mix(in srgb, var(--pg-warning) 20%, transparent);
  color: var(--pg-warning-fg-emphasis);
}
.ws-priority-urgent {
  background: color-mix(in srgb, var(--pg-danger) 16%, transparent);
  color: var(--pg-danger-fg-emphasis);
}
/* Scheduled actions: the card (in its channel, its note and the list) and
   the form. */
.ws-sa-card {
  max-width: 40rem;
  margin: .25rem 0;
  padding: .6rem .75rem;
  border: 1px solid var(--pg-border-color);
  border-left: 3px solid var(--ws-accent);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-body);
  font-size: .85rem;
}
.ws-sa-card.ws-sa-paused {
  border-left-color: var(--pg-warning);
}
.ws-sa-card.ws-sa-failed {
  border-left-color: var(--pg-danger);
}
.ws-sa-card.ws-sa-done,
.ws-sa-card.ws-sa-cancelled {
  border-left-color: var(--pg-fg-2);
  opacity: .85;
}
.ws-sa-card-head {
  display: flex;
  align-items: center;
  gap: .45rem;
  margin-bottom: .3rem;
}
.ws-sa-card-icon {
  color: var(--ws-accent);
}
.ws-sa-card-name {
  flex: 1 1 auto;
  min-width: 0;
}
.ws-sa-state {
  flex: none;
  padding: .05rem .5rem;
  border-radius: 999px;
  font-size: .7rem;
  font-weight: 600;
  background: rgba(var(--ws-accent-rgb), .14);
  color: var(--ws-accent);
}
.ws-sa-state-paused {
  background: color-mix(in srgb, var(--pg-warning) 18%, transparent);
  color: var(--pg-warning-fg-emphasis);
}
.ws-sa-state-failed {
  background: color-mix(in srgb, var(--pg-danger) 14%, transparent);
  color: var(--pg-danger-fg-emphasis);
}
.ws-sa-state-done,
.ws-sa-state-cancelled {
  background: var(--pg-bg-1);
  color: var(--pg-fg-2);
}
.ws-sa-line {
  display: flex;
  align-items: baseline;
  gap: .1rem;
  margin: .15rem 0;
  color: var(--pg-fg-body);
}
/* A card reads as its flow: each line hangs on a thin rail. */
.ws-sa-card > .ws-sa-line {
  position: relative;
  padding-left: .15rem;
}
.ws-sa-card > .ws-sa-line + .ws-sa-line::before {
  content: "";
  position: absolute;
  left: .42rem;
  top: -.35rem;
  height: .4rem;
  border-left: 1px dashed rgba(var(--ws-accent-rgb), .4);
}
.ws-sa-line > .bi {
  flex: none;
  color: var(--pg-fg-2);
}
.ws-sa-last-failed {
  color: var(--pg-danger-fg-emphasis);
}
.ws-sa-last-skipped {
  color: var(--pg-warning-fg-emphasis);
}
.ws-sa-meta {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
  margin-top: .3rem;
  font-size: .72rem;
  color: var(--pg-fg-2);
}
.ws-sa-tools {
  display: flex;
  flex-wrap: wrap;
  gap: .15rem;
  margin-top: .35rem;
}
.ws-sa-history {
  margin-top: .35rem;
  padding-top: .35rem;
  border-top: 1px dashed var(--pg-border-color);
}
.ws-sa-history-row {
  display: flex;
  flex-wrap: wrap;
  gap: .5rem;
  font-size: .76rem;
  margin-bottom: .2rem;
}
.ws-sa-strip {
  margin-bottom: .5rem;
}
.ws-sa-view .ws-sa-filters {
  margin-bottom: .5rem;
}
.ws-sa-list-item {
  margin-bottom: .75rem;
}
.ws-sa-where {
  font-size: .75rem;
  color: var(--pg-fg-2);
}
.ws-sa-field .form-label {
  color: var(--pg-fg-2);
}
.ws-sa-picker {
  position: relative;
}
.ws-sa-picker-list {
  position: absolute;
  z-index: 10;
  left: 0;
  right: 0;
  top: calc(100% + .15rem);
  max-height: 14rem;
  overflow-y: auto;
  padding: .25rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-body);
  box-shadow: 0 8px 24px -8px rgba(0, 0, 0, .25);
}
.ws-sa-picker-item {
  display: flex;
  align-items: center;
  gap: .4rem;
  width: 100%;
  padding: .3rem .45rem;
  border: 0;
  border-radius: var(--ws-radius-xs);
  background: transparent;
  font-size: .82rem;
  text-align: left;
}
.ws-sa-picker-item:hover {
  background: var(--pg-bg-1);
}
.ws-delete-scopes .form-field {
  margin-bottom: .45rem;
}
/* Who has seen a message. */
.ws-seen-list {
  display: flex;
  flex-direction: column;
  gap: .35rem;
  margin: .35rem 0 .6rem;
}
.ws-seen-row {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: .9rem;
}
/* A picture or a name that opens the person's account (edit_user.php). */
a.ws-person-link {
  color: inherit;
  text-decoration: none;
}
a.ws-person-link:hover b,
a.ws-person-link:hover div,
a.ws-person-link:hover span,
a.ws-person-link:focus-visible b {
  text-decoration: underline;
}
a.ws-person-link:hover .avatar {
  box-shadow: 0 0 0 2px var(--pg-primary);
}
.ws-seen-row a.ws-person-link {
  display: inline-flex;
  min-width: 0;
}
.ws-msg-avatar a.ws-person-link {
  display: block;
  line-height: 0;
}
.ws-seen-row .avatar {
  flex: none;
  --bs-avatar-size: 1.6rem;
}
.ws-seen-row span {
  min-width: 0;
  overflow-wrap: anywhere;
}
/* An agent among them: its square face, its name with the badge and under
   it what it did with the message. */
.ws-seen-agent {
  align-items: flex-start;
}
.ws-seen-agent-text {
  min-width: 0;
  line-height: 1.3;
}
.ws-seen-agent-name .ws-info-badge {
  margin-left: .4rem;
  vertical-align: .1em;
}
/* The agents the message did not wake, named apart. */
.ws-seen-quiet {
  overflow-wrap: anywhere;
}
/* Changed after it was sent. */
/* A reader's highlight on a message (workspace_highlights.js): a <mark>
   around pieces of the drawn text in its maker's colour (data-ws-tone, the
   tones of the message box tint), strong enough to read on the box's own
   faint tint in both themes; one only its maker sees has a dotted
   underline. Overlaps nest, so the inner one shows through both. */
.ws-hl {
  --ws-hl-tone: var(--pg-primary);
  padding: 0;
  color: inherit;
  background: color-mix(in srgb, var(--ws-hl-tone) 24%, transparent);
  border-radius: .15em;
  cursor: pointer;
}
html[data-bs-theme="dark"] .ws-hl {
  background: color-mix(in srgb, var(--ws-hl-tone) 34%, transparent);
}
.ws-hl.ws-hl-me {
  text-decoration: underline dotted;
  text-decoration-thickness: 1px;
  text-underline-offset: .2em;
}
.ws-hl:focus-visible {
  outline: 2px solid var(--ws-hl-tone);
  outline-offset: 1px;
}
.ws-hl[data-ws-tone="info"], .ws-hl-swatch[data-ws-tone="info"] { --ws-hl-tone: var(--pg-info); }
.ws-hl[data-ws-tone="warning"], .ws-hl-swatch[data-ws-tone="warning"] { --ws-hl-tone: var(--pg-warning); }
.ws-hl[data-ws-tone="accent"], .ws-hl-swatch[data-ws-tone="accent"] { --ws-hl-tone: var(--pg-tone-violet); }
.ws-hl[data-ws-tone="danger"], .ws-hl-swatch[data-ws-tone="danger"] { --ws-hl-tone: var(--pg-danger); }
.ws-hl[data-ws-tone="secondary"], .ws-hl-swatch[data-ws-tone="secondary"] { --ws-hl-tone: var(--pg-secondary); }
.ws-hl[data-ws-tone="success"], .ws-hl-swatch[data-ws-tone="success"] { --ws-hl-tone: var(--pg-success); }
.ws-hl[data-ws-tone="inverse"], .ws-hl-swatch[data-ws-tone="inverse"] { --ws-hl-tone: var(--pg-fg-emphasis); }
/* The toolbar on a selection and the card of a highlight float over the
   conversation, outside its scrolling pane. */
.ws-hl-bar, .ws-hl-card {
  position: absolute;
  z-index: 1080;
}
.ws-hl-bar {
  /* One rounded surface, the look's floating bar (.pg-floatbar draws its
     radius, surface and shadow), holding one sentence: the highlighter,
     "Highlight for", the joined pair. Inner corners follow the bar's
     (inner radius = outer minus padding): 16 - 5 = the pair's 11 px. */
  --ws-hl-bar-pad: 5px;
  --ws-hl-bar-inner: max(0px, calc(var(--pg-radius-card) - var(--ws-hl-bar-pad)));
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  max-width: calc(100vw - 1rem);
  padding: var(--ws-hl-bar-pad);
}
.ws-hl-bar-line {
  display: flex;
  align-items: center;
  gap: .375rem;
  white-space: nowrap;
}
.ws-hl-bar-icon {
  padding-inline-start: .375rem;
  color: var(--pg-fg-3);
}
.ws-hl-bar-text:last-child {
  padding-inline-end: .375rem;
}
/* The pair is one segmented control (.pg-seg): two flat segments in one
   outline. They are actions, not a kept choice: none is chosen, the one
   under the pointer rises as a chosen one does. */
.ws-hl-bar .ws-hl-bar-pair {
  flex-shrink: 0;
  border-radius: var(--ws-hl-bar-inner);
}
.ws-hl-bar-pair > .pg-seg-item:hover {
  background: var(--pg-thumb);
  color: var(--pg-fg-body);
  box-shadow: var(--pg-thumb-shadow);
}
.ws-hl-bar-pair > .pg-seg-item:disabled {
  opacity: .5;
  pointer-events: none;
}
.ws-hl-bar .ws-hl-bar-one {
  border-radius: var(--ws-hl-bar-inner);
}
/* The "too long" note takes a line of its own under the sentence. */
.ws-hl-bar-note {
  padding: .25rem .5rem;
}
.ws-hl-card {
  width: min(20rem, calc(100vw - 1rem));
  padding: .5rem .75rem;
}
.ws-hl-card-row + .ws-hl-card-row {
  margin-top: .5rem;
  padding-top: .5rem;
  border-top: 1px solid var(--pg-border-color);
}
.ws-hl-card-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .25rem .5rem;
}
.ws-hl-swatch {
  --ws-hl-tone: var(--pg-primary);
  width: .75rem;
  height: .75rem;
  border-radius: 50%;
  background: color-mix(in srgb, var(--ws-hl-tone) 60%, transparent);
}
.ws-hl-note {
  margin-top: .25rem;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.ws-hl-card-tools {
  display: flex;
  gap: .75rem;
  margin-top: .25rem;
}
/* A highlight opened from My highlights lights up for a moment. */
.ws-hl.ws-hl-flash {
  outline: 2px solid var(--ws-hl-tone);
  outline-offset: 1px;
  animation: ws-hl-flash 1.2s ease-in-out 2;
}
@keyframes ws-hl-flash {
  50% { background: color-mix(in srgb, var(--ws-hl-tone) 55%, transparent); }
}
@media (prefers-reduced-motion: reduce) {
  .ws-hl.ws-hl-flash { animation: none; }
}
/* My highlights in My Notes: a tick, then the highlighted text whole in
   the person's colour with where it is under it; the row leads to the
   message. */
.ws-hl-mine-row {
  display: flex;
  align-items: flex-start;
  gap: .75rem;
  padding: .75rem 0;
  border-top: 1px solid var(--pg-border-color);
}
.ws-hl-mine-row:first-child {
  border-top: 0;
}
.ws-hl-mine-link {
  min-width: 0;
  color: inherit;
  text-decoration: none;
}
.ws-hl-mine-link:hover .ws-hl-mine-quote,
.ws-hl-mine-link:focus-visible .ws-hl-mine-quote {
  text-decoration: underline;
}
.ws-hl-mine-quote {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.ws-hl-mine-quote .ws-hl {
  cursor: inherit;
}
.ws-hl-mine-count {
  font-variant-numeric: tabular-nums;
  opacity: .8;
}
.ws-msg-edited {
  display: inline-block;
  margin-left: .35rem;
  font-size: .7rem;
  color: var(--pg-fg-2);
  white-space: nowrap;
  vertical-align: baseline;
}
.ws-msg-edited .bi {
  font-size: 11px;
}
/* The card of a message's first web address (link_preview.php): site
   name, title and a description of two lines, the whole card one link. It
   never widens the list: a long title or address breaks inside it. */
.ws-link-card {
  display: flex;
  flex-direction: column;
  gap: .1rem;
  max-width: 32rem;
  min-width: 0;
  margin: .3rem 0 .15rem;
  padding: .45rem .7rem;
  border: 1px solid var(--pg-border-color);
  border-left: 3px solid var(--pg-primary);
  border-radius: .5rem;
  background: var(--pg-bg-2);
  color: inherit;
  text-decoration: none;
  overflow-wrap: anywhere;
}
.ws-link-card:hover,
.ws-link-card:focus-visible {
  border-color: var(--pg-fg-2);
  text-decoration: none;
}
.ws-link-card-site {
  font-size: .75rem;
  color: var(--pg-fg-2);
}
.ws-link-card-title {
  font-size: .875rem;
  font-weight: 650;
  line-height: 1.35;
}
.ws-link-card-text {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  font-size: .8125rem;
  line-height: 1.4;
  color: var(--pg-fg-2);
}
/* Translate on a message (workspace_translate.js): the line under it. */
.ws-msg-tr {
  margin-top: .15rem;
  font-size: .75rem;
  color: var(--pg-fg-2);
}
.ws-msg-tr:empty {
  display: none;
}
.ws-msg-tr .bi {
  font-size: 11px;
}
.ws-msg-tr .ws-msg-tr-toggle {
  display: inline;
  height: auto;
  padding: 0;
  font-size: inherit;
  line-height: inherit;
  vertical-align: baseline;
}
/* The messages a reply answers, lit up for a moment when it is followed. */
@keyframes ws-msg-flash {
  0%, 35% { background: rgba(var(--ws-accent-rgb), .28); box-shadow: inset 3px 0 0 var(--ws-accent); }
  100% { background: transparent; box-shadow: inset 3px 0 0 transparent; }
}
.ws-msg.ws-msg-flash {
  animation: ws-msg-flash 2.6s ease-out;
}
@media (prefers-reduced-motion: reduce) {
  .ws-msg.ws-msg-flash {
    animation: none;
    background: rgba(var(--ws-accent-rgb), .2);
  }
}
.ws-msg-file {
  margin-top: .35rem;
}
.ws-msg-file img {
  display: block;
  max-width: min(26rem, 100%);
  max-height: 20rem;
  min-width: 4rem;
  min-height: 3rem;
  object-fit: contain;
  border-radius: var(--ws-radius-sm);
  border: 1px solid var(--pg-border-color-translucent);
  background: var(--pg-bg-1);
}
.ws-file-link {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .35rem .6rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  text-decoration: none;
  color: var(--pg-fg-body);
  font-size: .85rem;
}
.ws-file-ext {
  font-size: .68rem;
  font-weight: 700;
  text-transform: uppercase;
  background: var(--pg-bg-2);
  border-radius: var(--ws-radius-xs);
  padding: .05rem .35rem;
}
.ws-chip {
  display: inline-flex;
  align-items: center;
  gap: .25rem;
  max-width: 100%;
  vertical-align: baseline;
  padding: .02rem .5rem;
  border-radius: 999px;
  font-size: .85em;
  line-height: 1.5;
  background: color-mix(in srgb, var(--pg-primary) 12%, transparent);
  color: var(--pg-primary-fg-emphasis);
  text-decoration: none;
  white-space: nowrap;
}
.ws-chip > span {
  overflow: hidden;
  text-overflow: ellipsis;
}
a.ws-chip:hover {
  background: color-mix(in srgb, var(--pg-primary) 22%, transparent);
}
.ws-chip-user,
.ws-chip-dept {
  background: color-mix(in srgb, var(--pg-warning) 18%, transparent);
  color: var(--pg-warning-fg-emphasis);
}
.ws-chip-task {
  background: color-mix(in srgb, var(--pg-success) 14%, transparent);
  color: var(--pg-success-fg-emphasis);
}
.ws-chip-muted {
  background: var(--pg-bg-2);
  color: var(--pg-fg-2);
}
/* Another message pointed at (<#message:N>): a chip of its own tone that
   opens the message in the agent card's frame (messageRefShow()). */
.ws-chip-message {
  background: color-mix(in srgb, var(--pg-info) 14%, transparent);
  color: var(--pg-info-fg-emphasis);
  cursor: pointer;
}
a.ws-chip-message:hover,
.ws-chip-message[aria-expanded="true"] {
  background: color-mix(in srgb, var(--pg-info) 24%, transparent);
}
.ws-chip-message.ws-chip-muted {
  background: var(--pg-bg-2);
  color: var(--pg-fg-2);
}
.pg-card.ws-agent-card.ws-msgref-card {
  width: min(24rem, calc(100vw - 1rem));
}
.ws-msgref-head {
  display: flex;
  gap: .625rem;
  align-items: center;
}
.ws-msgref-head > .avatar {
  flex: none;
}
.ws-msgref-mark {
  display: inline-flex;
  flex: none;
  justify-content: center;
  align-items: center;
  width: 2rem;
  height: 2rem;
  border-radius: .625rem;
  background: var(--pg-surface-inset);
  color: var(--pg-fg-3);
}
.ws-msgref-who {
  min-width: 0;
}
.ws-msgref-name {
  overflow: hidden;
  font-weight: var(--pg-weight-strong);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-msgref-meta {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-msgref-none {
  margin-top: .75rem;
}
/* The words as the channel draws them, cut at a height and faded out. */
.ws-msgref-text {
  max-height: 12rem;
  margin-top: .75rem;
  overflow: hidden;
  overflow-wrap: anywhere;
}
.ws-msgref-text.ws-msgref-cut {
  -webkit-mask-image: linear-gradient(to bottom, var(--pg-fg-emphasis) 75%, transparent);
  mask-image: linear-gradient(to bottom, var(--pg-fg-emphasis) 75%, transparent);
}
.ws-msgref-picture {
  display: block;
  margin-top: .75rem;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: .75rem;
  background: var(--pg-surface-inset);
  cursor: zoom-in;
}
.ws-msgref-picture img {
  display: block;
  max-width: 100%;
  max-height: 12rem;
  object-fit: contain;
}
.ws-msgref-file {
  display: flex;
  gap: .5rem;
  align-items: center;
  margin-top: .75rem;
  padding: .5rem .75rem;
  border-radius: .75rem;
  background: var(--pg-surface-inset);
  font-size: var(--pg-text-2);
}
.ws-msgref-poll {
  margin-top: .75rem;
  padding: .5rem .75rem;
  border-radius: .75rem;
  background: var(--pg-surface-inset);
  font-size: var(--pg-text-2);
}
.ws-msgref-poll-head {
  display: flex;
  gap: .5rem;
  align-items: center;
  margin-bottom: .25rem;
}
.ws-msgref-poll-head .pg-text-meta {
  margin-inline-start: auto;
}
.ws-msgref-poll-option {
  position: relative;
  display: flex;
  gap: .75rem;
  justify-content: space-between;
  padding: .25rem .5rem;
  overflow: hidden;
  border-radius: .5rem;
}
.ws-msgref-poll-option > .ws-poll-bar {
  position: absolute;
  inset: 0 auto 0 0;
}
.ws-msgref-poll-label {
  position: relative;
  min-width: 0;
  overflow-wrap: anywhere;
}
.ws-msgref-poll-count {
  position: relative;
  flex: none;
  color: var(--pg-fg-3);
}
.ws-msgref-go {
  margin-top: .75rem;
}
.ws-task-card {
  margin-top: .35rem;
  max-width: 36rem;
  /* A long word or link in the title wraps inside the card. */
  overflow-wrap: anywhere;
  border: 1px solid var(--pg-border-color-translucent);
  border-left: 4px solid var(--ws-accent);
  border-radius: var(--ws-radius-sm);
  padding: .6rem .85rem;
  background: var(--pg-bg-1);
  box-shadow: 0 1px 2px rgba(0, 0, 0, .04);
}
.ws-task-card.ws-task-done {
  border-left-color: var(--pg-success);
  opacity: .8;
}
.ws-task-card.ws-task-done .ws-task-card-title {
  text-decoration: line-through;
}
.ws-task-card.ws-task-cancelled {
  border-left-color: var(--pg-secondary);
  opacity: .7;
}
.ws-task-card.ws-task-waiting {
  border-left-color: var(--pg-warning);
}
.ws-task-card-head {
  display: flex;
  gap: .4rem;
  align-items: center;
  font-size: .75rem;
}
.ws-task-number {
  font-weight: 700;
  color: var(--pg-fg-2);
}
.ws-task-status {
  background: var(--pg-bg-2);
  color: var(--pg-fg-body);
  font-weight: 600;
}
.ws-task-priority {
  background: var(--pg-danger);
}
.ws-task-card-title {
  font-weight: 600;
  margin: .15rem 0;
}
.ws-task-card-meta {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
  font-size: .8rem;
  color: var(--pg-fg-2);
}
.ws-task-card-people {
  display: flex;
  flex-wrap: wrap;
  gap: .4rem;
  margin-top: .35rem;
  font-size: .8rem;
}
.ws-task-person {
  display: inline-flex;
  align-items: center;
  gap: .25rem;
}
.ws-task-person .avatar {
  --bs-avatar-size: 1.2rem;
}
.ws-task-card-actions {
  display: flex;
  flex-wrap: wrap;
  gap: .25rem;
  margin-top: .45rem;
}
.ws-composer-wrap {
  position: relative;
  padding: .5rem 1rem .75rem;
}
/* Back down to the newest line, over the end of the conversation. */
.ws-jump-end {
  position: absolute;
  right: 1.5rem;
  bottom: calc(100% + .5rem);
  z-index: 4;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .3rem;
  min-width: 2.4rem;
  height: 2.4rem;
  padding: 0 .7rem;
  border: 1px solid var(--pg-border-color);
  border-radius: 999px;
  background: var(--pg-bg-body);
  color: var(--pg-fg-body);
  box-shadow: 0 4px 14px -4px rgba(0, 0, 0, .25);
  font-size: 1rem;
}
.ws-jump-end[hidden] {
  display: none;
}
.ws-jump-end:hover {
  background: var(--pg-bg-1);
}
.ws-jump-end.ws-jump-news {
  border-color: var(--ws-accent);
  color: var(--ws-accent);
}
.ws-jump-count {
  min-width: 1.2rem;
  padding: 0 .35rem;
  border-radius: 999px;
  background: var(--ws-accent);
  color: #fff;
  font-size: .72rem;
  font-weight: 700;
  line-height: 1.2rem;
}
.ws-jump-count[hidden] {
  display: none;
}
/* A room a guest reads (includes/workspace/guests.php). */
.ws-guest-bar-text {
  flex: 1 1 18rem;
  min-width: 0;
}
.ws-guest-bar .ws-guest-state {
  display: flex;
  flex-wrap: wrap;
  gap: .25rem .75rem;
}
.ws-guest-online {
  color: var(--pg-success-fg-emphasis);
  font-weight: 600;
}
.ws-guest-online::before {
  content: "";
  display: inline-block;
  width: .5rem;
  height: .5rem;
  margin-right: .3rem;
  border-radius: 50%;
  background: var(--pg-success);
  vertical-align: middle;
}
.ws-guest-badge {
  background: var(--pg-warning-bg-subtle);
  color: var(--pg-warning-fg-emphasis);
  font-weight: 600;
  font-size: .7rem;
}
/* The OAuth client a person's message was written through ("via Claude Code"). */
.ws-via-badge {
  background: var(--pg-secondary-bg-subtle);
  color: var(--pg-secondary-fg-emphasis);
  font-weight: 500;
  font-size: .7rem;
}
.ws-guest-room .ws-composer {
  border-color: var(--pg-warning-border-subtle);
}
.ws-guest-duration {
  margin: .35rem 0 0 1.5rem;
  max-width: 14rem;
}
.ws-composer {
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius);
  background: var(--pg-card-bg);
  padding: .45rem .55rem .35rem;
  box-shadow: var(--ws-shadow);
  transition: border-color .15s ease, box-shadow .15s ease;
}
.ws-composer:focus-within {
  border-color: rgba(var(--ws-accent-rgb), .65);
  box-shadow: var(--ws-shadow-accent);
}
/* The frame above is the writing field's focus mark, so the field inside
   draws no ring of its own. A text field matches :focus-visible on a mouse
   click too, and the workspace-wide ring rule (body.workspace *:focus-visible)
   outranks the field's outline: 0, which drew a second ring inside the frame. */
.ws-composer .ws-rich:focus-visible,
.ws-composer > textarea:focus-visible {
  outline: 0;
  box-shadow: none;
}
.ws-composer textarea {
  display: block;
  width: 100%;
  resize: none;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--pg-fg-body);
  font-size: .92rem;
  line-height: 1.45;
  min-height: 1.6rem;
  max-height: 12rem;
  padding: .15rem .25rem;
}
/* Files waiting for Send over the field (drawWaiting()): one chip each, a
   picture's thumbnail or a file icon, the name and size, the remove button. */
.ws-composer-files {
  display: flex;
  flex-wrap: wrap;
  gap: .4rem;
  padding: .1rem .1rem .4rem;
}
.ws-composer-files[hidden] {
  display: none;
}
.ws-wait-file {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  min-width: 0;
  max-width: min(18rem, 100%);
  padding: .25rem .25rem .25rem .3rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-1);
}
.ws-wait-thumb {
  display: grid;
  place-items: center;
  flex: none;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: var(--ws-radius-xs);
  background: var(--pg-bg-2);
  color: var(--pg-fg-2);
  font-size: 1.0625rem;
  object-fit: cover;
}
.ws-wait-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.3;
}
.ws-wait-name {
  overflow: hidden;
  color: var(--pg-fg-body);
  font-size: .8125rem;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-wait-size {
  color: var(--pg-fg-2);
  font-size: .75rem;
}
/* The row wraps where it has no room (a phone, the narrow discussion
   panel), so Send and Send later stay inside the box. */
.ws-composer-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .15rem;
}
.ws-composer-tools .ws-grow {
  flex: 1 1 auto;
}
/* The composer's own marks and steps (PGWsEditor.toolbar()) wait behind
   "Aa": the row is one line of inserts, then Send; "Aa" opens the taller box
   with every mark (below). The bar over a selection still formats. */
.ws-composer-format {
  display: none;
  align-items: center;
  gap: .15rem;
  margin-left: .1rem;
  padding-left: .25rem;
  border-left: 1px solid var(--pg-border-color-translucent);
}
/* Empty in the one-line box; the expanded box names its keys there. */
.ws-composer-hint {
  min-width: 0;
  overflow: hidden;
  color: var(--pg-fg-2);
  font-size: .72rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* The "Aa" expanded box (PGWsEditor, expand()): a taller field, and every
   tool of the row, wrapped onto a second line where it has no room. */
.ws-composer .ws-rich.is-expanded {
  min-height: 7.5rem;
  max-height: min(24rem, 50vh);
}
.ws-composer-tools.is-expanded .ws-composer-format {
  display: flex;
}
.ws-rich-expand {
  font-weight: 600;
  letter-spacing: -.02em;
}
/* The length meter near the message limit, before Send; empty while the
   text is short. */
.ws-composer-meter {
  font-size: .72rem;
  color: var(--pg-fg-2);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.ws-composer-meter:empty {
  display: none;
}
.ws-composer-meter.is-over {
  color: var(--pg-danger-fg-emphasis);
  font-weight: 600;
}
/* A mark the caret or the selection has, on a button of a box's row of
   tools: the tint of the bar over a selection, in place of the icon
   button's grey pressed fill. Undo and redo with nothing to take back are
   faded and draw no hover. */
.ws-rich-tools .pg-icon-button[aria-pressed="true"] {
  background: color-mix(in srgb, var(--ws-accent) 15%, transparent);
  color: var(--ws-accent);
  box-shadow: none;
}
.ws-rich-tools .pg-icon-button:disabled {
  opacity: .45;
  pointer-events: none;
}

/* The writing box: formatted text, chips and cards, and still a chat field.
   (assets/js/workspace_editor.js) */
/* The box is a div.form-control, which Bootstrap 6 lays out as a flex row:
   text runs, code spans, tables and lists would stand side by side as
   columns. Its content flows as text and blocks. */
.ws-rich {
  display: block;
  position: relative;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  cursor: text;
}
.ws-composer .ws-rich {
  display: block;
  width: 100%;
  border: 0;
  border-radius: 0;
  outline: 0;
  box-shadow: none;
  background: transparent;
  color: var(--pg-fg-body);
  font-size: .92rem;
  line-height: 1.45;
  min-height: 1.6rem;
  max-height: 12rem;
  overflow-y: auto;
  padding: .15rem .25rem;
}
.ws-rich.is-empty::before,
.ws-cell-edit.is-empty::before {
  content: attr(data-placeholder);
  position: absolute;
  color: var(--pg-fg-2);
  pointer-events: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: calc(100% - .5rem);
}
.ws-cell-edit.is-empty::before {
  position: static;
  display: inline-block;
}
.ws-rich-surface code {
  font-family: var(--pg-font-mono);
  font-size: .85em;
  background: var(--pg-bg-2);
  padding: 0 .25rem;
  border-radius: .25rem;
}
.ws-rich-surface a {
  color: var(--pg-link-color);
  text-decoration: underline;
  cursor: text;
}
.ws-rich-chip {
  cursor: default;
  margin: 0 .05rem;
  user-select: all;
}
.ws-rich-block {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  max-width: 100%;
  margin: .15rem 0;
  padding: .3rem .3rem .3rem .6rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-1);
  font-size: .8rem;
  line-height: 1.3;
  white-space: nowrap;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  transition: border-color .15s ease;
}
.ws-rich-block:hover {
  border-color: rgba(var(--ws-accent-rgb), .6);
}
.ws-rich-block > .bi {
  flex-shrink: 0;
  font-size: 1rem;
  color: rgba(var(--ws-accent-rgb), 1);
}
.ws-rich-block-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.ws-rich-block-text > b {
  font-weight: 600;
}
.ws-rich-block-text > span {
  max-width: 22rem;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--pg-fg-2);
}
.ws-rich-block-remove {
  flex-shrink: 0;
  border: 0;
  background: transparent;
  color: var(--pg-fg-2);
  padding: .2rem .3rem;
  border-radius: var(--ws-radius-xs);
  line-height: 1;
}
.ws-rich-block-remove:hover {
  background: var(--pg-bg-2);
  color: var(--pg-danger);
}

/* In a note a card shows what it holds, drawn as in a message; a click on it
   still opens its window. */
.ws-rich-block.ws-rich-block-shown {
  position: relative;
  display: inline-block;
  width: 100%;
  margin: .1rem 0;
  padding: .3rem 2rem .3rem .5rem;
  border-color: transparent;
  background: transparent;
  font-size: inherit;
  line-height: inherit;
  white-space: normal;
  vertical-align: top;
  transition: border-color .15s ease, background-color .15s ease;
}
.ws-rich-block.ws-rich-block-shown:hover {
  border-color: rgba(var(--ws-accent-rgb), .45);
  background: var(--pg-bg-1);
}
.ws-rich-block-shown > .bi,
.ws-rich-block-shown > .ws-rich-block-text {
  display: none;
}
.ws-rich-block-view {
  display: block;
  min-width: 0;
}
.ws-rich-block-view a,
.ws-rich-block-view input,
.ws-rich-block-view button {
  pointer-events: none;
}
.ws-rich-block-view > :last-child {
  margin-bottom: 0;
}
/* A media card in a note's writing box: the picture or player the server
   drew is only shown (a click opens the viewer or the preview); a
   recording's own player is used where it is. */
.ws-rich-block-view video,
.ws-rich-block-view audio {
  pointer-events: none;
}
.ws-rich-block-player {
  display: block;
  min-width: 0;
  cursor: auto;
}
/* A media card's one action (Edit the picture on a canvas), beside its
   remove button. */
.ws-rich-block-action {
  flex-shrink: 0;
  border: 0;
  background: transparent;
  color: var(--pg-fg-2);
  padding: .2rem .3rem;
  border-radius: var(--ws-radius-xs);
  line-height: 1;
}
.ws-rich-block-action:hover {
  background: var(--pg-bg-2);
  color: var(--ws-accent);
}
.ws-rich-block-shown > .ws-rich-block-action {
  position: absolute;
  top: .3rem;
  right: 2.1rem;
  background: var(--pg-bg-1);
}
/* The panel gives every table in a card a bottom margin (important). */
.card .ws-table-wrap .table.ws-table,
.card .ws-calc-block .table.ws-table {
  margin-bottom: 0 !important;
}
.ws-rich-block-shown > .ws-rich-block-remove {
  position: absolute;
  top: .3rem;
  right: .3rem;
}
@media (hover: hover) {
  .ws-rich-block-shown > .ws-rich-block-remove {
    opacity: 0;
    transition: opacity .15s ease;
  }
  .ws-rich-block-shown:hover > .ws-rich-block-remove {
    opacity: 1;
  }
}

/* The bar over a selection, and the link tip. */
.ws-format-bar,
.ws-link-tip {
  position: fixed;
  z-index: 1096;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-body);
  animation: wsCtxIn .1s ease-out;
}
.ws-format-bar {
  display: flex;
  gap: .1rem;
  padding: .2rem;
}
.ws-format-tool {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  border: 0;
  border-radius: var(--ws-radius-xs);
  background: transparent;
  color: var(--pg-fg-body);
  font-size: 1rem;
}
.ws-format-tool:hover {
  background: var(--pg-bg-2);
}
.ws-format-tool.active {
  background: rgba(var(--ws-accent-rgb), .15);
  color: rgba(var(--ws-accent-rgb), 1);
}
.ws-link-tip {
  width: min(24rem, calc(100vw - 16px));
  padding: .35rem;
}
.ws-link-tip .pg-input {
  min-width: 0;
}
.ws-link-tip :is(.pg-button, .pg-icon-button) {
  flex-shrink: 0;
}
/* The find tip of a writing box and the matches it paints. */
.ws-find-count {
  min-width: 3.5rem;
  text-align: center;
}
::highlight(ws-find) {
  background-color: rgba(var(--ws-accent-rgb), .2);
}
::highlight(ws-find-current) {
  background-color: rgba(var(--ws-accent-rgb), .55);
  color: var(--pg-fg-body);
}

/* The design windows: table, checklist, code. */
.ws-table-tools {
  position: sticky;
  top: calc(-1 * var(--bs-dialog-padding, 1rem));
  z-index: 2;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .15rem;
  margin: calc(-1 * var(--bs-dialog-padding, 1rem)) calc(-1 * var(--bs-dialog-padding, 1rem)) .6rem;
  padding: .45rem var(--bs-dialog-padding, 1rem);
  border-bottom: 1px solid var(--pg-border-color);
  background: var(--bs-dialog-bg, var(--pg-bg-body));
}
/* Under the title field the tools start in the flow, not over it. */
.ws-block-title-field + .ws-table-tools {
  margin-top: 0;
}
.ws-table-tools-gap {
  align-self: stretch;
  width: 1px;
  margin: .2rem .35rem;
  background: var(--pg-border-color);
}
.ws-tool-danger:hover:not(:disabled) {
  color: var(--pg-danger) !important;
}
.ws-table-edit-wrap {
  max-width: 100%;
  overflow: auto;
}
.table.ws-table-edit {
  width: auto;
  min-width: 100%;
  margin: 0;
  border: 1px solid var(--pg-border-color);
  font-size: .88rem;
}
.table.ws-table-edit > :not(caption) > * > * {
  min-width: 8rem;
  max-width: 24rem;
  padding: 0;
  vertical-align: top;
}
.ws-cell-edit {
  min-height: 2.1rem;
  padding: .4rem .6rem;
  outline: 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.ws-table-edit .ws-cell-edit:focus {
  background: var(--pg-bg-body);
  box-shadow: inset 0 0 0 2px rgba(var(--ws-accent-rgb), .55);
}
.ws-table-edit thead .ws-cell-edit {
  font-weight: 600;
}
.ws-check-edit {
  display: flex;
  flex-direction: column;
  gap: .1rem;
}
.ws-check-edit-row {
  display: flex;
  align-items: flex-start;
  gap: .35rem;
  padding: .1rem .25rem;
  border-radius: var(--ws-radius-sm);
}
.ws-check-edit-row:focus-within {
  background: var(--pg-bg-1);
}
.ws-check-edit-row > :is(.check, .radio) {
  flex-shrink: 0;
  margin: .6rem .15rem 0;
}
.ws-check-edit-row > .ws-cell-edit {
  flex: 1 1 auto;
  min-width: 0;
}
.ws-check-edit-row > .pg-icon-button {
  opacity: .45;
}
.ws-check-edit-row:hover > .pg-icon-button,
.ws-check-edit-row:focus-within > .pg-icon-button {
  opacity: 1;
}
.ws-code-language {
  max-width: 12rem;
}
.pg-input.ws-code-edit {
  min-height: 16rem;
  font-family: var(--pg-font-mono);
  font-size: .85rem;
  line-height: 1.5;
  white-space: pre;
  overflow: auto;
  tab-size: 4;
  resize: vertical;
}
/* iOS Safari zooms the page in when a field under 16px takes the focus and
   leaves it zoomed: on a touch screen the emoji search, the poll window's
   fields and the code and calculation areas are 16px. After .ws-code-edit,
   whose own size it has to outrank. */
@media (pointer: coarse) {
  .ws-emoji-search,
  #ws-poll-form .pg-input,
  .pg-input.ws-code-edit,
  .pg-input.ws-tip-touch {
    font-size: var(--pg-text-field-touch);
  }
}

/* A block of code in a message: its own box, scrolled inside rather than
   stretching the conversation. */
.ws-code {
  max-width: 100%;
  margin: .25rem 0 .35rem;
  overflow: hidden;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-1);
}
.ws-code-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .5rem;
  padding: .15rem .25rem .15rem .7rem;
  border-bottom: 1px solid var(--pg-border-color);
  font-size: .72rem;
  color: var(--pg-fg-2);
}
.ws-code-copy {
  border: 0;
  border-radius: var(--ws-radius-xs);
  background: transparent;
  color: inherit;
  padding: .2rem .4rem;
  line-height: 1;
}
.ws-code-copy:hover {
  background: var(--pg-bg-2);
  color: var(--pg-fg-body);
}
.ws-code-copy.copied {
  color: var(--pg-success);
}
.ws-code pre {
  max-height: 18rem;
  margin: 0;
  padding: .55rem .75rem;
  overflow: auto;
  font-size: .8rem;
  line-height: 1.5;
  white-space: pre;
  overflow-wrap: normal;
  tab-size: 4;
}
.ws-msg-body .ws-code code {
  padding: 0;
  border-radius: 0;
  background: transparent;
  font-size: inherit;
  white-space: inherit;
}

/* 16px keeps iOS from zooming in on the field when it is tapped. */
@media (pointer: coarse) {
  .ws-composer .ws-rich {
    font-size: 16px;
  }
}
@media (max-width: 767.98px) {
  .ws-composer .ws-rich {
    min-height: 2.5rem;
  }
  .ws-rich-block-text > span {
    max-width: 12rem;
  }
}
.ws-reply-bar {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: .8rem;
  color: var(--pg-fg-2);
  padding: 0 .25rem .3rem;
}
.ws-reply-bar span {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* A channel shared outside the team (guests.php): the people in the
   manage drawer, and the two ways it can be shared. */
.ws-bulk-reach {
  margin: .15rem 0 .25rem;
  font-size: .8rem;
}
.ws-bulk-progress {
  height: .45rem;
  margin: .4rem 0 .2rem;
}
.ws-share-row {
  padding: .6rem 0;
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-share-choice + .ws-share-choice {
  margin-top: .4rem;
}
/* Scheduled messages (scheduled_messages.php): the send button's second
   half, the line above the box that says some wait, and their cards. */
.ws-composer-tools > .ws-send-group {
  margin-left: auto;
}
.ws-sm-bar {
  display: flex;
  align-items: center;
  gap: .5rem;
  width: 100%;
  margin: 0 0 .35rem;
  padding: .3rem .6rem;
  border: 1px dashed rgba(var(--ws-accent-rgb), .45);
  border-radius: var(--ws-radius-sm);
  background: var(--ws-soft);
  color: var(--pg-fg-body);
  font-size: .8rem;
  text-align: left;
}
.ws-sm-bar:hover {
  border-style: solid;
}
.ws-sm-bar .bi {
  color: var(--ws-accent);
}
.ws-sm-bar-link {
  color: var(--ws-accent);
  font-weight: 600;
  white-space: nowrap;
}
.ws-sm-list {
  display: flex;
  flex-direction: column;
  gap: .6rem;
}
.ws-sm-card {
  padding: .6rem .75rem;
  border: 1px solid var(--pg-border-color);
  border-left: 3px solid var(--ws-accent);
  border-radius: var(--ws-radius);
  background: var(--pg-bg-body);
}
.ws-sm-card.ws-sm-failed {
  border-left-color: var(--pg-danger);
}
.ws-sm-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .4rem;
  font-size: .85rem;
}
.ws-sm-icon {
  color: var(--ws-accent);
}
.ws-sm-failed .ws-sm-icon {
  color: var(--pg-danger);
}
.ws-sm-where {
  color: var(--pg-fg-2);
  text-decoration: none;
}
.ws-sm-body {
  margin-top: .35rem;
}
.ws-sm-tools {
  display: flex;
  flex-wrap: wrap;
  gap: .15rem;
  margin-top: .4rem;
}
.ws-picker {
  position: absolute;
  left: 1rem;
  bottom: calc(100% - .25rem);
  z-index: 20;
  width: min(26rem, calc(100% - 2rem));
  max-height: 18rem;
  display: flex;
  flex-direction: column;
  background: var(--pg-bg-body);
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  box-shadow: 0 8px 24px rgba(0, 0, 0, .15);
  overflow: hidden;
}
/* The ; list of saved replies in the e-mail reply drawer
   (workspace_mail.js), under the answer: above it the drawer's top would
   cut it off. */
/* A written mail's writing box (workspace_mail.js mailText()): the
   height of the text area it replaces, its tools under it. */
.ws-mail-rich .ws-rich {
  min-height: 12rem;
}
.ws-mail-rich .ws-mail-rich-tools {
  margin-top: var(--ws-space-1, .25rem);
}
.ws-mail-reply-box .ws-picker {
  top: 100%;
  bottom: auto;
  left: 0;
  width: min(26rem, 100%);
}
/* Recipient suggestions under To, Cc and Bcc of New e-mail and the reply
   drawer (workspace_mail.js suggest()): the Workspace picker's list,
   opened under its field and as wide as it. */
.ws-mail-suggest-host {
  position: relative;
}
.ws-mail-suggest-host .ws-mail-suggest {
  top: calc(100% + .25rem);
  bottom: auto;
  left: 0;
  width: 100%;
}
.ws-mail-suggest .ws-picker-item {
  cursor: pointer;
}
/* The E-mails screen (workspace_mail.php): the list, and the reading pane
   beside it once a row is open; on a phone the pane takes the list's
   place. */
.ws-mail-toolbar-break {
  /* The toolbar's views start a line of their own: a filter or the search
     that wraps stays on the line above them. A break in the markup, not
     `order`, so the keyboard meets them where they are drawn. */
  flex: 0 0 100%;
  height: 0;
}
.ws-mail-columns {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--ws-space-3);
  align-items: start;
}
.ws-mail-reading .ws-mail-columns {
  grid-template-columns: minmax(16rem, 1fr) minmax(0, 2fr);
}
/* With the pane open a row keeps who, subject, first words and time; of
   its last line only a mail that did not leave stays said. */
.ws-mail-reading .ws-mail-row-meta > :not(.badge) {
  display: none;
}
.ws-mail-rows {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
  overflow: hidden;
}
.ws-mail-row {
  display: flex;
  flex-direction: column;
  gap: .1rem;
  padding: .55rem .75rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
  color: var(--pg-fg-body);
  text-decoration: none;
}
.ws-mail-row:last-child {
  border-bottom: 0;
}
.ws-mail-row:hover {
  background: var(--pg-bg-1);
}
.ws-mail-row[aria-current] {
  background: var(--ws-soft);
}
.ws-mail-row-head {
  display: flex;
  align-items: center;
  gap: .5rem;
  min-width: 0;
}
.ws-mail-who,
.ws-mail-subject,
.ws-mail-snippet {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-mail-who {
  flex: 1 1 auto;
}
.ws-mail-row .ws-mail-time {
  flex: 0 0 auto;
  font-size: .78rem;
  color: var(--pg-fg-2);
}
.ws-mail-snippet,
.ws-mail-row-meta {
  font-size: .8rem;
  color: var(--pg-fg-2);
}
.ws-mail-row-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .25rem .6rem;
}
/* A Drafts row's application pill: a long name is cut inside the row's
   width, never widening it; the whole sentence is in its title. */
.ws-mail-draft-app {
  max-width: 100%;
  min-width: 0;
}
.ws-mail-draft-app-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* Unread: the name and subject in bold, and a bar in the accent. */
.ws-mail-unread {
  box-shadow: inset 3px 0 0 var(--ws-accent);
}
.ws-mail-unread .ws-mail-who,
.ws-mail-unread .ws-mail-subject {
  font-weight: 600;
  color: var(--pg-fg-emphasis);
}
.ws-mail-overdue .ws-mail-time {
  color: var(--pg-danger);
}
.ws-mail-more {
  padding: .75rem 0;
  text-align: center;
}
.ws-mail-pane {
  position: sticky;
  top: var(--ws-space-3);
  max-height: calc(100vh - 8rem);
  overflow: auto;
  padding: .75rem 1rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-body);
}
.ws-mail-pane-head {
  margin-bottom: .75rem;
  padding-bottom: .5rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
/* The conversation's channel in the head (ws_mail_pane_channel_pill()): a
   status pill that is a link, so the link's underline shows only on hover
   and focus; a long name is cut inside the pane's width, never widening it,
   the whole words in its title. */
.ws-mail-pane-channel {
  max-width: 100%;
  min-width: 0;
  text-decoration: none;
}
.ws-mail-pane-channel-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-mail-pane-channel:is(:hover, :focus-visible) .ws-mail-pane-channel-text {
  text-decoration: underline;
}
.ws-mail-pane-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .35rem;
  margin-top: .5rem;
}
.ws-mail-item {
  margin-bottom: .6rem;
  padding: .6rem .75rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
}
.ws-mail-item.ws-mail-out {
  background: var(--pg-bg-1);
}
/* Block sender's choices (mail_blocks.php): on a phone a choice wraps to a
   second line rather than being cut, so the address and the domain stay
   apart; a long address breaks anywhere. */
.ws-mail-block .pg-seg-item {
  height: auto;
  min-height: 26px;
  padding-block: 4px;
  white-space: normal;
  overflow-wrap: anywhere;
  text-align: start;
}
/* The blocked senders on the Mailboxes card: the value is the row, so it
   breaks onto a second line instead of ending in an ellipsis. */
.ws-mail-blocks .pg-list-row-title {
  white-space: normal;
  overflow-wrap: anywhere;
}
/* A rule's line on the same card breaks the same way. */
.ws-mail-rules .pg-list-row-title {
  white-space: normal;
  overflow-wrap: anywhere;
}
/* The Add rule form of the incoming mail rules: its fields side by side on
   a wide card, one under another on a phone; the button sits on their line.
   A select is as wide as its longest choice, so "The sender's domain is" is
   read whole (five equal 10rem columns cut it), and the address field takes
   what is left. */
.ws-mail-rule-add {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
  align-items: flex-end;
}
.ws-mail-rule-add > div {
  flex: 1 1 10rem;
  min-width: 0;
}
.ws-mail-rule-add > div:has(> select) {
  flex: 0 1 auto;
}
.ws-mail-rule-add > div > select {
  width: auto;
  max-width: 100%;
}
.ws-mail-rule-add > .ws-mail-rule-add-end {
  flex: 0 0 auto;
}
@media (max-width: 575.98px) {
  .ws-mail-rule-add > div:not(.ws-mail-rule-add-end) {
    flex-basis: 100%;
  }
  .ws-mail-rule-add > div > select {
    width: 100%;
  }
}
.ws-mail-item-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: .35rem;
}
.ws-mail-item-head .ws-mail-time {
  margin-inline-start: auto;
}
.ws-mail-text {
  margin-top: .5rem;
  overflow-wrap: anywhere;
}
/* A mail's HTML in its guarded frame (mail_pane.php
   ws_mail_pane_body_html()): white in both themes, as mail is written for
   white; its height follows the mail once the frame reports it
   (workspace_mail.js). */
.ws-mail-body {
  margin-top: .5rem;
}
.ws-mail-body-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .25rem .5rem;
  margin-bottom: .35rem;
}
.ws-mail-frame {
  display: block;
  width: 100%;
  height: 12rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
  background: #fff;
  color-scheme: light;
}
.ws-mail-frame[hidden],
.ws-mail-body .ws-mail-text[hidden],
.ws-mail-pictures[hidden] {
  display: none;
}
/* New e-mail (workspace_mail.js newForm()): the Signature as the mail
   carries it, its lines kept; the chosen files under the picker. */
.ws-mail-new-signature {
  margin-top: .5rem;
}
.ws-mail-new-signature-text {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  padding-inline-start: .75rem;
  border-inline-start: 2px solid var(--pg-border-color);
}
.ws-mail-new-cc-toggle {
  margin: -.75rem 0 1rem;
}
.ws-mail-new-files .text-truncate {
  min-width: 0;
}
@media (max-width: 767.98px) {
  .ws-mail-reading .ws-mail-columns {
    grid-template-columns: minmax(0, 1fr);
  }
  .ws-mail-reading .ws-mail-list {
    display: none;
  }
  /* While a mail is read the toolbar and its filters fold away (the id
     outranks #button_bar's own display rule): they stood
     about 490 px above the pane, so the mail began below the first screen.
     The pane's Close brings the list and the toolbar back. */
  .ws-mail-reading > #button_bar.pg-toolbar,
  .ws-mail-reading > .ws-mail-check-line {
    display: none;
  }
  .ws-mail-pane {
    position: static;
    max-height: none;
    padding: .5rem;
  }
  /* The pane's and each mail's paddings left a mail about 260 px of a
     375 px screen. */
  .ws-mail-pane .ws-mail-item {
    padding: .5rem;
  }
}
/* On touch the conversation's channel pill is a 32 px link, as the pane's
   other tools; the 22 px status pill stays under a mouse. */
@media (pointer: coarse) {
  .ws-mail-pane-channel {
    min-height: 2rem;
  }
}
/* The "/" list of a note's inserts, under the caret. */
.ws-picker.ws-slash {
  position: fixed;
  bottom: auto;
  width: 15rem;
  z-index: 1080;
}
/* The @ and # list of a formatted box, at the caret: placePicker() in
   workspace.js measures it at this width, then sets its left, top, width
   and height so it stays inside the field's column and the window. */
.ws-picker.ws-picker-caret {
  position: fixed;
  right: auto;
  bottom: auto;
  width: min(26rem, calc(100vw - 1rem));
}
/* One row of kinds that scrolls sideways inside the list's width: there
   are too many to wrap. */
.ws-picker-types {
  display: flex;
  flex-wrap: nowrap;
  gap: .25rem;
  padding: .4rem;
  border-bottom: 1px solid var(--pg-border-color);
  overflow-x: auto;
  scrollbar-width: thin;
}
.ws-picker-types button {
  flex: 0 0 auto;
  white-space: nowrap;
  border: 1px solid var(--pg-border-color);
  background: transparent;
  border-radius: 999px;
  font-size: .75rem;
  padding: .05rem .55rem;
  color: var(--pg-fg-body);
}
.ws-picker-types button.active {
  background: var(--pg-primary);
  border-color: var(--pg-primary);
  color: #fff;
}
.ws-picker-list {
  overflow-y: auto;
  padding: .25rem;
}
.ws-picker-item {
  display: flex;
  align-items: center;
  gap: .5rem;
  width: 100%;
  border: 0;
  background: transparent;
  text-align: left;
  border-radius: var(--ws-radius-xs);
  padding: .35rem .5rem;
  color: var(--pg-fg-body);
}
.ws-picker-item.active,
.ws-picker-item:hover {
  background: color-mix(in srgb, var(--pg-primary) 12%, transparent);
}
.ws-picker-item .avatar {
  --bs-avatar-size: 1.5rem;
}
.ws-picker-item .ws-picker-emoji {
  flex: 0 0 1.5rem;
  font-size: 1.25rem;
  line-height: 1;
  text-align: center;
}
.ws-picker-item .ws-picker-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: .88rem;
}
.ws-picker-item .ws-picker-meta {
  font-size: .75rem;
  color: var(--pg-fg-2);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 45%;
}
/* A flow of the "/" list or of /flow's list: the name is what the row is
   for, so "Start this flow" gives way first (it shrinks long before the
   name is cut) and goes on a phone. */
.ws-picker-flow-row .ws-picker-label {
  flex-shrink: .001;
}
.ws-picker-flow-row .ws-picker-meta {
  flex: 0 1000 auto;
  min-width: 0;
  margin-left: auto;
}
@media (max-width: 575.98px) {
  .ws-picker-flow-row .ws-picker-meta {
    display: none;
  }
}
/* A label with a second line under it (a slash command and its example). */
.ws-picker-item .ws-picker-text {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-width: 0;
}
.ws-picker-item .ws-picker-detail {
  font-size: .72rem;
  color: var(--pg-fg-2);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* A group's header in the "/" list (commandPickerGroups()): a muted line
   as /help's group header, never picked, so no hover and no pointer. */
.ws-picker-group {
  padding: .5rem .5rem .2rem;
  font-size: .75rem;
  font-weight: 550;
  color: var(--pg-fg-2);
  cursor: default;
  user-select: none;
}
.ws-picker-group:first-child {
  padding-top: .25rem;
}
/* A registry agent in the @ menu: its icon with the state mark in the
   corner, its name cut before its role, and the usage mark of a window at
   90% or more. */
.ws-picker-agent {
  position: relative;
  display: inline-grid;
  place-items: center;
  flex: none;
}
.ws-picker-agent .ws-agent-dot {
  position: absolute;
  right: -4px;
  bottom: -3px;
}
.ws-picker-item .ws-picker-meta-role {
  display: inline-flex;
  min-width: 0;
}
.ws-picker-meta-role > span {
  flex: none;
  white-space: pre;
}
.ws-picker-meta-role > .ws-picker-meta-name {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-picker-item .ws-picker-usage {
  flex: none;
  height: 18px;
  padding: 0 7px 0 6px;
  font-size: .7rem;
}
/* An agent's state mark, the one map of the plan for the menu and the
   message: working a blue dot, waiting an amber dot, not seen an amber
   square, paused a grey square; ready draws none. Tones of the agents
   panel; the square tells not seen from waiting without words. */
.ws-agent-dot {
  display: inline-block;
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--pg-tone, var(--pg-tone-gray));
  box-shadow: 0 0 0 2px var(--pg-bg-body);
}
.ws-agent-dot.is-late,
.ws-agent-dot.is-paused {
  border-radius: 2px;
}
.ws-agent-dot.is-working { --pg-tone: var(--pg-tone-blue); }
.ws-agent-dot.is-waiting,
.ws-agent-dot.is-late { --pg-tone: var(--pg-tone-amber); }
.ws-agent-dot.is-paused { --pg-tone: var(--pg-tone-gray); }
.ws-picker-empty {
  padding: .6rem .75rem;
  font-size: .85rem;
  color: var(--pg-fg-2);
}
/* The argument popup after a command picks no row by itself; the row Tab
   writes carries a mark, and the keys are named under the list. */
.ws-picker-item.ws-picker-next {
  box-shadow: inset 2px 0 0 var(--pg-primary);
}
.ws-picker-keys {
  padding: .25rem .65rem;
  border-top: 1px solid var(--pg-border-color);
  font-size: .72rem;
  color: var(--pg-fg-2);
}
/* Above the composer while a command is written: its usage, the argument
   expected now highlighted, and its example. */
.ws-cmd-strip {
  display: flex;
  align-items: baseline;
  gap: .75rem;
  min-width: 0;
  margin: 0 0 .35rem;
  padding: .2rem .6rem;
  font-size: .78rem;
  color: var(--pg-fg-2);
  border: 1px dashed var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
}
.ws-cmd-usage {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--pg-font-mono);
}
.ws-cmd-name {
  color: var(--pg-fg-body);
  font-weight: 600;
}
.ws-cmd-current {
  color: var(--pg-fg-body);
  background: color-mix(in srgb, var(--pg-primary) 14%, transparent);
  border-radius: var(--ws-radius-xs);
  padding: 0 .2rem;
  font-weight: 600;
}
.ws-cmd-example {
  flex: 1 1 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: right;
}
@media (max-width: 575.98px) {
  .ws-cmd-example {
    display: none;
  }
}
.ws-help-usage {
  font-size: .8em;
}
.ws-preview {
  border: 1px solid color-mix(in srgb, var(--pg-primary) 40%, transparent);
  background: color-mix(in srgb, var(--pg-primary) 6%, transparent);
  border-radius: var(--ws-radius-sm);
  padding: .6rem .75rem;
  margin: 0 0 .5rem;
  font-size: .88rem;
}
.ws-preview dl {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  gap: .15rem .75rem;
  margin: .35rem 0;
}
.ws-preview dt {
  font-weight: 600;
  color: var(--pg-fg-2);
}
.ws-preview dd {
  margin: 0;
}
/* The /create row card: a text column's box is one line high at rest and
   grows with its lines up to eight where the browser can, scrolling past
   them. The recipe's box (textarea.pg-input) is placed here, not changed. */
.ws-row-card textarea.pg-input.ws-row-text {
  min-height: 0;
  max-height: calc(8lh + 20px);
  /* One line as high as the card's other fields (36 px). */
  padding-block: calc((36px - 1lh - 2px) / 2);
  field-sizing: content;
  overflow-y: auto;
}
.ws-warning {
  display: flex;
  gap: .4rem;
  align-items: flex-start;
  font-size: .85rem;
  margin: .2rem 0;
}
.ws-warning.ws-warning-hard {
  color: var(--pg-danger-fg-emphasis);
}
.ws-warning.ws-warning-warning {
  color: var(--pg-warning-fg-emphasis);
}
.ws-warning.ws-warning-info {
  color: var(--pg-fg-2);
}
.ws-ephemeral {
  border: 1px dashed var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  padding: .6rem .75rem;
  margin: .5rem 0;
  font-size: .88rem;
  background: var(--pg-bg-1);
}
.ws-ephemeral-title {
  font-weight: 700;
  margin-bottom: .35rem;
}
.ws-help dt {
  margin-top: .35rem;
}
.ws-help dd {
  margin: 0 0 .2rem;
}
.ws-plan-mini th {
  padding-right: .75rem;
  font-weight: 600;
  white-space: nowrap;
}
.ws-plan-mini td {
  padding: .1rem .5rem .1rem 0;
}
.ws-load {
  display: inline-block;
  min-width: 3rem;
  text-align: center;
  font-size: .75rem;
  font-weight: 700;
  border-radius: var(--ws-radius-xs);
  padding: 0 .3rem;
}
.ws-load-ok {
  background: color-mix(in srgb, var(--pg-success) 15%, transparent);
  color: var(--pg-success-fg-emphasis);
}
.ws-load-full {
  background: color-mix(in srgb, var(--pg-warning) 22%, transparent);
  color: var(--pg-warning-fg-emphasis);
}
.ws-load-over {
  background: color-mix(in srgb, var(--pg-danger) 18%, transparent);
  color: var(--pg-danger-fg-emphasis);
}
.ws-load-away {
  background: var(--pg-bg-2);
  color: var(--pg-fg-2);
}
.ws-empty {
  text-align: center;
  color: var(--pg-fg-2);
  padding: 2.5rem 1rem;
}
.ws-empty i {
  font-size: 2rem;
  display: block;
  margin-bottom: .5rem;
}
/* An empty list with a drawing (emptyState() in workspace.js): the shapes
   take their colours from .pg-tour-art (pg_tour.css); here only the size. */
.ws-empty-friendly {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--ws-space-2);
  padding: var(--ws-space-4) var(--ws-space-3);
}
.ws-empty-friendly .ws-empty-art {
  width: 7.5rem;
  max-width: 100%;
  margin: 0;
  background: none;
}
.ws-empty-line {
  max-width: 22rem;
  font-size: .9rem;
}
.ws-empty-side {
  padding: var(--ws-space-2) var(--ws-space-2) var(--ws-space-3);
}
.ws-empty-side .ws-empty-art {
  width: 5rem;
}
.ws-empty-side .ws-empty-line {
  font-size: .8rem;
}
/* Rows standing in for what is loading (skeleton() in workspace.js, the
   first one in workspace.php). */
.ws-skeleton {
  display: flex;
  flex-direction: column;
  gap: var(--ws-space-3);
  width: 100%;
  max-width: 36rem;
  padding: var(--ws-space-4);
}
.ws-skeleton-row {
  display: flex;
  align-items: center;
  gap: var(--ws-space-3);
}
.ws-skeleton-dot,
.ws-skeleton-bar {
  display: block;
  background: var(--pg-bg-2);
}
.ws-skeleton-dot {
  flex: 0 0 auto;
  width: var(--ws-avatar);
  height: var(--ws-avatar);
  border-radius: 50%;
}
.ws-skeleton-bar {
  height: .75rem;
  width: 70%;
  border-radius: var(--ws-radius-xs);
}
.ws-skeleton-row:nth-child(3n) .ws-skeleton-bar { width: 52%; }
.ws-skeleton-row:nth-child(3n+1) .ws-skeleton-bar { width: 84%; }
.ws-skeleton-sm {
  gap: var(--ws-space-2);
  padding: var(--ws-space-1) 0;
}
.ws-skeleton-sm .ws-skeleton-dot {
  width: var(--ws-avatar-xs);
  height: var(--ws-avatar-xs);
}
.ws-skeleton-sm .ws-skeleton-bar {
  height: .55rem;
}
/* The first rows and a start-up error fill the whole channel screen, not
   only the column of the channel list. */
.ws-app > .ws-boot {
  grid-column: 1 / -1;
  align-self: start;
  justify-self: center;
}
@media (prefers-reduced-motion: no-preference) {
  .ws-skeleton-dot,
  .ws-skeleton-bar {
    background: linear-gradient(90deg, var(--pg-bg-2) 25%, var(--pg-bg-1) 50%, var(--pg-bg-2) 75%);
    background-size: 200% 100%;
    animation: ws-skeleton-shine 1.4s ease-in-out infinite;
  }
  .ws-empty-friendly .ws-empty-art {
    animation: ws-empty-in .35s ease-out both;
  }
}
@keyframes ws-skeleton-shine {
  from { background-position: 100% 0; }
  to { background-position: -100% 0; }
}
@keyframes ws-empty-in {
  from { opacity: 0; transform: translateY(.35rem); }
  to { opacity: 1; transform: none; }
}
/* Small motions: the Send button pops when a message goes, a reaction chip
   bounces when left or taken back, a message that arrives slides in. The
   classes are set by playMotion() in workspace.js. */
@media (prefers-reduced-motion: no-preference) {
  .ws-pop {
    animation: ws-pop .32s ease-out;
  }
  .ws-react.ws-bounce {
    animation: ws-bounce .45s ease-out;
  }
  .ws-msg-in {
    animation: ws-msg-in .25s ease-out backwards;
  }
}
@keyframes ws-pop {
  35% { transform: scale(.9); }
  70% { transform: scale(1.08); }
  to { transform: none; }
}
@keyframes ws-bounce {
  30% { transform: translateY(-.25rem) scale(1.12); }
  60% { transform: translateY(0) scale(.95); }
  80% { transform: scale(1.03); }
  to { transform: none; }
}
@keyframes ws-msg-in {
  from { opacity: 0; transform: translateY(.5rem); }
  to { opacity: 1; transform: none; }
}
.ws-summary-view {
  max-width: 52rem;
  line-height: 1.6;
}
/* The Summary tab (drawSummary()): the summary a card with Edit in its head,
   the customer and the time spent in a column beside it while the pane is
   wide enough, under it when it is not. The card fills its column; the text
   inside keeps the 52rem reading width of .ws-summary-view. */
.ws-pane-summary {
  container-type: inline-size;
}
.ws-summary-layout {
  display: grid;
  grid-template-columns: minmax(0, 3fr) minmax(0, 2fr);
  align-items: start;
  gap: .75rem;
}
.ws-summary-layout.ws-summary-alone {
  grid-template-columns: minmax(0, 1fr);
}
@container (max-width: 48rem) {
  .ws-summary-layout {
    grid-template-columns: minmax(0, 1fr);
  }
}
.ws-summary-side {
  display: flex;
  flex-direction: column;
  gap: .75rem;
  min-width: 0;
}
.ws-summary-layout .card {
  border-radius: .875rem;
}
/* The Memory tab (workspace_memory.js): in an agent channel the general
   memory and the channel's own as two parts, each a card of project
   headings that fold, one row per record under each. */
.ws-memory {
  display: flex;
  flex-direction: column;
  gap: .75rem;
  container-type: inline-size;
}
.ws-memory-part {
  border: 1px solid var(--pg-border-color);
  border-radius: .875rem;
  background: var(--pg-card-bg);
  overflow: hidden;
}
.ws-memory-part-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .75rem;
  padding: .75rem .9rem;
}
.ws-memory-part-head > div {
  flex: 1 1 20rem;
}
.ws-memory-part-title {
  margin: 0;
}
.ws-memory-part > .ws-empty {
  margin: 0 .9rem .9rem;
}
/* The search box over both parts; the parts under it keep the gap. */
.ws-memory-results {
  display: flex;
  flex-direction: column;
  gap: .75rem;
}
.ws-memory-bar .ws-bar-search {
  min-width: 0;
  flex: 0 1 18rem;
}
.ws-memory-more {
  padding: .55rem .9rem;
  border-top: 1px solid var(--pg-border-color);
}
.ws-memory-project {
  border-top: 1px solid var(--pg-border-color);
}
.ws-memory-project-head {
  display: flex;
  align-items: center;
  gap: .5rem;
  padding: .55rem .9rem;
  font-weight: var(--pg-weight-strong);
  cursor: pointer;
  list-style: none;
}
.ws-memory-project-head::-webkit-details-marker {
  display: none;
}
.ws-memory-chevron {
  transition: transform .15s ease;
}
.ws-memory-project[open] .ws-memory-chevron {
  transform: rotate(90deg);
}
.ws-memory-row {
  display: grid;
  grid-template-columns: 1.25rem minmax(0, 1fr) auto auto auto;
  align-items: center;
  gap: .75rem;
  padding: .5rem .9rem .5rem 1.75rem;
  border-top: 1px solid var(--pg-border-color);
}
.ws-memory-row:hover {
  background: var(--pg-hover);
}
.ws-memory-expired {
  opacity: .75;
}
.ws-memory-name {
  font-weight: var(--pg-weight-strong);
  overflow-wrap: anywhere;
}
.ws-memory-line {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-memory-tags {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: .25rem;
  max-width: 16rem;
}
.ws-memory-date {
  white-space: nowrap;
}
.ws-memory-actions {
  display: flex;
  gap: .25rem;
}
@container (max-width: 40rem) {
  .ws-memory-row {
    grid-template-columns: 1.25rem minmax(0, 1fr) auto;
    padding-left: .9rem;
  }
  .ws-memory-tags,
  .ws-memory-date {
    grid-column: 2;
    justify-content: flex-start;
    max-width: none;
  }
  .ws-memory-actions {
    grid-column: 3;
    grid-row: 1;
  }
}
/* An empty channel pane (Tasks, Decisions, Files, Notes, Summary, Board,
   Memory) shows its empty state in a dashed card. Other screens' .ws-empty
   (Today, My tasks, the kit's panels) keep their own look. */
.ws-pane:is(.ws-pane-tasks, .ws-pane-decisions, .ws-pane-files, .ws-pane-notes, .ws-pane-summary, .ws-pane-board, .ws-pane-memory) .ws-empty {
  border: 1px dashed var(--pg-border-color);
  border-radius: .875rem;
  background: var(--pg-card-bg);
}
.ws-list-row {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .55rem .75rem;
  border-bottom: 1px solid var(--pg-border-color);
  cursor: pointer;
}
.ws-list-row:hover {
  background: var(--pg-bg-1);
}
.ws-list-row .ws-grow {
  flex: 1 1 auto;
  min-width: 0;
}
.ws-list-row .ws-row-title {
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-list-row .ws-row-sub {
  font-size: .8rem;
  color: var(--pg-fg-2);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-list-row.ws-row-done .ws-row-title {
  text-decoration: line-through;
  color: var(--pg-fg-2);
}
/* My Tasks (workspace_my_tasks.js): the open tasks under date labels that
   fold, each task a .pg-list-row of one line (the Mark done circle, the
   number, the title; the due text, the priority pill and the initials at
   the right), a second line only for the agent channel, the application
   that made it and the progress. On a phone the title takes its own line. */
.ws-mt-list {
  padding: 6px;
}
.ws-mt-group + .ws-mt-group {
  margin-top: 4px;
}
.ws-mt-group-head {
  margin: 0;
  font: inherit;
}
.ws-mt-group-toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px 4px;
  border: 0;
  border-radius: 8px;
  background: none;
  cursor: pointer;
}
.ws-mt-group-toggle:hover {
  color: var(--pg-fg-body);
}
.ws-mt-group-toggle:focus-visible {
  outline: 2px solid var(--pg-accent);
  outline-offset: 0;
}
.ws-mt-row {
  align-items: flex-start;
  cursor: pointer;
}
.ws-mt-row:focus-visible {
  outline: 2px solid var(--pg-accent);
  outline-offset: -2px;
}
.ws-mt-done {
  flex: none;
  margin: -4px -2px -4px -4px;
  color: var(--pg-fg-3);
}
.ws-mt-done.is-still {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
}
.ws-mt-done > .ws-mt-done-tick,
button.ws-mt-done:hover > .bi-circle,
button.ws-mt-done:focus-visible > .bi-circle {
  display: none;
}
button.ws-mt-done:hover > .ws-mt-done-tick,
button.ws-mt-done:focus-visible > .ws-mt-done-tick {
  display: inline-block;
}
button.ws-mt-done:hover,
button.ws-mt-done:focus-visible,
.ws-mt-done > .bi-check-circle-fill {
  color: var(--pg-tone-teal);
}
.ws-mt-head {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 20px;
}
.ws-mt-number {
  margin-right: 6px;
  color: var(--pg-fg-3);
  font-weight: var(--pg-weight-regular);
  font-variant-numeric: tabular-nums;
}
.ws-mt-meta {
  display: flex;
  flex: none;
  align-items: center;
  gap: 8px;
}
.ws-mt-due {
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
  white-space: nowrap;
}
.ws-mt-due.is-late {
  color: var(--pg-tone-rose-text);
}
.ws-mt-people.ws-avatars .avatar {
  --bs-avatar-size: 22px;
}
.ws-mt-sub {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 12px;
  margin-top: 2px;
  color: var(--pg-fg-2);
  font-size: var(--pg-text-meta);
}
.ws-mt-sub-part {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}
@media (max-width: 575.98px) {
  .ws-mt-head {
    flex-wrap: wrap;
    row-gap: 4px;
  }
  .ws-mt-head > .ws-mt-name {
    flex-basis: 100%;
  }
}
/* "Add a task…" above the groups of the Mine view: the field of the
   Design examples (a .pg-input label holding its icon and a bare input),
   the keys' one line of help while it has the focus, and a refusal under
   it in place of that line. The help names Tab, so a phone leaves it out. */
.ws-mt-add {
  padding: 12px 12px 6px;
}
.ws-mt-add-icon {
  color: var(--pg-fg-3);
}
.ws-mt-add-hint {
  display: none;
}
.ws-mt-add:focus-within:not(.is-refused) > .ws-mt-add-hint {
  display: block;
}
@media (max-width: 575.98px) {
  .ws-mt-add:focus-within:not(.is-refused) > .ws-mt-add-hint {
    display: none;
  }
}
/* A task opened to read in the task drawer (workspace_task_read.js): the
   number and the status control in the head, the title changed in place,
   value rows with a 132 px label column, each opening its picker under its
   value, the description with its checklist, the parts as fold rows. On a
   phone a Back arrow takes Close's place and a picker is a bottom sheet. */
.ws-tr .drawer-header {
  gap: 10px;
  min-height: 56px;
  padding: 0 12px 0 20px;
}
.ws-tr .drawer-header .drawer-title {
  flex: none;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-2);
  font-weight: var(--pg-weight-strong);
  font-variant-numeric: tabular-nums;
}
.ws-tr .ws-tr-back {
  display: none;
}
.ws-tr-head-end {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}
.ws-tr-saved {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-right: 4px;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
}
.ws-tr-anchor,
.ws-tr-row-wrap {
  position: relative;
}
.ws-tr-status {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 28px;
  padding: 0 9px 0 10px;
  border: 0;
  border-radius: 14px;
  background: color-mix(in srgb, var(--pg-tone, var(--pg-tone-gray)) var(--pg-tint-to), transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pg-tone, var(--pg-tone-gray)) var(--pg-tint-line), transparent);
  color: color-mix(in srgb, var(--pg-tone, var(--pg-tone-gray)) 70%, var(--pg-fg-emphasis));
  font-size: var(--pg-text-2);
  font-weight: var(--pg-weight-strong);
  white-space: nowrap;
}
.ws-tr-status:disabled {
  opacity: 1;
}
.ws-tr-status:disabled > .ws-tr-caret {
  display: none;
}
.ws-tr-status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--pg-tone, var(--pg-tone-gray));
}
.ws-tr-caret {
  font-size: var(--pg-text-count);
}
.ws-tr-status[aria-expanded="true"] {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pg-tone, var(--pg-tone-gray)) 45%, transparent), 0 0 0 3px color-mix(in srgb, var(--pg-tone, var(--pg-tone-gray)) 16%, transparent);
}
.ws-tr .drawer-body {
  padding: 0;
}
.ws-tr-title-wrap {
  position: relative;
  margin: 14px 20px 8px;
}
.ws-tr-title {
  display: block;
  width: calc(100% + 18px);
  margin: -6px -9px;
  padding: 6px 9px;
  overflow: hidden;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--pg-fg-body);
  font-size: var(--pg-text-record-title);
  font-weight: var(--pg-weight-title);
  line-height: 28px;
  letter-spacing: -0.018em;
  resize: none;
  field-sizing: content;
}
textarea.ws-tr-title:hover {
  border-color: var(--pg-field-line);
}
textarea.ws-tr-title:focus {
  border-color: var(--pg-accent);
  outline: 0;
  background: var(--pg-field-bg);
  box-shadow: var(--pg-field-shadow), 0 0 0 4px color-mix(in srgb, var(--pg-accent) 24%, transparent);
}
.ws-tr-hint {
  display: none;
  margin-top: 8px;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
}
.ws-tr-title-wrap.is-changing:focus-within > .ws-tr-hint {
  display: block;
}
.ws-tr-rows {
  margin: 4px 20px 0;
}
.ws-tr-row-wrap + .ws-tr-row-wrap {
  border-top: 1px solid var(--pg-border-color-translucent);
}
.ws-tr-row {
  position: relative;
  display: grid;
  grid-template-columns: 132px minmax(0, 1fr) auto;
  column-gap: 12px;
  align-items: center;
  width: 100%;
  min-height: 44px;
  padding: 5px 0;
  border: 0;
  background: none;
  color: var(--pg-fg-body);
  font-size: var(--pg-text-base);
  text-align: start;
}
.ws-tr-row::before {
  content: "";
  position: absolute;
  inset: 3px -8px;
  z-index: 0;
  border-radius: 10px;
}
.ws-tr-row > * {
  position: relative;
}
button.ws-tr-row:hover::before,
.ws-tr-row-wrap.is-open > .ws-tr-row::before {
  background: var(--pg-hover);
}
button.ws-tr-row:focus-visible {
  outline: 0;
}
button.ws-tr-row:focus-visible::before {
  box-shadow: 0 0 0 2px var(--pg-accent);
}
.ws-tr-k {
  color: var(--pg-fg-2);
  font-size: var(--pg-text-2);
}
.ws-tr-v {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;
  min-width: 0;
  font-weight: var(--pg-weight-medium);
}
.ws-tr-v.is-none,
.ws-tr-quiet {
  color: var(--pg-fg-3);
  font-weight: var(--pg-weight-regular);
}
.ws-tr-v.is-busy {
  color: var(--pg-fg-3);
}
.ws-tr-v.is-late {
  color: var(--pg-tone-rose-text);
}
.ws-tr-pen,
.ws-tr-chev {
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
  opacity: 0;
}
.ws-tr-chev {
  display: none;
}
button.ws-tr-row:hover > .ws-tr-pen,
button.ws-tr-row:focus-visible > .ws-tr-pen {
  opacity: 1;
}
.ws-tr-row-wrap.is-open .ws-tr-pen {
  display: none;
}
.ws-tr-row-wrap.is-open .ws-tr-chev {
  display: inline;
  opacity: 1;
}
.ws-tr-people,
.ws-tr-person {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px 12px;
}
.ws-tr-person {
  gap: 7px;
}
.ws-tr-person > .avatar {
  --pg-avatar-size: 24px;
  width: 24px;
  height: 24px;
}
.ws-tr-dot {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.ws-tr-dot::before {
  content: "";
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--pg-tone, var(--pg-tone-gray));
}
.ws-tr-link {
  color: var(--pg-accent);
  text-decoration: none;
}
.ws-tr-link:hover {
  text-decoration: underline;
}
.ws-tr-why {
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding: 0 0 5px 144px;
  color: var(--pg-tone-rose-text);
  font-size: var(--pg-text-meta);
}
.ws-tr-title-wrap > .ws-tr-why,
.ws-tr-desc > .ws-tr-why {
  padding-left: 0;
  margin-top: 8px;
}
.ws-tr-spin {
  flex: none;
  width: 13px;
  height: 13px;
  margin-left: auto;
  border: 2px solid color-mix(in srgb, var(--pg-fg-3) 35%, transparent);
  border-top-color: var(--pg-accent);
  border-radius: 50%;
  animation: ws-tr-spin 0.8s linear infinite;
}
@keyframes ws-tr-spin {
  to {
    transform: rotate(360deg);
  }
}
/* The picker under a value: 242 px, never wider than the drawer. */
.ws-tr-pick {
  position: absolute;
  top: calc(100% - 4px);
  left: 144px;
  z-index: 6;
  width: 242px;
  max-width: calc(100% - 144px);
  max-height: 360px;
  overflow: auto;
  padding: 5px;
  border-radius: 12px;
  background: var(--pg-surface-1);
  box-shadow: var(--pg-shadow-float), 0 0 0 1px var(--pg-border-color-translucent);
  color: var(--pg-fg-body);
}
.ws-tr-pick.is-wide {
  left: 0;
  width: 100%;
  max-width: none;
  max-height: none;
  padding: 12px;
}
.ws-tr-anchor > .ws-tr-pick {
  top: calc(100% + 6px);
  left: 0;
  max-width: none;
}
.ws-tr-scrim {
  display: none;
}
.ws-tr-opt {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 34px;
  padding: 0 10px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--pg-fg-body);
  font-size: var(--pg-text-base);
  text-align: start;
}
.ws-tr-opt:hover,
.ws-tr-opt:focus-visible,
.ws-tr-opt.is-on {
  outline: 0;
  background: var(--pg-hover);
}
.ws-tr-opt:focus-visible {
  box-shadow: inset 0 0 0 2px var(--pg-accent);
}
.ws-tr-opt-check {
  margin-left: auto;
  color: var(--pg-accent);
  visibility: hidden;
}
.ws-tr-opt.is-on > .ws-tr-opt-check {
  visibility: visible;
}
.ws-tr-opt-text {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.ws-tr-search {
  margin: 2px 0 4px;
}
.ws-tr-month {
  padding: 8px 6px 4px;
}
.ws-tr-month-head {
  display: flex;
  align-items: center;
  gap: 2px;
  margin-bottom: 6px;
}
.ws-tr-month-head > b {
  flex: 1;
  font-weight: var(--pg-weight-strong);
}
.ws-tr-days {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
  text-align: center;
}
.ws-tr-wd {
  color: var(--pg-fg-3);
  font-size: var(--pg-text-count);
}
.ws-tr-day {
  height: 30px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--pg-fg-body);
  font-size: var(--pg-text-2);
  font-variant-numeric: tabular-nums;
}
.ws-tr-day.is-out {
  color: var(--pg-fg-3);
}
.ws-tr-day:hover {
  background: var(--pg-hover);
}
.ws-tr-day.is-today {
  box-shadow: inset 0 0 0 1.5px var(--pg-accent);
}
.ws-tr-day.is-on {
  background: linear-gradient(180deg, var(--pg-accent-1), var(--pg-accent-2));
  color: var(--pg-on-accent-fill);
  font-weight: var(--pg-weight-strong);
}
.ws-tr-day:focus-visible {
  outline: 2px solid var(--pg-accent);
  outline-offset: 1px;
}
.ws-tr-pick-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--pg-border-color-translucent);
}
.ws-tr-time {
  width: 96px;
}
.ws-tr-time-label {
  color: var(--pg-fg-2);
  white-space: nowrap;
  font-size: var(--pg-text-2);
}
.ws-tr-clear {
  margin-left: auto;
}
.ws-tr-pick-label {
  margin: 4px 4px 0;
  color: var(--pg-fg-2);
  font-size: var(--pg-text-2);
}
.ws-tr-hosted {
  margin: 0;
}
.ws-tr-hosted > .ws-when-head,
.ws-tr-hosted > .row:first-of-type {
  display: none;
}
.ws-tr-label {
  display: flex;
  align-items: center;
  min-height: 28px;
  margin-bottom: 4px;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
  font-weight: var(--pg-weight-strong);
}
.ws-tr-desc {
  margin: 16px 20px 0;
  font-size: var(--pg-text-base);
}
.ws-tr-desc-text .ws-checklist {
  margin: 4px 0 0;
  padding: 0;
  list-style: none;
}
.ws-tr-desc-text .ws-check {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 32px;
}
.ws-tr-desc-text .ws-check.is-busy {
  opacity: 0.55;
}
.ws-tr-desc-text .ws-check > label {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.ws-tr-desc-text .ws-check-who {
  margin-left: auto;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-count);
  white-space: nowrap;
}
.ws-tr-add {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 32px;
  color: var(--pg-fg-3);
}
.ws-tr-add > .bi {
  width: 18px;
  text-align: center;
}
.ws-tr-add-input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: none;
  color: var(--pg-fg-body);
  font-size: var(--pg-text-base);
}
.ws-tr-add:focus-within {
  box-shadow: inset 0 -1px 0 var(--pg-accent);
}
.ws-tr-progress {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 24px;
  margin-top: 6px;
  color: var(--pg-fg-2);
  font-size: var(--pg-text-meta);
}
.ws-tr-progress > .progress {
  flex: none;
  width: 96px;
}
.ws-tr-folds {
  margin: 16px 20px 0;
  border-top: 1px solid var(--pg-border-color-translucent);
}
.ws-tr-fold {
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-tr-fold-head {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 48px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--pg-fg-body);
  font-size: var(--pg-text-base);
  font-weight: var(--pg-weight-strong);
  text-align: start;
}
.ws-tr-fold-head:focus-visible {
  outline: 2px solid var(--pg-accent);
  outline-offset: -2px;
  border-radius: 8px;
}
.ws-tr-fold-icon {
  width: 18px;
  color: var(--pg-fg-3);
  text-align: center;
}
.ws-tr-fold-state {
  margin-left: auto;
  color: var(--pg-fg-2);
  font-size: var(--pg-text-meta);
  font-weight: var(--pg-weight-regular);
  white-space: nowrap;
}
.ws-tr-fold-chev {
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
  transition: transform 0.15s;
}
.is-open > .ws-tr-fold-head > .ws-tr-fold-chev,
.ws-tr-more.is-open .ws-tr-fold-chev {
  transform: rotate(180deg);
}
.ws-tr-fold-body {
  padding: 0 0 16px 28px;
  font-size: var(--pg-text-2);
}
.ws-tr-fold-body > * {
  margin: 0;
  padding: 0;
  border: 0;
}
.ws-tr-fold-body .ws-task-time-head,
.ws-tr-fold-body > .ws-task-links > .ws-task-links-head:first-child,
.ws-tr-fold-body > .ws-task-approvals > .ws-task-links-head:first-child,
.ws-tr-fold-body .ws-task-notes-head,
.ws-tr-fold-body > .ws-plan-field > .pg-field-label,
.ws-tr-fold-body > .mb-5 > .pg-field-label {
  display: none;
}
.ws-tr-made {
  margin: 14px 20px 20px;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
}
/* New task: five fields, the rest under "More". */
.ws-tr-more {
  margin-bottom: 16px;
  border-radius: 12px;
  background: var(--pg-surface-inset);
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
}
.ws-tr-more-head {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 12px 14px;
  border: 0;
  background: none;
  color: var(--pg-fg-body);
  text-align: start;
}
.ws-tr-more-text {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}
.ws-tr-more-name {
  font-weight: var(--pg-weight-strong);
}
.ws-tr-more-line {
  color: var(--pg-fg-2);
  font-size: var(--pg-text-2);
}
.ws-tr-more-body {
  padding: 0 14px 14px;
}
@media (max-width: 575.98px) {
  .ws-tr .drawer-header .btn-close {
    display: none;
  }
  .ws-tr .ws-tr-back {
    display: inline-grid;
    width: 44px;
    height: 44px;
    margin-left: -12px;
  }
  .ws-tr-status {
    height: 36px;
    border-radius: 18px;
  }
  .ws-tr-row {
    grid-template-columns: 104px minmax(0, 1fr) auto;
  }
  .ws-tr-why {
    padding-left: 116px;
  }
  .ws-tr-desc-text .ws-check,
  .ws-tr-add {
    min-height: 44px;
  }
  .ws-tr-scrim {
    position: fixed;
    inset: 0;
    z-index: 5;
    display: block;
    background: var(--pg-scrim);
  }
  .ws-tr-pick,
  .ws-tr-pick.is-wide,
  .ws-tr-anchor > .ws-tr-pick {
    position: fixed;
    top: auto;
    right: 0;
    bottom: 0;
    left: 0;
    width: auto;
    max-width: none;
    max-height: 80vh;
    padding: 16px;
    border-radius: 16px 16px 0 0;
  }
  .ws-tr-day {
    height: 44px;
  }
  .ws-tr-opt {
    min-height: 44px;
  }
}

/* The channel's Tasks tab (drawTasks()): a quiet toolbar row, then each
   task a card; the cards flow in columns as the decisions do, one on a
   phone. A record's window draws the same .ws-list-row as a list and keeps
   it. */
.ws-pane-toolbar {
  padding: 0;
  border-bottom: 0;
}
.ws-task-grid {
  columns: var(--ws-flow-col);
  column-gap: 1rem;
}
.ws-task-grid > .ws-empty {
  column-span: all;
}
.ws-task-grid > .ws-list-row {
  break-inside: avoid;
  gap: .6rem;
  min-width: 0;
  margin: 0 0 1rem;
  padding: .8rem 1rem;
  border: 1px solid var(--pg-border-color);
  border-radius: 1rem;
  background: var(--pg-card-bg);
  box-shadow: var(--ws-shadow-soft);
}
.ws-task-grid > .ws-list-row:hover {
  border-color: rgba(var(--ws-accent-rgb), .45);
  background: var(--pg-card-bg);
}
.ws-task-grid > .ws-list-row.ws-row-done {
  opacity: .75;
}
.ws-status-dot {
  width: .65rem;
  height: .65rem;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--pg-primary);
}
.ws-status-dot.ws-s-doing {
  background: var(--pg-info);
}
.ws-status-dot.ws-s-waiting {
  background: var(--pg-warning);
}
.ws-status-dot.ws-s-done {
  background: var(--pg-success);
}
.ws-status-dot.ws-s-cancelled {
  background: var(--pg-secondary);
}
.ws-people-select {
  display: flex;
  flex-wrap: wrap;
  gap: .35rem;
  max-height: 12rem;
  overflow-y: auto;
  padding: .25rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--pg-radius);
}
.ws-person-toggle {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  border: 1px solid var(--pg-border-color);
  background: transparent;
  border-radius: 999px;
  padding: .1rem .55rem .1rem .15rem;
  font-size: .82rem;
  color: var(--pg-fg-body);
}
.ws-person-toggle .avatar {
  --bs-avatar-size: 1.4rem;
}
.ws-person-toggle.active {
  border-color: var(--ws-accent);
  background: rgba(var(--ws-accent-rgb), .14);
  font-weight: 600;
}
.ws-refs-field {
  display: flex;
  flex-wrap: wrap;
  gap: .35rem;
  align-items: center;
}
.ws-refs-field .ws-chip button {
  border: 0;
  background: transparent;
  color: inherit;
  padding: 0 0 0 .15rem;
  line-height: 1;
}
.ws-ref-search-box {
  position: relative;
}
.ws-ref-search-box .ws-picker {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(100% + .25rem);
  bottom: auto;
  width: auto;
}

/* The planning board: people down the side, days across. */
.ws-board-wrap {
  overflow-x: auto;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius);
  background: var(--pg-bg-body);
  box-shadow: 0 1px 2px rgba(0, 0, 0, .04), 0 10px 30px -14px rgba(0, 0, 0, .16);
}
.ws-board {
  display: grid;
  /* The grid's real minimum: an 11rem person column and seven 7rem days
     (workspace.js); a larger grid would scroll inside the wrapper. */
  min-width: 60rem;
}
.ws-board-cell,
.ws-board-head,
.ws-board-person {
  border-right: 1px solid var(--pg-border-color);
  border-bottom: 1px solid var(--pg-border-color);
  min-width: 0;
}
.ws-board-head {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--pg-bg-1);
  font-size: .8rem;
  font-weight: 700;
  padding: .45rem .5rem;
  text-align: center;
}
/* The corner above the names stays put both ways. */
.ws-board > .ws-board-head:first-child {
  left: 0;
  z-index: 3;
}
.ws-board-head.ws-today {
  color: var(--ws-accent);
  box-shadow: inset 0 -2px 0 var(--ws-accent);
}
.ws-board-cell:hover {
  background: var(--ws-soft);
}
.ws-board-head.ws-weekend,
.ws-board-cell.ws-weekend {
  background: var(--pg-bg-1);
}
.ws-board-person {
  position: sticky;
  left: 0;
  z-index: 1;
  background: var(--pg-bg-body);
  display: flex;
  align-items: center;
  gap: .5rem;
  padding: .45rem .6rem;
  font-size: .85rem;
}
.ws-board-person .avatar {
  --bs-avatar-size: 1.9rem;
}
.ws-board-person .ws-grow {
  min-width: 0;
}
.ws-board-person b {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-board-person small {
  color: var(--pg-fg-2);
}
.ws-board-cell {
  position: relative;
  padding: .3rem .3rem 1.4rem;
  min-height: 5rem;
}
.ws-board-cell.ws-drop {
  background: color-mix(in srgb, var(--pg-primary) 10%, transparent);
}
.ws-board-cell.ws-cell-away {
  background: repeating-linear-gradient(135deg, var(--pg-bg-1), var(--pg-bg-1) 6px, var(--pg-bg-body) 6px, var(--pg-bg-body) 12px);
}
.ws-board-bar {
  position: absolute;
  left: .3rem;
  right: .3rem;
  bottom: .35rem;
  height: .5rem;
  border-radius: 999px;
  background: var(--pg-bg-2);
  overflow: hidden;
}
.ws-board-bar span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--pg-success);
}
.ws-board-bar.ws-bar-full span {
  background: var(--pg-warning);
}
.ws-board-bar.ws-bar-over span {
  background: var(--pg-danger);
}
.ws-board-pct {
  position: absolute;
  right: .35rem;
  bottom: .9rem;
  font-size: .68rem;
  color: var(--pg-fg-2);
}
.ws-board-item {
  display: block;
  width: 100%;
  border: 0;
  text-align: left;
  font-size: .75rem;
  line-height: 1.3;
  border-radius: var(--ws-radius-xs);
  padding: .15rem .35rem;
  margin-bottom: .2rem;
  background: color-mix(in srgb, var(--pg-primary) 12%, transparent);
  color: var(--pg-fg-body);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: grab;
}
.ws-board-item.ws-item-due {
  font-weight: 700;
}
/* "Made by <application>" on a board card, under its title. */
.ws-board-item .ws-board-made-by {
  display: block;
  font-size: var(--pg-text-meta);
  font-weight: 400;
  color: var(--pg-fg-2);
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-board-item.ws-item-urgent {
  box-shadow: inset 3px 0 0 var(--pg-danger);
}
.ws-board-item.ws-item-event {
  background: color-mix(in srgb, var(--pg-info) 15%, transparent);
  cursor: pointer;
}
.ws-board-item.ws-item-leave {
  background: var(--pg-bg-2);
  color: var(--pg-fg-2);
  cursor: pointer;
}
/* A coming copy of a repeating task: where it will run, not handed out yet. */
.ws-board-item.ws-item-upcoming {
  background: transparent;
  border: 1px dashed color-mix(in srgb, var(--pg-primary) 45%, transparent);
  color: var(--pg-fg-2);
  font-weight: 400;
  cursor: pointer;
}
.ws-board-item.ws-item-upcoming.ws-item-due {
  font-weight: 600;
}
/* A coming copy waiting for an overdue one: it comes only if that is done. */
.ws-board-item.ws-item-upcoming.ws-item-waits {
  border-color: color-mix(in srgb, var(--pg-warning) 75%, transparent);
  opacity: .75;
}
.ws-board-add {
  position: absolute;
  top: .15rem;
  right: .15rem;
  border: 0;
  background: transparent;
  color: var(--pg-fg-2);
  opacity: 0;
  width: 1.4rem;
  height: 1.4rem;
  border-radius: var(--ws-radius-xs);
}
.ws-board-cell:hover .ws-board-add,
.ws-board-add:focus {
  opacity: 1;
}
.ws-board-add:hover {
  background: var(--pg-bg-2);
}
/* The plan board's legend dots. Not .ws-swatch: that is the colour picker's
   button (above), and a second rule under the same name overrode its size,
   shape and centring. */
.ws-legend-swatch {
  display: inline-block;
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 999px;
  line-height: 1;
}
.ws-swatch-ok {
  background: var(--pg-success);
}
.ws-swatch-full {
  background: var(--pg-warning);
}
.ws-swatch-over {
  background: var(--pg-danger);
}
.ws-swatch-away {
  background: repeating-linear-gradient(135deg, var(--pg-bg-2), var(--pg-bg-2) 3px, var(--pg-bg-body) 3px, var(--pg-bg-body) 6px);
  border: 1px solid var(--pg-border-color);
}
.ws-conflict {
  display: flex;
  gap: .5rem;
  align-items: flex-start;
  padding: .4rem 0;
  border-bottom: 1px solid var(--pg-border-color);
  font-size: .85rem;
}

/* The Workspace button and drawer on other screens. */
.ws-record-drawer .ws-record-section {
  margin-bottom: 1.25rem;
}
.ws-record-drawer .ws-record-title {
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  color: var(--pg-fg-2);
  margin-bottom: .4rem;
}
.ws-record-item {
  display: block;
  padding: .45rem .5rem;
  border-radius: var(--ws-radius-xs);
  text-decoration: none;
  color: var(--pg-fg-body);
  font-size: .85rem;
}
.ws-record-item:hover {
  background: var(--pg-bg-1);
}
.ws-record-item small {
  display: block;
  color: var(--pg-fg-2);
}
/* The record's fields, edited in the drawer (quick_edit.php). */
.ws-qe-glance {
  display: flex;
  flex-wrap: wrap;
  gap: .25rem .75rem;
}
.ws-qe-glance-item {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}
.ws-qe-form .ws-sa-field {
  margin-bottom: .5rem;
}
.ws-qe-form .ws-sa-field .form-label {
  margin-bottom: .15rem;
}
.ws-side-card .card-body {
  padding: .75rem;
}


/* ── Files: pictures, video, sound, PDF, and the rest ── */
.ws-image-link {
  display: inline-block;
  position: relative;
  cursor: zoom-in;
  text-decoration: none;
  border-radius: var(--ws-radius-sm);
}
.ws-image-link .ws-image-name {
  display: block;
  font-size: .72rem;
  color: var(--pg-fg-2);
  margin-top: .2rem;
  max-width: 26rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-image-link:hover img {
  filter: brightness(.95);
}
.ws-media {
  max-width: min(28rem, 100%);
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
  overflow: hidden;
  background: var(--pg-bg-1);
}
.ws-media video {
  display: block;
  width: 100%;
  max-height: 18rem;
  background: #000;
}
.ws-media audio {
  display: block;
  width: 100%;
  padding: .4rem .5rem 0;
}
.ws-media-bar {
  display: flex;
  align-items: center;
  gap: .4rem;
  padding: .25rem .5rem;
  font-size: .78rem;
  color: var(--pg-fg-2);
}
/* Voice messages (assets/js/workspace_voice.js): the player every sound file
   is drawn with, and the recording row that stands in for the writing box
   while the microphone is on. */
.ws-voice {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ws-space-2);
  width: 22rem;
  max-width: 100%;
  padding: var(--ws-space-2) var(--ws-space-2) var(--ws-space-2) var(--ws-space-3);
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius);
  background: var(--pg-bg-1);
}
.ws-voice audio {
  display: none;
}
.ws-voice > .ws-voice-play {
  flex: 0 0 auto;
  width: var(--ws-avatar);
  height: var(--ws-avatar);
  padding: 0;
  border-radius: 50%;
  font-size: 1.1rem;
}
/* The name and the time keep at least 7rem: in a narrower player the
   buttons after them take the next line as one group, at its right. */
.ws-voice-main {
  flex: 1 1 7rem;
  min-width: 0;
}
.ws-voice-tools {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--ws-space-2);
  margin-left: auto;
}
.ws-voice-name {
  overflow: hidden;
  font-size: .8rem;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-voice-bar {
  position: relative;
  height: .3rem;
  margin: .3rem 0 .2rem;
  border-radius: 999px;
  background: var(--pg-border-color);
  cursor: pointer;
}
/* The played part; a recording's waveform draws its strokes instead
   (waveform() in workspace_voice.js), so the rule names the fill alone. */
.ws-voice-fill {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 0;
  border-radius: inherit;
  background: var(--ws-accent);
}
.ws-voice-time {
  font-size: .72rem;
  font-variant-numeric: tabular-nums;
  color: var(--pg-fg-2);
}
.ws-voice-tools > :is(.pg-button, .pg-icon-button) {
  flex: 0 0 auto;
}
.ws-voice .ws-voice-speed {
  min-width: 2.75rem;
  padding-inline: .35rem;
  font-variant-numeric: tabular-nums;
}
/* Convert to text (pg_voice_text.js): a small "Aa" in the player's row. */
.ws-voice .pg-voice-text-button {
  width: 1.9rem;
  height: 1.9rem;
  padding: 0;
  font-size: .75rem;
  font-weight: 700;
}
.ws-voice-error .ws-voice-bar {
  opacity: .4;
}
/* Calls (workspace_calls.js): the head's two buttons, the ringing card at
   the top right and the call window at the bottom right, both on the body,
   so a call stays while the person moves between channels. */
.ws-call-head {
  display: inline-flex;
  gap: var(--ws-space-1);
}
.ws-call-rings {
  position: fixed;
  top: calc(var(--pg-navbar-h, 3.5rem) + var(--ws-space-2));
  right: var(--ws-space-3);
  z-index: 1085;
  display: flex;
  flex-direction: column;
  gap: var(--ws-space-2);
  width: min(22rem, calc(100vw - 2rem));
}
.ws-call-ring,
.ws-call {
  box-shadow: var(--pg-shadow-lg);
}
.ws-call-ring {
  display: flex;
  flex-direction: column;
  gap: var(--ws-space-2);
  padding: var(--ws-space-3);
}
.ws-call-ring-text {
  display: flex;
  align-items: center;
  gap: var(--ws-space-2);
  font-weight: var(--pg-weight-strong);
}
.ws-call-ring-tools,
.ws-call-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--ws-space-1);
}
.ws-call {
  position: fixed;
  right: var(--ws-space-3);
  bottom: var(--ws-space-3);
  z-index: 1080;
  display: flex;
  flex-direction: column;
  gap: var(--ws-space-2);
  width: min(20rem, calc(100vw - 2rem));
  padding: var(--ws-space-2);
}
.ws-call.is-group {
  width: min(28rem, calc(100vw - 2rem));
}
/* The grid: one tile a member; of two, one's own picture sits small in
   the corner of the other's. The one speaking is ringed. */
.ws-call-stage {
  position: relative;
  display: grid;
  gap: var(--ws-space-1);
}
.ws-call-tile {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 4.5rem;
  overflow: hidden;
  border-radius: var(--pg-radius);
  background: var(--pg-bg-2);
  box-shadow: 0 0 0 2px transparent;
  transition: box-shadow .15s ease;
}
.ws-call[data-kind="video"] .ws-call-tile {
  aspect-ratio: 16 / 9;
}
.ws-call-tile.is-speaking {
  box-shadow: 0 0 0 2px var(--pg-success-fg-emphasis);
}
.ws-call-tile.is-lost {
  opacity: .5;
}
/* A raised hand and a weak connection, at the tile's top left. */
.ws-call-tile-marks {
  position: absolute;
  top: var(--ws-space-1);
  left: var(--ws-space-1);
  display: flex;
  gap: var(--ws-space-1);
}
.ws-call-tile-mark {
  display: inline-flex;
  align-items: center;
  padding: 0 var(--ws-space-1);
  border-radius: var(--pg-radius);
  background: var(--pg-bg-1);
  color: var(--pg-warning-fg-emphasis);
  font-size: var(--pg-text-meta);
}
.ws-call-tile-mark.is-weak {
  color: var(--pg-danger-fg-emphasis);
}
.ws-call-tile-mark[hidden] {
  display: none;
}
.ws-call-video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.ws-call-tile > .bi {
  font-size: var(--pg-text-figure);
  color: var(--pg-fg-2);
}
.ws-call[data-kind="voice"] .ws-call-video,
.ws-call-tile.is-camera-off .ws-call-video {
  visibility: hidden;
}
.ws-call[data-kind="video"] .ws-call-tile:not(.is-camera-off) > .bi {
  visibility: hidden;
}
.ws-call-tile-name {
  position: absolute;
  left: var(--ws-space-1);
  bottom: var(--ws-space-1);
  max-width: calc(100% - 2 * var(--ws-space-1));
  overflow: hidden;
  padding: 0 var(--ws-space-1);
  border-radius: var(--pg-radius);
  background: var(--pg-bg-1);
  font-size: var(--pg-text-meta);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-call-stage[data-count="2"],
.ws-call-stage[data-count="3"],
.ws-call-stage[data-count="4"] {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.ws-call[data-kind="video"] .ws-call-stage[data-count="2"] {
  grid-template-columns: minmax(0, 1fr);
}
.ws-call[data-kind="video"] .ws-call-stage[data-count="2"] .ws-call-tile.is-self {
  position: absolute;
  right: var(--ws-space-1);
  bottom: var(--ws-space-1);
  z-index: 1;
  width: 28%;
  min-height: 0;
}
.ws-call[data-kind="video"] .ws-call-stage[data-count="2"] .ws-call-tile.is-self .ws-call-tile-name {
  display: none;
}
.ws-call-bar {
  display: flex;
  align-items: center;
  gap: var(--ws-space-2);
  min-width: 0;
}
.ws-call-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  padding: 0;
  border: 0;
  background: none;
  color: var(--pg-fg-body);
  font-weight: var(--pg-weight-strong);
  text-align: start;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-call-name:hover {
  text-decoration: underline;
}
.ws-call-state {
  color: var(--pg-fg-2);
  font-variant-numeric: tabular-nums;
}
.ws-call.is-connected .ws-call-state {
  color: var(--pg-success-fg-emphasis);
}
.ws-call-devices {
  display: grid;
  gap: var(--ws-space-1);
}
.ws-call-devices[hidden] {
  display: none;
}
/* A shared screen: while another member shares, the window grows from its
   corner into the stage, the screen large (never cut: contain) and the
   tiles in a rail beside it; under 992px it covers the view, the tiles in
   one row under the screen. Made smaller, the screen takes the grid's
   place at card size, the tiles in one row under it. */
.ws-call-body {
  position: relative;
  display: grid;
  gap: var(--ws-space-1);
  min-height: 0;
}
.ws-call-share {
  position: relative;
  min-height: 0;
  overflow: hidden;
  border-radius: var(--pg-radius);
  background: var(--pg-bg-2);
  aspect-ratio: 16 / 9;
}
.ws-call-share[hidden] {
  display: none;
}
.ws-call-share:fullscreen {
  border-radius: 0;
  aspect-ratio: auto;
}
.ws-call-share-video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.ws-call-share-name {
  position: absolute;
  top: var(--ws-space-1);
  left: var(--ws-space-1);
  max-width: calc(100% - 7rem);
  overflow: hidden;
  padding: 0 var(--ws-space-1);
  border-radius: var(--pg-radius);
  background: var(--pg-bg-1);
  font-size: var(--pg-text-meta);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-call-share-tools {
  position: absolute;
  top: var(--ws-space-1);
  right: var(--ws-space-1);
  display: flex;
  gap: var(--ws-space-1);
  border-radius: var(--pg-radius);
  background: var(--pg-scrim);
}
.ws-call-notice {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ws-space-2);
  margin: 0;
}
.ws-call-notice[hidden] {
  display: none;
}
.ws-call-tile-name > .bi,
.ws-call-share-name > .bi {
  margin-inline-end: var(--ws-space-1);
}
.ws-call.is-showing .ws-call-stage[data-count] {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.ws-call.is-showing .ws-call-tile {
  min-height: 0;
  aspect-ratio: 16 / 9;
}
.ws-call.is-showing .ws-call-stage[data-count] .ws-call-tile.is-self {
  position: relative;
  right: auto;
  bottom: auto;
  z-index: auto;
  width: auto;
}
.ws-call.is-showing .ws-call-stage[data-count] .ws-call-tile.is-self .ws-call-tile-name {
  display: block;
}
/* Another share at the rail's end: a button that puts it on the stage;
   its screen shows in voice calls too and is never cut. */
.ws-call-tile.is-screen {
  width: 100%;
  padding: 0;
  border: 0;
  color: inherit;
  font: inherit;
  cursor: pointer;
}
.ws-call-tile.is-screen:focus-visible {
  outline: var(--pg-focus-ring-width) solid var(--pg-primary-ink);
  outline-offset: var(--pg-focus-ring-offset);
}
.ws-call-tile.is-screen .ws-call-video {
  visibility: visible;
  object-fit: contain;
}
.ws-call.is-stage {
  width: min(72rem, calc(100vw - 2rem));
  height: min(45rem, calc(100vh - 2rem));
}
.ws-call.is-stage .ws-call-body {
  flex: 1 1 auto;
  grid-template-columns: minmax(0, 1fr) 11rem;
}
.ws-call.is-stage .ws-call-share {
  aspect-ratio: auto;
}
.ws-call.is-stage .ws-call-stage[data-count] {
  grid-template-columns: minmax(0, 1fr);
  align-content: start;
  overflow-y: auto;
}
/* Made larger with nothing on the stage: the grid fills the window. A
   tile clicked is pinned large in the share's place, the others in the
   rail; one's own tile can be hidden on this screen. The head holds the
   size, full screen and the window's menu. */
.ws-call.is-stage:not(.is-showing) .ws-call-body {
  grid-template-columns: minmax(0, 1fr);
}
.ws-call.is-stage:not(.is-showing) .ws-call-stage[data-count] {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-auto-rows: minmax(0, 1fr);
  min-height: 0;
}
.ws-call.is-stage:not(.is-showing) .ws-call-stage[data-count="1"],
.ws-call[data-kind="video"].is-stage:not(.is-showing) .ws-call-stage[data-count="2"] {
  grid-template-columns: minmax(0, 1fr);
}
.ws-call.is-stage:not(.is-showing) .ws-call-tile {
  min-height: 0;
  aspect-ratio: auto;
}
.ws-call[data-kind="video"].is-stage:not(.is-showing) .ws-call-stage[data-count="2"] .ws-call-tile.is-self {
  aspect-ratio: 16 / 9;
}
.ws-call:fullscreen {
  border-radius: 0;
}
.ws-call-tile[hidden],
.ws-call-tile.is-pinned,
.ws-call-share > .bi[hidden],
.ws-call-share-tools > [hidden] {
  display: none;
}
.ws-call-tile-pin {
  position: absolute;
  inset: 0;
  padding: 0;
  border: 0;
  border-radius: inherit;
  background: none;
  cursor: pointer;
}
.ws-call-tile-pin:focus-visible {
  outline: var(--pg-focus-ring-width) solid var(--pg-primary-ink);
  outline-offset: calc(-1 * var(--pg-focus-ring-width));
}
.ws-call-tile-name,
.ws-call-tile-marks {
  z-index: 1;
  pointer-events: none;
}
.ws-call-share > .bi {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--pg-text-figure);
  color: var(--pg-fg-2);
}
.ws-call-bar .pg-icon-button {
  flex: 0 0 auto;
}
.ws-call-menu-wrap {
  position: relative;
  flex: 0 0 auto;
}
.ws-call-menu {
  top: 100%;
  right: 0;
  z-index: 2;
}
@media (max-width: 991.98px) {
  .ws-call.is-stage {
    inset: 0;
    width: auto;
    height: auto;
    border-radius: 0;
  }
  .ws-call.is-stage .ws-call-body {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr) auto;
  }
  .ws-call.is-stage .ws-call-stage[data-count] {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    overflow: visible;
  }
  .ws-call.is-stage.is-showing .ws-call-tile {
    height: 4.5rem;
    aspect-ratio: auto;
  }
}
/* A phone: at card size the window sits at the top under the panel's bar,
   across the width, so the writing box at the bottom stays free; it never
   runs off a short screen, and scrolls inside itself. On its side (a short
   landscape screen) it keeps to the right half, the conversation beside
   it. */
.ws-call:not(.is-stage) {
  max-height: calc(100dvh - 2 * var(--ws-space-3));
  overflow-y: auto;
}
@media (max-width: 575.98px) {
  .ws-call:not(.is-stage) {
    top: calc(var(--pg-navbar-h, 3.5rem) + .5rem + env(safe-area-inset-top));
    right: .5rem;
    bottom: auto;
    left: .5rem;
    width: auto;
    max-height: calc(100dvh - var(--pg-navbar-h, 3.5rem) - 1rem - env(safe-area-inset-top));
  }
}
@media (orientation: landscape) and (max-height: 500px) {
  .ws-call:not(.is-stage) {
    top: .5rem;
    right: max(.5rem, env(safe-area-inset-right));
    bottom: auto;
    left: auto;
    width: min(24rem, 48vw);
    max-height: calc(100dvh - 1rem);
  }
  .ws-call:not(.is-stage) .ws-call-stage[data-count="3"],
  .ws-call:not(.is-stage) .ws-call-stage[data-count="4"] {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
/* Popped out: the call window fills its small Picture-in-Picture window,
   which shows the tiles, Mute, camera and Hang up only. */
.ws-call-pip {
  margin: 0;
  overflow: hidden;
  background: var(--pg-bg-body);
}
.ws-call.is-popped,
.ws-call.is-popped.is-stage {
  position: static;
  inset: auto;
  width: 100%;
  height: 100vh;
  max-height: none;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}
.ws-call.is-popped .ws-call-body {
  flex: 1 1 auto;
  min-height: 0;
}
.ws-call.is-popped .ws-call-not-popped {
  display: none;
}
/* The head's Join button in a narrow head: its words give way first. */
@container (max-width: 40rem) {
  .ws-head-channel .ws-call-join {
    max-width: 9rem;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}
.ws-composer.ws-voice-recording > :not(.ws-voice-rec) {
  display: none;
}
.ws-voice-rec {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ws-space-2);
  min-height: 2.6rem;
  padding: 0 var(--ws-space-1);
}
.ws-voice-rec .ws-grow {
  flex: 1 1 auto;
}
.ws-voice-rec-hint {
  flex: 0 0 100%;
  padding-bottom: var(--ws-space-1);
  font-size: .8rem;
  color: var(--pg-fg-2);
}
.ws-voice-rec-dot {
  flex: 0 0 auto;
  width: .7rem;
  height: .7rem;
  border-radius: 50%;
  background: var(--pg-danger);
}
.ws-voice-rec-time {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.ws-voice-rec-cap {
  font-size: .8rem;
  font-variant-numeric: tabular-nums;
  color: var(--pg-fg-2);
}
.ws-voice-rec-ending .ws-voice-rec-time {
  color: var(--pg-danger);
}
@media (prefers-reduced-motion: no-preference) {
  .ws-voice-rec-dot {
    animation: ws-voice-rec-pulse 1.2s ease-in-out infinite;
  }
}
@keyframes ws-voice-rec-pulse {
  50% {
    opacity: .3;
  }
}
/* A narrow column (a discussion panel, a phone) keeps the file's name at
   least 8rem wide: the buttons then take the next line as one group, at
   its right. */
.ws-file-card {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .6rem;
  max-width: min(28rem, 100%);
  padding: .5rem .6rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-1);
}
.ws-file-card > .ws-grow {
  flex: 1 1 8rem;
  min-width: 0;
}
.ws-file-tools {
  display: flex;
  flex: none;
  align-items: center;
  gap: .6rem;
  margin-left: auto;
}
.ws-file-card .ws-file-name {
  display: block;
  font-size: .85rem;
  font-weight: 600;
  color: var(--pg-fg-body);
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* A file the channel shows (fileShowWay() in workspace.js): its name is a
   button that opens it, and a click anywhere on its card or row does too. */
.ws-file-shows {
  cursor: pointer;
}
button.ws-file-name,
button.ws-file-link {
  background: none;
  font-family: inherit;
  line-height: inherit;
  text-align: start;
  cursor: pointer;
}
button.ws-file-name {
  width: 100%;
  padding: 0;
  border: 0;
}
/* Preview and Download (fileAction()): under 576 px the icon alone, the
   word kept for a screen reader. */
@media (max-width: 575.98px) {
  .ws-file-act .pg-btn-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}
.ws-file-card .ws-file-ext,
.ws-file-row .ws-file-ext {
  min-width: 2.4rem;
  text-align: center;
  padding: .45rem .3rem;
  border-radius: var(--ws-radius-xs);
  background: rgba(var(--ws-accent-rgb), .14);
  color: var(--ws-accent);
}
.ws-file-card .ws-ext-pdf {
  background: color-mix(in srgb, var(--pg-danger) 14%, transparent);
  color: var(--pg-danger-fg-emphasis);
}
.ws-section-title {
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--pg-fg-2);
  margin: .5rem 0 .5rem;
}
/* An item shared by link (share_links.php): a quiet round link mark at
   the card's top right, inline in a Files tab row. */
.ws-share-host {
  position: relative;
}
.ws-share-mark {
  position: absolute;
  top: .35rem;
  right: .35rem;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 50%;
  border: 1px solid var(--pg-border-color-translucent);
  background: var(--pg-bg-1);
  color: var(--pg-fg-2);
}
/* A note card's menu button sits at its top right: the mark rides the
   card's corner, as on a file card. */
.ws-file-card.ws-share-host > .ws-share-mark,
.ws-cn-card.ws-share-host > .ws-share-mark {
  top: -.6rem;
  right: -.6rem;
}
.ws-share-mark.ws-share-mark-inline {
  position: static;
  flex: none;
}
/* The head's share menu (sharingButton()): a read row holds the kind icon,
   the name and its line, cut to the menu's width. */
.ws-sharing-menu {
  width: min(22rem, calc(100vw - 2rem));
}
.ws-sharing-row {
  display: flex;
  align-items: flex-start;
}
.ws-sharing-text {
  min-width: 0;
}
.ws-sharing-name,
.ws-sharing-line {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-sharing-line {
  white-space: normal;
}
/* Channel info's Sharing: a part's name over its rows, Stop sharing at a
   link row's right. */
.ws-info-sharing-part {
  margin-top: .5rem;
}
.ws-info-sharing-none {
  margin: 0;
  white-space: normal;
}
.ws-info-links .pg-button {
  flex: none;
}
.ws-share-address {
  display: flex;
  gap: .5rem;
  align-items: center;
}
.ws-share-address .pg-input {
  flex: 1 1 auto;
  min-width: 0;
}
.ws-gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(9.5rem, 1fr));
  gap: .6rem;
  margin-bottom: 1.25rem;
}
.ws-gallery-tile {
  position: relative;
  display: block;
  aspect-ratio: 4 / 3;
  padding: 0;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
  overflow: hidden;
  background: var(--pg-bg-1);
  cursor: zoom-in;
}
.ws-gallery-tile img,
.ws-gallery-tile video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .25s ease;
}
.ws-gallery-tile:hover img,
.ws-gallery-tile:hover video {
  transform: scale(1.04);
}
.ws-gallery-video {
  cursor: pointer;
}
.ws-gallery-play {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.2rem;
  color: rgba(255, 255, 255, .92);
  text-shadow: 0 2px 10px rgba(0, 0, 0, .45);
}
.ws-gallery-caption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  padding: 1.2rem .5rem .35rem;
  font-size: .7rem;
  color: #fff;
  text-align: left;
  background: linear-gradient(transparent, rgba(0, 0, 0, .62));
}
.ws-gallery-caption b,
.ws-gallery-caption span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-file-list {
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
  overflow: hidden;
}
.ws-file-row {
  display: flex;
  align-items: center;
  gap: .6rem;
  padding: .45rem .6rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-file-row:last-child {
  border-bottom: 0;
}
.ws-file-row .ws-file-link {
  border: 0;
  padding: 0;
  min-width: 0;
  max-width: 55%;
}
.ws-file-row .ws-file-meta {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-file-row audio {
  height: 2rem;
  max-width: 16rem;
}
/* The Files tab (drawFiles()): pictures, videos, sounds and documents each
   a card with its title and count at the top; inside, the gallery or the
   rows, with no rule between rows. */
.ws-pane-files {
  display: flex;
  flex-direction: column;
  gap: .75rem;
}
/* The Notes tab (PGWsChannelNotes.tab()): its bar, then the Files tab's
   rows with the note icon in place of the extension. The bar and the list
   stand apart by the Files tab's gap, and the search and Write a note by
   the toolbar's own. */
.ws-pane-notes {
  display: flex;
  flex-direction: column;
  gap: var(--ws-space-3, .75rem);
}
.ws-pane-notes .ws-cn-bar {
  flex-wrap: nowrap;
  gap: var(--ws-space-3, .75rem);
}
.ws-pane-notes .ws-cn-bar .ws-bar-search {
  min-width: 0;
  flex: 0 1 18rem;
}
.ws-cn-row .ws-file-link {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: none;
  color: inherit;
  text-align: start;
}
.ws-cn-row .ws-cn-row-icon {
  color: var(--ws-accent);
}
.ws-file-group {
  padding: .75rem .9rem;
  border: 1px solid var(--pg-border-color);
  border-radius: .875rem;
  background: var(--pg-card-bg);
}
.ws-file-group > .ws-section-title {
  margin-top: 0;
}
.ws-file-group > .ws-gallery {
  margin-bottom: 0;
}
/* The gallery is drawn a page at a time (FILE_PAGE in workspace.js); each
   tile keeps its 4 / 3 box before its picture arrives, so a page loading
   in moves nothing, and Show more under the grid draws the next page. */
.ws-gallery-tile img {
  display: block;
}
.ws-file-group > .ws-gallery-more {
  margin-top: .6rem;
}
/* The Files tab's next page from the server, under the last group. */
.ws-files-older {
  align-self: flex-start;
  margin-top: .6rem;
}
.ws-file-group .ws-file-list {
  border: 0;
  border-radius: 0;
}
.ws-file-group .ws-file-row {
  padding: .4rem .5rem;
  border-bottom: 0;
  border-radius: var(--ws-radius-xs);
}
.ws-file-group .ws-file-row:hover {
  background: var(--pg-bg-2);
}
.ws-preview-modal .dialog-body {
  background: #111;
  min-height: 60vh;
}
.ws-preview-frame {
  display: block;
  width: 100%;
  height: 78vh;
  border: 0;
  background: #fff;
}
.ws-preview-video {
  display: block;
  width: 100%;
  max-height: 80vh;
  background: #000;
}
.ws-preview-office {
  height: 78vh;
  background: var(--pg-bg-body);
}
/* "Save as data" (previewTableButton()): where the sheet goes, over the
   footer's own line. */
.ws-preview-table-form {
  display: flex;
  flex: 1 1 100%;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: .6rem;
}
.ws-preview-table-form > .ws-plan-field {
  flex: 1 1 16rem;
  min-width: 0;
}

/* ── Word and Excel previews (assets/js/pg_office_view.js) ──
   One look in the file manager's window and Quick Look and in the
   Workspace's preview: a workbook as tabs over a grid, a document as a
   page of text. */
.office-view {
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  font-size: .85rem;
  color: var(--pg-fg-body);
}
.office-view .empty-note {
  margin: auto;
}
.office-book {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-height: 0;
  position: relative;
}
.office-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: .25rem;
  padding: .4rem .5rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
  background: var(--pg-bg-1);
}
.office-tab {
  border: 1px solid transparent;
  border-radius: 999px;
  padding: .15rem .7rem;
  font: inherit;
  font-size: .8rem;
  color: var(--pg-fg-2);
  background: transparent;
}
.office-tab.active {
  color: var(--pg-fg-body);
  background: var(--pg-bg-body);
  border-color: var(--pg-border-color);
}
.office-tab-hidden {
  font-style: italic;
  opacity: .7;
}
/* A workbook whose sheets may change: its tab list is laid out in one strip
   with the add button. */
.office-tablist {
  display: contents;
}
.office-tab-add {
  border: 1px solid transparent;
  border-radius: 999px;
  padding: .15rem .6rem;
  font: inherit;
  font-size: .8125rem;
  color: var(--pg-fg-2);
  background: transparent;
}
.office-tab-add:hover {
  color: var(--pg-fg-body);
  background: var(--pg-bg-body);
}
.office-tab-input {
  width: 10rem;
  font-size: .8125rem;
}
/* The separator and character set a .csv is read with, above its sheet. */
.office-choice {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .4rem 1rem;
  padding: .4rem .5rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
  background: var(--pg-bg-1);
}
.office-choice-group {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .4rem;
}
.office-choice-problem {
  margin-top: 0;
}
.office-choice-problem:empty {
  display: none;
}
.office-pane {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  background: var(--pg-bg-body);
}
.office-sheet {
  border-collapse: separate;
  border-spacing: 0;
  table-layout: auto;
  min-width: 100%;
}
.office-sheet th,
.office-sheet td {
  border-right: 1px solid var(--pg-border-color-translucent);
  border-bottom: 1px solid var(--pg-border-color-translucent);
  padding: .15rem .45rem;
  white-space: pre;
  max-width: 24rem;
  overflow: hidden;
  text-overflow: ellipsis;
  vertical-align: top;
}
.office-sheet thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  text-align: center;
  font-weight: 600;
  color: var(--pg-fg-2);
  background: var(--pg-bg-1);
}
.office-sheet tbody th {
  position: sticky;
  left: 0;
  z-index: 1;
  text-align: right;
  font-weight: 500;
  color: var(--pg-fg-2);
  background: var(--pg-bg-1);
}
.office-sheet .office-corner {
  left: 0;
  z-index: 3;
}
.office-sheet .office-num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
/* A formula whose result the file does not hold: worked out by the
   spreadsheet program that opens it (includes/fn/office.php). */
.office-sheet td.office-calc::before {
  content: "\0192x";
  font-style: italic;
  color: var(--pg-fg-2);
  opacity: .7;
}
/* A workbook offered for editing (pg_office_view.js). */
.office-sheet[role="grid"] td {
  cursor: cell;
}
.office-sheet td.office-selected {
  box-shadow: inset 0 0 0 2px var(--pg-primary-ink);
}
.office-sheet td.office-edited {
  background: var(--pg-warning-bg-subtle);
}
/* The cells selected with Shift, for the format bar. */
.office-sheet td.office-in-range {
  box-shadow: inset 0 0 0 100vmax color-mix(in srgb, var(--pg-primary) 12%, transparent);
}
.office-sheet td.office-selected.office-in-range {
  box-shadow: inset 0 0 0 2px var(--pg-primary-ink), inset 0 0 0 100vmax color-mix(in srgb, var(--pg-primary) 12%, transparent);
}
/* The colour buttons of the format bar: the glyph over a 3 px bar in the
   selected cell's colour; the colours on offer as a grid in the editor's
   menu, the chosen one ringed. The swatches are file content, the same in
   both themes. */
.office-colour-button {
  flex-direction: column;
  gap: 1px;
}
.office-colour-bar {
  display: block;
  width: 1rem;
  height: 3px;
  border-radius: 1px;
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
}
.office-swatches {
  display: grid;
  grid-template-columns: repeat(5, 1.5rem);
  gap: .35rem;
  padding: .4rem .6rem .5rem;
}
.office-swatch {
  width: 1.5rem;
  height: 1.5rem;
  padding: 0;
  border: 1px solid var(--pg-border-color);
  border-radius: .35rem;
  cursor: pointer;
}
.office-swatch:focus-visible {
  outline: 2px solid var(--pg-primary);
  outline-offset: 1px;
}
.office-swatch.is-chosen {
  box-shadow: 0 0 0 2px var(--pg-bg-body), 0 0 0 4px var(--pg-primary-ink);
}
/* The format bar above an editable grid: look A's buttons and segmented
   controls in one line. */
.office-format {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .4rem;
  padding: .4rem .5rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
  background: var(--pg-bg-1);
}
/* A document's format bar holds its colour menus, placed under their
   button. */
.office-doc-format {
  position: relative;
}
/* The link window under a document bar's Link button: the address with
   its help, then Remove link, Cancel and Apply; floats over the page, kept
   inside the bar's width on a phone. */
.pg-card.office-link-window {
  position: absolute;
  z-index: 6;
  display: flex;
  flex-direction: column;
  gap: .35rem;
  width: min(22rem, calc(100% - 1rem));
  padding: .75rem;
  background: var(--pg-surface-float);
  box-shadow: var(--pg-shadow-float);
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);
}
.office-link-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .4rem;
  margin-top: .25rem;
}
.office-link-gap {
  flex: 1 1 auto;
}
/* The size grid under a document bar's Table button: the size pointed at
   above ten columns of squares, the rows growing as they are reached; the
   squares of the size chosen in the accent. */
.pg-card.office-table-window {
  width: auto;
}
.office-table-size {
  font-size: .75rem;
  font-weight: 600;
  color: var(--pg-fg-2);
}
.office-table-grid {
  display: grid;
  grid-template-columns: repeat(10, 1.25rem);
  gap: .2rem;
}
.office-table-cell {
  width: 1.25rem;
  height: 1.25rem;
  padding: 0;
  border: 1px solid var(--pg-border-color);
  border-radius: .2rem;
  background: var(--pg-bg-body);
}
.office-table-cell.is-on {
  border-color: var(--pg-primary);
  background: color-mix(in srgb, var(--pg-primary) 25%, transparent);
}
.office-table-cell:focus-visible {
  outline: 2px solid var(--pg-primary-ink);
  outline-offset: 1px;
}
/* The picture window under a document bar's Picture button in a channel:
   the channel's pictures as square tiles, Upload and Cancel below. */
.office-picture-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(4.5rem, 1fr));
  gap: .4rem;
  max-height: 16rem;
  overflow-y: auto;
  font-size: .8125rem;
  color: var(--pg-fg-2);
}
.office-picture-tile {
  aspect-ratio: 1;
  padding: 0;
  overflow: hidden;
  border: 1px solid var(--pg-border-color);
  border-radius: .35rem;
  background: var(--pg-bg-body);
}
.office-picture-tile img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.office-picture-tile:hover {
  border-color: var(--pg-primary);
}
.office-picture-tile:focus-visible {
  outline: 2px solid var(--pg-primary-ink);
  outline-offset: 1px;
}
@media (pointer: coarse) {
  /* Squares a finger can pick; ten still fit a 390 px screen. */
  .office-table-grid {
    grid-template-columns: repeat(10, 1.75rem);
  }
  .office-table-cell {
    width: 1.75rem;
    height: 1.75rem;
  }
}
/* The table controls of a document's bar, shown with the caret in a
   table. */
.office-table-tools {
  display: inline-flex;
  flex-wrap: wrap;
  gap: .4rem;
}
.office-table-tools[hidden] {
  display: none;
}
/* A link on a document being typed in, drawn as the page draws one and
   never followed: a click opens the link window. */
.office-paper .office-link {
  color: var(--pg-link-color);
  text-decoration: underline;
}
/* The paragraph style choice in a document's format bar. */
.office-format .office-kind {
  width: auto;
  max-width: 12rem;
}
/* The font size choice in a workbook's format bar. */
.office-format .office-size {
  width: auto;
}
/* A cell's border: a line along each side drawn, just inside the cell
   (a cell clips what passes its edge). File content drawn in the text
   colour of the theme, black on a cell drawn on paper (paint() in
   pg_office_view.js). */
.office-sheet td.office-bd {
  position: relative;
}
.office-sheet td.office-bd::after {
  content: "";
  position: absolute;
  inset: 0;
  border: 0 solid var(--pg-fg-emphasis);
  pointer-events: none;
}
.office-sheet td.office-bd-paper::after {
  color-scheme: light;
}
.office-sheet td.office-bd-l::after {
  border-left-width: 1px;
}
.office-sheet td.office-bd-r::after {
  border-right-width: 1px;
}
.office-sheet td.office-bd-t::after {
  border-top-width: 1px;
}
.office-sheet td.office-bd-b::after {
  border-bottom-width: 1px;
}
/* The tools over a workbook's grid: find in the workbook, the sheet's sort
   and filter with Clear, Download as CSV at the end. Wraps on a phone. */
.office-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .4rem .6rem;
  padding: .4rem .5rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
  background: var(--pg-bg-1);
}
.office-find {
  display: flex;
  align-items: center;
  gap: .25rem;
  flex: 1 1 14rem;
  max-width: 22rem;
  min-width: 0;
}
.office-find-field > .bi {
  color: var(--pg-fg-3);
}
.office-view-state:empty {
  display: none;
}
.office-tools .office-csv {
  margin-left: auto;
}
/* A match of the search, the current one ringed. */
.office-sheet td.office-found {
  box-shadow: inset 0 0 0 100vmax color-mix(in srgb, var(--pg-warning) 28%, transparent);
}
.office-sheet td.office-found-current {
  box-shadow: inset 0 0 0 2px var(--pg-warning), inset 0 0 0 100vmax color-mix(in srgb, var(--pg-warning) 28%, transparent);
}
/* The sort and filter marks on a column's head. */
.office-sheet .office-head-mark {
  margin-left: .2rem;
  font-size: .75em;
  color: var(--pg-primary);
}
/* A column's values to filter by: a long list scrolls in the menu, a long
   value is cut; the check shows on a value kept. */
.office-head-menu {
  max-height: min(60vh, 26rem);
  max-width: min(20rem, 92vw);
  overflow-y: auto;
}
.office-head-menu .menu-item > span:last-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.office-menu-check {
  visibility: hidden;
}
.office-head-menu [aria-checked="true"] > .office-menu-check {
  visibility: visible;
}
/* A row's or column's head opens its insert and delete menu; the head of a
   row or column inserted by a change waiting is drawn in the accent. */
.office-sheet .office-head {
  display: block;
  width: 100%;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: inherit;
  cursor: pointer;
}
.office-sheet .office-head:hover,
.office-sheet .office-head:focus-visible {
  color: var(--pg-primary);
}
.office-sheet .office-head-added {
  color: var(--pg-primary);
}
.office-head-menu {
  position: absolute;
  z-index: 5;
}
.office-sheet[role="grid"] td.office-locked {
  cursor: default;
  color: var(--pg-fg-2);
}
.office-sheet td.office-editing {
  padding: 0;
  overflow: visible;
  position: relative;
}
.office-editor {
  display: block;
  width: 100%;
  min-width: 10rem;
  margin: 0;
  padding: .15rem .45rem;
  border: 0;
  outline: 2px solid var(--pg-primary);
  outline-offset: -2px;
  font: inherit;
  line-height: inherit;
  white-space: pre;
  resize: none;
  overflow: hidden;
  color: var(--pg-fg-body);
  background: var(--pg-bg-body);
}
.office-status:empty {
  display: none;
}
.office-tab-edited::after {
  content: "";
  display: inline-block;
  width: .4rem;
  height: .4rem;
  margin-left: .35rem;
  border-radius: 50%;
  vertical-align: middle;
  background: var(--pg-warning);
}
.office-doc {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 1.25rem 1.5rem;
  line-height: 1.5;
  background: var(--pg-bg-body);
}
/* A Word document (renderDocument()) is drawn as a white sheet on the
   window's quiet ground: a page wide at most, its side margins those of a
   page, narrow on a phone. The sheet carries data-bs-theme="light", so its
   tokens are the light theme's in both: file content, like a mail's body. */
.office-doc-paged {
  container: office-doc / inline-size;
  padding: 1.5rem 1rem;
  background: var(--pg-bg-2);
}
.office-paper {
  box-sizing: border-box;
  width: 100%;
  max-width: 816px;
  min-height: 100%;
  margin: 0 auto;
  padding: 72px 96px;
  color: var(--pg-fg-body);
  background: var(--pg-bg-body);
  color-scheme: light;
  border-radius: .25rem;
  box-shadow: 0 0 0 1px var(--pg-border-color-translucent), 0 .25rem .75rem color-mix(in srgb, var(--pg-fg-body) 10%, transparent);
}
@container office-doc (max-width: 600px) {
  .office-paper {
    padding: 24px 16px;
  }
}
@media (max-width: 599.98px) {
  .office-doc-paged {
    padding: .5rem 0;
  }
  .office-paper {
    border-radius: 0;
  }
}
.office-doc h1, .office-doc h2, .office-doc h3, .office-doc h4, .office-doc h5, .office-doc h6 {
  margin: 1rem 0 .4rem;
  font-weight: 600;
}
.office-doc h1 { font-size: 1.5rem; }
.office-doc h2 { font-size: 1.25rem; }
.office-doc h3 { font-size: 1.1rem; }
.office-doc p {
  margin: 0 0 .6rem;
}
.office-doc blockquote {
  margin: .6rem 0;
  padding-left: .9rem;
  border-left: 3px solid var(--pg-border-color);
  color: var(--pg-fg-2);
}
.office-doc .office-list {
  margin: 0 0 .6rem;
  padding-left: 1.6rem;
}
.office-doc .office-lvl-1 { margin-left: 1.2rem; }
.office-doc .office-lvl-2 { margin-left: 2.4rem; }
.office-doc .office-lvl-3 { margin-left: 3.6rem; }
.office-doc .office-lvl-4, .office-doc .office-lvl-5, .office-doc .office-lvl-6, .office-doc .office-lvl-7, .office-doc .office-lvl-8 { margin-left: 4.8rem; }
/* A paragraph given another kind, shown so until the save draws it again:
   the heading sizes above, a list's mark before it, a list item's own
   mark taken off. */
.office-doc [data-kind] {
  font-size: 1em;
  font-weight: 400;
}
.office-doc li[data-kind] {
  list-style: none;
}
.office-doc [data-kind="heading1"] { font-size: 1.5em; font-weight: 650; }
.office-doc [data-kind="heading2"] { font-size: 1.25em; font-weight: 650; }
.office-doc [data-kind="heading3"] { font-size: 1.1em; font-weight: 650; }
.office-doc [data-kind="bullet"]::before { content: "\2022\00a0\00a0"; }
.office-doc [data-kind="number"]::before { content: "1.\00a0"; }
.office-doc .office-table {
  border-collapse: collapse;
  margin: .6rem 0;
  max-width: 100%;
}
.office-doc .office-table td {
  border: 1px solid var(--pg-border-color);
  padding: .25rem .5rem;
  vertical-align: top;
}
.office-doc .office-table td p:last-child {
  margin-bottom: 0;
}
/* A table put in on the page is drawn as the writer saves it: its columns
   share the text's width. */
.office-doc .office-added-table {
  width: 100%;
  table-layout: fixed;
}
.office-doc .office-img {
  max-width: 100%;
  height: auto;
}
.office-doc .office-tabchar {
  display: inline-block;
  min-width: 2em;
}
.office-doc .office-page {
  margin: 1.25rem 0;
  border: 0;
  border-top: 1px dashed var(--pg-border-color);
}
.office-doc .office-lost {
  color: var(--pg-fg-2);
  font-style: italic;
}
/* A presentation (pg_office_view.js): its slides as a list, each its
   title, text, pictures and speaker notes, without the slide's layout. */
.office-slides {
  list-style: none;
  margin: 0;
}
.office-slide {
  padding: 0 0 1rem;
  margin: 0 0 1rem;
  border-bottom: 1px solid var(--pg-border-color);
}
.office-slide:last-child {
  border-bottom: 0;
  margin-bottom: 0;
}
.office-doc .office-slide-title {
  margin-top: 0;
  font-size: 1.0625rem;
}
.office-slide-n {
  font-weight: 400;
}
.office-slide-hidden {
  margin-left: .5rem;
  font-size: .8125rem;
  font-weight: 400;
  font-style: italic;
  color: var(--pg-fg-2);
}
.office-doc .office-slide-text {
  margin: 0 0 .35rem;
  white-space: pre-wrap;
}
.office-doc .office-slide-row {
  tab-size: 4;
  font-variant-numeric: tabular-nums;
}
.office-slide-notes {
  margin-top: .6rem;
  padding: .5rem .75rem;
  border-left: 3px solid var(--pg-border-color);
  color: var(--pg-fg-2);
}
/* A document offered for editing (pg_office_view.js): a paragraph that
   may change is typed where it stands (contenteditable, .office-typing),
   with no box or ring; one that may not is picked and ringed. Spaces and
   line ends show as they are typed, and an empty one keeps a line. */
.office-doc [data-p] {
  border-radius: .2rem;
}
/* The preview frame clips (overflow: hidden), so a focused cell, paragraph
   or scrolling box wears the ring inset; .office-view outranks the global
   [tabindex] ring. */
.office-view .office-sheet td:focus-visible,
.office-view .office-doc [data-p]:focus-visible,
.office-view .office-pane:focus-visible,
.office-view .office-doc:focus-visible {
  outline: 2px solid var(--pg-primary-ink);
  outline-offset: -2px;
  box-shadow: none;
}
.office-doc-edit .office-para {
  cursor: text;
}
/* The sheet is the one place typed in: the caret shows where, no ring
   around the page. */
.office-view .office-paper.office-sheet-typing {
  outline: 0;
}
.office-doc-edit .office-typing {
  min-height: 1.5em;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  tab-size: 4;
  outline: 0;
}
.office-view .office-doc .office-typing:focus-visible {
  outline: 0;
}
.office-doc .office-selected:not(.office-typing) {
  box-shadow: 0 0 0 2px var(--pg-primary);
}
.office-doc .office-edited,
.office-doc-edit .office-edited:hover {
  background: var(--pg-warning-bg-subtle);
}
.office-doc-edit .office-locked {
  cursor: default;
}
/* A paragraph added in the editor keeps a line's height while empty; one
   to be deleted shows struck through until the save. */
.office-doc .office-added {
  min-height: 1.5em;
}
.office-doc .office-deleted {
  text-decoration: line-through;
  opacity: .55;
}
.office-note {
  padding: .5rem .75rem;
  font-size: .8rem;
  color: var(--pg-fg-2);
  border-top: 1px solid var(--pg-border-color-translucent);
}

/* Files dragged over a conversation. */
.ws-drop-overlay {
  position: absolute;
  inset: .5rem;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px dashed var(--ws-accent);
  border-radius: var(--ws-radius);
  background: rgba(var(--ws-accent-rgb), .1);
  backdrop-filter: blur(2px);
  pointer-events: none;
}
.ws-drop-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .25rem;
  text-align: center;
  color: var(--pg-fg-emphasis);
}
.ws-drop-inner .bi {
  font-size: 2.4rem;
  color: var(--ws-accent);
}
.ws-drop-inner small {
  color: var(--pg-fg-2);
  max-width: 22rem;
}

/* The channel's catch-up line (catchupNode()): what came while the reader
   was away, the way to it, the late tasks, Pinegrap AI's summary. */
.ws-catchup {
  margin: .5rem 1rem 0;
  border: 1px solid color-mix(in srgb, var(--ws-accent) 24%, transparent);
  border-radius: var(--ws-radius);
  background: color-mix(in srgb, var(--ws-accent) 7%, var(--pg-bg-body));
}
.ws-catchup-row {
  display: flex;
  align-items: center;
  gap: .5rem;
  min-height: 2.5rem;
  padding: .3rem .4rem .3rem .75rem;
}
.ws-catchup-icon {
  flex: 0 0 auto;
  color: var(--ws-accent);
}
.ws-catchup-text {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  color: var(--pg-fg-2);
  font-size: .85rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-catchup-text strong {
  color: var(--pg-fg-emphasis);
  font-weight: 600;
}
.ws-catchup-action {
  flex: 0 0 auto;
  gap: .3rem;
  font-size: .78rem;
  white-space: nowrap;
}
.ws-catchup-close {
  flex: 0 0 auto;
  margin-left: .1rem;
  font-size: .6rem;
}
/* Pinegrap AI's summary of what was missed, under the line. */
.ws-catchup-recap {
  margin: 0 .75rem .6rem 2.1rem;
  padding-left: .65rem;
  border-left: 2px solid color-mix(in srgb, var(--ws-accent) 45%, transparent);
}
.ws-catchup-recap:empty {
  display: none;
}
.ws-catchup-recap-text {
  color: var(--pg-fg-body);
  font-size: .88rem;
  line-height: 1.5;
  white-space: pre-line;
}
.ws-catchup-recap-by {
  margin-top: .15rem;
  color: var(--pg-fg-2);
  font-size: .72rem;
}

/* Context menus: the panel's own look, placed at the pointer. Built
   without .show, which is what gives a Bootstrap 6 .popover its opacity. */
.ws-ctx.contextmenu.popover {
  position: fixed;
  z-index: 1095;
  opacity: 1;
  max-width: 19rem;
  min-width: 12rem;
  border-radius: var(--ws-radius-sm);
  animation: wsCtxIn .1s ease-out;
}
@keyframes wsCtxIn {
  from { opacity: 0; transform: translateY(-3px); }
  to { opacity: 1; transform: none; }
}
.ws-ctx .ws-ctx-item {
  display: flex;
  align-items: center;
  width: 100%;
  padding: .32rem .6rem;
  font-size: .86rem;
  border-radius: var(--ws-radius-xs);
}
.ws-ctx .ws-ctx-item:hover,
.ws-ctx .ws-ctx-item:focus {
  background: rgba(var(--ws-accent-rgb, 94, 53, 177), .12);
}
.ws-ctx .ws-ctx-item .bi,
.ws-ctx .ws-ctx-item .pg-dc-mono {
  width: 1.1rem;
  opacity: .8;
}
.ws-ctx .ws-ctx-danger {
  color: var(--pg-danger-fg-emphasis) !important;
}
.ws-ctx .ws-ctx-checked {
  font-weight: 600;
}
.ws-ctx-header {
  padding: .3rem .6rem .35rem;
  font-size: .72rem;
  font-weight: 700;
  color: var(--pg-fg-2);
  max-width: 18rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  border-bottom: 1px solid var(--pg-border-color-translucent);
  margin-bottom: .2rem;
}
.ws-tool-danger:hover {
  color: var(--pg-danger) !important;
}

/* The month calendar. */
.ws-cal {
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius);
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(0, 0, 0, .04), 0 10px 30px -14px rgba(0, 0, 0, .16);
}
.ws-cal-head,
.ws-cal-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
}
.ws-cal-head > div {
  padding: .45rem .6rem;
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--pg-fg-2);
  background: var(--pg-bg-1);
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-cal-day {
  min-height: 8.2rem;
  padding: .35rem .4rem .45rem;
  border-right: 1px solid var(--pg-border-color-translucent);
  border-bottom: 1px solid var(--pg-border-color-translucent);
  cursor: pointer;
  min-width: 0;
  transition: background .12s ease;
}
.ws-cal-day:nth-child(7n) {
  border-right: 0;
}
.ws-cal-day:hover {
  background: var(--ws-soft);
}
.ws-cal-day.ws-cal-weekend {
  background: color-mix(in srgb, var(--pg-fg-emphasis) 2%, transparent);
}
.ws-cal-day.ws-cal-out {
  opacity: .45;
}
.ws-cal-day-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: .25rem;
}
.ws-cal-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.7rem;
  height: 1.7rem;
  border-radius: 999px;
  font-size: .82rem;
  font-weight: 700;
}
.ws-cal-today .ws-cal-num {
  background: var(--ws-accent);
  color: #fff;
}
/* The dark theme's accent is the light lilac (--workspace-color-highlight),
   where white reads at 2.4:1; the near-black accent ink clears 8:1. */
html[data-bs-theme="dark"] .ws-cal-today .ws-cal-num {
  color: var(--pg-on-accent);
}
.ws-cal-talk {
  font-size: .7rem;
  color: var(--pg-fg-2);
  padding: 0 .35rem;
  border-radius: 999px;
  background: var(--pg-bg-1);
}
.ws-cal-task,
.ws-cal-event,
.ws-cal-channel {
  display: flex;
  align-items: center;
  gap: .3rem;
  width: 100%;
  margin-bottom: .18rem;
  padding: .12rem .35rem;
  border: 0;
  border-radius: var(--ws-radius-xs);
  font-size: .72rem;
  line-height: 1.3;
  text-align: left;
  text-decoration: none;
  overflow: hidden;
  white-space: nowrap;
}
.ws-cal-task {
  background: rgba(var(--ws-accent-rgb), .1);
  color: var(--pg-fg-body);
}
.ws-cal-task:hover {
  background: rgba(var(--ws-accent-rgb), .2);
}
.ws-cal-task .ws-status-dot {
  width: .5rem;
  height: .5rem;
}
.ws-cal-task-title {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-cal-task.ws-cal-late {
  background: color-mix(in srgb, var(--pg-danger) 12%, transparent);
  color: var(--pg-danger-fg-emphasis);
}
.ws-cal-task.ws-cal-hot {
  box-shadow: inset 2px 0 0 var(--pg-danger);
}
.ws-cal-task.ws-cal-closed .ws-cal-task-title {
  text-decoration: line-through;
  opacity: .7;
}
.ws-cal-task.ws-cal-upcoming {
  background: transparent;
  box-shadow: inset 0 0 0 1px rgba(var(--ws-accent-rgb), .4);
  color: var(--pg-fg-2);
}
.ws-cal-task.ws-cal-upcoming:hover {
  background: rgba(var(--ws-accent-rgb), .08);
}
.ws-cal-task.ws-cal-upcoming .bi {
  font-size: .7rem;
}
.ws-cal-task.ws-cal-upcoming.ws-cal-waits {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pg-warning) 75%, transparent);
  opacity: .75;
}
/* A task that runs across days: one piece a day, the pieces joined over the
   cell padding and border into one bar; an empty gap keeps the lane's height
   on a day it has nothing. */
.ws-cal-day {
  --ws-cal-pad: .4rem;
}
.ws-cal-task.ws-cal-span,
.ws-cal-lane-gap {
  height: 1.3rem;
}
.ws-cal-lane-gap {
  margin-bottom: .18rem;
}
.ws-cal-task.ws-cal-span-l {
  width: calc(100% + var(--ws-cal-pad));
  margin-left: calc(-1 * var(--ws-cal-pad));
  border-top-left-radius: 0;
  border-bottom-left-radius: 0;
  box-shadow: none;
}
.ws-cal-task.ws-cal-span-r {
  width: calc(100% + var(--ws-cal-pad) + 1px);
  margin-right: calc(-1 * var(--ws-cal-pad) - 1px);
  border-top-right-radius: 0;
  border-bottom-right-radius: 0;
}
.ws-cal-task.ws-cal-span-l.ws-cal-span-r {
  width: calc(100% + 2 * var(--ws-cal-pad) + 1px);
}
.ws-list-row.ws-row-upcoming .ws-row-title {
  color: var(--pg-fg-2);
}

/* The dates and the repeat of a task, one box in the task drawer. */
.ws-when {
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  padding: .6rem .75rem .55rem;
  background: var(--pg-bg-1);
}
.ws-when-head {
  display: flex;
  align-items: center;
  gap: .4rem;
  margin-bottom: .45rem;
  font-size: .8rem;
  font-weight: 600;
  color: var(--pg-fg-2);
}
.ws-when-custom,
.ws-when-end {
  margin-top: .5rem;
}
.ws-when-summary {
  margin-top: .55rem;
  padding: .45rem .6rem;
  border-radius: var(--ws-radius-xs);
  background: rgba(var(--ws-accent-rgb), .08);
  font-size: .8rem;
}
.ws-when-rule {
  font-weight: 600;
}
.ws-when-span {
  color: var(--pg-fg-2);
}
.ws-when-next {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .3rem;
  margin-top: .3rem;
}
.ws-when-date {
  padding: .05rem .4rem;
  border: 1px solid var(--pg-border-color);
  border-radius: 999px;
  background: var(--pg-bg-body);
  white-space: nowrap;
}
.ws-when-warn {
  margin-top: .35rem;
  color: var(--pg-warning-fg-emphasis);
}
.ws-when-dayoff {
  margin: -.25rem 0 .5rem;
  font-size: .8rem;
}
.ws-when-dayoff .ws-when-warn {
  margin-top: 0;
}
.ws-when-date.ws-when-moved {
  border-style: dashed;
}
.ws-when-date .bi {
  margin-right: .1rem;
}

/* The working calendar card of the settings screen. */
.ws-feed-row {
  display: flex;
  align-items: center;
  gap: .6rem;
  padding: .45rem 0;
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-next-off li {
  padding: .15rem 0;
}
.ws-feed-days {
  padding: .35rem 0 .45rem 1.6rem;
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-feed-days summary {
  cursor: pointer;
  color: var(--pg-fg-2);
}
.ws-feed-days ul {
  max-height: 16rem;
  overflow-y: auto;
}
.ws-feed-day {
  display: flex;
  align-items: baseline;
  gap: .6rem;
  padding: .15rem 0;
}
.ws-feed-day-off .ws-grow {
  color: var(--pg-fg-2);
  text-decoration: line-through;
}
.ws-when-state {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .5rem;
  margin-top: .5rem;
  font-size: .8rem;
}
.ws-avatars-sm .avatar {
  --bs-avatar-size: var(--ws-avatar-xs);
  --bs-avatar-border-width: 1px;
}
.ws-cal-event {
  background: color-mix(in srgb, var(--pg-info) 14%, transparent);
  color: var(--pg-info-fg-emphasis);
}
.ws-cal-event.ws-kind-leave,
.ws-cal-event.ws-kind-holiday {
  background: var(--pg-bg-2);
  color: var(--pg-fg-2);
}
.ws-cal-event.ws-kind-visit {
  background: color-mix(in srgb, var(--pg-warning) 16%, transparent);
  color: var(--pg-warning-fg-emphasis);
}
.ws-cal-event-dot {
  width: .6rem;
  height: .6rem;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--pg-info);
}
.ws-cal-event-dot.ws-kind-leave,
.ws-cal-event-dot.ws-kind-holiday {
  background: var(--pg-secondary);
}
.ws-cal-event-dot.ws-kind-visit {
  background: var(--pg-warning);
}
/* A booking from the agenda (includes/workspace/calendar.php). */
.ws-cal-event.ws-kind-booking {
  background: color-mix(in srgb, var(--pg-success) 14%, transparent);
  color: var(--pg-success-fg-emphasis);
}
.ws-cal-event-dot.ws-kind-booking {
  background: var(--pg-success);
}
/* A person's own plan (includes/workspace/personal_plans.php), on My calendar
   alone: look A's violet tone. */
.ws-cal-event.ws-kind-personal {
  background: color-mix(in srgb, var(--pg-tone-violet) 16%, transparent);
  color: var(--pg-fg-body);
}
.ws-cal-event-dot.ws-kind-personal {
  background: var(--pg-tone-violet);
}
.ws-cal-channel {
  color: var(--ws-accent);
  background: transparent;
  padding-left: .2rem;
}
.ws-cal-channel:hover {
  background: var(--ws-soft);
}
.ws-cal-more {
  font-size: .7rem;
  color: var(--pg-fg-2);
  padding-left: .35rem;
}
/* My calendar (workspace_my_calendar.php): the Work Calendar's cells, a
   taller row for the week, and the list of days drawn with look A's rows. */
button.ws-cal-more {
  border: 0;
  background: none;
}
/* The Work Calendar's cells (workspace_calendar_cells.js): a chip takes its
   cell's width and the title gets the room; the people's faces show only in
   a cell wide enough to keep the title whole beside them. */
.ws-cal-work .ws-cal-day {
  container-type: inline-size;
}
.ws-cal-work .ws-cal-task .ws-avatars {
  flex: none;
}
@container (max-width: 15rem) {
  .ws-cal-work .ws-cal-task .ws-avatars {
    display: none;
  }
}
.ws-cal-work button.ws-cal-more {
  width: 100%;
  padding: .1rem .35rem;
  border-radius: var(--ws-radius-xs);
  text-align: left;
}
.ws-cal-work button.ws-cal-more:hover,
.ws-cal-work button.ws-cal-more[aria-expanded="true"] {
  background: var(--pg-hover);
  color: var(--pg-fg-body);
}
.ws-cal-work button.ws-cal-more:focus-visible {
  outline: 2px solid var(--pg-focus-ring-color);
  outline-offset: 1px;
}
/* The day's list "+N more" opens beside its cell. */
.ws-cal-more-card {
  position: fixed;
  z-index: 1060;
  display: flex;
  flex-direction: column;
  width: 20rem;
  max-width: calc(100vw - 16px);
  max-height: min(28rem, calc(100vh - 16px));
  padding: 12px 8px 8px;
  box-shadow: var(--pg-shadow-float);
}
.ws-cal-more-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 4px 6px 8px;
}
.ws-cal-more-head .pg-title-section {
  margin: 0;
}
.ws-cal-more-list {
  overflow-y: auto;
  min-height: 0;
}
.ws-cal-more-row {
  cursor: pointer;
  color: inherit;
  text-decoration: none;
}
.ws-cal-more-row > .ws-status-dot,
.ws-cal-more-row > .ws-cal-event-dot {
  margin-top: 6px;
}
/* The day's list reads each title whole: it wraps instead of being cut. */
.ws-cal-more-row .pg-list-row-title {
  white-space: normal;
  overflow-wrap: anywhere;
}
.ws-cal-more-row.is-done .pg-list-row-title {
  text-decoration: line-through;
  color: var(--pg-fg-2);
}
.ws-cal-more-row:focus-visible {
  outline: 2px solid var(--pg-focus-ring-color);
  outline-offset: -2px;
}
.ws-cal-more-day {
  align-self: flex-start;
  margin: 6px 4px 0;
}
/* "Figures" in the bar shows whether the side column is open. */
.ws-cal-figures-toggle[aria-expanded="true"] {
  background: var(--pg-hover);
}
/* The plans switch under the calendar: the text takes the row's width. */
.ws-calsync-plans {
  margin-top: 16px;
}
.ws-calsync-plans-text {
  flex: 1;
  min-width: 0;
}
/* My calendar's week (workspace_my_calendar_week.js): the days' heads, a
   strip of what has no hour, then 24 hours of which 07:00 to 20:00 are in
   view; a column of hour labels on the left of each row. */
.ws-mycal-hours {
  --ws-mycal-hour: 3rem;
  --ws-mycal-gutter: 3.5rem;
}
.ws-mycal-hours-row {
  display: grid;
  grid-template-columns: var(--ws-mycal-gutter) repeat(var(--ws-mycal-days, 7), minmax(0, 1fr));
}
.ws-mycal-hours-head {
  background: var(--pg-bg-1);
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-mycal-hours-day {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 0;
  padding: 6px 4px;
  cursor: pointer;
}
.ws-mycal-hours-day:hover {
  background: var(--ws-soft);
}
.ws-mycal-weekday {
  color: var(--pg-fg-2);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-mycal-gutter {
  display: flex;
  align-items: flex-start;
  justify-content: flex-end;
  padding: 6px 8px 0 0;
  border-right: 1px solid var(--pg-border-color-translucent);
}
.ws-mycal-strip {
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-mycal-strip-day {
  --ws-cal-pad: .4rem;
  min-width: 0;
  min-height: 2rem;
  padding: .3rem var(--ws-cal-pad) .1rem;
  border-right: 1px solid var(--pg-border-color-translucent);
}
.ws-mycal-strip-day:last-child,
.ws-mycal-hours-col:last-child {
  border-right: 0;
}
.ws-mycal-strip-day.ws-cal-weekend,
.ws-mycal-hours-col.ws-cal-weekend {
  background: color-mix(in srgb, var(--pg-fg-emphasis) 2%, transparent);
}
.ws-mycal-scroll {
  height: calc(var(--ws-mycal-hour) * 13);
  overflow-y: auto;
  overscroll-behavior: contain;
}
.ws-mycal-hours-grid {
  height: calc(var(--ws-mycal-hour) * 24);
}
.ws-mycal-hour-labels {
  position: relative;
  padding: 0;
}
.ws-mycal-hour-label {
  position: absolute;
  right: 8px;
  transform: translateY(-50%);
}
.ws-mycal-hours-col {
  position: relative;
  min-width: 0;
  border-right: 1px solid var(--pg-border-color-translucent);
}
.ws-mycal-slot {
  height: calc(100% / 24);
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-mycal-slot[role="button"] {
  cursor: pointer;
}
.ws-mycal-slot[role="button"]:hover {
  background: var(--ws-soft);
}
.ws-mycal-slot:focus-visible {
  outline: 2px solid var(--ws-accent);
  outline-offset: -2px;
}
/* An item with a time: the chip of its kind, at its start and as tall as
   it lasts, its share of the width beside the items it overlaps. */
.ws-cal-task.ws-mycal-block,
.ws-cal-event.ws-mycal-block {
  position: absolute;
  align-items: flex-start;
  margin: 0;
  padding: .1rem .3rem;
  border: 1px solid var(--pg-bg-body);
  white-space: normal;
  overflow: hidden;
  z-index: 1;
}
.ws-cal-task.ws-mycal-block .ws-status-dot {
  margin-top: .3rem;
}
.ws-mycal-block:focus-visible {
  outline: 2px solid var(--ws-accent);
  outline-offset: 0;
  z-index: 2;
}
/* A plan or task the reader may move (workspace_my_calendar_move.js):
   held while dragged, and the day or hours it would land on ringed. */
.ws-mycal-movable {
  cursor: grab;
}
.ws-mycal-dragging {
  opacity: .5;
}
.ws-mycal-drop {
  box-shadow: inset 0 0 0 2px var(--ws-accent);
  background-color: color-mix(in srgb, var(--ws-accent) 8%, transparent);
}
/* The line of now across today's column. */
.ws-mycal-now {
  position: absolute;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--pg-danger);
  pointer-events: none;
  z-index: 3;
}
.ws-mycal-now::before {
  content: "";
  position: absolute;
  left: -4px;
  top: -3px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--pg-danger);
}
/* On a phone the week's items keep the month's coloured bars, and an item
   with a time still opens on a tap rather than the hour under it. */
@media (max-width: 575.98px) {
  .ws-mycal-hours {
    --ws-mycal-gutter: 2.75rem;
  }
  .ws-mycal-hours-day {
    flex-direction: column;
    gap: 2px;
  }
  .ws-cal-task.ws-mycal-block,
  .ws-cal-event.ws-mycal-block {
    margin: 0;
    border-radius: var(--ws-radius-xs);
    pointer-events: auto;
  }
}
/* My calendar on a phone: the views keep their icons in the bar (no
   select), the month's chosen day is ringed and listed under the grid, and
   the week's one day shows its chips whole rather than as bars. */
@container ws-bar (max-width: 1000px) {
  .ws-mycal-screen .ws-bar-views-seg {
    display: inline-flex;
  }
  .ws-mycal-screen .ws-bar-views-select {
    display: none;
  }
}
/* Hidden from 576 px; the panel's .pg-button sets a display of its own. */
.ws-mycal-screen .ws-mycal-fab {
  display: none;
}
@media (max-width: 575.98px) {
  /* The Work Calendar is reached from the Workspace menu's Tools. */
  .ws-mycal-screen .ws-bar > [data-ws-new-plan],
  .ws-mycal-screen .ws-bar > [data-ws-work-calendar] {
    display: none;
  }
  .ws-mycal-screen .ws-mycal-fab {
    display: inline-flex;
    position: fixed;
    right: 16px;
    bottom: calc(16px + env(safe-area-inset-bottom, 0px));
