  border-top: 1px solid var(--pg-border-color-translucent);
}
.ws-mycal-picked-empty {
  margin: 0;
  padding: 4px 12px 8px;
}
@media (max-width: 575.98px) {
  .ws-mycal-one-day :is(.ws-cal-task, .ws-cal-event) {
    height: auto;
    padding: .12rem .35rem;
    font-size: .75rem;
    border-radius: var(--ws-radius-xs);
    pointer-events: auto;
  }
  .ws-mycal-one-day :is(.ws-cal-task, .ws-cal-event):not(.ws-mycal-block) {
