  }
  .ws-mycal-one-day .ws-cal-task.ws-cal-span,
  .ws-mycal-one-day .ws-cal-lane-gap {
    height: 1.3rem;
  }
  .ws-mycal-one-day .ws-cal-task > * {
    display: block;
  }
  .ws-mycal-one-day .ws-cal-task .ws-avatars {
    display: none;
  }
  .ws-mycal-one-day .ws-cal-task-title {
    font-size: .75rem;
  }
  .ws-mycal-one-day .ws-cal-task {
    background: color-mix(in srgb, var(--ws-accent) 10%, transparent);
  }
  .ws-mycal-one-day .ws-cal-task.ws-cal-late {
    background: color-mix(in srgb, var(--pg-danger) 12%, transparent);
  }
  .ws-mycal-one-day .ws-cal-task.ws-cal-upcoming {
    background: transparent;
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ws-accent) 40%, transparent);
  }
  .ws-mycal-one-day .ws-cal-event {
    background: color-mix(in srgb, var(--pg-info) 14%, transparent);
  }
  .ws-mycal-one-day .ws-cal-event:is(.ws-kind-leave, .ws-kind-holiday) {
    background: var(--pg-bg-2);
  }
  .ws-mycal-one-day .ws-cal-event.ws-kind-visit {
    background: color-mix(in srgb, var(--pg-warning) 16%, transparent);
  }
  .ws-mycal-one-day .ws-cal-event.ws-kind-booking {
    background: color-mix(in srgb, var(--pg-success) 14%, transparent);
  }
  .ws-mycal-one-day .ws-cal-event.ws-kind-personal {
    background: color-mix(in srgb, var(--pg-tone-violet) 16%, transparent);
  }
}
.ws-mycal-list {
  padding: 8px 12px 12px;
}
.ws-mycal-day + .ws-mycal-day {
  margin-top: 8px;
}
.ws-mycal-day-label {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 10px 12px 4px;
}
.ws-mycal-row {
  align-items: center;
  cursor: pointer;
}
.ws-mycal-row > .ws-status-dot,
.ws-mycal-row > .ws-cal-event-dot,
.ws-mycal-row > .bi {
  flex: none;
}
/* The New plan drawer: look A's fields, two to a row where they pair. */
.ws-plan-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
}
.ws-plan-field.ws-field-flush {
  margin-bottom: 0;
}
/* A look A field joined to its buttons in an .input-group: the field
   takes the room left, a button is as tall as the field. The joined
   corners come from the restated .input-group.input-group rules. */
.input-group > .pg-input {
  flex: 1 1 auto;
  width: 1%;
}
.input-group > :is(.pg-button, .pg-icon-button) {
  height: auto;
}
.input-group > .pg-input:focus {
  z-index: 5;
}
.ws-plan-pair {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.ws-plan-switch {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 16px;
}
/* Who can see: the three segments share the drawer's width and a long label
   breaks onto two lines; one nowrap line ran past the drawer at 320 px. */
.ws-plan-who {
  display: flex;
}
.ws-plan-who .pg-seg-item {
  flex: 1 1 auto;
  min-width: 0;
  height: auto;
  min-height: 26px;
  white-space: normal;
  text-align: center;
}
/* Repeat every: the number and its unit on one line, at 390 too. */
.ws-plan-every {
  display: flex;
  align-items: center;
  gap: 8px;
}
.ws-plan-every .pg-input {
  flex: 1 1 auto;
  min-width: 0;
}
/* A plan item's meeting link: the address, Jitsi and Join on one row that
   wraps on a phone. */
.ws-plan-meeting {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.ws-plan-meeting .pg-input {
  flex: 1 1 12rem;
  min-width: 0;
}
/* A button in a field's place (Meeting note) keeps its own width. */
.ws-plan-field > .pg-button {
  align-self: flex-start;
}
/* Somebody else's plan, read only: the fields dimmed as a disabled switch,
   nothing that invites typing. */
.ws-plan-readonly .pg-input:disabled,
.ws-plan-readonly .pg-input:has(> :disabled) {
  opacity: 0.5;
  cursor: default;
}
.ws-plan-readonly textarea.pg-input {
  resize: none;
}
.ws-people-select[aria-invalid="true"] {
  border-color: var(--pg-tone-rose);
}
.ws-plan-private {
  display: flex;
  align-items: center;
  margin-bottom: 16px;
}
/* An invitation in a mail (personal_plan_mail.php). */
.ws-mail-invite {
  max-width: 480px;
  padding: 12px;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius);
}
.ws-mail-invite-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
}
.ws-mycal-empty {
  margin: 0;
  padding: 32px 16px;
  text-align: center;
}
/* A plan's roadmap in its drawer: the bar of its days with each dated step
   on its day, the share done filled in the violet of a plan, then the steps. */
.ws-roadmap {
  border-top: 1px solid var(--pg-border-color-translucent);
  margin-top: 8px;
  padding-top: 16px;
}
.ws-roadmap-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}
.ws-roadmap-head .pg-group-label {
  margin: 0;
}
.ws-roadmap-bar {
  position: relative;
  height: 8px;
  margin: 6px 6px 18px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--pg-tone-violet) 14%, transparent);
}
.ws-roadmap-fill {
  height: 100%;
  border-radius: inherit;
  background: var(--pg-tone-violet);
  transition: width .2s ease;
}
.ws-roadmap-marks {
  position: absolute;
  inset: 0;
}
.ws-roadmap-mark {
  position: absolute;
  top: 50%;
  width: 12px;
  height: 12px;
  border: 2px solid var(--pg-tone-violet);
  border-radius: 50%;
  background: var(--pg-bg-body);
  transform: translate(-50%, -50%);
}
.ws-roadmap-mark.is-done {
  background: var(--pg-tone-violet);
}
.ws-roadmap-steps {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0 0 10px;
  padding: 0;
  list-style: none;
}
.ws-roadmap-step {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) 9.5rem 4rem;
  align-items: center;
  gap: 8px;
}
.ws-roadmap-step.is-done .ws-roadmap-title {
  color: var(--pg-fg-2);
  text-decoration: line-through;
}
.ws-roadmap-tools {
  display: flex;
  grid-row: 1;
  grid-column: 4;
  align-items: center;
  justify-content: flex-end;
  gap: 2px;
}
.ws-roadmap-meta {
  display: flex;
  grid-column: 2 / -1;
  align-items: center;
  gap: 6px;
  margin-top: -2px;
}
.ws-roadmap-task {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 0;
}
.ws-roadmap-empty {
  padding: 4px 0;
}
/* Under the steps: "Move the following steps too", then Add a step and
   "Save as team template" on one line, and the template chooser. */
.ws-roadmap-move {
  margin-bottom: 2px;
}
.ws-roadmap-move-help {
  margin: 0 0 10px;
}
.ws-roadmap-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.ws-roadmap-keep {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
}
.ws-roadmap-keep .form-control {
  flex: 1 1 auto;
  min-width: 0;
}
.ws-roadmap-count {
  margin-left: 4px;
  color: var(--pg-fg-2);
  font-size: 11px;
}
/* A step's date calendar (drawn open after the box in a drawer) takes a row
   of its own under the step: in a column of the row it widened it past the
   drawer. The tools are pinned to the step's first row, so they stay beside
   the date and do not drop under the calendar. */
.ws-roadmap-step > .pg-date-inline {
  grid-column: 1 / -1;
  margin-top: 0;
}
@media (max-width: 575.98px) {
  .ws-roadmap-step {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }
  /* A touch target of 40 px for "Make a task" and "Remove the step". */
  .ws-roadmap-tools .pg-icon-button {
