}

@media (max-width: 767.98px) {
  /* The channel screen fills what can be seen of the window, under the
     panel's top bar; the script keeps --ws-fit-* on the visual viewport so
     the on-screen keyboard does not push the header and tabs away. */
  .ws-app {
    position: fixed;
    top: var(--ws-fit-top, var(--pg-navbar-h, 3.125rem));
    left: 0;
    right: 0;
    z-index: 1010;
    grid-template-columns: minmax(0, 1fr);
    height: var(--ws-fit-h, calc(100vh - 3.125rem));
    min-height: 0;
    border: 0;
    border-radius: 0;
    box-shadow: none;
  }
  /* The channel view's full window height (.ws-app:not(:has(.ws-home))
     above) is the more specific selector: without this, 100dvh, which the
     on-screen keyboard does not shorten, beat --ws-fit-h and left the
     writing box under the keyboard. */
  .ws-app:not(:has(.ws-home)) {
    height: var(--ws-fit-h, calc(100vh - 3.125rem));
  }
  body.workspace_channels {
    overflow: hidden;
  }
  .ws-head {
    gap: .5rem;
    padding: .4rem .6rem;
    min-height: 3rem;
  }
  .ws-head-title h2 {
    font-size: 1rem;
  }
  .ws-head-icon {
    width: 1.5rem;
    height: 1.5rem;
    margin-right: .35rem;
    font-size: .85rem;
  }
  .ws-tabs {
    gap: 0;
    padding: .1rem .35rem 0;
  }
  .ws-tabs button {
    padding: .55rem .6rem;
    font-size: .84rem;
  }
  .ws-channel-card {
    margin: .35rem .35rem 0;
    border-radius: var(--ws-radius-sm);
  }
  .ws-channel-card > .ws-tabs {
    gap: .2rem;
    padding: .3rem .4rem .4rem;
  }
  .ws-channel-card .ws-tabs button {
    padding: .35rem .7rem;
  }
  .ws-pane {
    padding: .5rem .65rem;
  }
  .ws-composer-wrap {
    padding: .4rem .5rem calc(.45rem + env(safe-area-inset-bottom, 0px));
  }
  /* 16px keeps iOS from zooming in on the field when it is tapped. */
  .ws-composer textarea {
    font-size: 16px;
    min-height: 2.5rem;
  }
  /* Narrow pads keep the inserts, Send and Send later on one line at
     375 px; the row still wraps where even that has no room. 44 px high,
     the touch target a finger hits; the height costs no width. */
  .ws-composer-tools .btn,
  .ws-composer-tools .pg-button,
  .ws-composer-tools .pg-icon-button {
    min-height: 2.75rem;
    padding: .3rem .4rem;
  }
  /* The field takes the full width on top and the row of tools with Send
     sits under it, as on a wide screen; the frame is a little tighter. */
  .ws-composer {
    padding: .3rem .35rem;
  }
  /* Send keeps its icon and a narrow pad, so the row fits a phone. */
  .ws-composer-tools .pg-button-fill {
    padding-inline: .6rem;
  }
  /* A recording row as tall as the box it stands in for, with buttons a
     finger hits; the player's small buttons the same. */
  .ws-voice-rec {
    min-height: 3.4rem;
  }
  .ws-voice-rec :is(.pg-button, .pg-icon-button),
  .ws-voice-tools > :is(.pg-button, .pg-icon-button) {
    min-width: 2.5rem;
    min-height: 2.5rem;
  }
  /* Up to three of those beside the name (speed, reply, download): closer
     together, so the name keeps room to be read. */
  .ws-voice {
    gap: var(--ws-space-1);
  }
  body.workspace_channels #pg-chat-root .pg-chat-launcher {
    right: 12px;
    bottom: calc(var(--ws-composer-h, 6rem) + 12px);
    width: 46px;
    height: 46px;
    font-size: 18px;
  }
  body.workspace_channels.ws-keyboard #pg-chat-root .pg-chat-launcher {
    display: none;
  }
  /* Filter pills stay on one line and scroll sideways. */
  body.workspace .pg-toolbar .btn-group {
    flex-wrap: nowrap;
    max-width: 100%;
    overflow-x: auto;
    scrollbar-width: none;
  }
  body.workspace .pg-toolbar .btn-group > .btn {
    flex: 0 0 auto;
    white-space: nowrap;
  }
  /* The board: a narrow name column, so more than one day fits. */
  .ws-board {
    min-width: 0;
    --ws-board-person: 7.25rem;
    --ws-board-day: 6.25rem;
  }
  .ws-board-person {
    gap: .35rem;
    padding: .35rem .4rem;
    font-size: .78rem;
  }
  .ws-board-person .avatar {
    --bs-avatar-size: 1.5rem;
  }
  .ws-board-person small {
    display: none;
  }
  /* A discussion or the channel's info covers the channel until it is
     closed. */
  .ws-app.ws-thread-open,
  .ws-app.ws-info-open {
    grid-template-columns: minmax(0, 1fr);
  }
  .ws-app.ws-thread-open .ws-thread-panel,
  .ws-app.ws-info-open .ws-info-panel {
    position: absolute;
    inset: 0;
    z-index: 6;
    border-left: 0;
  }
  .ws-thread-resizer {
    display: none;
  }
  .ws-msg-tools,
  .ws-msg:hover .ws-msg-tools {
    display: none;
    position: static;
    flex-wrap: wrap;
    justify-content: flex-end;
    border: 0;
    box-shadow: none;
    background: transparent;
    grid-column: 2;
  }
  .ws-msg.ws-msg-active .ws-msg-tools {
    display: flex;
  }
  .ws-cal-day {
    --ws-cal-pad: .2rem;
    min-height: 4.5rem;
    padding: .2rem;
  }
  .ws-cal-task.ws-cal-span,
  .ws-cal-lane-gap {
    height: 1.1rem;
  }
  .ws-cal-task-title,
  .ws-cal-event,
  .ws-cal-channel {
    font-size: .62rem;
  }
  .ws-cal-task .ws-avatars {
    display: none;
  }
  /* One thin line on a phone: the buttons keep their icons. */
  .ws-catchup {
    margin: .35rem .5rem 0;
  }
  .ws-catchup-row {
    gap: .35rem;
    min-height: 2.25rem;
    padding: .2rem .3rem .2rem .6rem;
  }
  .ws-catchup-label {
    display: none;
  }
  /* Buttons a finger hits (2.5rem, like the composer's) inside the thin
     line: the negative margins keep the row's height. */
  .ws-catchup-action {
    min-width: 2.5rem;
    min-height: 2.5rem;
    margin-block: -.35rem;
    justify-content: center;
    padding: .2rem .45rem;
  }
  .ws-catchup-close {
    min-width: 2.5rem;
    min-height: 2.5rem;
    margin-block: -.35rem;
    mask-size: .6rem;
  }
  .ws-catchup-text strong {
    display: none;
  }
  .ws-pin-bar,
  .ws-open-bar {
    margin: .35rem .5rem 0;
  }
  /* The open items line alone keeps its text; Go keeps its icon. */
  .ws-open-label,
  .ws-open-yours {
    display: none;
  }
  .ws-open-go,
  .ws-open-count {
    min-width: 2.5rem;
    min-height: 2.5rem;
    margin-block: -.35rem;
    justify-content: center;
    padding: .2rem .45rem;
  }
  /* Both there: one row, the catch-up line first and the pin a button
     beside it. */
  .ws-strip:has(.ws-catchup):has(.ws-pin-bar) {
    flex-direction: row;
    gap: .35rem;
    margin: .35rem .5rem 0;
  }
  .ws-strip:has(.ws-catchup):has(.ws-pin-bar) > .ws-catchup {
    flex: 1 1 auto;
    min-width: 0;
    margin: 0;
  }
  .ws-strip:has(.ws-catchup) > .ws-pin-holder {
    display: flex;
  }
  .ws-strip:has(.ws-catchup) .ws-pin-bar {
    margin: 0;
    padding: 0 .55rem;
  }
  .ws-strip:has(.ws-catchup) .ws-pin-words,
  .ws-strip:has(.ws-catchup) .ws-pin-bar > :not(.ws-pin-text) {
    display: none;
  }
  /* Open items beside the catch-up line or the pin: the same row, only the
     count, a button that lists them (one item too). */
  .ws-strip:has(.ws-open-bar):has(.ws-catchup, .ws-pin-bar) {
    flex-direction: row;
    align-items: center;
    gap: .35rem;
    margin: .35rem .5rem 0;
  }
  .ws-strip:has(.ws-open-bar):has(.ws-catchup, .ws-pin-bar) > .ws-catchup {
    flex: 1 1 auto;
    min-width: 0;
    margin: 0;
  }
  .ws-strip:has(.ws-open-bar):not(:has(.ws-catchup)) > .ws-pin-holder {
    flex: 1 1 auto;
    min-width: 0;
  }
  .ws-strip:has(.ws-open-bar):has(.ws-catchup, .ws-pin-bar) .ws-pin-bar {
    margin: 0;
  }
  .ws-strip:has(.ws-open-bar):has(.ws-catchup, .ws-pin-bar) > .ws-open-holder {
    display: flex;
    flex: 0 0 auto;
  }
  .ws-strip:has(.ws-open-bar):has(.ws-catchup, .ws-pin-bar) .ws-open-bar {
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
  }
  .ws-strip:has(.ws-open-bar):has(.ws-catchup, .ws-pin-bar) :is(.ws-open-text, .ws-open-go) {
    display: none;
  }
  .ws-strip:has(.ws-open-bar):has(.ws-catchup, .ws-pin-bar) .ws-open-bar .ws-open-count {
    display: inline-flex;
    margin-block: 0;
  }
  /* While the keyboard is up the tabs wait too: the conversation keeps
     the height between the header and the box. */
  body.ws-keyboard .ws-center > :is(.ws-strip, .ws-tabs),
  body.ws-keyboard .ws-channel-card > .ws-tabs {
    display: none;
  }
  body.ws-keyboard .ws-channel-card > .ws-ctl {
    display: none;
  }
  /* The expanded box (Aa) rides on the keyboard as the one-line box does:
     its 50vh cap reads the layout viewport, so the field alone could take
     what the keyboard leaves and push the tools and Send under it. The
     hint names Ctrl+Enter, which a phone's keyboard does not have. */
  body.ws-keyboard .ws-composer .ws-rich.is-expanded {
    min-height: 2.5rem;
    max-height: 6rem;
  }
  body.ws-keyboard .ws-composer-hint {
    display: none;
  }
}
@media (max-width: 575.98px) {
  /* On a phone a day is a tap target: what is in it shows as bars, the day drawer tells the rest. */
  .ws-cal-day {
    --ws-cal-pad: .15rem;
    min-height: 3.8rem;
    padding: .2rem .15rem;
  }
  .ws-cal-task.ws-cal-span,
  .ws-cal-lane-gap {
    height: .32rem;
  }
  .ws-cal-lane-gap {
    margin-bottom: .16rem;
  }
  .ws-cal-day-top {
    flex-wrap: wrap;
    gap: .1rem;
  }
  .ws-cal-num {
    min-width: 1.45rem;
    height: 1.45rem;
    font-size: .74rem;
  }
  .ws-cal-talk {
    font-size: .6rem;
    padding: 0 .25rem;
  }
  .ws-cal-talk .bi {
    display: none;
  }
  .ws-cal-task,
  .ws-cal-event,
  .ws-cal-channel {
    height: .32rem;
    padding: 0;
    margin-bottom: .16rem;
    font-size: 0;
    border-radius: 999px;
    pointer-events: none;
  }
  .ws-cal-task > *,
  .ws-cal-channel > * {
    display: none;
  }
  .ws-cal-task {
    background: rgba(var(--ws-accent-rgb), .6);
  }
  .ws-cal-task.ws-cal-late {
    background: color-mix(in srgb, var(--pg-danger) 70%, transparent);
  }
  .ws-cal-task.ws-cal-upcoming {
    background: rgba(var(--ws-accent-rgb), .25);
    box-shadow: none;
  }
  .ws-cal-task.ws-cal-upcoming.ws-cal-waits {
    background: color-mix(in srgb, var(--pg-warning) 40%, transparent);
  }
  .ws-cal-event {
    background: color-mix(in srgb, var(--pg-info) 60%, transparent);
  }
  .ws-cal-event.ws-kind-leave,
  .ws-cal-event.ws-kind-holiday {
    background: var(--pg-secondary);
  }
  .ws-cal-event.ws-kind-visit {
    background: color-mix(in srgb, var(--pg-warning) 70%, transparent);
  }
  /* A plan of the reader's own: its violet as strong as the list's dot. */
  .ws-cal-event.ws-kind-personal {
    background: color-mix(in srgb, var(--pg-tone-violet) 80%, transparent);
  }
  .ws-cal-channel {
    background: rgba(var(--ws-accent-rgb), .25);
  }
  .ws-cal-more {
    font-size: .58rem;
    padding-left: .1rem;
  }
}
/* Asking Claude: where a request stands, the tasks an answer proposes, and
   the settings card. An agent line is the icon and a wrapping body: a row
   of the label, "since HH:MM" and Stop, then the progress note. The note
   stays on that row only when the whole of it fits; otherwise it takes a
   line of its own under the label. The same rule holds in every column
   (the channel, a discussion panel, a phone). */
.ws-claude-state {
  display: flex;
  align-items: baseline;
  gap: .35rem;
  margin-top: .3rem;
  font-size: .76rem;
  color: var(--pg-fg-2);
}
.ws-claude-state > .bi {
  flex: none;
}
.ws-claude-state .ws-claude-body {
  display: flex;
  flex: 1 1 auto;
  flex-wrap: wrap;
  align-items: baseline;
  min-width: 0;
  column-gap: .35rem;
  row-gap: .1rem;
}
/* The row shrinks to the column when it alone is wider. */
.ws-claude-state .ws-claude-head {
  display: flex;
  flex: 0 1 auto;
  align-items: baseline;
  gap: .35rem;
  min-width: 0;
  max-width: 100%;
}
/* A label sharing its row with since and Stop (sent, running) stays on one
   line and is cut with an ellipsis, the whole label in its title; when the
   row is short, the word of "since" goes first (claudeStateFit() in
   workspace.js). A label that is a sentence (waiting, failed, cancelled:
   it says when it is tried again) wraps between words. */
.ws-claude-state .ws-claude-label {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ws-claude-state.ws-claude-sent .ws-claude-label,
.ws-claude-state.ws-claude-running .ws-claude-label {
  white-space: nowrap;
}
.ws-claude-state .ws-claude-since,
.ws-claude-state .ws-claude-stop {
  flex: none;
  white-space: nowrap;
}
.ws-claude-state.ws-claude-tight .ws-claude-since-word {
  display: none;
}
.ws-claude-state.ws-claude-running > .bi,
.ws-claude-state.ws-claude-sent > .bi {
  color: rgb(var(--ws-accent-rgb));
}
.ws-claude-state.ws-claude-answered > .bi {
  color: var(--pg-success);
}
/* An agent's progress note (up to 200 characters, never cut): its whole
   width decides whether it fits on the row; on its own line it wraps
   between words, and only a word longer than the line is split. */
.ws-claude-state .ws-claude-note {
  flex: 0 0 auto;
  min-width: 0;
  max-width: 100%;
  overflow-wrap: break-word;
  font-style: italic;
}
.ws-claude-state.ws-claude-failed,
.ws-claude-state.ws-claude-cancelled {
  color: var(--pg-danger-fg-emphasis);
}
/* Right and Wrong under an agent's reply: the state line's colour at the
   scale's 12 px; the chosen mark takes the answered or failed colour. */
.ws-agent-feedback {
  max-width: 34rem;
  margin-top: .3rem;
  font-size: .75rem;
  color: var(--pg-fg-2);
}
.ws-agent-feedback-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .25rem;
}
.ws-agent-feedback-row .ws-agent-feedback-mark {
  font-size: inherit;
  color: inherit;
}
.ws-agent-feedback-row .ws-agent-feedback-mark.is-right {
  color: var(--pg-success);
}
.ws-agent-feedback-row .ws-agent-feedback-mark.is-wrong {
  color: var(--pg-danger-fg-emphasis);
}
.ws-agent-feedback-reason {
  margin-top: .2rem;
  overflow-wrap: anywhere;
  font-style: italic;
}
.ws-agent-feedback-form {
  display: grid;
  gap: .3rem;
  margin-top: .3rem;
}
.ws-agent-feedback-actions {
  display: flex;
  gap: .3rem;
}
/* One column no wider than the list: a card is never wider than its text
   column, so a flow drawing wider than the card scrolls in its own pane
   instead of widening the card and the whole channel with it. */
.ws-drafts {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: .4rem;
  max-width: 34rem;
  margin-top: .45rem;
}
.ws-drafts-title {
  font-size: .72rem;
  font-weight: 600;
  letter-spacing: .02em;
  text-transform: uppercase;
  color: var(--pg-fg-2);
}
.ws-draft {
  padding: .5rem .7rem;
  border: 1px dashed rgba(var(--ws-accent-rgb), .55);
  border-radius: var(--ws-radius-sm);
  background: rgba(var(--ws-accent-rgb), .05);
  font-size: .84rem;
}
.ws-draft.ws-draft-accepted,
.ws-draft.ws-draft-dismissed {
  border-style: solid;
  border-color: var(--pg-border-color);
  background: transparent;
}
.ws-draft.ws-draft-dismissed .ws-draft-head b {
  text-decoration: line-through;
  color: var(--pg-fg-2);
}
.ws-draft-head {
  display: flex;
  align-items: baseline;
  gap: .4rem;
}
.ws-draft-head > .bi {
  color: rgb(var(--ws-accent-rgb));
}
.ws-draft-meta,
.ws-draft-done {
  margin-top: .15rem;
  font-size: .76rem;
  color: var(--pg-fg-2);
}
.ws-draft-text {
  margin-top: .25rem;
  white-space: pre-line;
}
.ws-fd-window {
  margin-top: .35rem;
}
/* The pane looks like the Flows canvas (.pgc-stage, .pgc-viewport): its
   surface and its grid of dots, light or dark with the panel, the dots 10 px
   apart (the canvas's 16 px grid at the card's 128/208 scale) and moving
   with the drawing as it scrolls. */
.ws-fd-pane {
  max-width: 100%;
  max-height: 16rem;
  overflow: auto;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius);
  background-color: var(--pg-bg-1);
  background-image: radial-gradient(circle, color-mix(in srgb, var(--pg-fg-body) 16%, transparent) 1px, transparent 1.25px);
  background-size: 10px 10px;
  background-attachment: local;
}
.ws-fd-pane svg {
  display: block;
}
/* A card at rest: the picture opens the canvas (flowWindow()). */
.ws-fd-stage > .ws-fd-pane {
  cursor: zoom-in;
}
.ws-fd-stage > .ws-fd-pane:focus-visible {
  outline: 2px solid rgb(var(--ws-accent-rgb));
  outline-offset: 2px;
}
.ws-fd-window.is-loading .ws-fd-stage {
  opacity: .6;
  cursor: progress;
}
/* An open card: the Flows canvas read-only (PGWsFlow.embed()) in a 20 rem
   pane, 40 rem when Larger, the full width of the card; on a phone a larger
   pane stays inside the screen. The canvas draws its own frame and takes
   pinch and drag itself. */
.ws-fd-stage.is-open {
  position: relative;
  width: 100%;
  height: 20rem;
}
/* The canvas fills the pane, on a phone too (the Flows screen's stage is
   60vh there). */
.ws-fd-stage .pgc-stage {
  height: 100%;
}
.ws-fd-stage.is-open.is-large {
  height: 40rem;
}
@media (max-width: 575.98px) {
  .ws-fd-stage.is-open.is-large {
    height: min(40rem, 75vh);
  }
}
.ws-fd-bar {
  display: flex;
  justify-content: flex-end;
  gap: .25rem;
  margin-bottom: .25rem;
}
.ws-fd-detail {
  margin-top: .35rem;
}
/* The mini flow window in px, to the visual spec: control arrows 2 px with a
   filled head, data threads 1 px in their type's tone, boxes 128 x 60. */
.ws-fd-arrow {
  fill: none;
  stroke: #7d8696;
  stroke-width: 2;
}
.ws-fd-head {
  fill: #7d8696;
}
.ws-fd-thread {
  fill: none;
  stroke: var(--ws-fd-tone);
  stroke-width: 1;
}
.ws-fd-dot {
  fill: var(--ws-fd-tone);
}
.ws-fd-tone-number-0 { --ws-fd-tone: #2f6fcc; }
.ws-fd-tone-number-1 { --ws-fd-tone: #5a8fdd; }
.ws-fd-tone-number-2 { --ws-fd-tone: #1d56a8; }
.ws-fd-tone-text-0 { --ws-fd-tone: #a8760f; }
.ws-fd-tone-text-1 { --ws-fd-tone: #c08f2e; }
.ws-fd-tone-text-2 { --ws-fd-tone: #8c6200; }
html[data-bs-theme="dark"] .ws-fd-tone-number-0 { --ws-fd-tone: #6ea8ff; }
html[data-bs-theme="dark"] .ws-fd-tone-number-1 { --ws-fd-tone: #9cc4ff; }
html[data-bs-theme="dark"] .ws-fd-tone-number-2 { --ws-fd-tone: #4d8fe8; }
html[data-bs-theme="dark"] .ws-fd-tone-text-0 { --ws-fd-tone: #e9b44c; }
html[data-bs-theme="dark"] .ws-fd-tone-text-1 { --ws-fd-tone: #f5cf7d; }
html[data-bs-theme="dark"] .ws-fd-tone-text-2 { --ws-fd-tone: #f0c060; }
.ws-fd-box rect {
  fill: var(--pg-bg-body);
  stroke: var(--pg-border-color);
  stroke-width: 1.5;
}
.ws-fd-box.is-outbound rect {
  stroke: var(--pg-warning);
}
.ws-fd-box.is-added rect,
.ws-fd-box.is-changed rect {
  stroke: var(--pg-info);
  stroke-dasharray: 5 3;
  fill: var(--pg-info-bg-subtle);
}
.ws-fd-name {
  fill: var(--pg-fg-body);
  font-size: 11px;
  font-weight: 600;
}
.ws-fd-kind,
.ws-fd-said {
  fill: var(--pg-fg-2);
  font-size: 10px;
}
.ws-fd-said.is-failed {
  fill: var(--pg-danger-ink);
}
.ws-fd-icon {
  fill: none;
  stroke: var(--pg-fg-2);
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}
/* A flow box kind's line icon (flowIcon() in workspace.js), in the colour
   of the text around it, 16 px so its stroke stays 1.5 px. */
.ws-flow-icon {
  flex: none;
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  vertical-align: -.125em;
}
.ws-fd-out {
  fill: none;
  stroke: var(--pg-warning);
  stroke-width: 1.5;
  stroke-linecap: round;
}
.ws-fd-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .5rem;
}
.ws-fd-try {
  white-space: pre-line;
}
.ws-draft-actions {
  display: flex;
  flex-wrap: wrap;
  gap: .35rem;
  margin-top: .45rem;
}
.ws-change.ws-change-applied,
.ws-change.ws-change-dismissed,
.ws-change.ws-change-stale,
.ws-change.ws-change-failed {
  border-style: solid;
  border-color: var(--pg-border-color);
  background: transparent;
}
.ws-change-record {
  min-width: 0;
  overflow-wrap: anywhere;
}
.ws-change-type {
  margin-left: auto;
  font-size: .72rem;
  color: var(--pg-fg-2);
  white-space: nowrap;
}
.ws-change-fields {
  display: grid;
  grid-template-columns: minmax(6rem, max-content) 1fr;
  gap: .15rem .6rem;
  margin: .35rem 0 0;
}
.ws-change-fields dt {
  font-weight: 500;
  color: var(--pg-fg-2);
}
.ws-change-fields dd {
  margin: 0;
  min-width: 0;
  overflow-wrap: anywhere;
}
.ws-change-from {
  color: var(--pg-fg-2);
  text-decoration: line-through;
}
.ws-change-arrow {
  margin: 0 .3rem;
  color: var(--pg-fg-2);
}
.ws-change-to {
  font-weight: 600;
}
.ws-change-warning {
  margin-top: .35rem;
  font-size: .78rem;
  color: var(--pg-warning-fg-emphasis);
}
.ws-change-action {
  flex: none;
  padding: .05rem .45rem;
  border-radius: var(--ws-radius);
  font-size: .7rem;
  font-weight: 600;
  white-space: nowrap;
  color: var(--pg-primary-fg-emphasis);
  background: var(--pg-primary-bg-subtle);
}
.ws-change-do-delete .ws-change-action {
  color: var(--pg-danger-fg-emphasis);
  background: var(--pg-danger-bg-subtle);
}
.ws-change-held {
  color: var(--pg-fg-2);
}
.ws-change-fields .ws-change-to .ws-chip {
  margin: 0 .2rem .2rem 0;
  font-weight: 500;
}
@media (max-width: 575.98px) {
  .ws-change-fields {
    grid-template-columns: 1fr;
  }
  .ws-change-fields dd {
    margin-bottom: .25rem;
  }
}
/* Claude's opened row (ws_claude_row_html()): the switch with its one line
   and "How does this work?", two columns of fields (Application and Summary
   channel, Routine address and Token), then Try and Set up on claude.ai
   with the newest request beside them. */
.ws-claude-lead {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}
.ws-claude-how-link,
.ws-claude-last {
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
}
.ws-claude-how-link {
  color: var(--pg-accent);
  font-weight: var(--pg-weight-strong);
  text-decoration: none;
}
.ws-claude-how-link:hover {
  text-decoration: underline;
}
.ws-claude-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px 12px;
}
.ws-claude-cell {
  min-width: 0;
}
.ws-claude-pair {
  display: flex;
  gap: 8px;
}
.ws-claude-pair > .ws-claude-select:first-child {
  flex: 1;
  min-width: 0;
}
.ws-claude-pair > .ws-claude-select + .ws-claude-select {
  flex: none;
  width: 7.5rem;
}
.ws-claude-select {
  position: relative;
}
.ws-claude-select > select {
  -webkit-appearance: none;
  appearance: none;
  padding-right: 22px;
  text-overflow: ellipsis;
  cursor: pointer;
}
.ws-claude-select > .pg-input-end {
  position: absolute;
  right: 12px;
  pointer-events: none;
}
.ws-claude-token > input {
  font-family: var(--bs-font-monospace);
}
.ws-claude-token > .pg-icon-button {
  flex: none;
  margin-right: -6px;
}
.ws-claude-token > .pg-icon-button + .pg-icon-button {
  margin-left: -6px;
}
.ws-claude-token > [aria-pressed="true"][data-ws-claude-clear] {
  color: var(--pg-tone-rose-text);
}
.ws-claude-acts {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
}
.ws-claude-last {
  min-width: 0;
  max-width: 100%;
  margin-left: 6px;
  color: var(--pg-fg-3);
  text-align: start;
}
.ws-claude-last:hover {
  color: var(--pg-fg-2);
  text-decoration: underline;
}
.ws-claude-fold {
  margin-top: 16px;
}
@media (max-width: 575.98px) {
  .ws-claude-grid {
    grid-template-columns: 1fr;
  }
  .ws-claude-cell[aria-hidden="true"] {
    display: none;
  }
}
.ws-claude-copy {
  display: flex;
  align-items: flex-start;
  gap: .35rem;
}
.ws-claude-copy .pg-input {
  font-size: var(--pg-text-meta);
}
/* The steps for connecting Claude (claude_setup.php), drawn by the set-up
   drawer of Claude's row in a .stepper: a title, one sentence, the values to
   copy. claude.ai's own names stay bold and unbroken. */
.ws-claude-setup-steps .ws-ui {
  font-weight: 600;
  color: var(--pg-fg-emphasis);
  white-space: nowrap;
}
.ws-claude-setup-steps a.ws-ui {
  color: var(--pg-primary);
  text-decoration: none;
}
.ws-claude-setup-steps a.ws-ui:hover {
  text-decoration: underline;
}
.ws-claude-step-body {
  padding-top: .55rem;
}
.ws-claude-step-title {
  font-size: var(--pg-text-base);
  font-weight: var(--pg-weight-strong);
  color: var(--pg-fg-emphasis);
  margin-bottom: 2px;
}
.ws-claude-step-body > .pg-card-inner,
.ws-claude-step-body > .ws-claude-code {
  margin-top: 10px;
}
/* A value to copy: its name, the value in a borderless read-only field, Copy
   at the row's end. */
.ws-claude-value-name {
  flex: 0 0 auto;
  min-width: 4.5rem;
  margin: 0;
}
.ws-claude-value-field {
  flex: 1 1 auto;
  min-width: 0;
  padding: 0;
  border: 0;
  background: none;
  color: var(--pg-fg-body);
  font-size: var(--pg-text-meta);
  text-overflow: ellipsis;
}
.ws-claude-value-field:focus-visible {
  outline: 2px solid var(--pg-primary);
  outline-offset: 3px;
  border-radius: 4px;
}
/* A text to copy: the inner card's surface, the text unwrapped and
   scrolling on its own, Copy in the top corner beside it rather than over
   it. */
.ws-claude-code {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 8px 8px 12px;
  border-radius: 10px;
  background: var(--pg-surface-inset);
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
}
.ws-claude-code > textarea {
  flex: 1 1 auto;
  min-width: 0;
  padding: 2px 0;
  border: 0;
  background: none;
  color: var(--pg-fg-2);
  font-size: 12px;
  line-height: 1.6;
  white-space: pre;
  overflow: auto;
  resize: none;
}
.ws-claude-code > textarea:focus-visible {
  outline: 2px solid var(--pg-primary);
  outline-offset: 2px;
  border-radius: 4px;
}
.ws-claude-code > .ws-claude-copy-button {
  flex: 0 0 auto;
}
/* Which name Claude answers under: a quiet note in the accent's tint. */
.ws-claude-note {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-top: 18px;
  padding: 10px 12px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--pg-primary) 9%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pg-primary) 24%, transparent);
  color: var(--pg-fg-2);
  font-size: var(--pg-text-meta);
}
.ws-claude-note > .bi {
  flex: 0 0 auto;
  margin-top: 1px;
  color: var(--pg-primary);
}
.ws-claude-recent-row {
  align-items: flex-start;
  font-size: var(--pg-text-2);
}
.ws-claude-recent-row > .bi {
  margin-top: .15rem;
  color: var(--pg-fg-2);
}
/* The decision timeline: a day heading, then the day's decisions on a line
   of dots - the time on its left, the decision's card on its right. Its two
   days share a row of the toolbar, narrower on a phone. */
.ws-tl-dates {
  flex: 0 1 22rem;
  min-width: 0;
}
.ws-tl-dates > .pg-date-box {
  flex: 1 1 0;
  min-width: 0;
}
.ws-tl-summary {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .25rem 1rem;
  font-size: .85rem;
  color: var(--pg-fg-2);
  margin-bottom: .75rem;
}
.ws-tl-hidden {
  font-size: .85rem;
}
.ws-tl-hidden summary {
  cursor: pointer;
}
.ws-tl-day + .ws-tl-day {
  margin-top: 1.25rem;
}
.ws-tl-date {
  font-size: .78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .04em;
  color: var(--pg-fg-2);
  margin: 0 0 .5rem 5.75rem;
}
.ws-tl-item {
  display: grid;
  grid-template-columns: 3rem 1.75rem minmax(0, 1fr);
  column-gap: .5rem;
}
.ws-tl-time {
  text-align: right;
  font-size: .78rem;
  font-variant-numeric: tabular-nums;
  color: var(--pg-fg-2);
  padding-top: .95rem;
}
.ws-tl-line {
  position: relative;
}
.ws-tl-line::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 2px;
  transform: translateX(-50%);
  background: var(--pg-border-color);
}
.ws-tl-item:first-child .ws-tl-line::before {
  top: 1.35rem;
}
.ws-tl-item:last-child .ws-tl-line::before {
  bottom: calc(100% - 1.35rem);
}
.ws-tl-item:only-child .ws-tl-line::before {
  display: none;
}
.ws-tl-dot {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.6rem;
  height: 1.6rem;
  margin: .55rem auto 0;
  border-radius: 50%;
  border: 2px solid var(--pg-success);
  background: var(--pg-bg-body);
  color: var(--pg-success);
  font-size: .78rem;
}
.ws-tl-note .ws-tl-dot {
  border-color: var(--pg-info);
  color: var(--pg-info);
}
.ws-tl-by-claude .ws-tl-dot {
  border-color: var(--ws-accent);
  color: var(--ws-accent);
}
.ws-tl-card {
  padding: .65rem .85rem;
  margin-bottom: .75rem;
}
.ws-tl-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .35rem .6rem;
  margin-bottom: .35rem;
  font-size: .82rem;
}
.ws-tl-channel {
  display: inline-flex;
  align-items: center;
  gap: .15rem;
  font-weight: 600;
  color: var(--pg-fg-body);
  text-decoration: none;
}
.ws-tl-channel:hover {
  text-decoration: underline;
}
.ws-tl-ai {
  display: inline-flex;
  align-items: center;
  gap: .25rem;
  font-size: .72rem;
  font-weight: 600;
  padding: 0 .4rem;
  border-radius: var(--ws-radius-xs);
  background: var(--ws-soft);
  color: var(--ws-accent);
}
.ws-tl-file {
  display: inline-block;
  margin-top: .5rem;
  font-size: .85rem;
}
.ws-tl-file img {
  display: block;
  max-width: 100%;
  max-height: 8rem;
  border-radius: var(--ws-radius-sm);
}
.ws-tl-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .25rem .75rem;
  margin-top: .5rem;
  font-size: .78rem;
  color: var(--pg-fg-2);
}
.ws-tl-who {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  color: var(--pg-fg-body);
}
.ws-tl-who .avatar {
  --bs-avatar-size: 1.25rem;
}
.ws-tl-more {
  text-align: center;
  padding: .25rem 0 1rem;
}
.ws-tl-side {
  position: sticky;
  top: calc(var(--pg-navbar-h) + 1rem);
}
.ws-tl-side .list-group-item {
  font-size: .85rem;
}
@media (max-width: 575.98px) {
  .ws-tl-item {
    grid-template-columns: 2.4rem 1.4rem minmax(0, 1fr);
    column-gap: .35rem;
  }
  .ws-tl-date {
    margin-left: 4.5rem;
  }
  .ws-tl-dot {
    width: 1.35rem;
    height: 1.35rem;
    font-size: .7rem;
  }
  .ws-tl-card {
    padding: .55rem .65rem;
  }
}
/* The Workspace list in the main menu's Workspace panel (workspace_side.js,
   includes/workspace/nav.php). The menu body is the one scroller, so the
   search head sticks to its top edge instead of the list scrolling in a
   column of its own; it takes the menu's own ground so the list does not
   show through it. The ws- id brings the --ws-* tokens to every panel
   page. */
/* An entry scrolled to stops clear of the head. */
#menu .menu-body:has(.pg-menu-panel.is-open #ws-menu-side) {
  padding-bottom: 0;
  scroll-padding: 3rem 0 9rem;
}
#ws-menu-side .ws-side-head {
  position: sticky;
  top: 0;
  z-index: 2;
  gap: .25rem;
  margin: 0 -2px;
  padding: .25rem 2px .5rem;
  background: var(--pg-navbar-bg);
}
/* The one search field: a button drawn as a field, opening the workspace
   search (workspace_palette.js) or the page that opens it. */
#ws-menu-side .ws-side-find {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  gap: .4rem;
  min-width: 0;
  height: 1.9rem;
  padding: 0 .7rem;
  border: 1px solid var(--pg-border-color);
  border-radius: 999px;
  background: var(--pg-bg-body);
  color: var(--pg-fg-2);
  font-size: .8rem;
  text-align: start;
  text-decoration: none;
  cursor: text;
}
#ws-menu-side .ws-side-find:hover {
  border-color: color-mix(in srgb, var(--ws-accent) 45%, var(--pg-border-color));
}
#ws-menu-side .ws-side-find:focus-visible {
  outline: 2px solid var(--ws-accent);
  outline-offset: 1px;
}
#ws-menu-side .ws-side-find-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
:is(#ws-menu-side, .ws-side-head-tools) .ws-side-tool {
  flex: 0 0 auto;
  width: 1.9rem;
  height: 1.9rem;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
:is(#ws-menu-side, .ws-side-head-tools) .ws-side-tool.active {
  color: var(--ws-accent);
}
/* The new channel and the settings stand beside the panel's name
   (workspace_side.js), which then starts at the left; the last one keeps
   clear of the menu's edge. */
#menu .pg-menu-panel-head .ws-side-head-tools {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: .125rem;
  margin-left: auto;
  padding-right: .25rem;
}
#menu .pg-menu-panel-head:has(.ws-side-head-tools) .pg-menu-panel-title {
  padding-right: 0;
  text-align: start;
}
/* Two squares beside the name: the New channel button narrowed to
   1.625rem and still 1.9rem tall was an upright oval against the menu's
   edge. A little smaller than the list's buttons, so the name
   keeps to one line when a long list gives the menu body a classic
   scrollbar; still over the 24px target size. */
#menu .pg-menu-panel-head .ws-side-head-tools .ws-side-tool {
  width: 1.75rem;
  height: 1.75rem;
}
/* The search keeps its row: its key where Ctrl+K opens it. */
#ws-menu-side .ws-side-find-key {
  flex: 0 0 auto;
  margin-left: auto;
  padding: 0 .3rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--pg-radius-sm);
  background: transparent;
  color: var(--pg-fg-2);
  font-family: inherit;
  font-size: .68rem;
  line-height: 1.4;
}
@media (pointer: coarse) {
  #ws-menu-side .ws-side-find-key {
    display: none;
  }
}
/* The parts of the Channels section follow each other without headings:
   pinned, the groups, the person's other channels, those not joined. */
#ws-menu-side .ws-side-part + .ws-side-part {
  margin-top: .35rem;
}
#ws-menu-side .ws-side-groups:empty {
  display: none;
}
#ws-menu-side .ws-channel-link.ws-notjoined {
  opacity: .72;
}
#ws-menu-side .ws-channel-link.ws-notjoined:hover,
#ws-menu-side .ws-channel-link.ws-notjoined.active {
  opacity: 1;
}
/* A group reads as a folder of the Channels section: its name as written,
   not in a section heading's capitals, its folder in the channels' own
   column and the chevron at the end of the line, shown on hover and while
   the group is closed. Its channels and the groups inside it hang under it
   on a thin line of its colour. */
#ws-menu-side .ws-group-title {
  padding: 0;
  font-size: .85rem;
  font-weight: 600;
  letter-spacing: normal;
  text-transform: none;
}
#ws-menu-side .ws-group-toggle {
  align-items: center;
  gap: 8px;
  min-height: calc(30px - .3rem + var(--ws-row-y, .3rem));
  padding: 0 8px;
  border-radius: 8px;
}
#ws-menu-side .ws-group-icon {
  width: 1rem;
  height: auto;
  background: none;
  font-size: .9rem;
  color: color-mix(in srgb, var(--ws-group, var(--pg-fg-2)) 80%, var(--pg-fg-emphasis));
}
#ws-menu-side .ws-group-toggle .ws-group-chevron {
  margin-left: auto;
  opacity: 0;
  transition: opacity .12s ease;
}
#ws-menu-side .ws-group-toggle:is(:hover, :focus-visible, [aria-expanded="false"]) .ws-group-chevron {
  opacity: .7;
}
#ws-menu-side .ws-group-inner {
  margin: 1px 0 .25rem .95rem;
  border-left: 1.5px solid color-mix(in srgb, var(--ws-group, var(--pg-border-color)) 45%, transparent);
}
#ws-menu-side .ws-group-inner > .ws-channel-link {
  border-radius: 0 var(--ws-radius-sm) var(--ws-radius-sm) 0;
}
#ws-menu-side .ws-side-subgroup {
  margin-left: 0;
  padding-left: 0;
  border-left: 0;
}
#ws-menu-side .ws-side-scroll {
  overflow: visible;
  padding: 0 0 .75rem;
}
#ws-menu-side .ws-side-section:first-child {
  margin-top: .25rem;
}
/* A long press on a phone is the item's own menu on the channel screen,
   not the browser's link card. */
#ws-menu-side a.ws-channel-link {
  -webkit-touch-callout: none;
}
#ws-menu-side .ws-skeleton {
  padding: var(--ws-space-2) 0;
}
/* The list could not be read: what happened, and the way to ask again. */
#ws-menu-side .ws-side-error {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: .5rem;
  padding: .5rem .25rem;
  color: var(--pg-fg-2);
  font-size: .85rem;
}
/* The rows of the Workspace list (workspace_side.js; board L3 of
   plans/workspace-interface): 30 px (a little less in the compact density,
   through --ws-row-y), the channel's 18 px tile, the name, its marks at the
   end. Written on the box's class, so the Design examples
   screen draws the same row ("Workspace list row"). */
.ws-menu-side .ws-channel-link {
  gap: 8px;
  min-height: calc(30px - .3rem + var(--ws-row-y, .3rem));
  padding: 0 8px;
  border-radius: 8px;
  color: var(--pg-fg-2);
  font-size: var(--pg-text-base);
}
.ws-menu-side .ws-channel-link:hover {
  background: var(--pg-hover);
  color: var(--pg-fg-body);
}
/* The open entry: the quiet fill and an accent line at its left. */
.ws-menu-side .ws-channel-link.active {
  background: var(--pg-quiet);
  box-shadow: inset 2px 0 0 var(--pg-accent);
  color: var(--pg-fg-emphasis);
  font-weight: inherit;
}
.ws-menu-side .ws-channel-link.ws-unread {
  color: var(--pg-fg-emphasis);
}
.ws-menu-side .ws-channel-link.ws-unread .ws-channel-name {
  font-weight: var(--pg-weight-title);
}
/* Today and the rarer screens keep their icon in the tiles' column. */
.ws-menu-side .ws-channel-link[data-ws-nav] > .bi {
  flex: none;
  width: 18px;
  text-align: center;
}
/* The tile: the look's icon tile at 18 px, in the channel's colour; its
   icon keeps the ink the [data-ws-colored] rule pulls toward the text
   colour, 3:1 on every tone. */
.ws-menu-side .ws-side-ch-tile {
  width: 18px;
  height: 18px;
  border-radius: 6px;
  font-size: var(--pg-text-count);
}
.ws-menu-side .ws-channel-link[data-ws-colored] .ws-side-ch-tile {
  --pg-tone: var(--ws-ch);
}
/* Muted, or not joined: the tile grey and the name in the third ink. */
.ws-menu-side .ws-channel-link:is(.ws-side-muted, .ws-notjoined) .ws-side-ch-tile {
  --pg-tone: var(--pg-tone-gray);
  color: var(--pg-fg-3);
}
.ws-menu-side .ws-channel-link.ws-side-muted:not(.active) {
  color: var(--pg-fg-3);
}
/* The marks at the row's end: the draft's pencil, the struck bell, the
   count or a muted channel's dot. */
.ws-menu-side .ws-side-marks {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}
.ws-menu-side :is(.ws-side-draft, .ws-side-muted-bell) {
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
}
.ws-menu-side .ws-side-dot {
  width: 7px;
  height: 7px;
  margin: 0 5px;
  border-radius: 50%;
  background: var(--pg-fg-3);
}
/* The count: unread in a quiet pill, mentions in the accent. */
.ws-menu-side .ws-count {
  display: inline-grid;
  place-items: center;
  min-width: 20px;
  height: 18px;
  padding: 0 6px;
  border-radius: 9px;
  background: var(--pg-quiet);
  color: var(--pg-fg-2);
  font-size: var(--pg-text-count);
  font-weight: var(--pg-weight-title);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.ws-menu-side .ws-count.ws-count-mention {
  background: var(--pg-accent);
  color: var(--pg-on-accent-fill);
}
/* Pointing at a row the screen can pin shows the pin and "⋯" in the place
   of its marks; a pinned channel's pin shows only then too. */
.ws-menu-side .ws-side-row-tools {
  display: none;
  flex: none;
  align-items: center;
  gap: 2px;
  margin-left: auto;
}
.ws-menu-side .ws-channel-link.ws-side-has-tools:hover .ws-side-row-tools {
  display: inline-flex;
}
.ws-menu-side .ws-channel-link.ws-side-has-tools:hover .ws-side-marks {
  display: none;
}
.ws-menu-side .ws-side-row-tools > .no-popover {
  display: inline-grid;
  place-items: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border-radius: 6px;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
  cursor: pointer;
}
.ws-menu-side .ws-side-row-tools > .no-popover:hover {
  background: var(--pg-hover);
  color: var(--pg-fg-body);
}
/* Join on a channel not joined, on the channel screen. */
.ws-menu-side .ws-side-join-now {
  color: var(--pg-accent);
  font-size: var(--pg-text-count);
  font-weight: var(--pg-weight-strong);
  cursor: pointer;
}
/* A hairline closes the pinned channels when more follows. */
.ws-menu-side .ws-side-pinned:not(:last-child) {
  padding-bottom: 4px;
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
/* Section names as written, small and in the third ink; the chevron at the
   end shows on pointing, on focus and while the section is closed. */
.ws-menu-side .ws-side-title {
  min-height: 28px;
  padding: 0 8px;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
  font-weight: var(--pg-weight-strong);
  letter-spacing: normal;
  text-transform: none;
}
.ws-menu-side .ws-side-toggle-chevron {
  margin-left: auto;
  font-size: var(--pg-text-count);
  opacity: 0;
  transition: opacity .12s ease;
}
.ws-menu-side .ws-side-toggle:is(:hover, :focus-visible, [aria-expanded="false"]) .ws-side-toggle-chevron {
  opacity: 1;
}
/* All / Unread (board L2 of plans/workspace-interface): the segmented
   control across the list's width under the search field, the two
   segments sharing it. */
.ws-menu-side .ws-side-filter {
  display: flex;
  margin: 0 0 4px;
}
.ws-menu-side .ws-side-filter > .pg-seg-item {
  flex: 1 1 0;
  min-width: 0;
}
/* Mark all as read at the Channels heading's right while Unread is chosen. */
.ws-menu-side .ws-side-read-all {
  flex: none;
  height: 22px;
  padding: 0 6px;
  font-size: var(--pg-text-meta);
}
/* Nothing unread: one quiet line in place of the rows. */
.ws-menu-side .ws-side-all-read {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 30px;
  padding: 0 8px;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-2);
}
.ws-menu-side .ws-group-toggle:disabled {
  color: inherit;
  cursor: default;
}
/* "N channels you could join": a quiet row that opens them in place. */
.ws-menu-side .ws-side-join {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: calc(30px - .3rem + var(--ws-row-y, .3rem));
  padding: 0 8px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-2);
  text-align: start;
}
.ws-menu-side .ws-side-join:hover {
  background: var(--pg-hover);
  color: var(--pg-fg-body);
}
.ws-menu-side .ws-side-join-icon {
  flex: none;
  width: 18px;
  text-align: center;
}
.ws-menu-side .ws-side-join-chevron {
  margin-left: auto;
  font-size: var(--pg-text-count);
}
/* The tools dock (boards L1, L2 of plans/workspace-interface): a head line
   "Tools" with "⋯" (More) at its right, the screens of a working day four
   across, each a 26 px tile in its tone over its short name. It has one
   state and is never folded. The menu body is the one scroller, so the dock
   sticks to its bottom edge as the head sticks to its top. */
.ws-menu-side .ws-side-dock {
  position: sticky;
  bottom: 0;
  z-index: 2;
  margin: 0 -2px;
  padding: 2px 2px 8px;
  border-top: 1px solid var(--pg-border-color-translucent);
  background: var(--pg-navbar-bg);
}
.ws-menu-side .ws-side-dock-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 28px;
  padding: 0 0 0 4px;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
  font-weight: var(--pg-weight-strong);
}
.ws-menu-side .ws-side-cells {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 2px;
}
.ws-menu-side .ws-side-cell {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 4px;
  min-width: 0;
  padding: 6px 2px 5px;
  border-radius: 9px;
  color: var(--pg-fg-2);
  font-size: var(--pg-text-count);
  line-height: 1.2;
  text-decoration: none;
}
.ws-menu-side .ws-side-cell:hover {
  background: var(--pg-hover);
  color: var(--pg-fg-body);
}
/* The open screen's cell: the quiet fill. */
.ws-menu-side .ws-side-cell.active {
  background: var(--pg-quiet);
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
  color: var(--pg-fg-emphasis);
}
.ws-menu-side .ws-side-cell-tile {
  width: 26px;
  height: 26px;
  border-radius: 8px;
  font-size: 13px;
}
.ws-menu-side .ws-side-cell-name {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* A count at the tile's top right corner: the tasks due today or before in
   the accent, another (the unread e-mails) quiet. */
.ws-menu-side .ws-side-cell-count {
  position: absolute;
  top: 2px;
  left: calc(50% + 5px);
  display: inline-grid;
  place-items: center;
  min-width: 15px;
  height: 15px;
  padding: 0 4px;
  border-radius: 8px;
  background: var(--pg-quiet);
  box-shadow: 0 0 0 2px var(--pg-navbar-bg);
  color: var(--pg-fg-2);
  font-size: var(--pg-text-count);
  font-weight: var(--pg-weight-title);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.ws-menu-side .ws-side-cell-count.ws-side-cell-due {
  background: var(--pg-accent);
  color: var(--pg-on-accent-fill);
}
/* Each screen's tone on its tile; My calendar keeps the grey. */
.ws-menu-side .ws-side-cell:is([data-ws-nav="tasks"], [data-ws-nav="mcp"]) { --pg-tone: var(--pg-tone-teal); }
.ws-menu-side .ws-side-cell:is([data-ws-nav="notes"], [data-ws-nav="wtables"]) { --pg-tone: var(--pg-tone-amber); }
.ws-menu-side .ws-side-cell:is([data-ws-nav="flows"], [data-ws-nav="timeline"]) { --pg-tone: var(--pg-tone-blue); }
.ws-menu-side .ws-side-cell:is([data-ws-nav="calendar"], [data-ws-nav="mail"]) { --pg-tone: var(--pg-tone-rose); }
.ws-menu-side .ws-side-cell[data-ws-nav="board"] { --pg-tone: var(--pg-tone-violet); }
/* More: a card over the list, above the dock, its screens as rows. */
.ws-menu-side .ws-side-more-card {
  position: absolute;
  right: 2px;
  bottom: calc(100% + 4px);
  left: 2px;
  padding: 6px;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--pg-radius-card);
  /* The menu's own solid ground, as the head and the dock: the glass of
     --pg-surface-menu let the rows under it show through. */
  background: var(--pg-navbar-bg);
  box-shadow: var(--pg-shadow-float);
}
.ws-menu-side .ws-side-more-card .ws-channel-link {
  min-height: 32px;
}

/* The Design examples screen draws the rows at the menu panel's width. */
.pg-look-ws-list {
  width: 250px;
  max-width: 100%;
}
/* Room over the dock for its open More card. */
.pg-look-ws-dock {
  padding-top: 11rem;
}
/* The workspace screens other than the channels: the screen beside the
   main menu, whose Workspace panel is the way around them. */
.ws-shell {
  display: flex;
  align-items: flex-start;
}
.ws-shell-main {
  flex: 1 1 auto;
  min-width: 0;
}
/* The Today page's scroll area (showHome() in workspace.js); the cards
   inside are styled by ws_today.src.css. */
.ws-home {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 1.5rem var(--ws-space-4, 1rem) 2.5rem;
}
.ws-home > * {
  max-width: 74rem;
  margin-right: auto;
  margin-left: auto;
}
/* Worked-out figures: a formula cell and a hesap block show their value,
   the formula in the tooltip. */
.ws-calc {
  font-variant-numeric: tabular-nums;
  border-bottom: 1px dotted rgba(var(--ws-accent-rgb), .6);
  cursor: help;
}
.ws-calc-error {
  color: var(--pg-danger);
  border-bottom-color: var(--pg-danger);
}
.ws-calc-block {
  display: inline-block;
  min-width: min(22rem, 100%);
  max-width: 100%;
  margin: .25rem 0;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
  overflow: hidden;
}
.ws-calc-block-head {
  padding: .25rem .6rem;
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .03em;
  text-transform: uppercase;
  color: var(--ws-accent);
  background: var(--ws-soft);
}
.ws-calc-table {
  margin: 0;
}
.ws-calc-table th {
  font-weight: 500;
}
.ws-calc-derived th,
.ws-calc-derived td {
  font-weight: 700;
}
.ws-calc-remark td {
  font-size: .8rem;
  color: var(--pg-fg-2);
}
/* A hesap block's groups: the heading, the lines in it, the subtotal; a
   blank line as a gap. */
.ws-calc-group th {
  padding-top: .45rem;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .02em;
  color: var(--pg-fg-2);
}
.ws-calc-in th,
.ws-calc-remark.ws-calc-in td {
  padding-left: 1.25rem;
}
.ws-calc-total th,
.ws-calc-total td {
  font-weight: 700;
  border-top: 1px solid var(--pg-border-color-translucent);
  background: var(--pg-bg-1);
}
.ws-calc-func {
  margin-left: .25rem;
  font-size: .72rem;
  font-weight: 500;
  color: var(--pg-fg-2);
}
.ws-calc-gap td {
  height: .6rem;
  padding: 0;
  border-bottom: 0;
}
/* A figure a reader may try another value for (assets/js/workspace_editor.js). */
.ws-msg-body [data-ws-calc-input] {
  cursor: text;
  border-bottom-style: dashed;
}
.ws-msg-body [data-ws-calc-input]:hover {
  background: rgba(var(--ws-accent-rgb), .08);
}
.ws-rich [data-ws-calc-input] {
  cursor: inherit;
}
.pg-input.ws-calc-live-input {
  display: inline-block;
  width: 7.5rem;
  padding: 0 .35rem;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.ws-calc-block.ws-calc-tried {
  border-color: rgba(var(--ws-accent-rgb), .55);
}
.ws-calc-block-head {
  display: flex;
  align-items: center;
  gap: .3rem;
}
.ws-calc-reset {
  margin-left: auto;
  padding: 0;
  font-size: .72rem;
  font-weight: 600;
  text-transform: none;
  letter-spacing: 0;
}
.ws-calc.ws-calc-tried,
.ws-calc-tried .ws-calc-derived .ws-calc,
.ws-calc-tried .ws-calc-total .ws-calc {
  color: var(--ws-accent);
}
/* The calculation window: its tools, settings and the names to pick */
.ws-calc-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .15rem;
  margin-bottom: .4rem;
}
.ws-calc-tools .ws-calc-op {
  min-width: 2rem;
  font-family: var(--pg-font-mono);
  font-weight: 600;
}
.ws-calc-settings {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .35rem .6rem;
  margin-bottom: .4rem;
}
.ws-calc-settings select.pg-input {
  width: auto;
}
.ws-calc-settings .pg-input {
  width: 7rem;
}
.ws-calc-names {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .25rem;
  margin-top: .5rem;
}
.ws-calc-names-label {
  margin-right: .25rem;
  font-size: .75rem;
  color: var(--pg-fg-2);
}
.ws-calc-name:hover {
  color: var(--ws-accent);
}
/* A note's earlier versions */
.ws-nb-versions-grid {
  display: grid;
  grid-template-columns: minmax(12rem, 16rem) minmax(0, 1fr);
  gap: 1rem;
  align-items: start;
}
.ws-nb-versions-list {
  max-height: 65vh;
  overflow-y: auto;
}
.ws-nb-versions-view {
  min-width: 0;
  min-height: 8rem;
  padding: .75rem;
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
}
@media (max-width: 767.98px) {
  .ws-nb-versions-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .ws-nb-versions-list {
    max-height: 30vh;
  }
}
/* Notes brought in from other apps: the drop area, the files and what each becomes */
.ws-nb-import-drop {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--ws-space-1);
  padding: 2rem var(--ws-space-4);
  border: 2px dashed var(--pg-border-color);
  border-radius: var(--ws-radius);
  text-align: center;
  cursor: pointer;
  transition: border-color .15s ease, background-color .15s ease;
}
.ws-nb-import-drop > .bi {
  font-size: 2rem;
  color: var(--ws-accent);
}
.ws-nb-import-drop:hover,
.ws-nb-import-drop.ws-nb-import-over {
  border-color: var(--ws-accent);
  background-color: rgba(var(--ws-accent-rgb), .06);
}
/* The file picker inside is hidden; a keyboard focus on it shows on the
   area. A rule of its own: a browser without :has() drops only this one. */
.ws-nb-import-drop:has(:focus-visible) {
  border-color: var(--ws-accent);
  background-color: rgba(var(--ws-accent-rgb), .06);
  box-shadow: 0 0 0 .2rem rgba(var(--ws-accent-rgb), .25);
}
.ws-nb-import-list {
  max-height: 55vh;
  overflow-y: auto;
  border-radius: var(--ws-radius-sm);
}
.ws-nb-import-row {
  display: flex;
  gap: var(--ws-space-2);
  align-items: flex-start;
  cursor: pointer;
}
.ws-nb-import-row :is(.check, .radio) {
  flex: none;
  margin-top: .2rem;
}
.ws-nb-import-row.ws-nb-import-off {
  cursor: default;
}
.ws-nb-import-row.ws-nb-import-off .ws-nb-import-main > .fw-semibold {
  opacity: .6;
}
.ws-nb-import-main {
  flex: 1 1 auto;
  min-width: 0;
}
.ws-nb-import-path {
  overflow: hidden;
  font-size: .75rem;
  color: var(--pg-fg-2);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-nb-import-state {
  font-size: .8rem;
  color: var(--pg-fg-2);
}
.ws-nb-import-kind.ws-nb-import-new,
.ws-nb-import-badge.ws-nb-import-new {
  color: var(--pg-success-fg-emphasis);
}
.ws-nb-import-kind.ws-nb-import-update,
.ws-nb-import-badge.ws-nb-import-update {
  color: var(--ws-accent);
}
.ws-nb-import-kind.ws-nb-import-error,
.ws-nb-import-badge.ws-nb-import-error {
  color: var(--pg-danger-fg-emphasis);
}
.ws-nb-import-badge {
  font-weight: 500;
  background-color: var(--pg-bg-1);
  color: var(--pg-fg-2);
}
.ws-nb-import-warn {
  font-size: .75rem;
  color: var(--pg-warning-fg-emphasis);
}
.ws-table-edit td[data-ws-result]::after,
.ws-table-edit th[data-ws-result]::after {
  content: attr(data-ws-result);
  display: block;
  font-size: .72rem;
  font-variant-numeric: tabular-nums;
  text-align: right;
  color: var(--ws-accent);
}
.ws-table-edit .ws-cell-error::after {
  color: var(--pg-danger);
}
/* Workspace notes: the lists, the note, its writing box.
   My Notes is two cards (startNotes() in workspace.js): the list card,
   372 px from 1200 px up and 300 px below, then the note card, 20 px away
   (16 px below 1200 px). Below 1024 px one card at a time. */
.ws-nb {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
}
@media (min-width: 1024px) {
    .ws-nb {
        grid-template-columns: 300px minmax(0, 1fr);
        align-items: start;
    }
    /* The list stays while the note scrolls: sticky under the panel's
       header, its body scrolling inside the card. */
    .ws-nb-list-card {
        position: sticky;
        top: calc(var(--pg-navbar-h) + 16px);
        display: flex;
        flex-direction: column;
        max-height: calc(100vh - var(--pg-navbar-h) - 32px);
    }
    .ws-nb-list-card > .ws-nb-list {
        flex: 1 1 auto;
        min-height: 0;
        overflow-y: auto;
        overscroll-behavior: contain;
    }
}
@media (min-width: 1200px) {
    .ws-nb {
        grid-template-columns: 372px minmax(0, 1fr);
        gap: 20px;
    }
}
.ws-nb-list-card {
    overflow: hidden;
}
/* The list card's head: "Notes", the count, New group and the order; as
   tall as the note card's head, so their lines meet. */
.ws-nb-list-head {
    display: flex;
    flex: none;
    align-items: center;
    gap: 8px;
    min-height: 46px;
    padding-inline: 16px 10px;
    border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-nb-list-title {
    margin: 0;
    font-size: var(--pg-text-base);
    font-weight: var(--pg-weight-strong);
    line-height: var(--pg-leading);
}
.ws-nb-list-count {
    font-size: var(--pg-text-2);
    color: var(--pg-fg-3);
}
.ws-nb-list-tools {
    display: flex;
    align-items: center;
    gap: 4px;
    margin-inline-start: auto;
}
.ws-nb-list {
    display: flex;
    flex-direction: column;
    /* The card's own border closes the last row: its hairline is clipped. */
    margin-bottom: -1px;
}
.ws-nb-section {
    display: flex;
    flex-direction: column;
}
/* A section's head is a band across the card: its group label
   (.pg-group-label with its count, a button that folds the section;
   workspace_note_list.js). A folder's head is a band too, its label set in
   under the section's. */
.ws-nb-section-head {
    display: flex;
    align-items: center;
    gap: 6px;
    min-height: 34px;
    padding: 0 8px;
    border-bottom: 1px solid var(--pg-border-color-translucent);
    background: var(--pg-surface-1);
}
.ws-nb-section-title {
    flex: 1 1 auto;
    min-width: 0;
    margin: 0;
    font: inherit;
}
.ws-nb-section-body {
    display: flex;
    flex-direction: column;
}
.ws-nb-section-body[hidden] {
    display: none;
}
.ws-nb-fold {
    display: flex;
    align-items: center;
    gap: 6px;
    max-width: 100%;
    padding: 4px 8px;
    border: 0;
    border-radius: 8px;
    background: none;
    text-align: start;
    cursor: pointer;
}
.ws-nb-fold:hover {
    color: var(--pg-fg-2);
}
.ws-nb-fold:focus-visible {
    outline: var(--pg-focus-ring-width) solid var(--pg-focus-ring-color);
    outline-offset: calc(var(--pg-focus-ring-width) * -1);
}
/* The fold's gap spaces the count. */
.ws-nb-fold > .pg-group-label-count {
    margin-left: 0;
}
.ws-nb-fold-chevron {
    flex: none;
    font-size: 11px;
    transition: transform .15s ease;
}
.ws-nb-fold[aria-expanded="false"] .ws-nb-fold-chevron {
    transform: rotate(-90deg);
}
[dir="rtl"] .ws-nb-fold[aria-expanded="false"] .ws-nb-fold-chevron {
    transform: rotate(90deg);
}
@media (prefers-reduced-motion: reduce) {
    .ws-nb-fold-chevron {
        transition: none;
    }
}
.ws-nb-section-empty {
    padding: 10px 16px;
    border-bottom: 1px solid var(--pg-border-color-translucent);
    font-size: .8125rem;
    color: var(--pg-fg-2);
}
/* A note's row is a .pg-list-row (workspace.js, drawItem()) with a hairline
   under it, square in the card: the open note is the chosen row, a faint
   accent tint with a 3 px accent edge at its start; its ⋯ stays shown. */
.ws-nb-item {
    padding: 12px;
    padding-inline-start: 16px;
    border-bottom: 1px solid var(--pg-border-color-translucent);
    border-radius: 0;
    cursor: pointer;
}
.ws-nb-item:focus-visible {
    outline: var(--pg-focus-ring-width) solid var(--pg-focus-ring-color);
    outline-offset: calc(var(--pg-focus-ring-width) * -1);
}
.ws-nb-list .ws-nb-item.is-chosen {
    background: color-mix(in srgb, var(--pg-accent) var(--pg-tint-select), transparent);
    box-shadow: inset 3px 0 0 var(--pg-accent);
}
[dir="rtl"] .ws-nb-list .ws-nb-item.is-chosen {
    box-shadow: inset -3px 0 0 var(--pg-accent);
}
/* A note dragged beside the chosen row: the drop line takes the edge's
   place. */
.ws-nb-list .ws-nb-item.is-chosen.ws-nb-drop-before {
    box-shadow: inset 0 2px 0 var(--ws-accent);
}
.ws-nb-list .ws-nb-item.is-chosen.ws-nb-drop-after {
    box-shadow: inset 0 -2px 0 var(--ws-accent);
}
.ws-nb-item.is-chosen .pg-list-row-quick {
    display: flex;
}
/* The head holds marks beside the title (the unread dot, the pin, the
   lock): centred rather than on the text's baseline. */
.ws-nb-item .ws-nb-item-head {
    align-items: center;
}
.ws-nb-item-head > .bi {
    flex: none;
    color: var(--pg-fg-2);
}
.ws-nb-item-head > .ws-nb-item-pin {
    color: var(--pg-primary-ink);
}
/* Changed by somebody else, or answered by Claude, since it was last open:
   the dot after the title and a heavier title, never a tint (the tint means
   open). */
.ws-nb-item-unread .ws-nb-item-name {
    color: var(--pg-fg-emphasis);
    font-weight: var(--pg-weight-title);
}
.ws-nb-item-claude {
    flex: none;
    font-size: .72rem;
    white-space: nowrap;
    color: var(--pg-fg-2);
}
.ws-nb-item-claude-answered {
    color: var(--ws-accent);
    font-weight: 600;
}
.ws-nb-item-more {
    flex: none;
    padding: 0 .2rem;
    border: 0;
    background: transparent;
    color: var(--pg-fg-2);
    opacity: 0;
}
.ws-nb-item-more:focus-visible {
    opacity: 1;
}
/* Note groups as folders in My notes (workspace_note_groups.js): the
   folder's head is a band holding its group label (.ws-nb-fold) and its ⋯,
   set in under the section's band; its notes are set in by 14 px. */
.ws-nb-group-head {
    display: flex;
    align-items: center;
    gap: 2px;
    min-height: 34px;
    padding-inline: 22px 8px;
    border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-nb-group-head:hover {
    background: var(--pg-hover);
}
.ws-nb-group-head:hover .ws-nb-item-more,
.ws-nb-group-head .ws-nb-item-more:focus-visible {
    opacity: 1;
}
.ws-nb-group-toggle {
    flex: 1 1 auto;
    min-width: 0;
}
.ws-nb-group-dot {
    flex: none;
    width: .6rem;
    height: .6rem;
    border-radius: 50%;
}
.ws-nb-group-dot-none {
    border: 1px solid var(--pg-fg-2);
}
.ws-nb-group-name {
    flex: 0 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.ws-nb-group-lock {
    flex: none;
    color: var(--pg-fg-2);
}
/* The notes lock (workspace_note_lock.js): the pane drawn in place of a
   locked note, its narrow form, and the button in a closed locked folder. */
.ws-nb-lock-pane .ws-nb-lock-icon {
    font-size: 2rem;
    color: var(--pg-fg-2);
}
.ws-nb-lock-pane .ws-nb-lock-form {
    width: 100%;
    max-width: 18rem;
    text-align: start;
}
.ws-nb-lock-pin {
    letter-spacing: .3em;
}
.ws-nb-lock-list {
    align-self: flex-start;
}
.ws-nb-group-body {
    display: none;
    flex-direction: column;
}
.ws-nb-group-body > .ws-nb-item,
.ws-nb-group-body > .ws-nb-section-empty {
    padding-inline-start: 30px;
}
.ws-nb-group-body > .ws-nb-lock-list {
    margin-block: 8px;
    margin-inline: 30px 16px;
}
.ws-nb-group.open .ws-nb-group-body {
    display: flex;
}
/* Drag and drop in My notes: where a note or a folder would land. */
.ws-nb-dragging {
    opacity: .45;
}
.ws-nb-drop-into {
    outline: 2px dashed var(--ws-accent);
    outline-offset: -2px;
    border-radius: var(--ws-radius-sm);
}
.ws-nb-drop-before {
    box-shadow: inset 0 2px 0 var(--ws-accent);
}
.ws-nb-drop-after {
    box-shadow: inset 0 -2px 0 var(--ws-accent);
}
/* Shared note groups: a folder's owner, a channel's group card
   (workspace_note_group_shares.js). */
.ws-nb-group-owner {
    margin-inline-start: .4rem;
    font-size: .72rem;
    font-weight: 400;
    color: var(--pg-fg-2);
}
.ws-nb-group-card-notes {
    display: flex;
    flex-direction: column;
    gap: .1rem;
    margin: .35rem 0;
}
.ws-nb-group-card-note {
    display: flex;
    align-items: center;
    gap: .45rem;
    width: 100%;
    padding: .25rem .4rem;
    border: 0;
    border-radius: var(--ws-radius-sm);
    background: transparent;
    color: inherit;
    text-align: start;
}
.ws-nb-group-card-note:hover {
    background: var(--pg-bg-1);
}
.ws-nb-group-card-note:focus-visible {
    outline: 2px solid var(--pg-primary-border-subtle);
    outline-offset: -2px;
}
/* An open note's group as tabs over it (workspace_note_tabs.js). */
.ws-nb-tabs {
    display: flex;
    align-items: center;
    gap: .4rem;
    padding: .35rem .6rem 0;
    border-bottom: 1px solid var(--pg-border-color);
    font-size: .8125rem;
}
.ws-nb-tabs-group {
    display: flex;
    flex: none;
    align-items: center;
    gap: .35rem;
    max-width: 10rem;
    padding-bottom: .35rem;
    font-weight: 600;
}
.ws-nb-tabs-name {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.ws-nb-tabs-row {
    display: flex;
    flex: 1 1 auto;
    gap: .15rem;
    min-width: 0;
    overflow-x: auto;
    overscroll-behavior-x: contain;
    scrollbar-width: thin;
}
.ws-nb-tab {
    display: flex;
    flex: none;
    align-items: center;
    gap: .3rem;
    max-width: 14rem;
    padding: .35rem .65rem;
    border: 0;
    border-bottom: 2px solid transparent;
    background: transparent;
    color: var(--pg-fg-2);
    white-space: nowrap;
}
.ws-nb-tab:hover {
    color: inherit;
    background: var(--pg-bg-1);
}
.ws-nb-tab.active {
    border-bottom-color: var(--ws-accent);
    color: inherit;
    font-weight: 600;
}
.ws-nb-tab:focus-visible,
.ws-nb-tabs-add:focus-visible {
    outline: 2px solid var(--pg-primary-border-subtle);
    outline-offset: -2px;
}
.ws-nb-tab-name {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
}
.ws-nb-tab-mark {
    flex: none;
    font-size: .7rem;
    color: var(--pg-fg-2);
}
.ws-nb-tab-dragging {
    opacity: .5;
}
.ws-nb-tab-drop-before {
    box-shadow: inset 2px 0 0 var(--ws-accent);
}
.ws-nb-tab-drop-after {
    box-shadow: inset -2px 0 0 var(--ws-accent);
}
[dir="rtl"] .ws-nb-tab-drop-before {
    box-shadow: inset -2px 0 0 var(--ws-accent);
}
[dir="rtl"] .ws-nb-tab-drop-after {
    box-shadow: inset 2px 0 0 var(--ws-accent);
}
.ws-nb-tabs-add {
    flex: none;
    margin-bottom: .2rem;
    padding: .15rem .45rem;
    border: 0;
    border-radius: var(--ws-radius-sm);
    background: transparent;
    color: var(--pg-fg-2);
}
.ws-nb-tabs-add:hover {
    background: var(--pg-bg-1);
    color: inherit;
}
/* A phone: the group's name gives the row its room. */
@media (max-width: 575.98px) {
    .ws-nb-tabs-group {
        max-width: 5rem;
    }
    .ws-nb-tab {
        max-width: 9rem;
    }
}
/* No hover on a touch screen: the folder's menu button stays visible. */
@media (pointer: coarse) {
    .ws-nb-group-head .ws-nb-item-more {
        opacity: 1;
    }
}
.ws-nb-item-meta {
    display: flex;
    align-items: center;
    gap: .4rem;
    min-width: 0;
    margin-top: .25rem;
    font-size: .75rem;
    color: var(--pg-fg-2);
}
.ws-nb-faces {
    display: inline-flex;
    flex: none;
    align-items: center;
}
.ws-nb-face {
    position: relative;
    margin-right: -.35rem;
    border: 2px solid var(--pg-bg-body);
    border-radius: 50%;
    line-height: 0;
}
.ws-nb-face .avatar {
    --bs-avatar-size: var(--ws-avatar-sm);
}
.ws-nb-face-edit::after {
    content: "\F4CB";
    position: absolute;
    right: -.3rem;
    bottom: -.3rem;
    padding: .05rem;
    border-radius: 50%;
    background: var(--pg-bg-body);
    font-family: bootstrap-icons;
    font-size: .6rem;
    line-height: 1;
    color: var(--pg-primary);
}
.ws-nb-face-more,
.ws-nb-face-channel {
    margin-left: .55rem;
    font-size: .75rem;
    color: var(--pg-fg-2);
    white-space: nowrap;
}
/* No note yet: one card in the screen's place, no empty list beside it
   (showList() in workspace.js). */
.ws-nb.ws-nb-none {
    grid-template-columns: minmax(0, 1fr);
}
.ws-nb.ws-nb-none > .ws-nb-list-col {
    display: none;
}
.ws-nb-card {
    position: relative;
}
.ws-nb-card.ws-nb-dropping {
    outline: 2px dashed var(--pg-primary);
    outline-offset: 4px;
}
.ws-nb-card.ws-nb-dropping::after {
    content: attr(data-drop-label);
    position: absolute;
    inset: 0;
    z-index: 5;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: inherit;
    background: color-mix(in srgb, var(--pg-primary) 8%, transparent);
    font-weight: 600;
    color: var(--pg-primary-fg-emphasis);
    pointer-events: none;
}
.ws-nb-head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: .35rem;
    background: transparent;
}
.ws-nb-head .ws-nb-faces {
    margin-right: .6rem;
}
.ws-nb-status {
    margin-right: .25rem;
    font-size: .75rem;
    color: var(--pg-fg-2);
    white-space: nowrap;
}
.ws-nb-status-unsaved {
    color: var(--pg-warning-fg-emphasis);
}
.ws-nb-info {
    display: flex;
    flex-wrap: wrap;
    gap: .25rem 1rem;
    padding: .4rem 1rem;
    border-bottom: 1px solid var(--pg-border-color-translucent);
    font-size: .8125rem;
    color: var(--pg-fg-2);
}
.ws-nb-info-part > .bi {
    margin-right: .3rem;
}
.ws-nb-tools {
    position: sticky;
    top: 0;
    z-index: 3;
    display: flex;
    flex-wrap: wrap;
    gap: .25rem .75rem;
    margin: -.25rem 0 .5rem;
    padding: .25rem 0;
    background: var(--pg-bg-body);
}
.ws-nb-tool-group {
    display: flex;
    gap: .1rem;
}
.ws-nb-tool-group + .ws-nb-tool-group {
    padding-left: .75rem;
    border-left: 1px solid var(--pg-border-color-translucent);
}
.ws-nb-editor {
    position: relative;
}
.ws-rich.ws-rich-field.ws-nb-text {
    min-height: 55vh;
    max-height: none;
    padding: 1rem 1.1rem;
    font-size: .95rem;
    line-height: 1.6;
}
.ws-nb-claude {
    display: flex;
    align-items: center;
    margin-top: .5rem;
}
.ws-nb-read {
    min-height: 8rem;
}
.ws-nb-shares {
    margin-top: 1rem;
}
.ws-nb-share-row {
    display: flex;
    align-items: center;
    gap: .5rem;
    padding: .25rem 0;
}
.ws-nb-share-row .avatar {
    --bs-avatar-size: var(--ws-avatar-sm);
}
@media (max-width: 1023.98px) {
    .ws-nb-open .ws-nb-list-col,
    #ws-root:not(.ws-nb-open) .ws-nb-pane-col {
        display: none;
    }
}
/* My Notes' note drawn as a page (drawNote() in workspace.js). The head
   keeps "Saved" and the last change on one quiet line that is cut short
   before the buttons wrap. One row of tools spans the card, sticky under the
   panel's fixed header, and never wraps: the tools that do not fit are
   folded into its More menu (workspace_note_page.js). The title and the
   text stand in a column of at most 46rem, written on the card without a
   field's frame or focus box; the caret marks the focus. Every rule starts
   at .ws-nb-page, so a channel's note, the highlights and lock panes, the
   task description and the other writing boxes keep the rules above. */
/* As tall as the list card's head, so their lines meet. */
.ws-nb-page > .ws-nb-head {
    min-height: 46px;
    padding-block: 4px;
}
.ws-nb-page .ws-nb-meta {
    flex: 1 1 0;
    min-width: 5rem;
    overflow: hidden;
    font-size: var(--pg-text-meta);
    color: var(--pg-fg-2);
    text-overflow: ellipsis;
    white-space: nowrap;
}
.ws-nb-page .ws-nb-meta .ws-nb-status {
    margin-right: 0;
}
.ws-nb-page .ws-nb-status:not(:empty) + .ws-nb-last:not(:empty)::before {
    content: "\00B7";
    margin: 0 .4rem;
}
.ws-nb-page .ws-nb-tools {
    top: var(--pg-navbar-h);
    flex-wrap: nowrap;
    align-items: center;
    margin: calc(-1 * var(--bs-card-spacer-y)) calc(-1 * var(--bs-card-spacer-x)) 1.5rem;
    padding: .5rem var(--bs-card-spacer-x);
    overflow: hidden;
    border-bottom: 1px solid var(--pg-border-color-translucent);
    background: var(--bs-card-bg);
}
.ws-nb-page .ws-nb-tools > * {
    flex: none;
}
.ws-nb-page .ws-nb-more {
    margin-left: auto;
}
.ws-nb-page .ws-nb-folded {
    display: none;
}
.ws-nb-page .ws-nb-sheet {
    max-width: 46rem;
    margin-right: auto;
    margin-left: auto;
}
.ws-nb-page .ws-nb-sheet .ws-nb-title {
    display: block;
    width: 100%;
    margin: 0 0 1rem;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    color: var(--pg-fg-body);
    box-shadow: none;
}
.ws-nb-page .ws-nb-sheet .ws-nb-title::placeholder {
    color: var(--pg-fg-3);
}
.ws-nb-page .ws-nb-sheet .ws-nb-title:focus,
.ws-nb-page .ws-nb-sheet .ws-nb-title:focus-visible {
    outline: 0;
    box-shadow: none;
}
.ws-nb-page .ws-rich.ws-rich-field.ws-nb-text {
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
}
.ws-nb-page .ws-rich.ws-rich-field.ws-nb-text:focus,
.ws-nb-page .ws-rich.ws-rich-field.ws-nb-text:focus-visible {
    border-color: transparent;
    outline: 0;
    box-shadow: none;
}
/* A note shared in a channel, as its card in the conversation */
.ws-nb-msg-card {
    max-width: 34rem;
    padding: .6rem .75rem;
    border: 1px solid var(--pg-border-color);
    border-left: 3px solid var(--pg-primary);
    border-radius: var(--ws-radius-sm);
    background: var(--pg-bg-1);
}
.ws-nb-msg-card-head {
    display: flex;
    align-items: center;
    gap: .4rem;
}
.ws-nb-msg-card-kind {
    font-size: .7rem;
    font-weight: 600;
    letter-spacing: .04em;
    color: var(--pg-fg-2);
    text-transform: uppercase;
}
.ws-nb-msg-card-text {
    display: -webkit-box;
    margin-top: .25rem;
    overflow: hidden;
    font-size: .875rem;
    color: var(--pg-fg-2);
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
}
/* The note drawn (tables, checklists): no line clamp, which would cut a
   table mid-row; a long note scrolls inside the card instead. */
.ws-nb-msg-card-text.ws-nb-msg-card-html {
    display: block;
    max-height: 18rem;
    overflow: auto;
    color: var(--pg-fg-body);
    -webkit-line-clamp: unset;
}
.ws-nb-msg-card-html > :last-child {
    margin-bottom: 0;
}
.ws-nb-msg-card-foot {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: .25rem .75rem;
    margin-top: .4rem;
    font-size: .75rem;
    color: var(--pg-fg-2);
}
/* A note card's fold (workspace_channel_notes.js): the note drawn whole,
   folded at 18rem (FOLD_REM in the script) behind "Show all" in place of
   an inner scroll. */
.ws-nb-msg-card-text.ws-cn-fold {
    max-height: none;
    overflow: visible;
}
.ws-nb-msg-card-text.ws-cn-fold.is-folded {
    max-height: 18rem;
    overflow: hidden;
    mask-image: linear-gradient(to bottom, var(--pg-bg-1) calc(100% - 3rem), transparent);
}
/* The note card is look A's plain card (.pg-card draws its surface, line
   and corners) as wide as the message column, on a phone too; these rules
   only place its parts. */
.ws-cn-card {
    padding: 12px 14px;
}
.ws-cn-head {
    gap: 8px;
}
.ws-cn-icon {
    color: var(--pg-fg-2);
}
.ws-cn-title {
    font-weight: var(--pg-weight-strong);
}
.ws-cn-card .ws-nb-msg-card-text {
    margin-top: 6px;
}
/* "Show all" / "Show less": a small quiet button centred under the note */
.ws-cn-more {
    margin-top: 6px;
    text-align: center;
}
/* The foot: one muted line (.pg-text-meta), Versions at its end */
.ws-cn-foot {
    display: flex;
    align-items: center;
    gap: 8px;
    min-height: 28px;
    margin-top: 8px;
}
.ws-cn-foot-words {
    flex: 1 1 auto;
    min-width: 0;
}
.ws-cn-versions-button {
    flex: none;
}
/* On a phone Versions is its icon and count, so the words keep the line */
@media (max-width: 575.98px) {
    .ws-cn-versions-button .pg-btn-label {
        position: absolute;
        width: 1px;
        height: 1px;
        overflow: hidden;
        clip-path: inset(50%);
        white-space: nowrap;
    }
}
/* Inside the note: headings measured against the text (the first one step
   bigger), paragraphs and lists close together, the "Written up to …"
   line as a meta line. */
.ws-cn-card .ws-heading {
    margin: 10px 0 2px;
    font-size: var(--pg-text-base);
    font-weight: var(--pg-weight-title);
    line-height: var(--pg-leading);
    letter-spacing: normal;
}
.ws-cn-card h2.ws-heading {
    font-size: var(--pg-text-status-title);
}
.ws-cn-card h4.ws-heading {
    font-weight: var(--pg-weight-strong);
}
.ws-cn-card .ws-cn-fold > :first-child {
    margin-top: 0;
}
.ws-cn-card .ws-text + .ws-text {
    margin-top: 6px;
}
.ws-cn-card .ws-list,
.ws-cn-card .ws-quote {
    margin: 4px 0;
}
.ws-cn-card .ws-list > li + li {
    margin-top: 2px;
}
.ws-cn-meta {
    margin-bottom: 6px;
}
/* An empty line between paragraphs (workspace_channel_notes.js tightGaps()) */
.ws-cn-gap {
    display: block;
    height: 6px;
}
/* The writing box in the Write a note and Edit windows */
.ws-cn-editor .ws-rich-field {
    min-height: 12rem;
}
/* The Versions drawer: 480 px from the end, a tall sheet on a phone so the
   version shown stays in sight under the list */
.ws-cn-versions {
    --pg-drawer-width: 480px;
    --pg-drawer-height: 88vh;
}
.ws-cn-versions.drawer-bottom {
    border-start-start-radius: var(--pg-radius-sheet);
    border-start-end-radius: var(--pg-radius-sheet);
}
/* The version shown is marked in the list */
.ws-cn-version.is-active {
    background: var(--pg-bg-2);
}
.ws-cn-version-view {
    margin-top: 1rem;
    padding-top: 1rem;
    border-top: 1px solid var(--pg-border-color);
}
/* The result of a line that ends with "=" */
.ws-calc.ws-calc-inline {
    margin-left: .25rem;
    padding: 0 .35rem;
    border-radius: .25rem;
    background: var(--pg-success-bg-subtle);
    color: var(--pg-success-fg-emphasis);
    font-variant-numeric: tabular-nums;
    font-weight: 600;
}
.ws-calc.ws-calc-inline.ws-calc-error {
    background: var(--pg-danger-bg-subtle);
    color: var(--pg-danger-fg-emphasis);
}
.ws-inline-result {
    margin-left: .3rem;
    padding: 0 .35rem;
    border-radius: .25rem;
    background: var(--pg-success-bg-subtle);
    color: var(--pg-success-fg-emphasis);
    font-variant-numeric: tabular-nums;
    font-weight: 600;
    user-select: none;
}
.ws-inline-result.ws-inline-error {
    background: var(--pg-danger-bg-subtle);
    color: var(--pg-danger-fg-emphasis);
}
/* The table window as a sheet: formula bar, column letters, row numbers */
.ws-sheet-bar {
    display: flex;
    align-items: center;
    gap: .5rem;
    margin-bottom: .5rem;
}
.ws-sheet-ref {
    flex: none;
    min-width: 3rem;
    padding: .25rem .5rem;
    border: 1px solid var(--pg-border-color);
    border-radius: var(--ws-radius-xs);
    background: var(--pg-bg-1);
    font-family: var(--pg-font-mono);
    font-size: .8125rem;
    font-weight: 600;
    text-align: center;
}
.ws-sheet-formula {
    font-family: var(--pg-font-mono);
}
.ws-sheet-result {
    flex: none;
    font-family: var(--pg-font-mono);
    font-size: .8125rem;
    color: var(--pg-success-fg-emphasis);
    white-space: nowrap;
}
.ws-sheet-result.ws-sheet-error-text {
    color: var(--pg-danger-fg-emphasis);
}
.ws-table-sheet .ws-sheet-letters th,
.ws-table-sheet th.ws-sheet-num {
    padding: .15rem .45rem;
    background: var(--pg-bg-1);
    font-size: .75rem;
    font-weight: 600;
    color: var(--pg-fg-2);
    text-align: center;
    vertical-align: middle;
    user-select: none;
}
.ws-table-sheet .ws-sheet-corner,
.ws-table-sheet th.ws-sheet-num {
    width: 2.5rem;
}
.ws-table-sheet .ws-sheet-col.active,
.ws-table-sheet th.ws-sheet-num.active {
    background: var(--pg-primary-bg-subtle);
    color: var(--pg-primary-fg-emphasis);
}
.ws-cell-edit.ws-cell-computed {
    color: var(--pg-success-fg-emphasis);
    font-variant-numeric: tabular-nums;
    text-align: right;
}
.ws-cell-edit.ws-cell-error {
    color: var(--pg-danger-fg-emphasis);
}
.ws-calc-preview {
    margin-top: .75rem;
}
/* Workspace: an edited file's earlier versions, the text window */
.ws-file-versions {
    display: inline-flex;
    align-items: center;
    gap: .3rem;
    margin-top: .3rem;
    padding: 0;
    border: 0;
    background: transparent;
    font-size: .75rem;
    color: var(--pg-fg-2);
}
.ws-file-versions:hover {
    color: var(--pg-primary);
    text-decoration: underline;
}
/* Two classes: the field recipe's textarea height and size come later. */
.pg-input.ws-text-area {
    min-height: 60vh;
    font-family: var(--pg-font-mono);
    font-size: .875rem;
    white-space: pre;
    resize: vertical;
}
.ws-text-view {
    min-height: 60vh;
}
/* Mentioned here, not in the channel */
.ws-msg-invite {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: .4rem;
    max-width: 34rem;
    margin-top: .35rem;
    padding: .3rem .5rem;
    border-radius: var(--ws-radius-xs);
    background: var(--pg-warning-bg-subtle);
    font-size: .8125rem;
    color: var(--pg-warning-fg-emphasis);
}
/* The search box of the whole workspace (assets/js/workspace_palette.js) */
.ws-palette.dialog {
    margin-top: 8vh;
}
.ws-palette-head {
    display: flex;
    align-items: center;
    gap: .5rem;
    padding: .55rem .9rem;
    border-bottom: 1px solid var(--pg-border-color);
}
.ws-palette-glass {
    color: var(--pg-fg-2);
    font-size: 1.1rem;
}
/* A bare search box in the palette's head: the head draws the frame. */
.ws-palette-input,
.ws-palette-input:focus {
    flex: 1;
    min-width: 0;
    -webkit-appearance: none;
    appearance: none;
    outline: 0;
    color: var(--pg-fg-body);
    padding: .35rem 0;
    border: 0;
    background: transparent;
    box-shadow: none;
    font-size: 1.05rem;
}
.ws-palette-esc {
    background: var(--pg-bg-2);
    color: var(--pg-fg-2);
    font-size: .7rem;
}
.ws-palette-filters {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: .4rem .75rem;
    padding: .45rem .9rem;
    border-bottom: 1px solid var(--pg-border-color);
}
/* "Only in #channel" carries the channel's name: the control and its
   segment shrink to the palette's width and the name is cut. */
.ws-palette-scope {
    max-width: 100%;
    min-width: 0;
}
.ws-palette-scope > .pg-seg-item {
    min-width: 0;
}
.ws-palette-kinds {
    display: flex;
    flex-wrap: wrap;
    gap: .25rem;
}
.ws-palette-kind {
    --bs-btn-padding-y: .1rem;
    --bs-btn-padding-x: .55rem;
    --bs-btn-font-size: .75rem;
    border: 1px solid var(--pg-border-color);
    border-radius: 999px;
    color: var(--pg-fg-2);
}
.ws-palette-kind.active {
    border-color: transparent;
    background: rgba(var(--ws-accent-rgb), .14);
    color: var(--ws-accent);
}
.ws-palette-list {
    max-height: min(60vh, 34rem);
    overflow-y: auto;
    padding: .35rem 0;
}
.ws-palette-group {
    display: flex;
    align-items: center;
    gap: .25rem;
    padding: .55rem .9rem .2rem;
    color: var(--pg-fg-2);
    font-size: .7rem;
    font-weight: 600;
    letter-spacing: .04em;
    text-transform: uppercase;
}
.ws-palette-count {
    margin-left: .25rem;
    font-weight: 400;
}
.ws-palette-forget {
    font-size: .7rem;
    letter-spacing: 0;
    text-transform: none;
}
.ws-palette-item {
    display: flex;
    align-items: center;
    gap: .6rem;
    padding: .4rem .9rem;
    cursor: pointer;
}
.ws-palette-item.active {
    background: rgba(var(--ws-accent-rgb), .1);
}
.ws-palette-icon {
    flex: 0 0 1.6rem;
    color: var(--pg-fg-2);
    text-align: center;
}
.ws-palette-face {
    flex: 0 0 auto;
}
.ws-palette-main {
    flex: 1 1 auto;
    min-width: 0;
}
.ws-palette-title,
.ws-palette-sub {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.ws-palette-sub {
    color: var(--pg-fg-2);
    font-size: .78rem;
}
.ws-palette-done .ws-palette-title {
    color: var(--pg-fg-2);
    text-decoration: line-through;
}
.ws-palette-date {
    flex: 0 0 auto;
    color: var(--pg-fg-2);
    font-size: .75rem;
}
.ws-palette-mark {
    padding: 0;
    border-radius: .15rem;
    background: color-mix(in srgb, var(--pg-warning) 35%, transparent);
    color: inherit;
}
.ws-palette-empty,
.ws-palette-note {
    padding: .9rem;
    color: var(--pg-fg-2);
    font-size: .875rem;
}
.ws-palette-note {
    padding-bottom: .2rem;
}
.ws-palette-foot {
    padding: .4rem .9rem;
    border-top: 1px solid var(--pg-border-color);
    color: var(--pg-fg-2);
    font-size: .72rem;
}
/* A channel's Board tab (assets/js/workspace_board_channel.js): one bar
   for the Board and List views. Unlike the other screen bars it wraps:
   at phone width into three lines, the Segmented control with "New
   task", the grouping or the task status, then the search, "Only mine"
   and "Filter" as icons. */
.pg-toolbar.ws-bar.ws-cb-bar {
    flex-wrap: wrap;
}
.ws-cb-bar > .ws-bar-search {
    flex: 0 1 230px;
    min-width: 0;
}
@media (max-width: 575.98px) {
    .ws-cb-bar > .ws-cb-views {
        order: 0;
    }
    .ws-cb-bar > .ws-cb-new {
        order: 1;
        margin-inline-start: auto;
    }
    .ws-cb-bar > .ws-cb-chips,
    .ws-cb-bar > .pg-input {
        order: 2;
        flex-basis: 100%;
    }
    .ws-cb-bar > .pg-toolbar-grow {
        display: none;
    }
    .ws-cb-bar > .ws-bar-search {
        order: 3;
        flex: 1 1 0;
    }
    .ws-cb-bar > .ws-cb-chip,
    .ws-cb-bar > .ws-bar-filter,
    .ws-cb-bar > .ws-cb-auto {
        order: 4;
    }
}
/* "Automations" on the board's bar: the automations' violet bolt and the
   count of the rules that are on in a pill. */
.ws-cb-auto > .bi {
    color: color-mix(in srgb, var(--pg-tone-violet) 70%, var(--pg-fg-emphasis));
}
.ws-cb-auto-count {
    height: 18px;
    padding: 0 7px;
    font-size: .6875rem;
}
/* A status column's rule line (a rule that is on and tied to the column):
   one quiet line under the head, in the automations' violet tone. */
.ws-cb-rule {
    display: flex;
    align-items: center;
    gap: 7px;
    margin: 0 2px 10px;
    padding: 6px 9px;
    border-radius: 10px;
    background: color-mix(in srgb, var(--pg-tone-violet) var(--pg-tint-to), transparent);
    color: color-mix(in srgb, var(--pg-tone-violet) 70%, var(--pg-fg-emphasis));
    font-size: .75rem;
    font-weight: var(--pg-weight-medium);
}
.ws-cb-rule > span {
    min-width: 0;
}
/* The Automations drawer: the rules as Switch rows, a rule that is on
   with the primary line around it; a row asking for its answer opens
   under its words; the dashed "Build your own flow"; the last runs. */
.ws-cb-rule-row.is-on,
.ws-cb-rule-row.is-asking {
    box-shadow: inset 0 0 0 1px var(--pg-primary);
}
.ws-cb-rule-row {
    flex-wrap: wrap;
}
.ws-cb-rule-row .ws-cb-rule-when {
    margin-top: 0;
    font-size: var(--pg-text-meta);
}
.ws-cb-rule-row .ws-cb-rule-ran {
    color: var(--pg-fg-3);
    font-size: var(--pg-text-meta);
}
.ws-cb-ask {
    display: flex;
    flex: 1 0 100%;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    padding-inline-start: 57px;
}
.ws-cb-ask > .pg-field-label {
    margin-inline-end: auto;
}
.ws-cb-ask > .pg-input {
    flex: 1 1 10rem;
}
.ws-cb-own {
    display: flex;
    align-items: center;
    gap: 13px;
    width: 100%;
    padding: 12px 16px;
    border: 1.5px dashed var(--pg-border-color);
    border-radius: var(--pg-radius-card);
    background: none;
    color: inherit;
    text-align: start;
}
.ws-cb-own:hover {
    background: var(--pg-hover);
}
.ws-cb-own:focus-visible {
    outline: 2px solid var(--pg-accent);
    outline-offset: 2px;
}
.ws-cb-own-go {
    color: var(--pg-fg-3);
}
.ws-cb-runs {
    margin: 0;
    padding: 0;
    color: var(--pg-fg-2);
    font-size: var(--pg-text-meta);
    list-style: none;
}
.ws-cb-run {
    display: flex;
    align-items: baseline;
    gap: 8px;
    padding: 3px 0;
}
.ws-cb-run > .bi {
    flex: none;
    color: var(--pg-fg-3);
}
.ws-cb-run-done > .bi {
    color: var(--pg-tone-teal);
}
.ws-cb-run-failed > .bi {
    color: var(--pg-tone-rose);
}
@media (max-width: 575.98px) {
    .ws-cb-ask {
        padding-inline-start: 0;
    }
}
/* The board's choices as chips (toolbar() in workspace_board_channel.js):
   a pill that is filled while it is on; the two selects take the pill's
   shape. */
.ws-cb-chips {
    display: flex;
    flex-wrap: wrap;
    gap: .3rem;
}
.ws-cb-chip {
    padding: .2rem .75rem;
    border: 1px solid var(--pg-border-color);
    border-radius: 999px;
    background: transparent;
    color: var(--pg-fg-2);
    font-size: .8125rem;
    line-height: 1.4;
}
.ws-cb-chip:hover {
    background: var(--pg-bg-2);
    color: var(--pg-fg-emphasis);
}
.ws-cb-chip.active {
    border-color: rgba(var(--ws-accent-rgb), .45);
    background: rgba(var(--ws-accent-rgb), .14);
    color: var(--pg-fg-emphasis);
}
html[data-bs-theme="dark"] .ws-cb-chip.active {
    border-color: rgba(var(--ws-accent-rgb), .6);
    background: rgba(var(--ws-accent-rgb), .26);
}
.ws-cb-chip:focus-visible {
    outline: 2px solid var(--ws-accent);
    outline-offset: 1px;
}
.ws-cb-chip-select {
    border-radius: 999px;
    font-size: .8125rem;
}
.ws-pane .ws-cb-picker,
/* The Data list's New table on a phone (workspace_wtables.php): the filled
   button floating at the bottom right, above the page. */
.ws-wt-fab {
  position: fixed;
  right: 16px;
  bottom: calc(16px + env(safe-area-inset-bottom, 0px));
  z-index: 1010;
}
.ws-wt-board .ws-cb-picker {
    display: none;
}
.ws-cb-cols {
    display: flex;
    align-items: flex-start;
    gap: .75rem;
    padding-bottom: .5rem;
    overflow-x: auto;
}
.ws-cb-col {
    display: flex;
    flex: 0 0 17rem;
    flex-direction: column;
    min-width: 0;
    border: 2px solid transparent;
    border-radius: var(--ws-radius);
    background: var(--pg-bg-1);
}
.ws-cb-col.ws-cb-drop {
    border-color: rgba(var(--ws-accent-rgb), .55);
    background: rgba(var(--ws-accent-rgb), .07);
}
/* On the channel's Board tab a column is a gray surface the cards stand on;
   a card over it shows the column's drop place (.ws-cb-slot). The workflow
   table's board (.ws-wt-board) keeps its own columns. */
.ws-pane-board .ws-cb-col {
    flex: 1 1 17rem;
    max-width: 34rem;
    padding: 10px;
    border: 0;
    border-radius: 16px;
    background: var(--pg-bg-1);
}
.ws-cb-col-head {
    display: flex;
    align-items: center;
    gap: .4rem;
    padding: .5rem .6rem .35rem;
    font-size: .8125rem;
    font-weight: 600;
}
.ws-cb-col-icon {
    color: var(--pg-fg-2);
}
.ws-cb-col-title {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.ws-cb-col-count {
    color: var(--pg-fg-2);
    font-size: .75rem;
    font-weight: 400;
}
.ws-cb-add {
    --bs-btn-padding-y: 0;
    --bs-btn-padding-x: .3rem;
}
.ws-cb-list {
    display: flex;
    flex-direction: column;
    gap: .45rem;
    min-height: 2.5rem;
    padding: 0 .5rem .5rem;
}
.ws-cb-empty {
    padding: .6rem .2rem;
    color: var(--pg-fg-2);
    font-size: .75rem;
    text-align: center;
}
.ws-cb-more {
    align-self: flex-start;
    margin: 0 .5rem .4rem;
    font-size: .75rem;
}
.ws-cb-card {
    position: relative;
    padding: .5rem .6rem .5rem .75rem;
    border: 1px solid var(--pg-border-color-translucent);
    border-radius: var(--ws-radius-sm);
    background: var(--pg-bg-body);
    box-shadow: 0 1px 2px rgba(0, 0, 0, .04);
    cursor: pointer;
    font-size: .8125rem;
}
.ws-cb-card::before {
    content: "";
    position: absolute;
    top: .4rem;
    bottom: .4rem;
    left: 0;
    width: 3px;
    border-radius: 3px;
    background: transparent;
}
.ws-cb-card.ws-cb-pri-urgent::before {
    background: var(--pg-danger);
}
.ws-cb-card.ws-cb-pri-high::before {
    background: var(--pg-warning);
}
.ws-cb-card.ws-cb-pri-low::before {
    background: var(--pg-border-color);
}
.ws-cb-card:hover {
    border-color: rgba(var(--ws-accent-rgb), .35);
}
/* The keyboard moves cards here, so the card it is on has to show. */
.ws-cb-card:focus-visible {
    outline: 2px solid var(--ws-accent);
    outline-offset: 1px;
}
.ws-cb-card.ws-cb-lifted {
    outline: 2px dashed var(--ws-accent);
    outline-offset: 1px;
}
.ws-cb-card.ws-cb-dragging {
    opacity: .5;
}
.ws-cb-closed .ws-cb-title {
    color: var(--pg-fg-2);
}
.ws-cb-s-cancelled .ws-cb-title {
    text-decoration: line-through;
}
.ws-cb-card-top {
    display: flex;
    align-items: center;
    gap: .35rem;
    margin-bottom: .15rem;
    color: var(--pg-fg-2);
    font-size: .7rem;
}
.ws-cb-number {
    font-weight: 600;
}
.ws-cb-card-end {
    display: inline-flex;
    align-items: center;
    gap: .35rem;
    margin-inline-start: auto;
}
/* Urgent (rose) and high (amber) as a small chip with a flag. */
.ws-cb-priority {
    display: inline-flex;
    align-items: center;
    gap: .25rem;
    padding: 1px 8px;
    border-radius: 999px;
    font-weight: var(--pg-weight-strong);
}
.ws-cb-priority-urgent {
    background: var(--pg-danger-bg-subtle);
    color: var(--pg-danger-fg-emphasis);
}
.ws-cb-priority-high {
    background: var(--pg-warning-bg-subtle);
    color: var(--pg-warning-fg-emphasis);
}
.ws-cb-done-mark {
    color: var(--pg-success-fg-emphasis);
}
/* The due date as a chip: gray for a later day, amber for today and
   tomorrow, rose when late, green on a closed task. */
.ws-cb-due {
    display: inline-flex;
    align-items: center;
    gap: .3rem;
    padding: 2px 8px;
    border-radius: 8px;
    background: color-mix(in srgb, var(--pg-tone-gray) 12%, transparent);
    font-weight: var(--pg-weight-medium);
}
.ws-cb-due-soon {
    background: var(--pg-warning-bg-subtle);
    color: var(--pg-warning-fg-emphasis);
}
.ws-cb-due-late {
    background: var(--pg-danger-bg-subtle);
    color: var(--pg-danger-fg-emphasis);
}
.ws-cb-due-done {
    background: var(--pg-success-bg-subtle);
    color: var(--pg-success-fg-emphasis);
}
.ws-cb-title {
    font-weight: 500;
    line-height: 1.3;
    overflow-wrap: anywhere;
}
.ws-cb-sub {
    margin-top: .2rem;
    color: var(--pg-fg-2);
    font-size: .72rem;
}
.ws-cb-meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: .3rem .6rem;
    margin-top: .35rem;
    color: var(--pg-fg-2);
    font-size: .72rem;
}
.ws-cb-faces {
    margin-left: auto;
}
.ws-cb-faces .avatar {
    --bs-avatar-size: 1.35rem;
}
.ws-cb-more-faces {
    margin-left: .2rem;
    font-size: .68rem;
}
.ws-cb-progress {
    display: inline-flex;
    align-items: center;
    gap: .3rem;
}
/* Bootstrap's .progress at the size of a meta line */
.ws-cb-progress-bar {
    --bs-progress-height: .3rem;
    --bs-progress-bg: var(--pg-bg-2);
    --bs-progress-border-radius: var(--ws-radius-xs);
    --bs-progress-box-shadow: none;
    --bs-progress-bar-bg: var(--pg-success);
    --bs-progress-bar-transition: none;
    width: 2.6rem;
}
.ws-cb-thumb {
    display: block;
    width: 100%;
    max-height: 7rem;
    margin-bottom: .35rem;
    border-radius: var(--ws-radius-xs);
    object-fit: cover;
}
/* The channel's Board: its columns grow with the pane up to twice their
   width, and a card takes the panes' card manner; the priority stripe
   stands on the side reading starts from. The workflow table's board keeps
   the cards above. */
.ws-pane-board .ws-cb-card {
    padding: .65rem .8rem .65rem .95rem;
    border-color: var(--pg-border-color);
    border-radius: .75rem;
    background: var(--pg-card-bg);
    box-shadow: var(--ws-shadow-soft);
}
.ws-pane-board .ws-cb-card::before {
    content: none;
}
.ws-pane-board .ws-cb-card:hover {
    border-color: rgba(var(--ws-accent-rgb), .45);
}
.ws-cb-decision .ws-cb-kind-icon {
    color: var(--pg-success);
}
/* A phone shows one column, picked above the board. */
@media (max-width: 767.98px) {
    .ws-pane .ws-cb-picker,
    .ws-wt-board .ws-cb-picker {
        display: block;
    }
    .ws-cb-cols {
        display: block;
    }
    .ws-cb-col {
        display: none;
    }
    .ws-cb-col.ws-cb-col-current {
        display: flex;
    }
}
/* The channel's Board tab: the four figures above both views (buttons that
   filter, the chosen one in the primary's subtle fill), the columns on the
   gray surface with the status's dot and the count in a pill, the cards,
   and the dashed drop place of the column a card is over. At phone width
   the figures are one row and the columns scroll sideways. */
.ws-cb-figures {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 12px;
    margin-bottom: .75rem;
}
.ws-cb-figure {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
    padding: 12px 14px;
    border: 1px solid var(--pg-border-color);
    border-radius: 14px;
    background: var(--pg-card-bg);
    color: inherit;
    text-align: start;
}
.ws-cb-figure:hover {
    border-color: color-mix(in srgb, var(--pg-primary) 55%, transparent);
}
.ws-cb-figure.active {
    border-color: var(--pg-primary-border-subtle);
    background: var(--pg-primary-bg-subtle);
}
.ws-cb-figure:focus-visible {
    outline: 2px solid var(--ws-accent);
    outline-offset: 1px;
}
.ws-cb-figure-text {
    display: flex;
    flex-direction: column;
    min-width: 0;
}
.ws-cb-figure-value {
    font-size: var(--pg-text-figure-sm);
    font-weight: var(--pg-weight-title);
    font-variant-numeric: tabular-nums;
    line-height: 1.05;
}
.ws-cb-figure-label {
    overflow: hidden;
    color: var(--pg-fg-2);
    font-size: var(--pg-text-2);
    text-overflow: ellipsis;
    white-space: nowrap;
}
.ws-pane-board .ws-cb-col-head {
    padding: 4px 6px 10px;
    font-size: var(--pg-text-base);
    font-weight: var(--pg-weight-title);
}
.ws-cb-dot {
    flex: none;
    width: 9px;
    height: 9px;
    border-radius: 50%;
