/* ── Workspace: flows (workspace_flows.php, assets/js/workspace_flow.js) ──
   The list, the canvas and the settings side by side; under 768px one
   column, the list behind its toolbar button. A box is 208 x 80 canvas
   units (BOX_W, BOX_H in the script), which the arrows are drawn from. */
.wsf-bar .wsf-name {
  width: auto;
  min-width: 10rem;
  max-width: 22rem;
  font-weight: 600;
}
.wsf-bar .wsf-save {
  white-space: nowrap;
}
/* The whole Flows editor in a full-screen layer over a channel (flowLayer()
   in workspace.js): its bar, then the editor filling the rest; the page
   beneath does not scroll while it is open. Native dialogs sit in the top
   layer above it, menus and toasts on higher z-indexes. */
html.ws-flow-layer-on,
html.ws-flow-layer-on body {
  overflow: hidden;
}
.ws-flow-layer {
  position: fixed;
  inset: 0;
  z-index: 1035;
  display: flex;
  flex-direction: column;
  background: var(--pg-bg-body);
}
.ws-flow-layer-bar {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--ws-space-2);
  padding: var(--ws-space-2) var(--ws-space-3);
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.ws-flow-layer-title {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  overflow: hidden;
  font-size: 1rem;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ws-flow-layer-body {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-height: 0;
  overflow: auto;
  padding: var(--ws-space-3);
}
.ws-flow-layer-body .wsf-app {
  flex: 1 1 auto;
  height: auto;
  min-height: 20rem;
}
@media (max-width: 767.98px) {
  .ws-flow-layer-bar { flex-wrap: wrap; }
  .ws-flow-layer-title { flex-basis: 100%; }
  .ws-flow-layer-body { padding: var(--ws-space-2); }
  .ws-flow-layer-body .wsf-app { flex: none; min-height: 0; }
}
.wsf-app {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--ws-space-3);
  height: calc(100vh - 14rem);
  min-height: 26rem;
}
@supports (height: 100dvh) {
  .wsf-app { height: calc(100dvh - 14rem); }
}
.wsf-side {
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  padding: var(--ws-space-3);
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius);
  background: var(--pg-bg-body);
}
/* No flow open (the template gallery, the flow list): the main column
   takes the whole width. Three classes outweigh the two-class column rules
   of the narrower media queries further down. */
.wsf-app.wsf-no-palette.wsf-nothing {
  grid-template-columns: minmax(0, 1fr);
}
.wsf-app.wsf-nothing .wsf-side {
  display: none;
}
/* Nothing chosen: no panel (drawSettings() in workspace_flow.js); the
   flow's facts are in the name's window. */
.wsf-app:not(.wsf-side-open) .wsf-side {
  display: none;
}
/* From 768 px the chosen box's panel is a card over the canvas's right
   edge, 14 px in, on the floating surface; the bottom strip is centred in
   the part of the canvas beside it. */
@media (min-width: 768px) {
  .wsf-side {
    position: absolute;
    z-index: 5;
    top: 14px;
    right: 14px;
    bottom: 14px;
    width: 320px;
    max-width: calc(100% - 28px);
    border-radius: 13px;
    background: var(--pg-surface-float);
    box-shadow: var(--pg-shadow-float);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
  }
  .wsf-app.wsf-side-open .wsf-strip {
    left: calc((100% - 334px) / 2);
  }
}
/* A window of the bar (barWindow()): the flow's facts under the chevron
   beside its name, the problems under their button. */
.wsf-pop {
  position: absolute;
  z-index: 1020;
  top: calc(100% + 6px);
  left: 0;
  width: 320px;
  max-width: calc(100vw - 32px);
  max-height: min(70vh, 560px);
  overflow-y: auto;
  padding: 14px 16px;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: 13px;
  background: var(--pg-surface-float);
  box-shadow: var(--pg-shadow-float);
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);
  text-align: start;
}
.wsf-pop-problems {
  right: 0;
  left: auto;
}
.wsf-side-title {
  margin-bottom: var(--ws-space-2);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  color: var(--pg-fg-2);
}
/* The right panel of a chosen box, arrow or thread (sideHead() in
   workspace_flow.js): the tile, the kind in small capitals over the name,
   then ⋯ and Close; the tabs; the foot line at the bottom. */
.wsf-side {
  display: flex;
  flex-direction: column;
}
.wsf-side-head {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 12px;
}
.wsf-side-tile {
  --pg-tone: var(--wsf-kind, var(--pg-tone-gray));
}
.wsf-side-words {
  flex: 1 1 auto;
  min-width: 0;
}
.wsf-side-kind {
  font-size: var(--pg-text-count);
  font-weight: var(--pg-weight-title);
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--wsf-kind, var(--pg-fg-2));
}
.wsf-side-head .wsf-side-kind {
  color: var(--pg-fg-2);
}
.wsf-side-name {
  margin: 0;
  overflow-wrap: anywhere;
}
.wsf-side-tabs {
  flex-shrink: 0;
  margin-bottom: 14px;
}
.wsf-side-panel {
  flex: 1 0 auto;
}
.wsf-side-sub {
  margin: 0 0 6px;
  font-size: var(--pg-text-2);
  font-weight: var(--pg-weight-strong);
}
.wsf-links .wsf-side-sub ~ .wsf-side-sub {
  margin-top: 14px;
}
/* Connections: each box a row (its tile and name choose it); an arrow
   after it with its outcome and ×; Add an arrow under the list. */
.wsf-link-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
  padding: 4px 6px 4px 4px;
  border-radius: 11px;
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
}
.wsf-link-go {
  display: flex;
  flex: 1 1 8rem;
  align-items: center;
  gap: 10px;
  min-width: 0;
  height: 32px;
  padding: 0 6px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--pg-fg-body);
  font-size: var(--pg-text-2);
  text-align: left;
}
.wsf-link-go:hover {
  background: var(--pg-hover);
}
.wsf-link-row .wsf-link-on {
  flex: 0 1 9rem;
  width: auto;
}
.wsf-link-add {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.wsf-link-add .wsf-connect {
  flex: 1 1 8rem;
  width: auto;
}
.wsf-link-go:focus-visible,
.wsf-side-foot-go:focus-visible {
  outline: 2px solid var(--pg-accent);
  outline-offset: 1px;
}
/* The foot line: the box before and what comes after, each choosing it. */
.wsf-side-foot {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 6px 12px;
  margin-top: 14px;
  padding-top: 10px;
  border-top: 1px solid var(--pg-border-color-translucent);
}
.wsf-side-foot:empty {
  display: none;
}
.wsf-side-foot-go {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  padding: 2px 4px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: var(--pg-fg-body);
}
.wsf-side-foot-after {
  margin-left: auto;
}
.wsf-side-foot-go:hover {
  background: var(--pg-hover);
}
.wsf-scrim {
  display: none;
}
/* Somebody else's flow in the list: under its name what the person may do
   with it (Can view, Can run, Can edit). */
.wsf-list-level {
  font-size: .72rem;
  font-weight: 400;
  color: var(--pg-fg-2);
}
/* The flow list, full width while no flow is open (drawFlows() in
   workspace_flow.js): a search field and the filter chips over a table. */
.wsf-flows-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ws-space-2) var(--ws-space-3);
  margin-bottom: var(--ws-space-3);
}
.wsf-flows-search {
  flex: 0 1 18rem;
}
.wsf-flow-table th,
.wsf-flow-table td {
  vertical-align: top;
}
.wsf-flow-row {
  cursor: pointer;
}
.wsf-flow-row:hover > * {
  background: var(--pg-bg-2);
}
.wsf-flow-open {
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--pg-fg-body);
  font-weight: 600;
  text-align: left;
}
.wsf-flow-open:hover {
  text-decoration: underline;
}
.wsf-flow-name .wsf-list-level {
  display: block;
}
/* The start cell stays a table cell, as tall as its row, so its border
   and the hover band line up with the other columns; its wrapper lays the
   icon beside the sentence. */
.wsf-flow-start-in {
  display: flex;
  align-items: flex-start;
  gap: var(--ws-space-2);
}
.wsf-flow-start .ws-flow-icon {
  margin-top: .15rem;
  color: var(--wsf-kind);
}
.wsf-flow-last .wsf-flag {
  max-width: 16rem;
}
/* The scheduled actions the flow list ends with (drawScheduled()): the
   cards of the actions the conversion refused, whose state chips have
   nothing to filter there. */
.wsf-sched-group {
  margin-top: 1.5rem;
}
.wsf-sched-title {
  margin-bottom: var(--ws-space-3);
}
.wsf-sched-title:focus {
  outline: none;
}
.wsf-sched-refused .ws-sa-filters {
  display: none;
}
/* The quick setup of a flow (workspace_flow_quick.js): a wide dialog with
   its stages in a line under the head; the first stage is a rail of the
   site's areas beside the starts of one as radio cards and "Only when". */
.dialog.wsf-quick {
  --bs-dialog-width: 820px;
  height: min(700px, calc(100% - 3.5rem));
}
.wsf-quick-head {
  align-items: flex-start;
  border-bottom: 0;
  padding: 18px 16px 0 24px;
}
.wsf-quick-sub {
  margin: 3px 0 0;
  color: var(--pg-fg-2);
}
.wsf-quick-stages {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 14px 24px 13px;
  list-style: none;
  border-bottom: 1px solid var(--pg-border-color-translucent);
  color: var(--pg-fg-3);
  font-size: var(--pg-text-2);
  white-space: nowrap;
}
.wsf-quick-stage {
  display: inline-flex;
  flex: 1 1 auto;
  align-items: center;
  gap: 8px;
}
.wsf-quick-stage:last-child {
  flex: 0 0 auto;
}
.wsf-quick-stage:not(:last-child)::after {
  content: "";
  flex: 1 1 auto;
  min-width: 14px;
  height: 1px;
  background: var(--pg-border-color-translucent);
}
.wsf-quick-stage-n {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--pg-quiet);
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
  color: var(--pg-fg-2);
  font-size: var(--pg-text-meta);
  font-weight: var(--pg-weight-strong);
}
.wsf-quick-stage.is-done .wsf-quick-stage-n {
  background: color-mix(in srgb, var(--pg-tone-teal) 16%, transparent);
  box-shadow: none;
  color: var(--pg-tone-teal);
}
.wsf-quick-stage.is-active {
  color: var(--pg-fg-body);
  font-weight: var(--pg-weight-strong);
}
.wsf-quick-stage.is-active .wsf-quick-stage-n {
  background: linear-gradient(180deg, var(--pg-accent-1), var(--pg-accent-2));
  box-shadow: none;
  color: var(--pg-on-accent);
}
.wsf-quick-body {
  min-height: 0;
  padding: 16px 24px 0;
  overflow: hidden;
}
.wsf-quick-foot {
  border-top: 1px solid var(--pg-border-color-translucent);
  padding: 13px 24px;
}
.wsf-quick-hint {
  margin-right: auto;
  color: var(--pg-fg-3);
}
.wsf-quick-split {
  display: grid;
  grid-template-columns: 196px minmax(0, 1fr);
  gap: 18px;
  height: 100%;
}
.wsf-quick-rail {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-height: 0;
  padding: 0 14px 16px 0;
  overflow-y: auto;
  border-right: 1px solid var(--pg-border-color-translucent);
}
.wsf-quick-rail-line {
  margin: 7px 4px;
  border-top: 1px solid var(--pg-border-color-translucent);
  opacity: 1;
}
.wsf-quick-area {
  display: flex;
  flex: none;
  align-items: center;
  gap: 9px;
  height: 31px;
  padding: 0 9px;
  border: 0;
  border-radius: 9px;
  background: none;
  color: var(--pg-fg-2);
  font-size: var(--pg-text-2);
  text-align: left;
  white-space: nowrap;
}
.wsf-quick-area .bi {
  color: var(--pg-fg-3);
}
.wsf-quick-area:hover {
  background: var(--pg-hover);
}
.wsf-quick-area.is-active {
  background: var(--pg-quiet);
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
  color: var(--pg-fg-body);
  font-weight: var(--pg-weight-strong);
}
.wsf-quick-area.is-active .bi {
  color: var(--pg-accent);
}
.wsf-quick-area.is-quiet {
  opacity: .6;
}
.wsf-quick-area.is-quiet.is-active {
  background: none;
  box-shadow: none;
  font-weight: inherit;
}
.wsf-quick-area-name {
  overflow: hidden;
  text-overflow: ellipsis;
}
.wsf-quick-area-count {
  margin-left: auto;
  color: var(--pg-fg-3);
}
.wsf-quick-pane {
  min-height: 0;
  padding-bottom: 16px;
  overflow-y: auto;
}
.wsf-quick-find {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}
.wsf-quick-find input {
  flex: 1 1 auto;
  min-width: 0;
  border: 0;
  background: none;
  color: inherit;
  outline: 0;
}
.wsf-quick-find .bi {
  color: var(--pg-fg-3);
}
.wsf-quick-found {
  margin: 0 0 8px;
}
.wsf-quick-cards {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}
.wsf-quick-card {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 11px;
  margin: 0;
  padding: 11px 36px 11px 12px;
  border-radius: 13px;
  background: var(--pg-card-bg);
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
  cursor: pointer;
}
.wsf-quick-card:hover {
  background: var(--pg-hover);
}
.wsf-quick-card.is-active {
  background: color-mix(in srgb, var(--pg-accent) 9%, transparent);
  box-shadow: inset 0 0 0 1.5px var(--pg-accent);
}
.wsf-quick-card:has(.wsf-quick-radio:focus-visible) {
  outline: 2px solid var(--pg-accent);
  outline-offset: 2px;
}
.wsf-quick-radio {
  position: absolute;
  top: 13px;
  right: 12px;
  margin: 0;
  accent-color: var(--pg-accent);
}
.wsf-quick-card-words {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.wsf-quick-card-title {
  font-size: var(--pg-text-2);
  font-weight: var(--pg-weight-strong);
}
.wsf-quick-card-line {
  color: var(--pg-fg-2);
}
.wsf-quick-when {
  margin-top: 14px;
  padding: 12px 14px;
  border-radius: 13px;
  background: var(--pg-card-bg);
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
}
.wsf-quick-when-label {
  margin: 0 0 8px;
}
.wsf-quick-when-rows {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.wsf-quick-when-rows:not(:empty) {
  margin-bottom: 8px;
}
.wsf-quick-when-row {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr) minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
}
.wsf-quick-when-row .wsf-quick-when-value.d-none + .pg-icon-button {
  grid-column: 4;
}
/* The second stage: the steps chosen in a row, the recipes and the kinds
   by group, a step's own setting (the canvas's fields, nodeForm()). */
.wsf-quick-steps {
  height: 100%;
  padding-bottom: 16px;
  overflow-y: auto;
}
.wsf-quick-tile {
  --pg-tone: var(--wsf-kind, var(--pg-tone-gray));
}
.wsf-quick-tile .ws-flow-icon {
  width: 14px;
  height: 14px;
}
.wsf-quick-tile-sm {
  width: 22px;
  height: 22px;
  border-radius: 7px;
}
.wsf-quick-tile-sm .ws-flow-icon {
  width: 12px;
  height: 12px;
}
.wsf-quick-trail {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin: 0 0 16px;
  padding: 0;
  list-style: none;
}
.wsf-quick-trail-step,
.wsf-quick-trail-new {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 34px;
  padding: 0 11px 0 5px;
  border: 0;
  border-radius: 10px;
  background: none;
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
  color: var(--pg-fg-2);
  font-size: var(--pg-text-2);
  white-space: nowrap;
}
.wsf-quick-trail-step:hover {
  background: var(--pg-hover);
}
.wsf-quick-trail-step.is-active {
  background: color-mix(in srgb, var(--pg-accent) 9%, transparent);
  box-shadow: inset 0 0 0 1.5px var(--pg-accent);
  color: var(--pg-fg-body);
  font-weight: var(--pg-weight-strong);
}
.wsf-quick-trail-new {
  padding-left: 11px;
  box-shadow: inset 0 0 0 1px var(--pg-accent);
  color: var(--pg-accent);
  font-weight: var(--pg-weight-strong);
}
.wsf-quick-trail-n {
  padding-left: 4px;
  color: var(--pg-fg-3);
}
.wsf-quick-trail-name {
  max-width: 180px;
  overflow: hidden;
  text-overflow: ellipsis;
}
.wsf-quick-lead {
  outline: 0;
}
.wsf-quick-lead-sub {
  margin: 3px 0 14px;
}
.wsf-quick-recipes {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}
.wsf-quick-recipe {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  padding: 11px 12px 10px;
  border: 0;
  border-radius: 13px;
  background: color-mix(in srgb, var(--pg-accent) 6%, var(--pg-card-bg));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pg-accent) 22%, var(--pg-border-color-translucent));
  color: inherit;
  text-align: left;
}
.wsf-quick-recipe:hover {
  background: color-mix(in srgb, var(--pg-accent) 11%, var(--pg-card-bg));
}
.wsf-quick-recipe-chain {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  color: var(--pg-fg-3);
}
.wsf-quick-group {
  display: grid;
  grid-template-columns: 84px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  padding: 7px 0;
  border-top: 1px solid var(--pg-border-color-translucent);
}
.wsf-quick-group-name {
  padding-top: 8px;
  color: var(--pg-fg-3);
  font-weight: var(--pg-weight-strong);
}
.wsf-quick-acts {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}
.wsf-quick-act {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 32px;
  padding: 0 11px 0 5px;
  border: 0;
  border-radius: 10px;
  background: none;
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
  color: var(--pg-fg-2);
  font-size: var(--pg-text-2);
  white-space: nowrap;
}
.wsf-quick-act:hover {
  background: var(--pg-hover);
  color: var(--pg-fg-body);
}
.wsf-quick-step-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}
.wsf-quick-step-head h3 {
  margin-right: auto;
  outline: 0;
}
.wsf-quick-form {
  max-width: 560px;
}
/* The summary: the start and the steps on a line, a held step indented
   (--wsf-quick-depth), the name and "Start working when saved". */
.wsf-quick-line {
  margin: 4px 0 0;
  padding: 0;
  list-style: none;
}
.wsf-quick-event {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 13px;
  margin-left: calc(var(--wsf-quick-depth, 0) * 30px);
  padding-bottom: 14px;
}
.wsf-quick-event::before {
  content: "";
  position: absolute;
  top: 38px;
  bottom: 2px;
  left: 16px;
  width: 2px;
  border-radius: 1px;
  background: var(--pg-border-color-translucent);
}
.wsf-quick-event:last-child::before {
  display: none;
}
.wsf-quick-event-words {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  padding-top: 1px;
}
.wsf-quick-event-tools {
  display: flex;
  flex: none;
  gap: 2px;
}
.wsf-quick-add {
  margin: 0 0 12px 47px;
}
.wsf-quick-name {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 250px;
  gap: 14px;
  align-items: end;
  padding-top: 12px;
  border-top: 1px solid var(--pg-border-color-translucent);
}
.wsf-quick-publish {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 36px;
  margin: 0;
  color: var(--pg-fg-2);
  font-size: var(--pg-text-2);
}
.wsf-quick-error {
  margin: 12px 0 0;
}
@media (max-width: 767.98px) {
  .dialog.wsf-quick {
    --bs-dialog-width: 100%;
    height: 100%;
  }
  .wsf-quick-split {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
  }
  .wsf-quick-rail {
    flex-direction: row;
    padding: 0 0 8px;
    overflow-x: auto;
    overflow-y: hidden;
    border-right: 0;
    border-bottom: 1px solid var(--pg-border-color-translucent);
  }
  .wsf-quick-rail-line {
    display: none;
  }
  .wsf-quick-recipes,
  .wsf-quick-group,
  .wsf-quick-name,
  .wsf-quick-cards,
  .wsf-quick-when-row {
    grid-template-columns: minmax(0, 1fr);
  }
  .wsf-quick-hint {
    display: none;
  }
}
/* The Share dialog: one row per person or channel, the owner first. */
.wsf-share-row {
  display: flex;
  align-items: center;
  gap: var(--ws-space-2);
  padding: .35rem 0;
  border-bottom: 1px solid var(--pg-border-color-translucent);
}
.wsf-share-row:last-child {
  border-bottom: 0;
}
.wsf-share-who {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  gap: var(--ws-space-2);
  min-width: 0;
}
.wsf-share-who .avatar {
  flex: 0 0 auto;
  --bs-avatar-size: 1.5rem;
}
.wsf-share-level {
  flex: 0 0 auto;
  max-width: 50%;
  text-align: right;
}
.wsf-share-level select.pg-input {
  width: auto;
}
.wsf-main {
  position: relative;
  min-width: 0;
  min-height: 0;
}
/* Graph canvas core (pg_graph_canvas.js): the stage, the viewport that pans
   and zooms, the layer it moves, the arrows under the boxes, the boxes and
   their ports, whatever the boxes mean. Every colour, radius and shadow is a
   --pgc-* token with a panel fallback; a user maps the tokens to its own
   (the Workspace in its token block) and themes its boxes with modifier
   classes of its own prefix. Tokens: --pgc-accent, --pgc-soft (target fill),
   --pgc-radius, --pgc-radius-sm, --pgc-shadow, --pgc-shadow-accent,
   --pgc-line (arrows), --pgc-ring (selection ring), --pgc-node-accent (a
   box's border and ports), --pgc-marker and --pgc-marker-on (the url() of
   the arrowhead markers the user draws); with a focus --pgc-in (arrows
   into the box in focus), --pgc-faint and --pgc-dim (opacities),
   --pgc-trail and --pgc-marker-trail (a trail's arrows) and --pgc-group (a
   heading's label). */
.pgc-stage {
  position: relative;
  height: 100%;
  overflow: hidden;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--pgc-radius, var(--pg-radius));
  background: var(--pg-bg-1);
}
/* The grid's dots move and scale with the layer (the script sets their
   size and position). */
.pgc-viewport {
  position: absolute;
  inset: 0;
  overflow: hidden;
  touch-action: none;
  background-image: radial-gradient(circle, color-mix(in srgb, var(--pg-fg-body) 16%, transparent) 1px, transparent 1.25px);
}
.pgc-viewport.pgc-space,
.pgc-viewport.pgc-panning {
  cursor: grabbing;
}
.pgc-viewport:focus-visible {
  outline: 0;
  box-shadow: inset 0 0 0 2px var(--pgc-accent, var(--pg-primary));
}
.pgc-layer {
  position: absolute;
  top: 0;
  left: 0;
  transform-origin: 0 0;
}
.pgc-edges {
  position: absolute;
  top: 0;
  left: 0;
  overflow: visible;
  pointer-events: none;
}
.pgc-edge-line {
  fill: none;
  stroke: var(--pgc-line, #7d8696);
  stroke-width: 2;
  marker-end: var(--pgc-marker, none);
}
.pgc-edge-hit {
  fill: none;
  stroke: transparent;
  stroke-width: 14;
  pointer-events: stroke;
  cursor: pointer;
}
.pgc-arrowhead { fill: var(--pgc-line, #7d8696); }
.pgc-arrowhead-on { fill: var(--pgc-accent, var(--pg-primary)); }
.pgc-edge.pgc-selected .pgc-edge-line {
  stroke: var(--pgc-accent, var(--pg-primary));
  stroke-width: 3;
  marker-end: var(--pgc-marker-on, var(--pgc-marker, none));
}
.pgc-edge-label {
  font-size: 11px;
  fill: var(--pg-fg-2);
  paint-order: stroke;
  stroke: var(--pg-bg-1);
  stroke-width: 3px;
}
/* The outcome an arrow leaves by, on a pill at its middle. */
.pgc-edge-pill {
  fill: var(--pg-bg-1);
  stroke: var(--pg-border-color);
  stroke-width: 1;
}
.pgc-edge-pill + .pgc-edge-label {
  font-weight: var(--pg-weight-strong);
  stroke: none;
}
.pgc-edge.pgc-selected .pgc-edge-pill {
  stroke: var(--pgc-accent, var(--pg-primary));
}
.pgc-edge-temp {
  fill: none;
  stroke: var(--pgc-accent, var(--pg-primary));
  stroke-width: 2;
  stroke-dasharray: 5 4;
}
.pgc-edge-temp.pgc-hidden {
  display: none;
}
/* A canvas with a focus (adapter.focus): the arrows of the box in focus,
   out solid in the accent and in dashed in --pgc-in; the others hidden, or
   faint under them; the boxes and targets at neither end dimmed. */
.pgc-edge.pgc-hidden {
  display: none;
}
.pgc-edge.pgc-edge-out .pgc-edge-line {
  stroke: var(--pgc-accent, var(--pg-primary));
  marker-end: var(--pgc-marker-on, var(--pgc-marker, none));
}
.pgc-edge.pgc-edge-in .pgc-edge-line {
  stroke: var(--pgc-in, var(--pg-warning));
  stroke-dasharray: 6 4;
}
.pgc-edge.pgc-edge-faint {
  opacity: var(--pgc-faint, 0.3);
}
/* A trail (trail()): a set of arrows drawn in place of the focus's, wider
   in --pgc-trail. */
.pgc-edge.pgc-edge-trail .pgc-edge-line {
  stroke: var(--pgc-trail, var(--pgc-accent, var(--pg-primary)));
  stroke-width: 3;
  marker-end: var(--pgc-marker-trail, var(--pgc-marker-on, var(--pgc-marker, none)));
}
/* A proposed arrow (dashed()): dashed in a neutral colour, whatever the
   focus makes of it. */
.pgc-edge.pgc-edge-dashed .pgc-edge-line {
  stroke: var(--pgc-proposed, var(--pg-secondary));
  stroke-dasharray: 6 4;
}
.pgc-boxes .pgc-dim {
  opacity: var(--pgc-dim, 0.45);
}
/* Group headings behind the boxes (groups()): a label and a rule. */
.pgc-groups {
  position: absolute;
  top: 0;
  left: 0;
  pointer-events: none;
}
.pgc-group {
  position: absolute;
  display: flex;
  align-items: center;
  gap: 8px;
}
.pgc-group-label {
  font-weight: var(--pg-weight-strong);
  color: var(--pgc-group, var(--pg-fg-2));
  white-space: nowrap;
}
.pgc-group-rule {
  flex: 1;
  border-top: 1px solid var(--pgc-line, var(--pg-border-color));
}
.pgc-node {
  position: absolute;
  width: 208px;
  height: 80px;
  padding: 8px 12px;
  border: 1.5px solid var(--pgc-node-accent, var(--pg-border-color));
  border-radius: var(--pgc-radius-sm, var(--pg-radius-sm));
  background: var(--pg-bg-body);
  box-shadow: var(--pgc-shadow, var(--pg-shadow));
  cursor: grab;
  user-select: none;
  touch-action: none;
}
/* The selection ring outside the box's border. */
.pgc-node.pgc-selected {
  box-shadow: 0 0 0 1.5px var(--pg-bg-body), 0 0 0 3.5px var(--pgc-ring, var(--pgc-accent, var(--pg-primary))), var(--pgc-shadow-accent, none);
}
/* The rectangle a Shift+drag draws to choose the boxes it touches. */
.pgc-lasso {
  position: absolute;
  z-index: 3;
  border: 1px dashed var(--pgc-accent, var(--pg-primary));
  border-radius: var(--pgc-radius-sm, var(--pg-radius-sm));
  background: var(--pgc-soft, color-mix(in srgb, var(--pgc-accent, var(--pg-primary)) 8%, transparent));
  pointer-events: none;
}
.pgc-lasso.pgc-hidden {
  display: none;
}
/* The box an arrow being drawn would end on; the layer's class makes it
   win over a user's state border (a box with a problem). */
.pgc-boxes .pgc-node.pgc-target {
  border-color: var(--pgc-accent, var(--pg-primary));
  background: var(--pgc-soft, color-mix(in srgb, var(--pgc-accent, var(--pg-primary)) 8%, transparent));
}
/* An arrow port is drawn 10 px (12 px on hover) but taken by a 24 x 24 px
   target around it, so drawing an arrow, by mouse or by a long press, is as
   easy as with a larger dot. */
.pgc-port {
  position: absolute;
  top: 50%;
  width: 10px;
  height: 10px;
  margin-top: -5px;
  border: 1.5px solid var(--pg-bg-body);
  border-radius: 50%;
  background: var(--pgc-node-accent, var(--pg-fg-2));
}
.pgc-port::before {
  content: "";
  position: absolute;
  inset: -8.5px;
  border-radius: 50%;
}
.pgc-port-in {
  left: -7px;
}
.pgc-port-out {
  right: -7px;
  cursor: crosshair;
}
.pgc-port-out:hover {
  transform: scale(1.2);
}
/* A named port (a row's, data-port) sits at the middle of its row's edge:
   the user makes the row the dot's positioned parent, as wide as the box. */
.pgc-node [data-port] {
  z-index: 1;
}
/* A box's picture holder (thumb()), filled once the box is in sight. */
.pgc-thumb {
  display: block;
  overflow: hidden;
  pointer-events: none;
  background: var(--pg-bg-2);
  border-radius: var(--pgc-radius-sm, var(--pg-radius-sm));
}
.pgc-thumb > img {
  display: block;
  width: 100%;
  height: auto;
}
/* The Flows canvas on the core: its arrowhead markers, a box's border and
   ports in its group's colour (kindClasses() in workspace_flow.js), its
   problem state. */
.wsf-app {
  --pgc-marker: url(#wsf-arrow);
  --pgc-marker-on: url(#wsf-arrow-on);
}
.wsf-arrowhead-bad { fill: var(--pg-danger); }
.pgc-edge.wsf-bad .pgc-edge-pill { stroke: var(--pg-danger); }
.pgc-edge.wsf-bad .pgc-edge-line {
  stroke: var(--pg-danger);
  stroke-dasharray: 6 4;
  marker-end: url(#wsf-arrow-bad);
}
/* A box: its group's colour on its border, kind label and icon, the ports
   on the sides (kindClasses() in workspace_flow.js). The light theme takes
   deeper tones of the same hues, at least 4.5:1 on white. */
.wsf-group-start { --wsf-kind: #1a7f4e; }
.wsf-group-system { --wsf-kind: #0e7383; }
.wsf-group-logic { --wsf-kind: #8a5c00; }
.wsf-group-message { --wsf-kind: #2f62c4; }
.wsf-group-people { --wsf-kind: #6d4bd0; }
.wsf-group-values { --wsf-kind: #a8468f; }
[data-bs-theme="dark"] .wsf-group-start { --wsf-kind: #6fdca6; }
[data-bs-theme="dark"] .wsf-group-system { --wsf-kind: #45c4d6; }
[data-bs-theme="dark"] .wsf-group-logic { --wsf-kind: #e9b44c; }
[data-bs-theme="dark"] .wsf-group-message { --wsf-kind: #6ea8ff; }
[data-bs-theme="dark"] .wsf-group-people { --wsf-kind: #b49cff; }
[data-bs-theme="dark"] .wsf-group-values { --wsf-kind: #e58fd0; }
.pgc-node[class*="wsf-group-"] { --pgc-node-accent: var(--wsf-kind); }
/* A flow box as a card (wsf-card, cardFace() in workspace_flow.js): the
   card surface, the hairline and the card shadow; the group's colour only on
   the tile, the kind and the out port. Three lines beside the tile: the kind
   in small capitals, the title, what the box does; each cut to the width. */
.pgc-node.wsf-card {
  display: flex;
  gap: 10px;
  width: 196px;
  height: 72px;
  padding: 10px 12px;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: 13px;
  background: linear-gradient(180deg, var(--pg-surface-1), var(--pg-surface-2));
  box-shadow: var(--pg-shadow-card);
}
.pgc-node.wsf-card.pgc-selected {
  box-shadow: 0 0 0 1.5px var(--pg-bg-1), 0 0 0 3.5px var(--pgc-ring, var(--pgc-accent, var(--pg-primary))), var(--pg-shadow-card);
}
.pg-icon-tile.wsf-node-tile {
  --pg-tone: var(--wsf-kind, var(--pg-tone-gray));
  width: 30px;
  height: 30px;
}
.wsf-node-text {
  flex: 1 1 auto;
  min-width: 0;
}
.pgc-node.wsf-card .wsf-node-head {
  gap: 4px;
  height: 14px;
  font-weight: 650;
  letter-spacing: .06em;
}
.pgc-node.wsf-card :is(.wsf-run-badge, .wsf-ai-badge) {
  padding-block: 0;
  line-height: 12px;
}
.pgc-node.wsf-card .wsf-node-title {
  margin-top: 0;
  line-height: 1.35;
}
.pgc-node.wsf-card .wsf-node-meta {
  line-height: 1.35;
}
/* The out port an 8 px dot on the right edge, ringed in the canvas's
   ground; the in port shows while the box is pointed at, in focus, chosen
   or the end of an arrow being drawn. The 24 px target stays. */
.pgc-node.wsf-card .pgc-port {
  width: 8px;
  height: 8px;
  margin-top: -4px;
  border: 0;
  box-shadow: 0 0 0 2px var(--pg-bg-1);
}
.pgc-node.wsf-card .pgc-port::before {
  inset: -8px;
}
.pgc-node.wsf-card .pgc-port-out {
  right: -4.5px;
}
.pgc-node.wsf-card .pgc-port-in {
  left: -4.5px;
  opacity: 0;
}
.pgc-node.wsf-card:is(:hover, :focus-visible, .pgc-selected, .pgc-target) .pgc-port-in {
  opacity: 1;
}
/* Flow arrows are 1.75 px; the chosen and the run view's arrows keep their own. */
:is(.wsf-app, .wsf-embed) .pgc-edge:not(.pgc-selected) .pgc-edge-line {
  stroke-width: 1.75;
}
/* The Design examples screen draws flow boxes on a still stage of their
   own size, scrolled across in a narrow pane; the ring is the Workspace's. */
.pgc-stage.pg-look-flow {
  --pgc-ring: light-dark(#7c3aed, #a78bfa);
  height: 266px;
  overflow-x: auto;
}
/* The canvas's tools on the Design examples screen: the rail with its card
   open and the strip, on a still stage of their own size. */
.pgc-stage.pg-look-tools {
  height: 380px;
}
.pg-look-tools .wsf-palette-panel {
  display: flex;
}
/* A value box: no arrows, a dashed border. */
.pgc-node.wsf-group-values {
  border-style: dashed;
}
.wsf-constant {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 6.5rem minmax(0, 1.4fr) auto;
  gap: var(--ws-space-1);
  align-items: center;
  margin-bottom: var(--ws-space-1);
}
.wsf-readonly .pgc-node {
  cursor: pointer;
}
.pgc-node.wsf-bad {
  border-color: var(--pg-danger);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--pg-danger) 30%, transparent);
}
/* A box a patch of Pinegrap AI added or changed: a dashed ring outside the
   border, so selection and problems still show on the box itself. */
.pgc-node.wsf-ai-added,
.wsf-outline-item.wsf-ai-added {
  --wsf-ai: var(--pg-success);
  outline: 2px dashed var(--wsf-ai);
  outline-offset: 3px;
}
.pgc-node.wsf-ai-changed,
.wsf-outline-item.wsf-ai-changed {
  --wsf-ai: var(--pg-info);
  outline: 2px dashed var(--wsf-ai);
  outline-offset: 3px;
}
.wsf-ai-badge {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: .2rem;
  margin-left: auto;
  padding: 0 .4rem;
  border-radius: var(--ws-radius-xs);
  background: color-mix(in srgb, var(--wsf-ai) 15%, transparent);
  color: var(--pg-fg-body);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0;
  line-height: 1.5;
  text-transform: none;
  white-space: nowrap;
}
.pgc-node.wsf-bad .wsf-ai-badge {
  margin-left: 0;
}
.wsf-outline-head .wsf-ai-badge {
  font-size: .72rem;
}
.wsf-ai-marks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ws-space-2);
  margin-bottom: var(--ws-space-3);
  padding: var(--ws-space-2) var(--ws-space-3);
  border: 1px dashed var(--pg-info);
  border-radius: var(--ws-radius);
  background: var(--pg-info-bg-subtle);
  color: var(--pg-info-fg-emphasis);
  font-size: .875rem;
}
.wsf-ai-go {
  max-width: 16rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wsf-node-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--wsf-kind);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .03em;
  text-transform: uppercase;
}
.wsf-node-warn {
  display: none;
  margin-left: auto;
  color: var(--pg-danger);
}
.pgc-node.wsf-bad .wsf-node-warn {
  display: inline-block;
}
.wsf-node-title,
.wsf-node-meta {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wsf-node-title {
  margin-top: 2px;
  font-size: 14px;
  font-weight: 600;
}
.wsf-node-meta {
  font-size: 12px;
  color: var(--pg-fg-2);
}
.wsf-placeholder {
  color: var(--pg-fg-2);
  font-style: italic;
  font-weight: 400;
}
.wsf-readonly .pgc-port-out {
  cursor: inherit;
  transform: none;
}
.wsf-empty {
  position: absolute;
  top: 50%;
  left: 50%;
  max-width: 26rem;
  padding: var(--ws-space-4);
  transform: translate(-50%, -50%);
  color: var(--pg-fg-2);
  text-align: center;
  pointer-events: none;
}
/* "Add a box" (drawPalette()): floating 14 px in at the canvas's top left,
   a 48 px rail (a filled "+" and an icon for each group) and, beside it
   while open, the list as a 264 px card. The space between them lets the
   canvas take the pointer. Without it (a flow read-only, no flow open) and
   in the List view nothing floats. */
.wsf-palette {
  position: absolute;
  z-index: 5;
  top: 14px;
  bottom: 14px;
  left: 14px;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  pointer-events: none;
}
.wsf-app.wsf-no-palette .wsf-palette,
.wsf-app.wsf-outlined .wsf-palette {
  display: none;
}
.wsf-palette-rail,
.wsf-palette-panel,
.wsf-strip,
.wsf-add-pop {
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: 13px;
  background: var(--pg-surface-float);
  box-shadow: var(--pg-shadow-float);
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);
  pointer-events: auto;
}
.wsf-palette-rail {
  display: flex;
  flex: none;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  width: 48px;
  padding: 7px 0;
}
.wsf-palette-rail .wsf-palette-rail-open {
  width: 32px;
  height: 32px;
  padding: 0;
  margin-bottom: 4px;
  border-radius: 9px;
}
/* Two classes: the icon button's own colour comes later in the file. */
.wsf-palette-rail .wsf-palette-rail-group {
  color: var(--wsf-kind, var(--pg-fg-2));
}
.wsf-palette-panel {
  display: none;
  flex-direction: column;
  width: 264px;
  max-height: 100%;
  min-height: 0;
  overflow: hidden;
}
.wsf-app.wsf-palette-over .wsf-palette-panel {
  display: flex;
}
.wsf-palette-top {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 8px;
  padding: 8px 10px 6px 16px;
}
.wsf-palette-title {
  flex: 1 1 auto;
  margin: 0;
  font-size: var(--pg-text-base);
  font-weight: var(--pg-weight-strong);
}
/* The search field keeps its height while the sections under it scroll;
   inside its margins, not the look's full width. */
.wsf-palette .wsf-palette-search {
  flex-shrink: 0;
  width: auto;
  margin: 0 12px 10px;
}
.wsf-palette-groups {
  flex: 1 1 auto;
  min-height: 0;
  padding-bottom: 8px;
  overflow-x: hidden;
  overflow-y: auto;
}
/* A section: its number and heading (the hint is its tooltip), then its
   rows or its folding groups. */
.wsf-palette-stage {
  display: flex;
  flex-direction: column;
}
.wsf-palette-stage + .wsf-palette-stage {
  margin-top: 10px;
}
.wsf-palette-stage-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 6px 16px;
  font-size: var(--pg-text-meta);
  font-weight: var(--pg-weight-strong);
  color: var(--pg-fg-2);
}
.wsf-palette-stage-num {
  display: inline-grid;
  flex-shrink: 0;
  place-items: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  font-size: var(--pg-text-count);
  color: var(--pg-accent);
  background: color-mix(in srgb, var(--pg-accent) 16%, transparent);
}
/* The box that starts this flow as one row, "Change" at its end; the other
   start kinds under it while Change is open. */
.wsf-palette-current {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  margin: 0 12px 4px;
  padding: 6px 6px 6px 10px;
  border-radius: 11px;
  font-size: var(--pg-text-2);
  background: var(--pg-surface-1);
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
}
.wsf-palette-change {
  margin-left: auto;
}
.wsf-palette-swaps,
.wsf-palette-group,
.wsf-palette-rows {
  display: flex;
  flex-direction: column;
}
.wsf-palette-swaps {
  margin-bottom: 4px;
}
/* A group of steps that folds: its heading a button, its count while
   folded. */
.wsf-palette-head {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  margin: 2px 12px 0;
  padding: 0 6px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--pg-fg-3);
  font-size: var(--pg-text-meta);
  font-weight: var(--pg-weight-strong);
  text-align: left;
}
.wsf-palette-head:hover {
  background: var(--pg-hover);
  color: var(--pg-fg-2);
}
.wsf-palette-chevron {
  font-size: .8em;
}
.wsf-palette-count {
  margin-left: auto;
  font-weight: var(--pg-weight-regular);
}
/* A box: one 32 px row, its tile in its group's tone and its name on one
   line (the whole name is the row's tooltip). */
.wsf-palette-item {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 10px;
  height: 32px;
  min-width: 0;
  margin: 0 12px;
  padding: 0 8px;
  border: 0;
  border-radius: 9px;
  background: none;
  color: var(--pg-fg-body);
  font-size: var(--pg-text-2);
  text-align: left;
  cursor: grab;
}
.wsf-palette-item:hover,
.wsf-palette-item:focus-visible {
  background: var(--pg-hover);
}
.wsf-palette-item:focus-visible,
.wsf-palette-head:focus-visible {
  outline: 2px solid var(--pg-accent);
  outline-offset: -2px;
}
.wsf-palette-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wsf-palette-tile {
  --pg-tone: var(--wsf-kind, var(--pg-tone-gray));
  width: 22px;
  height: 22px;
  border-radius: 7px;
}
.wsf-palette-tip {
  flex-shrink: 0;
  margin: 0;
  padding: 10px 16px 12px;
  border-top: 1px solid var(--pg-border-color-translucent);
  color: var(--pg-fg-3);
}
/* The add list at a place (openAdd(), board B1): a 280 px card under the
   arrow's "+" or the box's, the search with its "/" key, "Often next", the
   groups as chips with their counts, the rows of the chip pressed. */
.wsf-add-pop {
  position: absolute;
  z-index: 6;
  display: flex;
  flex-direction: column;
  width: 280px;
  max-height: 420px;
  overflow: hidden;
}
.wsf-add-find {
  position: relative;
  flex-shrink: 0;
  margin: 12px 12px 6px;
}
.wsf-add-find .wsf-add-search {
  padding-right: 32px;
}
.wsf-add-key {
  position: absolute;
  top: 50%;
  right: 8px;
  transform: translateY(-50%);
  pointer-events: none;
}
.wsf-add-list {
  flex: 1 1 auto;
  min-height: 0;
  padding-bottom: 8px;
  overflow-y: auto;
}
.wsf-add-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin: 0 12px 6px;
}
.wsf-add-chip[aria-pressed="true"] {
  color: var(--pg-accent);
}
.wsf-add-chip .wsf-palette-count {
  margin-left: 2px;
}
.wsf-add-none {
  margin: 4px 16px;
}
/* The "+" on an arrow (pointed at or chosen) and the dashed one after a
   box with a free outcome: 20 px rounds on the canvas, at its zoom. */
.wsf-plus {
  position: absolute;
  z-index: 2;
  display: inline-grid;
  place-items: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 1px solid var(--pg-accent);
  border-radius: 50%;
  background: var(--pg-surface-float);
  color: var(--pg-accent);
  font-size: var(--pg-text-meta);
  line-height: 1;
}
.wsf-out-plus {
  border-style: dashed;
  color: var(--pg-fg-3);
  border-color: var(--pg-fg-3);
}
.wsf-plus:hover,
.wsf-plus:focus-visible {
  background: var(--pg-accent);
  color: var(--pg-on-accent);
  border-color: var(--pg-accent);
}
.wsf-app.wsf-outlined .wsf-add-pop {
  display: none;
}
/* The tools of several boxes chosen (drawSeveral(), board B2): a floating
   bar 12 px under the lowest box, at the canvas's zoom: the count,
   Duplicate, Copy and Delete. */
.wsf-several {
  position: absolute;
  z-index: 4;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 4px 4px 12px;
  white-space: nowrap;
}
.wsf-several-count {
  margin-right: 4px;
  color: var(--pg-fg-2);
}
/* Frames behind the boxes and notes over them (drawDecor()): a frame is a
   named rectangle whose body lets the pointer through to the canvas, its
   head moves it; folded it is the head alone. A note is a card of text with
   its writer and day, resized at its corner. */
.wsf-frames,
.wsf-notes {
  position: absolute;
  top: 0;
  left: 0;
}
.wsf-frame {
  position: absolute;
  border: 1.5px dashed color-mix(in srgb, var(--pg-fg-2) 45%, transparent);
  border-radius: var(--pg-radius);
  background: color-mix(in srgb, var(--pg-fg-2) 4%, transparent);
  pointer-events: none;
}
.wsf-frame-head {
  display: flex;
  align-items: center;
  gap: 4px;
  height: 36px;
  padding: 0 4px;
  cursor: grab;
  pointer-events: auto;
  touch-action: none;
}
.wsf-frame-folded {
  border-style: solid;
  background: var(--pg-bg-body);
  box-shadow: var(--pg-shadow-sm);
}
.wsf-frame-name {
  flex: 1 1 auto;
  min-width: 0;
  padding: 2px 6px;
  border: 1px solid transparent;
  border-radius: var(--pg-radius-sm);
  background: transparent;
  color: var(--pg-fg-body);
  font-weight: 600;
}
.wsf-frame-name:hover,
.wsf-frame-name:focus {
  border-color: var(--pg-border-color);
  background: var(--pg-bg-body);
  outline: none;
}
.wsf-frame-count {
  white-space: nowrap;
  color: var(--pg-fg-2);
}
.wsf-note {
  position: absolute;
  z-index: 3;
  display: flex;
  flex-direction: column;
  border: 1px solid color-mix(in srgb, var(--pg-warning) 45%, var(--pg-border-color));
  border-radius: var(--pg-radius-sm);
  background: color-mix(in srgb, var(--pg-warning) 14%, var(--pg-bg-body));
  box-shadow: var(--pg-shadow-sm);
  cursor: grab;
  touch-action: none;
}
.wsf-note-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 28px;
  padding: 2px 4px 0 10px;
  color: var(--pg-fg-2);
  font-size: 0.75rem;
}
.wsf-note-text {
  flex: 1 1 auto;
  width: 100%;
  padding: 2px 10px 10px;
  border: 0;
  background: transparent;
  color: var(--pg-fg-body);
  resize: none;
  cursor: text;
}
.wsf-note-text:focus {
  outline: none;
}
.wsf-note:focus-within {
  border-color: var(--pg-accent);
}
.wsf-note-grip {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 14px;
  height: 14px;
  border-right: 2px solid var(--pg-fg-2);
  border-bottom: 2px solid var(--pg-fg-2);
  border-bottom-right-radius: var(--pg-radius-sm);
  cursor: nwse-resize;
  opacity: 0.5;
}
/* The bottom strip (drawStrip()): centred 16 px over the canvas's bottom,
   44 px high; Undo and Redo, the zoom and Fit, the data threads. */
.wsf-strip {
  position: absolute;
  z-index: 4;
  bottom: 16px;
  left: 50%;
  display: flex;
  align-items: center;
  gap: 2px;
  height: 44px;
  padding: 0 8px;
  transform: translateX(-50%);
  white-space: nowrap;
}
/* The map (drawMap()): a 172 by 104 px card at the canvas's bottom left,
   the flow's boxes as small blocks, the part on screen framed. */
.wsf-map {
  position: absolute;
  z-index: 4;
  bottom: 16px;
  left: 16px;
  width: 172px;
  height: 104px;
  overflow: hidden;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--pg-radius-sm);
  background: var(--pg-surface-float);
  box-shadow: var(--pg-shadow-float);
  cursor: pointer;
  touch-action: none;
  pointer-events: auto;
}
.wsf-map-boxes {
  position: absolute;
  inset: 0;
}
.wsf-map-box,
.wsf-map-view {
  position: absolute;
  border-radius: 2px;
}
.wsf-map-box {
  background: color-mix(in srgb, var(--pg-fg-2) 40%, transparent);
}
.wsf-map-view {
  border: 1.5px solid var(--pg-primary);
  background: color-mix(in srgb, var(--pg-primary) 8%, transparent);
}
.wsf-strip-divider {
  width: 1px;
  height: 20px;
  margin: 0 6px;
  background: var(--pg-border-color-translucent);
}
.wsf-zoom-label {
  min-width: 3rem;
  font-size: .75rem;
  color: var(--pg-fg-2);
  text-align: center;
}
/* The ways to start a flow and the template gallery (workspace_flow.js,
   showGallery()). */
.wsf-gallery {
  height: 100%;
  padding: var(--ws-space-3);
  overflow-y: auto;
}
.wsf-starts,
.wsf-tpl-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(15rem, 1fr));
  gap: var(--ws-space-3);
}
.wsf-start-card,
.wsf-tpl-card {
  display: flex;
  flex-direction: column;
  gap: var(--ws-space-2);
  padding: var(--ws-space-3);
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-body);
  color: inherit;
  text-align: left;
}
.wsf-start-card:hover,
.wsf-start-card:focus-visible,
.wsf-tpl-card:hover {
  border-color: var(--pg-primary, #a78bfa);
}
.wsf-start-card > .bi {
  font-size: 1.25rem;
}
.wsf-start-ai:focus-within {
  border-color: var(--pg-primary, #a78bfa);
}
.wsf-ai-sketch-notes {
  flex-basis: 100%;
  padding-left: 1.25rem;
}
.wsf-start-title,
.wsf-tpl-name {
  margin: 0;
  font-size: .95rem;
  font-weight: 600;
}
.wsf-start-help,
.wsf-tpl-help {
  margin: 0;
  font-size: .8125rem;
  color: var(--pg-fg-2);
}
.wsf-tpl-category {
  margin-bottom: var(--ws-space-2);
  font-size: .75rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--pg-fg-2);
}
.wsf-tpl-icons {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ws-space-1);
  font-size: 1rem;
  color: var(--pg-fg-2);
}
.wsf-tpl-meta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ws-space-1) var(--ws-space-3);
  margin-top: auto;
  font-size: .75rem;
  color: var(--pg-fg-2);
}
.wsf-tpl-start {
  font-weight: 600;
}
.wsf-tpl-card > .pg-button {
  align-self: flex-start;
}
.wsf-palette-template {
  margin-bottom: 4px;
  cursor: pointer;
}
/* A template placed on the canvas (workspace_flow.js, arrive()): each box
   rises and grows from 92 %, its data threads are drawn in the text type's
   colour, then the setup panel slides in over the canvas. Without motion
   (prefers-reduced-motion) all of it is there at once. */
.pgc-node.wsf-arrive {
  animation-name: wsf-arrive;
  animation-timing-function: cubic-bezier(.2, .7, .3, 1);
  animation-fill-mode: both;
}
@keyframes wsf-arrive {
  from { opacity: 0; transform: translateY(10px) scale(.92); }
  to { opacity: 1; transform: none; }
}
.pgc-edge-line.wsf-arrow-hold {
  marker-end: none;
}
/* Data threads (drawData()): 1 px from a value's dot under the box that
   gives it to the chip of the field under the box that reads it, in its
   type's colour, threads of one type a few tones apart. The tones are the
   dark canvas's; the light one takes deeper ones. */
.wsf-tone-number-0 { --wsf-tone: #2f6fcc; }
.wsf-tone-number-1 { --wsf-tone: #5a8fdd; }
.wsf-tone-number-2 { --wsf-tone: #1d56a8; }
.wsf-tone-text-0 { --wsf-tone: #a8760f; }
.wsf-tone-text-1 { --wsf-tone: #c08f2e; }
.wsf-tone-text-2 { --wsf-tone: #8c6200; }
html[data-bs-theme="dark"] .wsf-tone-number-0 { --wsf-tone: #6ea8ff; }
html[data-bs-theme="dark"] .wsf-tone-number-1 { --wsf-tone: #9cc4ff; }
html[data-bs-theme="dark"] .wsf-tone-number-2 { --wsf-tone: #4d8fe8; }
html[data-bs-theme="dark"] .wsf-tone-text-0 { --wsf-tone: #e9b44c; }
html[data-bs-theme="dark"] .wsf-tone-text-1 { --wsf-tone: #f5cf7d; }
html[data-bs-theme="dark"] .wsf-tone-text-2 { --wsf-tone: #f0c060; }
.wsf-thread {
  fill: none;
  stroke: var(--wsf-tone, #a8760f);
  stroke-width: 1;
  pointer-events: none;
}
.wsf-thread-skipped {
  stroke-dasharray: 4 3;
}
/* A value whose box was deleted (goneThread()). */
.wsf-thread-gone {
  stroke: var(--pg-danger);
  stroke-dasharray: 4 3;
}
/* Placed from the box's outer edge (drawData()), so the box's 1 px border
   is taken back; as wide as dataRowSlots() lets it be (--wsf-w), so the row
   stays within its box. On hover an item shows its whole name over its
   neighbours. */
.wsf-data {
  position: absolute;
  top: calc(100% - 6px);
  margin-left: -1px;
  display: flex;
  align-items: center;
  height: 14px;
  font-size: 11px;
  line-height: 12px;
  white-space: nowrap;
  pointer-events: none;
}
.wsf-data-field {
  width: var(--wsf-w, 76px);
  padding: 0 6px;
  overflow: hidden;
  text-overflow: ellipsis;
  border: 1px solid var(--wsf-tone);
  border-radius: 999px;
  background: var(--pg-bg-body);
  color: var(--pg-fg-2);
}
.wsf-data-field.wsf-data-bad {
  border-color: var(--pg-danger);
  color: var(--pg-danger);
}
.wsf-data-out {
  width: var(--wsf-w, 84px);
  gap: 3px;
  color: var(--pg-fg-2);
}
/* The name keeps the ground's colour behind it, so a thread passing by
   never runs through it. */
.wsf-data-out .wsf-data-label {
  padding-right: 4px;
  border-radius: 0 999px 999px 0;
  background: var(--pg-bg-body);
}
.wsf-data-field,
.wsf-data-out {
  pointer-events: auto;
}
.wsf-data-field:hover,
.wsf-data-out:hover {
  z-index: 3;
  width: max-content;
  min-width: var(--wsf-w);
}
.wsf-data-out:hover {
  padding-right: 6px;
  border-radius: 999px;
  background: var(--pg-bg-body);
}
/* A value dot: a 14 px ring with an 8 px type icon, taken by a 24 x 24 px
   target around it for pulling a thread. */
.wsf-data-ring {
  position: relative;
  flex: none;
  width: 14px;
  height: 14px;
  border: 1.5px solid var(--wsf-tone);
  border-radius: 50%;
  background: var(--pg-bg-body);
  color: var(--wsf-tone);
  font-size: 8px;
  font-weight: 700;
  line-height: 11px;
  text-align: center;
}
.wsf-data-ring::before {
  content: "";
  position: absolute;
  inset: -6.5px;
  border-radius: 50%;
}
.wsf-data-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* A box whose threads are not drawn (markThreads()): a dot per value it
   reads, then "2 values", on its bottom edge. */
.wsf-data-mark {
  position: absolute;
  top: calc(100% - 9px);
  left: 8px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 18px;
  padding: 0 8px 0 6px;
  border-radius: 999px;
  background: var(--pg-bg-body);
  box-shadow: inset 0 0 0 1px var(--pg-border-color);
  color: var(--pg-fg-3);
  font-size: 11px;
  white-space: nowrap;
  pointer-events: none;
}
.wsf-data-mark-dot {
  flex: none;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--wsf-tone, #a8760f);
}
.wsf-data-mark-dot.wsf-data-bad {
  background: var(--pg-danger);
}
/* Drawing a thread (T2): the dots of a draft take the pointer; while a
   thread is on its way the fields it may go into are lit and the one
   under the pointer is filled. */
.wsf-data-live {
  pointer-events: auto;
  cursor: crosshair;
}
.wsf-data-unused .wsf-data-ring {
  border-style: dashed;
}
.wsf-data-unused {
  opacity: .75;
}
.wsf-data-live:hover .wsf-data-ring,
.wsf-data-out.wsf-data-hot .wsf-data-ring {
  background: var(--wsf-tone);
  color: var(--pg-bg-body);
}
.wsf-data-target {
  pointer-events: auto;
  cursor: copy;
  border-style: dashed;
  border-color: var(--ws-accent);
  color: var(--ws-accent);
  box-shadow: 0 0 0 2px rgba(var(--ws-accent-rgb), .25);
}
.wsf-data-target.wsf-data-hot {
  border-style: solid;
  background: var(--ws-soft);
}
.pgc-edge-temp.wsf-temp-thread {
  stroke: var(--ws-accent);
  stroke-width: 1;
  stroke-dasharray: none;
}
@media (prefers-reduced-motion: no-preference) {
  .wsf-thread,
  .wsf-data {
    transition: opacity 120ms ease-out;
  }
}
.wsf-outline-reads {
  margin: var(--ws-space-1) 0 var(--ws-space-2);
  color: var(--pg-fg-2);
}
.wsf-outline-read-icon {
  margin-right: var(--ws-space-1);
  color: var(--wsf-tone);
}
.wsf-outline-reads .wsf-data-bad,
.wsf-outline-reads .wsf-data-bad .wsf-outline-read-icon {
  color: var(--pg-danger);
}
.wsf-setup {
  position: absolute;
  top: var(--ws-space-3);
  right: var(--ws-space-3);
  z-index: 5;
  width: min(20rem, calc(100% - 2 * var(--ws-space-3)));
  max-height: calc(100% - 2 * var(--ws-space-3));
  padding: var(--ws-space-3);
  overflow-y: auto;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-body);
  box-shadow: 0 .5rem 1.5rem rgba(0, 0, 0, .18);
  animation: wsf-setup-in 260ms cubic-bezier(.2, .7, .3, 1) both;
}
@keyframes wsf-setup-in {
  from { opacity: 0; transform: translateX(1.5rem); }
  to { opacity: 1; transform: none; }
}
.wsf-setup-close {
  position: absolute;
  top: var(--ws-space-2);
  right: var(--ws-space-2);
}
.wsf-setup-title {
  margin: 0 2rem var(--ws-space-1) 0;
  font-size: 1rem;
  font-weight: 600;
}
.wsf-setup-help {
  margin-bottom: var(--ws-space-3);
  font-size: .8125rem;
  color: var(--pg-fg-2);
}
.wsf-setup-error {
  margin-bottom: var(--ws-space-2);
  font-size: .8125rem;
  color: var(--pg-danger);
}
.wsf-setup .wsf-people-list.is-invalid {
  outline: 1px solid var(--pg-danger);
}
.wsf-setup-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--ws-space-2);
}
@media (prefers-reduced-motion: reduce) {
  .pgc-node.wsf-arrive,
  .wsf-setup {
    animation: none;
  }
}
/* A problem or warning in the right panel with nothing chosen (problemList()):
   a row in its tone, its words, then "Go to the box". */
.wsf-problem {
  --pg-tone: var(--pg-tone-rose);
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 6px;
  padding: 8px 8px 8px 10px;
  border-radius: 11px;
  background: color-mix(in srgb, var(--pg-tone) 9%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pg-tone) 22%, transparent);
  font-size: var(--pg-text-2);
}
.wsf-problem > .bi {
  margin-top: 2px;
  color: var(--pg-tone);
}
.wsf-problem.wsf-warning {
  --pg-tone: var(--pg-tone-amber);
}
.wsf-problem-text {
  flex: 1 1 auto;
  min-width: 0;
  overflow-wrap: anywhere;
}
.wsf-problem-go {
  flex-shrink: 0;
}
.wsf-side-facts {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 6px 14px;
  margin: 0 0 12px;
  font-size: var(--pg-text-2);
}
.wsf-side-facts dd {
  margin: 0;
}
/* A text a box writes in, its values as chips (valueInput()); the list
   "Add value" opens under it (valueField()). */
/* A text box like any other, text and chips on one line until it wraps:
   .pg-input lays a field out as a flex row of a fixed height, which put every
   text piece and chip in a column of its own. Two classes, as .pg-input and
   .pg-input-sm come later. */
.pg-input.wsf-values {
  display: block;
  height: auto;
  min-height: 32px;
  padding: 5px 12px;
  line-height: 1.5;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.pg-input.wsf-values-multi {
  min-height: 5rem;
}
.wsf-chip {
  display: inline-block;
  margin: 0 .1rem;
  padding: 0 .4rem;
  border: 1px solid var(--pg-primary-border-subtle);
  border-radius: 999px;
  background: var(--pg-primary-bg-subtle);
  color: var(--pg-primary-fg-emphasis);
  font-size: .8rem;
  line-height: 1.4;
  white-space: nowrap;
  user-select: all;
}
/* A value's chip is never wider than its text box: a long name (a box named
   after its title, a value with its "When empty" text) wraps inside the
   chip, so its × stays in reach instead of beyond the side pane. */
.wsf-values .wsf-chip {
  max-width: 100%;
  border-radius: .7rem;
  white-space: normal;
  overflow-wrap: anywhere;
}
.wsf-chip-skipped {
  border-style: dashed;
  border-color: var(--pg-warning-border-subtle);
  background: var(--pg-warning-bg-subtle);
  color: var(--pg-warning-fg-emphasis);
}
.wsf-chip-bad {
  border-color: var(--pg-danger-border-subtle);
  background: var(--pg-danger-bg-subtle);
  color: var(--pg-danger-fg-emphasis);
}
.wsf-values-list {
  max-height: 16rem;
  overflow-y: auto;
  margin-top: var(--ws-space-1);
  padding: var(--ws-space-1);
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
}
.wsf-values-group {
  padding: .35rem .25rem .1rem;
  font-size: .75rem;
  font-weight: 600;
}
.wsf-values-pick {
  display: block;
  width: 100%;
  padding: .2rem .5rem;
  border: 0;
  border-radius: var(--ws-radius-sm);
  background: transparent;
  color: inherit;
  font-size: .85rem;
  text-align: left;
}
.wsf-values-pick:hover,
.wsf-values-pick:focus-visible {
  background: var(--pg-secondary-bg-subtle);
}
/* "Add value" as a small button inside its text box, at the bottom right
   (valueField()); the text keeps clear of it. */
.wsf-values-box {
  position: relative;
}
.wsf-values-box .wsf-values {
  padding-right: 2.25rem;
}
.wsf-values-add {
  position: absolute;
  right: var(--ws-space-1);
  bottom: var(--ws-space-1);
  width: 1.5rem;
  height: 1.5rem;
  border-radius: var(--ws-radius-sm);
  background: var(--pg-quiet);
  box-shadow: inset 0 0 0 1px var(--pg-border-color-translucent);
}
/* A field's name with its "?" at the right, and the small window the "?"
   opens over the panel with the field's whole help (helpAsk()). */
.wsf-field-head {
  display: flex;
  align-items: center;
  gap: var(--ws-space-2);
}
.wsf-help-ask {
  width: 1.5rem;
  height: 1.5rem;
  margin: -.25rem 0 -.25rem auto;
}
.wsf-help-pop {
  position: absolute;
  z-index: 5;
  left: 0;
  right: 0;
  margin-top: var(--ws-space-1);
  padding: var(--ws-space-2) .75rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-surface-float);
  box-shadow: var(--pg-shadow-float);
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);
}
/* A folded part of a box's settings (the e-mail's Sender): one row with a
   chevron, its name and, while closed, what it holds at the right. */
.wsf-fold-head {
  display: flex;
  align-items: center;
  gap: var(--ws-space-2);
  min-height: 2.375rem;
  border-top: 1px solid var(--pg-border-color);
  border-bottom: 1px solid var(--pg-border-color);
  list-style: none;
  cursor: pointer;
}
.wsf-fold-head::-webkit-details-marker {
  display: none;
}
.wsf-fold-head .bi {
  color: var(--pg-fg-3);
}
.wsf-fold[open] > .wsf-fold-head {
  margin-bottom: var(--ws-space-3);
}
.wsf-fold[open] > .wsf-fold-head .bi {
  transform: rotate(90deg);
}
.wsf-fold-shows {
  min-width: 0;
  margin-left: auto;
}
.wsf-fold[open] .wsf-fold-shows {
  display: none;
}
.wsf-people-list {
  max-height: 12rem;
  overflow-y: auto;
  padding: var(--ws-space-1);
  border: 1px solid var(--pg-border-color);
  border-radius: var(--ws-radius-sm);
}
.wsf-person {
  display: flex;
  align-items: center;
  gap: var(--ws-space-2);
  padding: .2rem .25rem;
  border-radius: var(--ws-radius-xs);
  font-size: .85rem;
  cursor: pointer;
}
.wsf-person:hover {
  background: var(--pg-bg-2);
}
.wsf-person .avatar {
  --bs-avatar-size: var(--ws-avatar-xs);
}
/* A Next row stays inside the side panel: the target box's name fills the
   first line and is cut with an ellipsis, the remove button ends it, and the
   outcome select goes on a line of its own under the name, as wide as the
   panel lets it be. */
.wsf-link {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ws-space-1) var(--ws-space-2);
  min-width: 0;
  padding: .15rem 0;
  font-size: .85rem;
}
.wsf-link-name {
  flex: 1 1 0;
  min-width: 0;
}
.wsf-link > .pg-icon-button {
  flex: none;
}
.wsf-link-on {
  flex: 1 1 100%;
  width: auto;
  min-width: 0;
  max-width: calc(100% - 1em - var(--ws-space-2));
  margin-left: calc(1em + var(--ws-space-2));
}
.wsf-number {
  max-width: 8rem;
}
.wsf-keys summary {
  cursor: pointer;
}
/* The outline: the same boxes as a list, each with its settings. */
.wsf-outline {
  height: 100%;
  overflow-y: auto;
}
.wsf-outline-list {
  margin: 0 0 var(--ws-space-3);
  padding-left: 1.5rem;
}
/* A List view entry is drawn as the canvas's card: the hairline, the card
   surface, the kind's tile and the kind over the title in its heading. */
.wsf-outline-item {
  margin-bottom: var(--ws-space-3);
  padding: var(--ws-space-3);
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: 13px;
  background: linear-gradient(180deg, var(--pg-surface-1), var(--pg-surface-2));
  box-shadow: var(--pg-shadow-card);
}
.wsf-outline-item.wsf-bad {
  border-color: var(--pg-danger);
}
.wsf-outline-head {
  display: flex;
  align-items: center;
  margin-bottom: var(--ws-space-2);
  font-size: 1rem;
  font-weight: 600;
}
.wsf-outline-toggle {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  min-width: 0;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: start;
}
.wsf-outline-head .wsf-node-tile {
  margin-right: 10px;
}
.wsf-outline-text {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-width: 0;
}
.wsf-outline-kind {
  color: var(--wsf-kind, var(--pg-fg-2));
  font-size: 11px;
  font-weight: 650;
  letter-spacing: .06em;
  line-height: 1.3;
  text-transform: uppercase;
}
.wsf-outline-title {
  overflow: hidden;
  font-size: 14px;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* The run view: every box wears its state in the run shown as a tone, a
   mark and a word (the word is never left out); the Bootstrap tones used
   follow the light and dark theme on their own. */
.wsf-run-ready { --wsf-run-fg: var(--pg-info-fg-emphasis); --wsf-run-bg: var(--pg-info-bg-subtle); --wsf-run-line: var(--pg-info-border-subtle); }
.wsf-run-running { --wsf-run-fg: var(--pg-primary-fg-emphasis); --wsf-run-bg: var(--pg-primary-bg-subtle); --wsf-run-line: var(--pg-primary-border-subtle); }
.wsf-run-waiting { --wsf-run-fg: var(--pg-warning-fg-emphasis); --wsf-run-bg: var(--pg-warning-bg-subtle); --wsf-run-line: var(--pg-warning-border-subtle); }
.wsf-run-done { --wsf-run-fg: var(--pg-success-fg-emphasis); --wsf-run-bg: var(--pg-success-bg-subtle); --wsf-run-line: var(--pg-success-border-subtle); }
.wsf-run-failed { --wsf-run-fg: var(--pg-danger-fg-emphasis); --wsf-run-bg: var(--pg-danger-bg-subtle); --wsf-run-line: var(--pg-danger-border-subtle); }
.wsf-run-skipped,
.wsf-run-cancelled,
.wsf-run-left { --wsf-run-fg: var(--pg-secondary-fg-emphasis); --wsf-run-bg: var(--pg-secondary-bg-subtle); --wsf-run-line: var(--pg-secondary-border-subtle); }
.wsf-run-none { --wsf-run-fg: var(--pg-fg-2); --wsf-run-bg: transparent; --wsf-run-line: var(--pg-border-color); }
.wsf-run-badge {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: .25rem;
  padding: .1rem .45rem;
  border: 1px solid var(--wsf-run-line);
  border-radius: var(--ws-radius-xs);
  background: var(--wsf-run-bg);
  color: var(--wsf-run-fg);
  font-size: .72rem;
  font-weight: 600;
  letter-spacing: 0;
  line-height: 1.3;
  text-transform: none;
  white-space: nowrap;
}
.pgc-node .wsf-run-badge {
  margin-left: auto;
  font-size: 10px;
}
/* A run's flag (runFlag()): Completed green, Waiting amber, Running blue,
   Failed red, each with its mark and word, the run's duration and one line
   of its result; ▾ opens the whole result. The dark values are the canvas
   spec's, the light ones the same hues on a light ground. */
.wsf-flag { --wsf-flag-bg: var(--pg-secondary-bg-subtle); --wsf-flag-fg: var(--pg-secondary-fg-emphasis); }
.wsf-flag-done { --wsf-flag-bg: #dff3e8; --wsf-flag-fg: #1d6b45; }
.wsf-flag-waiting { --wsf-flag-bg: #fbf1d8; --wsf-flag-fg: #6e5200; }
.wsf-flag-running { --wsf-flag-bg: #e3edfc; --wsf-flag-fg: #1f4f99; }
.wsf-flag-failed { --wsf-flag-bg: #fbe3e5; --wsf-flag-fg: #9b1c27; }
html[data-bs-theme="dark"] .wsf-flag-done { --wsf-flag-bg: #173a2a; --wsf-flag-fg: #6fdca6; }
html[data-bs-theme="dark"] .wsf-flag-waiting { --wsf-flag-bg: #2a2416; --wsf-flag-fg: #f3dca0; }
html[data-bs-theme="dark"] .wsf-flag-running { --wsf-flag-bg: #1b2638; --wsf-flag-fg: #b9d3ff; }
html[data-bs-theme="dark"] .wsf-flag-failed { --wsf-flag-bg: #2a1d21; --wsf-flag-fg: #ffb3b8; }
.wsf-flag {
  max-width: 100%;
  padding: .2rem .5rem;
  border-radius: var(--ws-radius-xs);
  background: var(--wsf-flag-bg);
  color: var(--wsf-flag-fg);
  font-size: .75rem;
  line-height: 1.35;
}
.wsf-flag-line {
  display: flex;
  align-items: center;
  gap: .35rem;
  min-width: 0;
}
.wsf-flag-state {
  flex: 0 0 auto;
  font-weight: 600;
}
.wsf-flag-time {
  flex: 0 0 auto;
  opacity: .8;
}
.wsf-flag-result {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wsf-flag .pg-button,
.wsf-flag .pg-icon-button {
  flex: 0 0 auto;
  width: auto;
  height: auto;
  padding: 0 .25rem;
  color: inherit;
  font-size: inherit;
  line-height: inherit;
}
.wsf-flag-fold .bi {
  display: inline-block;
  transition: transform .15s ease;
}
.wsf-flag-fold[aria-expanded="true"] .bi { transform: rotate(180deg); }
.wsf-flag-whole {
  margin-top: .25rem;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.wsf-flag-whole .pg-button { padding: 0; text-decoration: underline; }
/* Above the flow's last box on the canvas, as wide as the box. */
.wsf-flag-canvas {
  position: absolute;
  z-index: 2;
  width: 196px;
  transform: translateY(calc(-100% - 8px));
}
@media (prefers-reduced-motion: reduce) {
  .wsf-flag-fold .bi { transition: none; }
}
.wsf-node-head .wsf-node-kind {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wsf-run-view .pgc-node,
.wsf-trial .pgc-node {
  border-color: var(--wsf-run-line, var(--pg-border-color));
  background: linear-gradient(var(--wsf-run-bg, transparent), var(--wsf-run-bg, transparent)), var(--pg-bg-body);
}
.wsf-run-view .pgc-node.wsf-run-none {
  border-style: dashed;
  box-shadow: none;
}
.wsf-run-view .pgc-node.wsf-run-none .wsf-node-title {
  color: var(--pg-fg-2);
}
.wsf-run-view .pgc-node.pgc-selected,
.wsf-trial .pgc-node.pgc-selected {
  box-shadow: 0 0 0 1.5px var(--pg-bg-body), 0 0 0 3.5px var(--pgc-ring);
}
.wsf-run-task {
  position: relative;
  color: var(--wsf-run-fg, var(--ws-accent));
  font-weight: 600;
  cursor: pointer;
}
/* A trial marks its boxes and arrows as a run shown does: the arrows
   walked green, the others faint. */
.wsf-run-view .pgc-edge-line,
.wsf-trial .pgc-edge-line {
  opacity: .45;
}
.wsf-run-view .pgc-edge.wsf-edge-taken .pgc-edge-line,
.wsf-trial .pgc-edge.wsf-edge-taken .pgc-edge-line {
  stroke: var(--pg-success);
  opacity: 1;
  marker-end: url(#wsf-arrow-taken);
}
.wsf-arrowhead-taken { fill: var(--pg-success); }
/* A live flow's counts: the pills (look A's .pg-pill) stand in a row
   above their box, each a button listing its runs; the one listed is
   ringed in its tone. */
.pgc-node .wsf-counts {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 4px;
  display: flex;
  gap: 5px;
  max-width: 260px;
  pointer-events: none;
}
.wsf-counts .wsf-count {
  border: 0;
  cursor: pointer;
  pointer-events: auto;
}
.wsf-counts .wsf-count[aria-pressed="true"] {
  box-shadow: inset 0 0 0 1px var(--pg-tone), 0 0 0 3px color-mix(in srgb, var(--pg-tone) 26%, transparent);
}
.wsf-counts .wsf-count:focus-visible {
  outline: 2px solid var(--pg-focus-ring-color, var(--pg-primary));
  outline-offset: 2px;
}
.wsf-run-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ws-space-2);
  margin-bottom: var(--ws-space-2);
  padding: var(--ws-space-2) var(--ws-space-3);
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
  background: var(--ws-soft);
  font-size: .875rem;
}
.wsf-run-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  width: 100%;
  margin-bottom: var(--ws-space-1);
  padding: .45rem .55rem;
  border: 1px solid var(--pg-border-color-translucent);
  border-radius: var(--ws-radius-sm);
  background: var(--pg-bg-body);
  color: var(--pg-fg-body);
  font-size: .85rem;
  text-align: left;
}
.wsf-run-item:hover {
  background: var(--pg-bg-2);
}
.wsf-run-item-top {
  display: flex;
  align-items: center;
  gap: var(--ws-space-2);
}
.wsf-run-item-line {
  font-size: .78rem;
  color: var(--pg-fg-2);
}
.wsf-run-facts li + li {
  margin-top: 2px;
}
.wsf-run-step {
  padding-top: var(--ws-space-3);
  border-top: 1px solid var(--pg-border-color-translucent);
}
.wsf-run-steps {
  padding-top: var(--ws-space-2);
  border-top: 1px solid var(--pg-border-color-translucent);
}
.wsf-run-step-row {
  display: flex;
  align-items: center;
  gap: var(--ws-space-2);
  width: 100%;
  padding: .3rem .4rem;
  border: 0;
  border-radius: var(--ws-radius-sm);
  background: transparent;
  color: var(--pg-fg-body);
  font-size: .85rem;
  text-align: left;
}
.wsf-run-step-row:hover {
  background: var(--pg-bg-2);
}
.wsf-run-step-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wsf-run-result {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.wsf-outline-item.wsf-run-none {
  border-style: dashed;
  box-shadow: none;
}
.wsf-run-view .wsf-outline-item:not(.wsf-run-none) {
  border-color: var(--wsf-run-line, var(--pg-border-color));
  background: linear-gradient(var(--wsf-run-bg, transparent), var(--wsf-run-bg, transparent)), var(--pg-bg-body);
}
@media (max-width: 767.98px) {
  .wsf-app {
    grid-template-columns: minmax(0, 1fr);
    height: auto;
    min-height: 0;
  }
  .wsf-app .wsf-palette { display: none; }
  /* A box chosen on the canvas: its panel is a sheet from the bottom over a
     scrim (closeSide() on a tap there, Close or Esc). */
  .wsf-app.wsf-side-chosen .wsf-side {
    position: fixed;
    z-index: 1046;
    right: 0;
    bottom: 0;
    left: 0;
    max-height: 85vh;
    padding-bottom: calc(var(--ws-space-3) + env(safe-area-inset-bottom, 0px));
    border-radius: var(--pg-radius-sheet) var(--pg-radius-sheet) 0 0;
    box-shadow: var(--pg-shadow-float);
  }
  /* "Add a box" opens the list as a sheet of the full height, in both
     views; Close, Esc or a box added closes it (foldPalette()). */
  .wsf-app.wsf-palette-over .wsf-palette {
    display: flex;
    position: fixed;
    z-index: 1047;
    inset: 0;
    padding-top: env(safe-area-inset-top, 0px);
    padding-bottom: env(safe-area-inset-bottom, 0px);
    background: var(--pg-bg-body);
    pointer-events: auto;
  }
  .wsf-app.wsf-palette-over .wsf-palette-rail { display: none; }
  .wsf-app.wsf-palette-over .wsf-palette-panel {
    flex: 1 1 auto;
    width: auto;
    border: 0;
    border-radius: 0;
    box-shadow: none;
  }
  .wsf-add-box { margin-bottom: var(--ws-space-2); }
  .wsf-app.wsf-side-chosen .wsf-scrim {
    display: block;
    position: fixed;
    z-index: 1045;
    inset: 0;
    background: color-mix(in srgb, var(--pg-fg-body) 32%, transparent);
  }
  .pgc-stage { height: 60vh; }
  .wsf-outline { height: auto; overflow: visible; }
  .wsf-bar .wsf-name { flex: 1 1 8rem; min-width: 0; }
  .wsf-bar .wsf-unpublished { display: none; }
  /* The flow list on a phone: each flow a block of stacked rows, each
     value under its column's name. */
  .wsf-flow-table thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
  .wsf-flow-table tr { display: block; padding: var(--ws-space-2) 0; border-bottom: 1px solid var(--pg-border-color-translucent); }
  .wsf-flow-table th,
  .wsf-flow-table td { display: block; padding: .2rem 0; border: 0; }
  .wsf-flow-table td::before { content: attr(data-label); display: block; font-size: .72rem; color: var(--pg-fg-2); }
  .wsf-flow-table .wsf-flow-start-in { display: block; }
}
/* ── /Workspace ── */
/* A scheduled action drawn read-only in the Scheduled actions section of
   Flows (showAction() in workspace_flow.js): the flow boxes on a canvas
   that scrolls, in their groups' colours (ACTION_KINDS). */
.ws-sa-graph {
  height: auto;
  overflow: auto;
}
.ws-sa-graph-layer {
  position: relative;
}
.ws-sa-graph .pgc-node {
  cursor: default;
  touch-action: auto;
  user-select: text;
}
.ws-sa-graph .pgc-node:focus-visible {
  outline: 0;
  box-shadow: 0 0 0 2px var(--ws-accent);
}
.ws-sa-graph .pgc-port-out {
  cursor: inherit;
}
.ws-sa-graph-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}
.ws-sa-graph-chip {
  font-weight: 500;
  white-space: normal;
  text-align: left;
}

/* Windows High Contrast (forced colours). The browser paints every author
   background as Canvas and drops box-shadow, so a state drawn only by a fill,
   a ::before background or mask, or a shadow ring disappears. These rules
   draw those states in system colours; outside this query nothing changes. */
@media (forced-colors: active) {
  /* The tick, the radio dot and the switch knob are ::before backgrounds or
     masks; a checked switch fills its track. */
  .check::before,
  .radio::before,
  .switch::before {
    forced-color-adjust: none;
    background-color: CanvasText;
  }
  .switch:has(input:checked) {
    forced-color-adjust: none;
    background-color: Highlight;
    border-color: Highlight;
  }
  .switch:has(input:checked)::before {
    background-color: HighlightText;
  }
  /* The X is a mask over currentcolor. */
  .btn-close {
    forced-color-adjust: none;
    background-color: ButtonText;
  }
  /* A bell row's menu (pg_bell_row()). */
  #notifications .pg-bell-menu {
    border: 1px solid CanvasText;
  }
  #notifications .pg-bell-dot {
    forced-color-adjust: none;
    background-color: Highlight;
  }

  /* The current or pressed item, shown elsewhere only by a fill, a tint or a
     shadow. :is() takes its most specific selector, so this beats every
     screen rule it repeats. */
  :is(
    .nav-link.active,
    .page-link.active,
    .active > .page-link,
    .list-group-item.active,
    .menu-item.active,
    input.btn-check:checked + .btn,
    .btn-text.theme-secondary.active,
    #header .pg-um-themebtn.active,
    .pg-filter[aria-pressed="true"],
    #notifications .pg-bell-filter[aria-pressed="true"],
    button.pg-vs-cell.is-active,
    .pg-sale-switch .btn.active,
    .pg-sale-switch .btn[aria-pressed="true"],
    .pg-sale-method[aria-pressed="true"],
    .ws-rich-tools .pg-icon-button[aria-pressed="true"],
    .ws-format-tool.active,
    .btn-check:checked + .pg-role-card,
    .ws-status-choice.btn-check:has(input:checked)
  ) {
    forced-color-adjust: none;
    background-color: Highlight;
    color: HighlightText;
    border-color: Highlight;
  }
  /* Labels and icons inside take the item's text colour, not their own. */
  :is(
    .nav-link.active,
    .page-link.active,
    .active > .page-link,
    .list-group-item.active,
    .menu-item.active,
    input.btn-check:checked + .btn,
    .btn-text.theme-secondary.active,
    #header .pg-um-themebtn.active,
    .pg-filter[aria-pressed="true"],
    #notifications .pg-bell-filter[aria-pressed="true"],
    button.pg-vs-cell.is-active,
    .pg-sale-switch .btn.active,
    .pg-sale-switch .btn[aria-pressed="true"],
    .pg-sale-method[aria-pressed="true"],
    .ws-rich-tools .pg-icon-button[aria-pressed="true"],
    .ws-format-tool.active,
    .btn-check:checked + .pg-role-card
  ) *,
  .ws-status-choice.btn-check > i {
    color: inherit;
    background-color: transparent;
    border-color: currentcolor;
  }

  /* Progress bars: the track gets a frame, the bar a fill. */
  .progress,
  .progress-stacked {
    border: 1px solid CanvasText;
  }
  .progress-bar {
    forced-color-adjust: none;
    background-color: Highlight;
    color: HighlightText;
  }

  /* Stepper: every disc gets a frame, a reached step a fill, the current step
     a ring as well. */
  .stepper-item::before {
    border: 1px solid CanvasText;
  }
  .stepper-item.active::before {
    forced-color-adjust: none;
    background-color: Highlight;
    color: HighlightText;
    border-color: Highlight;
  }
  .stepper-item.active::after {
    forced-color-adjust: none;
    background-color: Highlight;
  }
  .stepper-item[aria-current="step"]::before {
    outline: 2px solid CanvasText;
    outline-offset: 2px;
  }

  /* Focus drawn only as a shadow ring: the chips field. */
  .pg-chips:focus-within {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
  /* The role card's ring is an outline of the token size; it takes the
     system focus colour. */
  .btn-check:focus-visible + .pg-role-card {
    outline-color: Highlight;
  }
}

/* List table driver (assets/js/pg_list_table.js, includes/fn/list_table.php):
   the list fills the window from where it starts; its rows scroll in their
   own box under a sticky heading row, the selection bar stays above them.
   The list is one framed surface, look A's card (.pg-card on the root): the
   bar is its header strip, the rows and the details panel its body. The
   rows sit on the card's top surface; a sticky cell paints it under its own
   hover or selection tint, so the columns that scroll never show through. */
.pg-list-table {
  --pg-list-table-label: 8rem;
  --pg-list-table-cell-max: 22rem;
  --pg-list-table-bg: var(--pg-surface-1);
  --pg-list-table-line: var(--pg-border-color-translucent);
  --pg-list-table-row-tint: transparent;
  display: flex;
  flex-direction: column;
  min-height: 16rem;
  max-height: calc(100dvh - var(--pg-list-table-top, 12rem) - 1rem);
  overflow: hidden;
}
.pg-list-table-scroll {
  /* The containing block of absolutely positioned cell content
     (.visually-hidden): without it that content is placed against <body>,
     escapes this box's clip and makes the whole page scroll sideways. */
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  background: var(--pg-list-table-bg);
}
.pg-list-table-grid {
  width: max-content;
  min-width: 100%;
  margin-top: 0;
  margin-bottom: 0;
}
/* The heading row: 38 px, small strong text in the third text colour; the
   sorted column's heading in the text colour. */
.pg-list-table-grid > thead > tr > th {
  position: sticky;
  top: 0;
  z-index: 2;
  height: 38px;
  padding: 0 14px;
  border-bottom: 0;
  background: var(--pg-list-table-bg);
  box-shadow: inset 0 -1px 0 var(--pg-list-table-line);
  font-size: var(--pg-text-meta);
  font-weight: var(--pg-weight-strong);
  color: var(--pg-fg-3);
  white-space: nowrap;
  vertical-align: middle;
}
.pg-list-table-grid > thead > tr > th[aria-sort] {
  color: var(--pg-fg-body);
}
/* One line per row, so every row has the same height: a long text stops at
   the cell's widest size with an ellipsis (the details panel and the phone
   card show it whole); numbers and money keep their figures aligned. */
.pg-list-table-grid > tbody > tr > td {
  height: 52px;
  max-width: var(--pg-list-table-cell-max);
  padding: 0 14px;
  border-bottom: 1px solid var(--pg-list-table-line);
  background: linear-gradient(var(--pg-list-table-row-tint), var(--pg-list-table-row-tint));
  box-shadow: none;
  color: var(--pg-fg-body);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  vertical-align: middle;
}
/* A thumbnail is a 32 px square with the icon tile's corners; the details
   panel and the phone card show the picture whole. The cells print their
   pictures with an inline 50 px size, hence !important. */
@media (min-width: 768px) {
  .pg-list-table-grid > tbody > tr > td.pg-list-col-image :is(img, svg) {
    width: 32px !important;
    height: 32px !important;
    padding: 0;
    object-fit: cover;
    border-radius: 9px;
  }
}
.pg-list-table-grid > thead > tr > th.text-end,
.pg-list-table-grid > tbody > tr > td.text-end {
  font-variant-numeric: tabular-nums;
}
/* A second line some cells carry (the impact's view count) follows the
   first on the same line. */
.pg-list-table-grid > tbody > tr > td[data-pg-col="impact"] > div {
  display: inline;
  margin-inline-start: 0.375rem;
}
/* From 768 px the record's name stays at the left edge and the row's
   buttons at the right edge while the columns between scroll sideways. */
@media (min-width: 768px) {
  .pg-list-table-grid > tbody > tr > td.text-wrap,
  .pg-list-table-grid > tbody > tr > td .text-wrap {
    white-space: nowrap !important;
  }
  .pg-list-table-grid > * > tr > :first-child,
  .pg-list-table-grid > * > tr > [data-pg-col="actions"] {
    position: sticky;
    z-index: 1;
  }
  .pg-list-table-grid > tbody > tr > :first-child,
  .pg-list-table-grid > tbody > tr > [data-pg-col="actions"] {
    background: linear-gradient(var(--pg-list-table-row-tint), var(--pg-list-table-row-tint)), var(--pg-list-table-bg);
  }
  .pg-list-table-grid > * > tr > :first-child {
    inset-inline-start: 0;
    box-shadow: inset -1px 0 0 var(--pg-list-table-line);
  }
  .pg-list-table-grid > * > tr > [data-pg-col="actions"] {
    inset-inline-end: 0;
    box-shadow: inset 1px 0 0 var(--pg-list-table-line);
  }
  .pg-list-table-grid > thead > tr > :first-child {
    box-shadow: inset -1px 0 0 var(--pg-list-table-line), inset 0 -1px 0 var(--pg-list-table-line);
  }
  .pg-list-table-grid > thead > tr > [data-pg-col="actions"] {
    box-shadow: inset 1px 0 0 var(--pg-list-table-line), inset 0 -1px 0 var(--pg-list-table-line);
  }
  .pg-list-table-grid > thead > tr > :first-child,
  .pg-list-table-grid > thead > tr > [data-pg-col="actions"] {
    z-index: 3;
  }
  /* Each sticky cell is a layer of its own, so a row's open menu went
     under the action cells of the rows below it: the cell holding the open
     menu goes above them and the heading. */
  .pg-list-table-grid > tbody > tr > [data-pg-col="actions"]:has(> .menu-wrapper > .menu.show) {
    z-index: 4;
  }  /* Content review: a long page or record name stops at 14rem (the whole
     name is the link's title), so every column fits a 1440 px window under
     every filter. */
  .pg-list-table[data-pg-list-table="view_content_review"] .pg-list-table-grid > * > tr > [data-pg-col="name"] {
    max-width: 14rem;
  }
  /* A long collection name in the Kind pill stops at 8rem too. */
  .pg-list-table[data-pg-list-table="view_content_review"] .pg-list-table-grid > * > tr > [data-pg-col="kind"] {
    max-width: 8rem;
  }
  .pg-list-table[data-pg-list-table="view_content_review"] [data-pg-col="kind"] .pg-pill {
    max-width: 100%;
  }
  .pg-list-table[data-pg-list-table="view_content_review"] [data-pg-col="kind"] .pg-pill > span {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }
}
/* The row's own buttons: small, at the row's right end. */
.pg-list-table-grid > tbody > tr > td[data-pg-col="actions"] {
  padding-inline: 10px;
  text-align: end;
}
.pg-list-table-grid > tbody > tr > td[data-pg-col="actions"] .btn {
  --bs-btn-min-height: 28px;
  --bs-btn-padding-y: 0;
  --bs-btn-padding-x: 11px;
  --bs-btn-font-size: var(--pg-text-2);
  --bs-btn-font-weight: var(--pg-weight-strong);
  --bs-btn-border-radius: 8px;
  margin-block: 0 !important;
}
/* The SEO column: the score bar with its number, never under the name. */
.pg-seo-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  max-width: 170px;
}
.pg-seo-bar > small {
  min-width: 2ch;
  text-align: end;
  font-variant-numeric: tabular-nums;
}
.pg-list-table-seo {
  display: block;
  min-width: 5.5rem;
}
.pg-list-table-sort {
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: inherit;
}
.pg-list-table-grid th[aria-sort] .pg-list-table-sort::after {
  content: "\2191";
  margin-inline-start: 4px;
  font-size: var(--pg-text-count);
}
.pg-list-table-grid th[aria-sort="descending"] .pg-list-table-sort::after {
  content: "\2193";
}
.pg-list-table-grid > tbody > tr {
  cursor: default;
  user-select: none;
}
.pg-list-table-grid > tbody > tr:focus-visible {
  outline: var(--pg-focus-ring-width) solid var(--pg-focus-ring-color);
  outline-offset: calc(var(--pg-focus-ring-width) * -1);
}
.pg-list-table-grid > tbody > tr:hover {
  --pg-list-table-row-tint: var(--pg-hover);
}
.pg-list-table-grid > tbody > tr.pg-list-table-selected {
  --pg-list-table-row-tint: color-mix(in srgb, var(--pg-accent) var(--pg-tint-select), transparent);
}
/* The selection bar, the list's header strip: the clear button, the count
   and the screen's bulk actions at the left while rows are selected, the
   list's tools (quick edit, columns, details) always at the right. One
   height in both states, so the rows never jump. */
.pg-list-table-bar {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  min-height: 48px;
  padding: 6px 10px;
  border-bottom: 1px solid var(--pg-list-table-line);
  background: color-mix(in srgb, var(--pg-accent) 7%, transparent);
}
.pg-list-table-bar.is-empty {
  background: none;
}
.pg-list-table-count {
  font-weight: var(--pg-weight-title);
  color: var(--pg-accent);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.pg-list-table-count:not(:empty) {
  padding-inline: 4px 14px;
  margin-inline-end: 6px;
  border-inline-end: 1px solid var(--pg-list-table-line);
}
/* A screen's bulk buttons, sized as the bar's small buttons. */
.pg-list-table-actions .btn {
  --bs-btn-min-height: 28px;
  --bs-btn-padding-y: 0;
  --bs-btn-padding-x: 11px;
  --bs-btn-font-size: var(--pg-text-2);
  --bs-btn-font-weight: var(--pg-weight-strong);
  --bs-btn-border-radius: 8px;
  margin: 0 !important;
}
.pg-list-table-bar.is-empty > .pg-list-table-count,
.pg-list-table-bar.is-empty > .pg-list-table-actions {
  display: none;
}
.pg-list-table-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
/* The columns menu and the details switch keep the bar's right end. On a
   phone four labelled tools are wider than the bar: they wrap inside it
   (min-width: 0 lets the strip shrink to the bar) instead of running past
   the card's clipped edge. */
.pg-list-table-tools {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 6px;
  min-width: 0;
  margin-inline-start: auto;
}
.pg-list-table-columns-menu {
  min-width: 16rem;
  max-height: 60dvh;
  overflow: auto;
  padding: 0.25rem;
}
.pg-list-table-columns-menu.show {
  opacity: 1;
}
.pg-list-table-column {
  display: flex;
  align-items: center;
  gap: 0.125rem;
}
.pg-list-table-column-name {
  display: flex;
  align-items: center;
  flex: 1 1 auto;
  min-width: 0;
  padding: 0.25rem 0.5rem;
  cursor: pointer;
}
/* The rows and the details panel side by side. */
.pg-list-table-body {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
}
.pg-list-table-body > .pg-list-table-scroll {
  flex: 1 1 auto;
  min-width: 0;
}
/* The details panel, one rule for every list (ui/details-panel-rule.md):
   a header strip (title and close), then in this order the record's name
   as the heading, its pictures, one line per other column (a fixed label
   column at the left, the value at the right, a hairline between lines,
   the same spacing everywhere), and the row's buttons last. A column with
   nothing in its cell is left out (pg_list_table.js detailsSections()). */
.pg-list-table-details {
  display: flex;
  flex-direction: column;
  flex: 0 0 var(--pg-measure-details);
  min-height: 0;
  border-inline-start: 1px solid var(--pg-list-table-line);
  background: var(--pg-list-table-bg);
}
.pg-list-table-details[hidden] {
  display: none;
}
.pg-list-table-details-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 48px;
  padding: 6px 10px 6px 16px;
  border-bottom: 1px solid var(--pg-list-table-line);
  font-size: var(--pg-text-2);
  font-weight: var(--pg-weight-strong);
  color: var(--pg-fg-2);
}
.pg-list-table-details-body {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  flex: 1 1 auto;
  overflow: auto;
  padding: 0.75rem 1rem 1rem;
}
.pg-list-table-details-title {
  margin: 0;
  font-size: var(--pg-text-status-title);
  font-weight: var(--pg-weight-title);
  line-height: 1.5rem;
  overflow-wrap: anywhere;
}
.pg-list-table-details-pictures {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.pg-list-table-details-pictures img,
.pg-list-table-details dd img {
  max-width: 100%;
  height: auto;
}
.pg-list-table-details dl {
  display: grid;
  grid-template-columns: var(--pg-list-table-label) minmax(0, 1fr);
  margin: 0;
  border-bottom: 1px solid var(--pg-list-table-line);
}
.pg-list-table-details dt,
.pg-list-table-details dd {
  margin: 0;
  padding-block: 0.5rem;
  border-top: 1px solid var(--pg-list-table-line);
}
.pg-list-table-details dt {
  padding-inline-end: 0.75rem;
  font-size: var(--pg-text-meta);
  font-weight: var(--pg-weight-strong);
  line-height: 1.5rem;
  color: var(--pg-fg-3);
}
.pg-list-table-details dd {
  min-width: 0;
  font-size: var(--pg-text-base);
  line-height: 1.5rem;
  overflow-wrap: anywhere;
}
/* A fragment a cell's link loaded (the SEO analysis) spans the panel
   under its column's line, part of that line. */
.pg-list-table-details dd.pg-list-table-details-more {
  grid-column: 1 / -1;
  padding-top: 0;
  border-top: 0;
}
.pg-list-table-details-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
}
.pg-list-table-details-actions .btn {
  margin: 0 !important;
}
/* Below 1024 px the details panel is a sheet over the list's right side. */
@media (max-width: 1023.98px) {
  .pg-list-table-details {
    position: fixed;
    inset-block: 0;
    inset-inline-end: 0;
    z-index: 1045;
    width: min(22rem, 100vw);
    box-shadow: var(--pg-shadow-float);
  }
}
/* Below 768 px a row is a block of the frame's one surface, rows split by
   a line (no rounded card inside the rounded frame): every shown cell is a
   line with its column's name at the left and its value in one column at
   the right, however many pieces the value is made of. */
@media (max-width: 767.98px) {
  .pg-list-table-grid > thead {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
  }
  .pg-list-table-grid,
  .pg-list-table-grid > tbody,
  .pg-list-table-grid > tbody > tr,
  .pg-list-table-grid > tbody > tr > td {
    display: block;
    width: 100%;
  }
  .pg-list-table-grid > tbody > tr {
    padding: 6px 0;
    border-bottom: 1px solid var(--pg-list-table-line);
    background: linear-gradient(var(--pg-list-table-row-tint), var(--pg-list-table-row-tint));
  }
  .pg-list-table-grid > tbody > tr:last-child {
    border-bottom: 0;
  }
  .pg-list-table-grid > tbody > tr > td {
    position: relative;
    height: auto;
    min-height: 32px;
    max-width: none;
    padding: 6px 14px 6px calc(14px + var(--pg-list-table-label) + 0.75rem);
    text-align: start;
    white-space: normal;
    overflow-wrap: anywhere;
    border: 0;
    background: none;
  }
  .pg-list-table-grid > tbody > tr > td[hidden] {
    display: none;
  }
  /* A number or a row's buttons start in the value column too; the
     unlayered .text-end utility is beaten only by an important rule. */
  .pg-list-table-grid > tbody > tr > td:is(.text-end, [data-pg-col]) {
    text-align: start !important;
  }
  /* The row's buttons keep the label column too: the wide rule's 10 px
     sides would start them at the left edge, over their "Action" label.
     Offers is left as it is drawn today: its look waits for the owner. */
  .pg-list-table:not([data-pg-list-table="view_offers"]) .pg-list-table-grid > tbody > tr > td[data-pg-col="actions"] {
    padding-inline: calc(14px + var(--pg-list-table-label) + 0.75rem) 14px;
  }
  .pg-list-table-grid > tbody > tr > td::before {
    content: attr(data-pg-label);
    position: absolute;
    top: 8px;
    left: 14px;
    width: var(--pg-list-table-label);
    font-size: var(--pg-text-meta);
    text-align: start;
    font-weight: var(--pg-weight-strong);
    color: var(--pg-fg-3);
  }
}
/* The foot: what is loading at the left, "Show more" at the right. */
.pg-list-table-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  padding: 8px 14px;
  font-size: var(--pg-text-2);
  color: var(--pg-fg-3);
}
.pg-list-table-more {
  margin-inline-start: auto;
}
.pg-list-table-status:empty,
.pg-list-table-more[hidden] {
  display: none;
}
.pg-list-table-status {
  margin: 0;
  color: var(--pg-fg-3);
}
.pg-list-table-sentinel {
  height: 1px;
}
.pg-list-table-empty {
  padding: 24px 14px;
  margin: 0;
  font-size: var(--pg-text-2);
  color: var(--pg-fg-3);
  text-align: center;
}
/* Quick edit mode (pg_list_table_edit.js): each editable cell holds a
   field; a refused value is marked and its reason stands under it. Its
   switch in the bar is an icon button, pressed while the mode is on. */
.pg-list-table.is-quick-edit .pg-list-table-bar.is-empty.has-quick {
  background: color-mix(in srgb, var(--pg-accent) 7%, transparent);
}
.pg-list-table-field {
  min-width: 6rem;
}
/* A several-line field (a message, a description) is wide enough to read
   and grows by hand, never wider than its cell. */
textarea.pg-list-table-field-lines {
  min-width: 14rem;
  resize: vertical;
}
/* A several-choice field: its boxes one under the other, scrolled past a
   few, so a long list of groups or zones keeps the row short. */
.pg-list-table-choices {
  max-height: 9rem;
  overflow-y: auto;
  padding: 0.25rem 0.5rem;
}
.pg-list-table-choice {
  display: block;
  white-space: nowrap;
}
/* A select in a cell coloured by an access level (.private * and the like)
   keeps the field's own colour; it and each option wear their own level's
   class instead (the Pages list's folders, tintSelect()). */
select.pg-list-table-field,
select.pg-list-table-field option {
  color: var(--pg-fg-body);
}
select.pg-list-table-field.public,
select.pg-list-table-field option.public {
  color: var(--pg-access-public);
}
select.pg-list-table-field.guest,
select.pg-list-table-field option.guest {
  color: var(--pg-access-guest);
}
select.pg-list-table-field.registration,
select.pg-list-table-field option.registration {
  color: var(--pg-access-registration);
}
select.pg-list-table-field.membership,
select.pg-list-table-field option.membership {
  color: var(--pg-access-membership);
}
select.pg-list-table-field.private,
select.pg-list-table-field option.private {
  color: var(--pg-access-private);
}
.pg-list-table-grid > tbody > tr > td[aria-busy="true"] > .pg-list-table-field {
  opacity: 0.6;
}
.pg-list-table-field-note {
  margin-top: 0.125rem;
  font-size: var(--pg-text-meta);
  color: var(--pg-tone-rose-text);
  white-space: normal;
  text-align: start;
}
.pg-list-table-grid > tbody > tr > td.pg-list-table-saved {
  animation: pgListTableSaved 1.2s ease-out;
}
@keyframes pgListTableSaved {
  from {
    background-color: color-mix(in srgb, var(--pg-success) 30%, transparent);
  }
  to {
    background-color: transparent;
  }
}
@media (prefers-reduced-motion: reduce) {
  .pg-list-table-grid > tbody > tr > td.pg-list-table-saved {
    animation: none;
  }
}

/* Bookings week (view_bookings.php?view=week): seven day columns from xl up.
   A flex item's min-width is its content, so a booking's unbreakable first
   line (time and status badge) widened the columns until Saturday and Sunday
   wrapped to a second row; the columns may shrink and that line wraps. */
.pg-bookings-week > section {
  min-width: 0;
}
.pg-bookings-week .list-group-item .d-flex {
  flex-wrap: wrap;
}

/* Live picture of a design or template (pg_design_live_picture(),
   assets/js/pg_live_picture.js): the real page drawn at 1280x800 in a
   script-free frame, scaled to the box from its top left corner. The frame
   never takes a click: the box's parent (a card, a radio's label) does. */
.pg-live-picture {
  position: relative;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  border: 1px solid var(--pg-border-color);
  border-radius: .5rem;
  background: var(--pg-bg-2);
}
.pg-live-picture > iframe {
  position: absolute;
  top: 0;
  left: 0;
  border: 0;
  transform-origin: 0 0;
  pointer-events: none;
  background: #fff;
  opacity: 0;
  transition: opacity .2s ease;
}
.pg-live-picture.pg-loaded > iframe {
  opacity: 1;
}
.pg-live-picture-wait {
  position: absolute;
  inset: 0;
  display: none;
  background: linear-gradient(100deg, transparent 30%, color-mix(in srgb, var(--pg-border-color) 45%, transparent) 50%, transparent 70%) 0 0 / 300% 100%;
}
.pg-live-picture.pg-loading .pg-live-picture-wait {
  display: block;
  animation: pg-live-picture-wait 1.6s ease-in-out infinite;
}
@media (prefers-reduced-motion: reduce) {
  .pg-live-picture.pg-loading .pg-live-picture-wait {
    animation: none;
  }
  .pg-live-picture > iframe {
    transition: none;
  }
}
@keyframes pg-live-picture-wait {
  from { background-position: 100% 0; }
  to { background-position: 0 0; }
}
.pg-live-picture-fallback {
  position: absolute;
  inset: 0;
}
.pg-live-picture-fallback[hidden] {
  display: none;
}
.pg-live-picture-fallback > svg,
.pg-live-picture-fallback > img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.pg-live-picture.pg-failed:not(:has(.pg-live-picture-fallback))::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(135deg, transparent 0 .75rem, color-mix(in srgb, var(--pg-border-color) 35%, transparent) .75rem 1.5rem);
}

/* ── The picker dialog (assets/js/pg_picker.js) ─────────────────────────
   A folder tree beside the open folder as tiles or a list, a toolbar with
   the way up, the breadcrumb, the search, the sort and the view, and a
   footer with the pick. Tile and tree sizes follow the File Manager's
   (explorer-grid-tiles.md). Below 576 px a bottom sheet: the tree gives way
   to a folder chip that opens a folder list in the pane. */
.dialog.pg-picker {
  --bs-dialog-width: 1120px;
  --pg-picker-tile: 9rem;
  height: min(50rem, calc(100% - 3.5rem));
}
.pg-picker .dialog-header {
  gap: 0.75rem;
  padding: 1rem 1.25rem 0.75rem;
  border-bottom: 0;
}
.pg-picker .dialog-title {
  font-size: 1.15rem;
  font-weight: 600;
}
.pg-picker-types {
  font-size: 0.8rem;
  color: var(--pg-fg-2);
}
.pg-picker .dialog-body {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 0;
  overflow: hidden;
}
.pg-picker-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0 1.25rem 0.75rem;
  border-bottom: var(--pg-border-width) solid var(--pg-border-color);
}
.pg-picker-crumbs {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
}
.pg-picker-crumbs a {
  color: var(--pg-fg-body);
  text-decoration: none;
}
.pg-picker-crumbs a:hover {
  text-decoration: underline;
}
.pg-picker-crumbs .bi {
  font-size: 0.7rem;
  color: var(--pg-fg-3);
}
.pg-picker-crumbs strong {
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--pg-fg-emphasis);
}
.pg-picker-chip {
  display: none;
}
.pg-picker-search {
  position: relative;
  flex: 0 1 16rem;
}
.pg-picker-search > .bi-search {
  position: absolute;
  top: 50%;
  left: 0.8rem;
  transform: translateY(-50%);
  color: var(--pg-fg-2);
  pointer-events: none;
}
.pg-picker-search .form-control {
  padding-inline: 2.1rem 2rem;
  border-radius: var(--pg-radius-pill);
}
.pg-picker-search .form-control::-webkit-search-cancel-button {
  display: none;
}
.pg-picker-clear {
  position: absolute;
  top: 50%;
  right: 0.55rem;
  transform: translateY(-50%);
  padding: 0;
  border: 0;
  background: none;
  color: var(--pg-fg-3);
  line-height: 1;
}
.pg-picker-sort {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  margin: 0;
  color: var(--pg-fg-2);
}
.pg-picker-sort .form-control {
  width: auto;
}
.pg-picker-views {
  display: flex;
  gap: 0.15rem;
  padding-left: 0.5rem;
  border-left: var(--pg-border-width) solid var(--pg-border-color);
}
.pg-picker-views .btn.active {
  background: var(--pg-tint-strong);
  color: var(--pg-fg-emphasis);
}
.pg-picker-main {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
}
.pg-picker-tree {
  flex: 0 0 15rem;
  padding: 0.6rem 0.5rem;
  overflow: auto;
  font-size: 0.875rem;
  border-right: var(--pg-border-width) solid var(--pg-border-color);
}
.pg-picker-section {
  padding: 0.4rem 0.5rem 0.3rem;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--pg-fg-2);
}
.pg-picker-tree ul {
  margin: 0;
  padding: 0;
  list-style: none;
}
.pg-picker-tree ul ul {
  margin-left: 0.9rem;
  padding-left: 0.35rem;
  border-left: var(--pg-border-width) solid var(--pg-border-color-translucent);
}
.pg-picker-tree [role=treeitem] {
  outline: 0;
}
.pg-picker-row {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.25rem 0.45rem 0.25rem 0.2rem;
  border-radius: var(--pg-radius-lg);
  cursor: pointer;
  white-space: nowrap;
}
.pg-picker-row:hover {
  background: var(--pg-tint-hover);
}
.pg-picker-row.is-open {
  background: var(--pg-primary-bg-subtle);
  color: var(--pg-fg-emphasis);
  font-weight: 600;
}
.pg-picker-tree [role=treeitem]:focus-visible > .pg-picker-row {
  outline: var(--pg-focus-ring-width) solid var(--pg-focus-ring-color);
  outline-offset: calc(var(--pg-focus-ring-width) * -1);
}
.pg-picker-toggle {
  display: inline-flex;
  flex: 0 0 1rem;
  justify-content: center;
  font-size: 0.65rem;
  color: var(--pg-fg-2);
  transition: transform 0.12s ease;
}
.pg-picker-toggle.open {
  transform: rotate(90deg);
}
.pg-picker .pg-picker-folder,
.pg-picker-item.is-folder .pg-picker-thumb .bi {
  color: var(--pg-warning);
}
.pg-picker-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pg-picker-count {
  font-size: 0.75rem;
  font-weight: 400;
  color: var(--pg-fg-2);
}
.pg-picker-pane {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-width: 0;
}
.pg-picker-status {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 0.75rem;
  min-height: 2.5rem;
  padding: 0.5rem 1rem 0.25rem;
  font-size: 0.8rem;
  color: var(--pg-fg-2);
}
.pg-picker-status strong {
  color: var(--pg-fg-emphasis);
}
.pg-picker-note {
  margin-left: auto;
}
.pg-picker-only {
  border: var(--pg-border-width) solid var(--pg-border-color);
  border-radius: var(--pg-radius-pill);
}
.pg-picker-only.active {
  border-color: var(--pg-primary-border-subtle);
  background: var(--pg-primary-bg-subtle);
}
.pg-picker-items {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(var(--pg-picker-tile), 1fr));
  align-content: start;
  gap: 0.5rem;
  flex: 1 1 auto;
  min-height: 0;
  padding: 0.25rem 1rem 1rem;
  overflow: auto;
  outline: 0;
}
.pg-picker-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
  min-width: 0;
  padding: 0.5rem;
  border: var(--pg-border-width) solid transparent;
  border-radius: var(--pg-radius-lg);
  text-align: center;
  cursor: pointer;
  user-select: none;
}
.pg-picker-item:hover {
  background: var(--pg-tint-hover);
}
.pg-picker-item[aria-selected=true] {
  border-color: var(--pg-primary-border-subtle);
  background: var(--pg-primary-bg-subtle);
}
.pg-picker-items:focus-visible .pg-picker-item.is-cursor {
  outline: var(--pg-focus-ring-width) solid var(--pg-focus-ring-color);
  outline-offset: calc(var(--pg-focus-ring-width) * -1);
}
.pg-picker-thumb {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  border-radius: var(--pg-radius);
  background: var(--pg-bg-1);
  font-size: 2.25rem;
  color: var(--pg-fg-2);
}
.pg-picker-item.is-folder .pg-picker-thumb {
  background: none;
  font-size: 3rem;
}
.pg-picker-thumb img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.pg-picker-lock,
.pg-picker-tick {
  position: absolute;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.4rem;
  height: 1.4rem;
  border-radius: 50%;
  font-size: 0.75rem;
}
.pg-picker-lock {
  right: 0.3rem;
  bottom: 0.3rem;
  background: var(--pg-bg-body);
  color: var(--pg-fg-emphasis);
  box-shadow: var(--pg-shadow);
}
.pg-picker-tick {
  top: 0.3rem;
  left: 0.3rem;
  background: var(--pg-primary);
  color: var(--pg-bg-body);
}
.pg-picker-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
  width: 100%;
}
.pg-picker-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.85rem;
  color: var(--pg-fg-emphasis);
}
.pg-picker-name mark {
  padding: 0;
  background: color-mix(in srgb, var(--pg-warning) 35%, transparent);
  color: inherit;
}
.pg-picker-meta {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.75rem;
  color: var(--pg-fg-2);
}
.pg-picker-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  grid-column: 1 / -1;
  min-height: 16rem;
  border: var(--pg-border-width) dashed var(--pg-border-color);
  border-radius: var(--pg-radius-lg);
  color: var(--pg-fg-2);
  text-align: center;
}
.pg-picker-empty .bi {
  font-size: 2.5rem;
}
.pg-picker-empty strong {
  color: var(--pg-fg-emphasis);
}
.pg-picker-head {
  display: grid;
  margin: 0 1rem;
  border-bottom: var(--pg-border-width) solid var(--pg-border-color);
}
.pg-picker-head[hidden] {
  display: none;
}
.pg-picker-is-list .pg-picker-items {
  grid-template-columns: 1fr;
  gap: 0;
  padding-top: 0;
}
.pg-picker-is-list :is(.pg-picker-head, .pg-picker-item:not(.pg-picker-folder-row)) {
  grid-template-columns: minmax(12rem, 3fr) 6rem 6rem 9.5rem minmax(7rem, 1.2fr);
  align-items: center;
  column-gap: 0.75rem;
}
.pg-picker-is-list .pg-picker-item:not(.pg-picker-folder-row) {
  display: grid;
  padding: 0.3rem 0.5rem;
  border-width: 0 0 var(--pg-border-width);
  border-bottom-color: var(--pg-border-color);
  border-radius: 0;
  text-align: left;
}
.pg-picker-is-list .pg-picker-item > .pg-picker-thumb {
  justify-self: start;
  width: 2.25rem;
  font-size: 1.1rem;
}
.pg-picker-is-list .pg-picker-item {
  grid-template-areas: "name type size modified access";
}
.pg-picker-is-list .pg-picker-item > .pg-picker-thumb,
.pg-picker-is-list .pg-picker-item > .pg-picker-text {
  grid-area: name;
}
.pg-picker-is-list .pg-picker-item > .pg-picker-text {
  padding-left: 2.85rem;
}
.pg-picker-is-list .pg-picker-item.is-folder > .pg-picker-thumb {
  font-size: 1.4rem;
}
.pg-picker-is-list .pg-picker-item .pg-picker-meta,
.pg-picker-is-list .pg-picker-item .pg-picker-tick {
  display: none;
}
.pg-picker-head .pg-picker-col {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.5rem;
  border: 0;
  background: none;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--pg-fg-emphasis);
  text-align: left;
}
.pg-picker-item .pg-picker-col {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.85rem;
  color: var(--pg-fg-body);
}
.pg-picker-col.pg-picker-num {
  justify-content: flex-end;
  text-align: right;
}
/* Pages: rows of name, address, type and date; a chip per page type group;
   a page in an archived folder or in the Recycle Bin greyed with its mark. */
.pg-picker-is-pages.pg-picker-is-list :is(.pg-picker-head, .pg-picker-item:not(.pg-picker-folder-row)) {
  grid-template-columns: minmax(12rem, 3fr) minmax(8rem, 2fr) minmax(7rem, 1.2fr) 9.5rem;
}
.pg-picker-is-pages.pg-picker-is-list .pg-picker-item {
  grid-template-areas: "name address type modified";
}
.pg-picker-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  padding: 0 1rem 0.5rem;
}
.pg-picker-chips[hidden] {
  display: none;
}
.pg-picker-name-line {
  display: flex;
  /* In a narrow name column the mark goes under the name instead of
     squeezing it to one letter. */
  flex-wrap: wrap;
  align-items: center;
  gap: 0.1rem 0.4rem;
  min-width: 0;
}
.pg-picker-mark {
  flex: 0 0 auto;
  padding: 0.05rem 0.45rem;
  border-radius: var(--pg-radius-pill);
  font-size: 0.7rem;
  white-space: nowrap;
}
.pg-picker-mark.is-archived {
  background: var(--pg-warning-bg-subtle);
  color: var(--pg-warning-fg-emphasis);
}
.pg-picker-mark.is-binned {
  background: var(--pg-danger-bg-subtle);
  color: var(--pg-danger-fg-emphasis);
}
/* A file a channel would refuse: the reason, which may run to a line. */
.pg-picker-mark.is-refused {
  background: var(--pg-bg-1);
  color: var(--pg-fg-2);
  white-space: normal;
}
.pg-picker-item.is-marked {
  cursor: default;
}
.pg-picker-item.is-marked :is(.pg-picker-thumb, .pg-picker-name, .pg-picker-col) {
  opacity: 0.6;
}
.pg-picker .dialog-footer {
  flex-wrap: nowrap;
  padding: 0.75rem 1.25rem;
}
.pg-picker-pick {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  gap: 0.65rem;
  min-width: 0;
}
.pg-picker-pick .pg-picker-thumb {
  flex: 0 0 2.5rem;
  width: 2.5rem;
  font-size: 1.25rem;
}
.pg-picker-hint {
  font-size: 0.8rem;
  color: var(--pg-fg-2);
  white-space: nowrap;
}
.pg-picker-field {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
}
.pg-picker-field-input {
  flex: 1 1 auto;
  min-width: 0;
}
.pg-picker-folder-row {
  flex-direction: row;
  gap: 0.75rem;
  padding: 0.75rem;
  border-width: 0 0 var(--pg-border-width);
  border-bottom-color: var(--pg-border-color);
  border-radius: 0;
  text-align: left;
}
.pg-picker-folder-row .bi-folder-fill {
  font-size: 1.25rem;
}
.pg-picker-folders .pg-picker-items {
  grid-template-columns: 1fr;
  gap: 0;
}
.pg-picker-folders :is(.pg-picker-choose, .pg-picker-cancel, .pg-picker-pick, .pg-picker-search, .pg-picker-sort, .pg-picker-views, .pg-picker-chip, .pg-picker-up) {
  display: none;
}
.pg-picker-sheet.pg-picker-folders .pg-picker-crumbs {
  display: flex;
}
.pg-picker-sheet.pg-picker-folders .pg-picker-chip {
  display: none;
}
@media (prefers-reduced-motion: reduce) {
  .pg-picker-toggle {
    transition: none;
  }
}
/* Recent above the folders; Upload at the bar's end. */
.pg-picker-recent {
  width: 100%;
  margin-bottom: 0.35rem;
  padding-left: 0.45rem;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
}
.pg-picker-recent:focus-visible {
  outline: var(--pg-focus-ring-width) solid var(--pg-focus-ring-color);
  outline-offset: calc(var(--pg-focus-ring-width) * -1);
}
.pg-picker-upload {
  flex: 0 0 auto;
}
.pg-picker-upload:disabled {
  pointer-events: auto;
  cursor: not-allowed;
}
.pg-picker-folders .pg-picker-upload {
  display: none;
}
/* All heads the tree: its total at the row's end, as a folder's count. */
.pg-picker-all-row .pg-btn-label {
  flex: 1 1 auto;
}
/* The pick's way back to its folder, under its line. */
.pg-picker-in-folder {
  font-size: 0.75rem;
}
.pg-picker-folders .pg-picker-target {
  display: none;
}
/* Files dragged over the pane: the folder they go into, or why not. */
.pg-picker-pane {
  position: relative;
}
.pg-picker-drop {
  position: absolute;
  inset: 0.5rem;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 1rem;
  border: 2px dashed var(--pg-primary);
  border-radius: var(--pg-radius-lg);
  background: color-mix(in srgb, var(--pg-primary-bg-subtle) 92%, transparent);
  color: var(--pg-fg-emphasis);
  text-align: center;
  pointer-events: none;
}
.pg-picker-drop .bi {
  font-size: 2.5rem;
  color: var(--pg-primary);
}
.pg-picker-drop span {
  font-size: 0.85rem;
  color: var(--pg-fg-2);
}
.pg-picker-drop.is-refused {
  border-color: var(--pg-danger);
  background: color-mix(in srgb, var(--pg-danger-bg-subtle) 92%, transparent);
}
.pg-picker-drop.is-refused .bi {
  color: var(--pg-danger);
}
.pg-picker-drop[hidden],
.pg-picker-uploads[hidden] {
  display: none;
}
/* The files being sent, one row each. */
.pg-picker-uploads {
  position: absolute;
  right: 1rem;
  bottom: 1rem;
  z-index: 3;
  display: flex;
  flex-direction: column;
  width: min(22rem, calc(100% - 2rem));
  max-height: calc(100% - 2rem);
  border: var(--pg-border-width) solid var(--pg-border-color);
  border-radius: var(--pg-radius-lg);
  background: var(--pg-bg-body);
  box-shadow: var(--pg-shadow-lg);
}
.pg-picker-uploads-head {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.6rem 0.75rem;
  border-bottom: var(--pg-border-width) solid var(--pg-border-color);
  font-size: 0.875rem;
}
.pg-picker-uploads-head strong {
  flex: 0 0 auto;
  white-space: nowrap;
}
.pg-picker-uploads-folder {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  margin-right: auto;
  font-size: 0.8rem;
  color: var(--pg-fg-2);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pg-picker-uploads-list {
  margin: 0;
  padding: 0.25rem 0;
  overflow: auto;
  list-style: none;
}
.pg-picker-upload-row {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.4rem 0.75rem;
}
.pg-picker-upload-row .pg-picker-thumb {
  flex: 0 0 2.25rem;
  width: 2.25rem;
  font-size: 1.1rem;
}
.pg-picker-upload-row .pg-picker-text {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
}
.pg-picker-upload-row .pg-picker-name {
  overflow: hidden;
  font-size: 0.85rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pg-picker-upload-row .pg-picker-meta {
  white-space: normal;
}
.pg-picker-progress {
  display: block;
  height: 0.25rem;
  overflow: hidden;
  border-radius: var(--pg-radius-pill);
  background: var(--pg-border-color);
}
.pg-picker-progress > span {
  display: block;
  width: 0;
  height: 100%;
  background: var(--pg-primary);
  transition: width 0.15s linear;
}
.pg-picker-progress[hidden] {
  display: none;
}
.pg-picker-upload-state {
